INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f42f-7f2d-9526-4112b3f11bcd', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Identity Proofing", "es": "Verificación de Identidad"}', '{"en": "Identity Proofing — NIST SP 800-63A-4 IAL1-3 · ISO/IEC 29115:2013", "es": "Verificación de Identidad — NIST SP 800-63A-4 IAL1-3 · ISO/IEC 29115:2013"}', NULL, '{"en": "Identity Proofing · proofing. What is it? Documented process and result of verifying that a real person corresponds to the identity they claim: IAL1 (self-declared, no documentary verification), IAL2 (remote documentary verification, official document + liveness selfie), IAL3 (in-person or biometric supervised with authorized database comparison). The result is immutable evidence: documents verified, liveness technology used, operator who performed the verification. What is it for? Ensuring that behind every account there is a real person verified at the level required by resource criticality, eliminating synthetic identities and fraudulent accounts. How is it used? When creating an account the system requires the minimum IAL per the tier of the role to be assigned; SU and SYS tier roles require IAL3 mandatorily. Why? Without proofing anyone can create an account with false data; proofing is the only barrier against identity takeover at the source. Standards: NIST SP 800-63A-4 IAL1-3, ISO/IEC 29115:2013 LoA1-4, eIDAS 2.0 Art. 8, W3C VC Data Model 2.0.", "es": "Verificación de Identidad · proofing. ¿Qué es? Proceso y resultado documentado de comprobar que una persona real corresponde a la identidad que reclama: IAL1 (autodeclarado, sin verificación documental), IAL2 (verificación documental remota, documento oficial + selfie con detección de vivacidad), IAL3 (presencial o biométrica supervisada con comparación contra bases de datos autorizadas). El resultado es evidencia inmutable: documentos verificados, tecnología de liveness usada, operador que realizó la verificación. ¿Para qué sirve? Garantizar que detrás de cada cuenta existe una persona real verificada al nivel exigido por la criticidad del recurso, eliminando identidades sintéticas y cuentas fraudulentas. ¿Cómo se usa? Al crear una cuenta el sistema exige el IAL mínimo según el tier del rol a asignar; los roles SU y SYS requieren IAL3 obligatoriamente. ¿Por qué? Sin proofing cualquier persona puede crear una cuenta con datos falsos; el proofing es la única barrera contra la apropiación de identidad en el origen. Normas: NIST SP 800-63A-4 IAL1-3, ISO/IEC 29115:2013 LoA1-4, eIDAS 2.0 Art. 8, W3C VC Data Model 2.0."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.proofing', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'proofing', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f415-7cd9-b631-d58b2d1c2929', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Role Schema", "es": "Esquema del Rol"}', '{"en": "Role Schema — ANSI INCITS 359-2004 §4.1 · SCIM 2.0 RFC 7643 §8", "es": "Esquema de Rol — ANSI INCITS 359-2004 §4.1 · SCIM 2.0 RFC 7643 §8"}', NULL, '{"en": "Role Schema · rol_esquema. What is it? Canonical mold defining the complete structure of a role: the 14 JSONB blocks of the RolTemplate contract (B01 identity, B02 classification, B03 BitMask, B04 DAG inheritance, B05 password policy, B06 MFA, B07 session, B08 restrictions, B09 SoD, B10 audit, B11 delegation, B12 lifecycle, B13 physical access, B14 metadata). Defines WHAT attributes a role can have, not the values of a specific assignment. What is it for? Ensuring all ecosystem roles follow the same canonical structure, enabling automatic validation, DAG inheritance, and SoD conflict detection without manual intervention. How is it used? The catalog loads 66 base schemas; each custom role inherits from one or more schemas and can only override non-locked fields (permitted override). Why? Without a canonical schema roles are defined heterogeneously, making automated evaluation and conflict detection across thousands of concurrent roles impossible. Standards: ANSI INCITS 359-2004 §4.1, SCIM 2.0 RFC 7643 §8, ISO/IEC 24760-2:2025 §7, NIST SP 800-162 §4.2.", "es": "Esquema de Rol · rol_esquema. ¿Qué es? Molde canónico que define la estructura completa de un rol: los 14 bloques JSONB del contrato RolTemplate (B01 identidad, B02 clasificación, B03 BitMask, B04 herencia DAG, B05 política de contraseña, B06 MFA, B07 sesión, B08 restricciones, B09 SoD, B10 auditoría, B11 delegación, B12 ciclo de vida, B13 acceso físico, B14 metadata). Define QUÉ atributos puede tener un rol, no los valores de una asignación específica. ¿Para qué sirve? Garantizar que todos los roles del ecosistema siguen la misma estructura canónica, habilitando validación automática, herencia DAG y detección de conflictos SoD sin intervención manual. ¿Cómo se usa? El catálogo carga 66 esquemas base; cada rol personalizado hereda de uno o más esquemas y puede sobrescribir únicamente los campos no bloqueados (override permitido). ¿Por qué? Sin esquema canónico los roles se definen de forma heterogénea, imposibilitando la evaluación automática y la detección de conflictos entre miles de roles concurrentes. Normas: ANSI INCITS 359-2004 §4.1, SCIM 2.0 RFC 7643 §8, ISO/IEC 24760-2:2025 §7, NIST SP 800-162 §4.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.rol_esquema', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'rol_esquema', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c82-0b2b-7909-a2d3-276b639531d8', '019f8ae0-4282-731e-8d71-c42029fded2f', NULL, 'tenant', '{"en": "skull", "es": "skull"}', '{"en": "skull", "es": "skull"}', NULL, '{"en": "Tenant root node. Anchor of the entire identity hierarchy; domains, blocks, and atoms are all descendants. Never directly evaluated. Standard: ISO/IEC 24760-1:2019.", "es": "Nodo raíz del tenant. Ancla de toda la jerarquía de identidad; dominios, bloques y átomos descienden de este nodo. Nunca se evalúa directamente. Estándar: ISO/IEC 24760-1:2019."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 0, 0, 'skull', true, '1.0', '2026-07-23', NULL, '2026-07-23 01:06:00.249333+00', '2026-07-23 01:06:00.249333+00', 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5ab-70b3-92bf-08dd4d938bec', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "ctx_id Lifecycle", "es": "Ciclo de Vida ctx_id"}', '{"en": "ctx_id Lifecycle — W3C Trace Context v2 · NIST SP 800-53 R5 AC-12", "es": "Ciclo de Vida del ctx_id — W3C Trace Context v2 · NIST SP 800-53 R5 AC-12"}', NULL, '{"en": "Session Management · session. What is it? Complete lifecycle of user sessions: creation (upon authentication, session is generated with complete metadata: IP, device, AAL, ctx_id, start time, last activity), active maintenance (token renewal before expiry without re-authentication if risk is low), normal termination (explicit user logout or inactivity expiration), forced termination (administrative revocation, anomaly detection, privilege change invalidating the session), and concurrency (configurable concurrent session limits per user by tier: SU maximum 1, SYS maximum 2, BIZ_N1 maximum 3). What is it for? Precisely controlling the lifecycle of each user session, ensuring sessions do not remain active longer than necessary and can be terminated instantaneously upon any security event. How is it used? Upon authentication, bAuth creates the session in Redis with TTL; the client renews the token before expiry; upon detecting a security event (password change, account lockout, anomaly detection), bAuth instantly invalidates all active user sessions via the Redis revocation list. Why? Sessions without controlled lifecycle are the origin of session fixation and session hijacking; tokens that cannot be revoked upon compromise leave the attacker with access until the token''s natural expiration. Standards: NIST SP 800-63B-4 §7.1, RFC 6749 §10.4, OWASP ASVS v5.0 §3.3, ISO 27001 A.8.18.", "es": "Gestión de Sesión · session. ¿Qué es? Ciclo de vida completo de las sesiones de usuario: creación (al autenticar, se genera sesión con metadata completo: IP, dispositivo, AAL, ctx_id, hora de inicio, última actividad), mantenimiento activo (renovación de tokens antes de expirar sin re-autenticación si el riesgo es bajo), terminación normal (logout explícito del usuario o expiración por inactividad), terminación forzada (revocación administrativa, detección de anomalía, cambio de privilegios que invalida la sesión) y concurrencia (límite de sesiones simultáneas por usuario configurables por tier: SU máximo 1, SYS máximo 2, BIZ_N1 máximo 3). ¿Para qué sirve? Controlar con precisión el ciclo de vida de cada sesión de usuario, garantizando que las sesiones no permanecen activas más tiempo del necesario y que pueden ser terminadas de forma instantánea ante cualquier evento de seguridad. ¿Cómo se usa? Al autenticar, bAuth crea la sesión en Redis con TTL; el cliente renueva el token antes de expirar; al detectar un evento de seguridad (cambio de contraseña, bloqueo de cuenta, detección de anomalía), bAuth invalida todas las sesiones activas del usuario de forma instantánea mediante la lista de revocación en Redis. ¿Por qué? Las sesiones sin ciclo de vida controlado son el origen del session fixation y del session hijacking; los tokens que no pueden revocarse ante un compromiso dejan al atacante con acceso hasta la expiración natural del token. Normas: NIST SP 800-63B-4 §7.1, RFC 6749 §10.4, OWASP ASVS v5.0 §3.3, ISO 27001 A.8.18."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.session', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'session', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f531-7d6b-a4d2-09163d4ca328', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "1:1 Biometric Verification", "es": "Verificación Biométrica 1:1"}', '{"en": "1:1 Biometric Verification — ISO/IEC 19794-2:2011 §5 · NIST SP 800-63B-4 §5.2.3", "es": "Verificación Biométrica 1:1 — ISO/IEC 19794-2:2011 §5 · NIST SP 800-63B-4 §5.2.3"}', NULL, '{"en": "1:1 Biometric Verification · verification. What is it? Biometric comparison engine verifying whether a freshly captured sample corresponds to the registered template for a specific user who has already declared their identity (1:1, not a full database search). Compares the current sample against the user''s reference template using similarity algorithms (FingerJet for fingerprint, FaceNet or ArcFace for face, IrisCodes for iris) and returns a similarity score with ACCEPT/REJECT decision based on the configured FAR/FRR threshold. What is it for? Confirming that the person presenting the biometric trait is effectively the user they claim to be, as a second or third authentication factor in AAL2/AAL3 flows. How is it used? The user declares their identity (scans their RFID card or enters their UPN); the system retrieves their template from Vault; the sensor captures the trait; the 1:1 engine compares and returns the decision with the similarity score for the audit log. Why? 1:1 verification is the highest precision and lowest latency biometric authentication mode, as it only compares against one template (not the entire database), and provides the certainty a token or PIN cannot: physical presence of the holder. Standards: ISO/IEC 19794-2:2011 §5, NIST SP 800-63B-4 §5.2.3 (AAL3), ISO/IEC 24745:2022 §4, FIDO2 §6.", "es": "Verificación Biométrica 1:1 · verification. ¿Qué es? Motor de comparación biométrica que verifica si una muestra recién capturada corresponde al template registrado para un usuario específico que ya declaró su identidad (1:1, no búsqueda en base completa). Compara la muestra actual contra el template de referencia del usuario usando algoritmos de similitud (FingerJet para huella, FaceNet o ArcFace para cara, IrisCodes para iris) y retorna un score de similitud con decisión ACCEPT/REJECT basada en el umbral FAR/FRR configurado. ¿Para qué sirve? Confirmar que la persona que presenta el rasgo biométrico es efectivamente el usuario que dice ser, como segundo o tercer factor de autenticación en flujos de AAL2/AAL3. ¿Cómo se usa? El usuario declara su identidad (escanea su tarjeta RFID o introduce su UPN); el sistema recupera su template de Vault; el sensor captura el rasgo; el motor 1:1 compara y retorna la decisión con el score de similitud para el log de auditoría. ¿Por qué? La verificación 1:1 es el modo de autenticación biométrica de más alta precisión y menor latencia, ya que solo compara contra un template (no contra toda la base), y proporciona la certeza que un token o PIN no puede dar: presencia física del titular. Normas: ISO/IEC 19794-2:2011 §5, NIST SP 800-63B-4 §5.2.3 (AAL3), ISO/IEC 24745:2022 §4, FIDO2 §6."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.verification', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'verification', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f637-7cd9-8068-38089f6ca593', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Delegation Renewal", "es": "Renovación de Delegación"}', '{"en": "Delegation Renewal — RFC 8693 §4.2 · ISO 27001 A.5.18", "es": "Renovación de Delegación — RFC 8693 §4.2 · ISO 27001 A.5.18"}', NULL, '{"en": "Role Renewal · renewal. What is it? Review and explicit renewal process for role assignments before expiration: 15 days before an assignment expires, the system notifies the role holder and their supervisor; if the role is still needed, the supervisor renews it with documented justification; if not renewed before the expiration date, the role expires automatically without manual action. Renewal requires active confirmation (\"positive re-certification\") — silence equals revocation. What is it for? Implementing the periodic access certification required by SOX, ISO 27001, and internal control frameworks: ensuring every assigned role is reviewed by a responsible human at least every N months, eliminating \"zombie\" roles that nobody remembers assigning. How is it used? The renewal manager runs a periodic review process; generates a list of assignments nearing expiration; notifies responsible supervisors; supervisors approve or let each assignment expire; the system logs every renewal or expiration decision with the responsible supervisor in audit. Why? 60% of privilege creep comes from roles assigned for a temporary project and never reviewed; active renewal with automatic expiration by inactivity is the most effective control for eliminating privilege creep. Standards: NIST SP 800-53 R5 AC-2(4), ISO 27001 A.5.18, SOX §404 (access review), PCI DSS 4.0 Req 7.2.4.", "es": "Renovación de Roles · renewal. ¿Qué es? Proceso de revisión y renovación explícita de las asignaciones de roles antes de su expiración: 15 días antes de que expire una asignación, el sistema notifica al titular del rol y a su supervisor; si el rol sigue siendo necesario, el supervisor lo renueva con justificación documentada; si no se renueva antes de la fecha de expiración, el rol expira automáticamente sin acción manual. La renovación requiere confirmación activa (\"positive re-certification\") — el silencio equivale a revocación. ¿Para qué sirve? Implementar la certificación periódica de accesos exigida por SOX, ISO 27001 y los marcos de control interno: garantizar que cada rol asignado es revisado por un humano responsable al menos cada N meses, eliminando roles \"zombie\" que nadie recuerda haber asignado. ¿Cómo se usa? El gestor de renovaciones ejecuta un proceso de revisión periódico; genera una lista de asignaciones próximas a expirar; notifica a los supervisores responsables; los supervisores aprueban o dejan expirar cada asignación; el sistema registra en auditoría cada decisión de renovación o expiración con el supervisor responsable. ¿Por qué? El 60% del privilege creep proviene de roles que se asignaron para un proyecto temporal y nunca se revisaron; la renovación activa con expiración automática por inactividad es el control más efectivo para eliminar privilege creep. Normas: NIST SP 800-53 R5 AC-2(4), ISO 27001 A.5.18, SOX §404 (access review), PCI DSS 4.0 Req 7.2.4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.renewal', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'renewal', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f63e-7266-bcc2-075c1cebd6ae', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "SoD Validation", "es": "Validación SoD"}', '{"en": "SoD Validation in Delegation — NIST SP 800-53 R5 AC-5 · ISO 27001 A.5.3", "es": "Validación de Segregación de Funciones — NIST SP 800-53 R5 AC-5 · ISO 27001 A.5.3"}', NULL, '{"en": "Assignment Restrictions · restrictions. What is it? Validation engine for restrictions governing which roles can be assigned to which users under what conditions: separation of duties restrictions (SoD — impossible to assign incompatible roles simultaneously), cardinality restrictions (no more than N users with the SU role simultaneously — NIST AC-2(1)), prerequisite restrictions (to assign BIZ_N3 role the user must already have BIZ_N2 active), tenant restrictions (a role from one tenant cannot be assigned to users from another tenant), and sector restrictions (a HEALTH sector role can only be assigned to a HEALTH sector tenant). What is it for? Ensuring role assignment complies with all defined business and security rules before becoming active: no assignment violates the SoD matrix, the role hierarchy is coherent, and high-sensitivity roles do not proliferate beyond established limits. How is it used? Every role assignment request passes through the restriction engine before execution; the engine evaluates restrictions in priority order; if any restriction fails, the assignment is rejected with a specific explanation of the violated constraint so the requester can correct it. Why? Without restriction validation at the assignment point, role configuration errors can remain active for months until an audit detects them; real-time validation ensures errors are detected and corrected immediately. Standards: NIST SP 800-53 R5 AC-5/AC-6, ANSI INCITS 359-2004 §4.3 (SoD), ISO 27001 A.5.3, NIST SP 800-63B-4 §4.", "es": "Restricciones de Asignación · restrictions. ¿Qué es? Motor de validación de las restricciones que gobiernan qué roles pueden asignarse a qué usuarios bajo qué condiciones: restricciones de separación de funciones (SoD — imposible asignar roles incompatibles simultáneamente), restricciones de cardinality (no más de N usuarios con el rol SU simultáneamente — NIST AC-2(1)), restricciones de prerequisito (para asignar el rol BIZ_N3 el usuario debe tener ya el rol BIZ_N2 activo), restricciones de tenant (un rol de un tenant no puede asignarse a usuarios de otro tenant) y restricciones de sector (un rol del sector SALUD solo puede asignarse a un tenant del sector SALUD). ¿Para qué sirve? Garantizar que la asignación de roles cumple todas las reglas de negocio y seguridad definidas antes de activarse: ninguna asignación viola la matriz SoD, la jerarquía de roles es coherente, y los roles de alta sensibilidad no se proliferan más allá de los límites establecidos. ¿Cómo se usa? Toda solicitud de asignación de rol pasa por el motor de restricciones antes de ser ejecutada; el motor evalúa las restricciones en orden de prioridad; si alguna restricción falla, la asignación es rechazada con una explicación específica del constraint violado para que el solicitante pueda corregirlo. ¿Por qué? Sin validación de restricciones en el punto de asignación, los errores de configuración de roles pueden permanecer activos durante meses hasta que una auditoría los detecte; la validación en tiempo real garantiza que los errores se detectan y corrigen inmediatamente. Normas: NIST SP 800-53 R5 AC-5/AC-6, ANSI INCITS 359-2004 §4.3 (SoD), ISO 27001 A.5.3, NIST SP 800-63B-4 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.restrictions', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'restrictions', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f42b-78e7-a501-64e09b73907b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Extended Attributes", "es": "Atributos Extendidos"}', '{"en": "Extended Attributes — SCIM 2.0 RFC 7643 · ISO/IEC 24760-1:2019", "es": "Atributos Extendidos — SCIM 2.0 RFC 7643 · ISO/IEC 24760-1:2019"}', NULL, '{"en": "Extended Attributes · atributos. What is it? Canonical repository of identity attributes beyond the basic profile: sector-specific data (license number, professional registration), geographic attributes (region, department), verification metadata (IAL achieved, verified document, proofing date), and access classification (clearance level, personnel category). What is it for? Enriching the identity context available to the PDP in ABAC evaluations, enabling decisions based on specific user characteristics beyond the role. How is it used? The PDP reads them as additional context during policy evaluation; updated when the user changes category, region, or verification level via SCIM PATCH or manual provisioning. Why? Modern ABAC/PBAC rules require rich, verified attributes for precise decisions; without them the PDP can only apply static RBAC and cannot discriminate access context. Standards: SCIM 2.0 RFC 7643 §4, ISO/IEC 24760-1:2019 §5, NIST SP 800-162 §4.2, GDPR Art. 4(1).", "es": "Atributos Extendidos · atributos. ¿Qué es? Repositorio canónico de atributos de identidad adicionales al perfil básico: datos sectoriales (número de licencia, matrícula profesional), atributos geográficos (región, departamento), metadatos de verificación (IAL alcanzado, documento verificado, fecha de proofing) y clasificación de acceso (clearance level, categoría de personal). ¿Para qué sirve? Enriquecer el contexto de identidad disponible al PDP en evaluaciones ABAC, permitiendo decisiones basadas en características específicas del usuario más allá del rol. ¿Cómo se usa? El PDP los lee como contexto adicional durante la evaluación de política; se actualizan cuando el usuario cambia de categoría, región o nivel de verificación mediante SCIM PATCH o provisión manual. ¿Por qué? Las reglas ABAC/PBAC modernas requieren atributos ricos y verificados para decisiones precisas; sin ellos el PDP solo aplica RBAC estático y no puede discriminar contexto de acceso. Normas: SCIM 2.0 RFC 7643 §4, ISO/IEC 24760-1:2019 §5, NIST SP 800-162 §4.2, GDPR Art. 4(1)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.atributos', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'atributos', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f53c-79d3-bf88-f0578d409bf9', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "Biometric Sample Quality", "es": "Calidad de Muestra Biométrica"}', '{"en": "Biometric Sample Quality — ISO/IEC 29794-1:2024 §5 · NIST SP 800-76-2 §3", "es": "Calidad de Muestra Biométrica — ISO/IEC 29794-1:2024 §5 · NIST SP 800-76-2 §3"}', NULL, '{"en": "Biometric Sample Quality · quality. What is it? Quality evaluation engine for captured biometric samples before comparison or enrollment: for fingerprint evaluates ridge clarity, area coverage, adequate pressure, and absence of scars masking minutiae; for face evaluates uniform lighting, frontal pose, open eyes, and absence of obstructions; for iris evaluates focus, dilation, and absence of reflections. Generates a numeric quality score and accepts or rejects the sample. What is it for? Ensuring only samples of sufficient quality enter the comparison engine, drastically reducing false rejection rates from low-quality samples captured in adverse conditions. How is it used? Each biometric capture receives an instant quality score; if the score is below the minimum threshold (configurable by trait type and zone), the system requests a new capture with visual feedback to the user on what to improve (reposition finger, improve lighting). Why? 70% of false rejections in biometrics are due to low-quality samples, not engine errors; quality control at capture improves user experience without sacrificing security. Standards: ISO/IEC 29794-1:2024 §5, NIST SP 800-76-2 §3, ISO/IEC 19794-2:2011 §4.", "es": "Calidad de Muestra Biométrica · quality. ¿Qué es? Motor de evaluación de la calidad de las muestras biométricas capturadas antes de la comparación o el enrolamiento: para huella dactilar evalúa nitidez de crestas, cobertura del área, presión adecuada y ausencia de cicatrices que enmascaren minutiae; para cara evalúa iluminación uniforme, pose frontal, ojos abiertos y ausencia de obstrucciones; para iris evalúa foco, dilatación y ausencia de reflejos. Genera un score de calidad numérico y acepta o rechaza la muestra. ¿Para qué sirve? Garantizar que solo muestras de calidad suficiente entran al motor de comparación, reduciendo drásticamente la tasa de falsas rechazos por muestras de baja calidad capturadas en condiciones adversas. ¿Cómo se usa? Cada captura biométrica recibe un score de calidad instantáneo; si el score es menor al umbral mínimo (configurable por tipo de rasgo y zona), el sistema solicita una nueva captura con retroalimentación visual al usuario sobre qué mejorar (reposicionar el dedo, mejorar iluminación). ¿Por qué? El 70% de los falsos rechazos en biometría se deben a muestras de baja calidad, no a errores del motor; el control de calidad en captura mejora la experiencia de usuario sin sacrificar seguridad. Normas: ISO/IEC 29794-1:2024 §5, NIST SP 800-76-2 §3, ISO/IEC 19794-2:2011 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.quality', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'quality', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f66e-72e2-97d6-e82b9e311a59', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Event Capture", "es": "Captura de Eventos"}', '{"en": "Event Capture — ISO 27001 A.8.15 · NIST SP 800-53 R5 AU-2", "es": "Captura de Eventos — ISO 27001 A.8.15 · NIST SP 800-53 R5 AU-2"}', NULL, '{"en": "Security Events · events. What is it? Catalog and generation engine for normalized security events (IoC — Indicators of Compromise, IoA — Indicators of Attack) emitted by the identity plane in CAEP/SET format (Continuous Access Evaluation Protocol / Security Event Tokens — RFC 8417): session revoked, compromised token detected, forced credential change, new device detected, login from new location, privilege escalation detected, and anomalous access pattern. Events are distributed to audit stream subscribers in real time. What is it for? Implementing CAEP (RFC 8935) which enables continuous real-time access evaluation: when bAuth detects a security event, it distributes it to all services with active sessions of the affected user so they can immediately reevaluate access without waiting for token expiration. How is it used? bAuth publishes events to Redis Streams when detecting relevant security state changes; subscriber services (biedata, bkernel, bsearch) consume events and update their cache policies; SIEM (Wazuh) consumes the stream for correlated threat detection. Why? Without CAEP, a token issued with permissions X remains valid during its TTL even if the user''s permissions change to Y; CAEP events enable real-time reevaluation without invalidating all tokens. Standards: RFC 8417 SET, RFC 8935 CAEP, NIST SP 800-53 R5 IR-4, OpenID Shared Signals Framework.", "es": "Eventos de Seguridad · events. ¿Qué es? Catálogo y motor de generación de eventos de seguridad normalizados (IoC — Indicators of Compromise, IoA — Indicators of Attack) emitidos por el plano de identidad en formato CAEP/SET (Continuous Access Evaluation Protocol / Security Event Tokens — RFC 8417): sesión revocada, token comprometido detectado, cambio de credencial forzado, dispositivo nuevo detectado, inicio de sesión desde nueva ubicación, escalada de privilegios detectada, y patrón de acceso anómalo. Los eventos se distribuyen a los suscriptores del stream de auditoría en tiempo real. ¿Para qué sirve? Implementar el CAEP (RFC 8935) que permite la evaluación de acceso continua en tiempo real: cuando bAuth detecta un evento de seguridad, lo distribuye a todos los servicios que tienen sesiones activas del usuario afectado para que puedan reevaluar el acceso inmediatamente sin esperar a la expiración del token. ¿Cómo se usa? bAuth publica eventos en Redis Streams al detectar cambios de estado de seguridad relevantes; los servicios suscriptores (biedata, bkernal, bsearch) consumen los eventos y actualizan sus políticas de caché; el SIEM (Wazuh) consume el stream para la detección de amenazas correlacionadas. ¿Por qué? Sin CAEP, un token emitido con permisos X sigue siendo válido durante su TTL aunque los permisos del usuario cambien a Y; los eventos CAEP permiten la reevaluación en tiempo real sin invalidar todos los tokens. Normas: RFC 8417 SET, RFC 8935 CAEP, NIST SP 800-53 R5 IR-4, OpenID Shared Signals Framework."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.events', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'events', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f494-7ce8-bf19-e54ead789de8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "OSDP Readers", "es": "Lectores OSDP"}', '{"en": "OSDP Readers — SIA OSDP v2.2.2 · IEC 60839-11-5 §6", "es": "Lectores OSDP — SIA OSDP v2.2.2 · IEC 60839-11-5 §6"}', NULL, '{"en": "OSDP Readers · readers. What is it? Lifecycle management of physical credential readers implementing the OSDP v2.2.2 (Open Supervised Device Protocol) with AES-128 secure channel: RFID card readers (HID, DESFire EV3), integrated biometric readers, PIN keypads, and multi-technology readers. OSDP v2.2.2 guarantees encrypted communication between the reader and the control panel, eliminating the Wiegand vulnerability (plaintext protocol). What is it for? Managing the inventory, configuration, health status, and firmware of all deployed physical readers, and ensuring they use secure communication with access control panels. How is it used? Each reader is registered with its OSDP address, associated zone, supported credential technologies, and status (operational, out of service, under maintenance); the system monitors connectivity in real time and alerts on disconnected readers or outdated firmware. Why? A reader with Wiegand protocol (unencrypted) can be intercepted with a $30 device; OSDP v2.2.2 with secure channel eliminates this attack vector in physical access hardware. Standards: SIA OSDP v2.2.2, IEC 60839-11-5 §6, ISO 27001 A.7.2, FIPS 197 (AES-128).", "es": "Lectores OSDP · readers. ¿Qué es? Gestión del ciclo de vida de los lectores de credenciales físicas que implementan el protocolo OSDP v2.2.2 (Open Supervised Device Protocol) con canal seguro AES-128: lectores de tarjeta RFID (HID, DESFire EV3), lectores biométricos integrados, teclados PIN y lectores multi-tecnología. OSDP v2.2.2 garantiza comunicación cifrada entre el lector y el panel de control, eliminando la vulnerabilidad de Wiegand (protocolo en claro). ¿Para qué sirve? Gestionar el inventario, configuración, estado de salud y firmware de todos los lectores físicos desplegados, y garantizar que usan comunicación segura con los paneles de control de acceso. ¿Cómo se usa? Cada lector se registra con su dirección OSDP, zona asociada, tecnologías de credencial soportadas y estado (operativo, fuera de servicio, en mantenimiento); el sistema monitorea la conectividad en tiempo real y alerta ante lectores desconectados o con firmware desactualizado. ¿Por qué? Un lector con protocolo Wiegand (sin cifrar) puede ser interceptado con un dispositivo de $30; OSDP v2.2.2 con canal seguro elimina este vector de ataque en el hardware de acceso físico. Normas: SIA OSDP v2.2.2, IEC 60839-11-5 §6, ISO 27001 A.7.2, FIPS 197 (AES-128)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.readers', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'readers', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6fb-71a6-aa29-18f954756f5c', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Decentralized Identities (DID)", "es": "Identidades Descentralizadas (DID)"}', '{"en": "Decentralized Identities (DID) — W3C DID Core 1.0 §3 · W3C VC Data Model 2.0", "es": "Identidades Descentralizadas (DID) — W3C DID Core 1.0 §3 · W3C VC Data Model 2.0"}', NULL, '{"en": "Decentralized Identity (DID) · did. What is it? Implementation of W3C DID (Decentralized Identifiers) standard to create self-sovereign digital identities: each user or entity in the ecosystem can have a DID (identifier of type `did:besu:0x...`) anchored in the Besu blockchain, with its associated DID document listing public verification keys, supported authentication methods, and service endpoints. DIDs are portable (do not depend on the SBOS provider), verifiable (the blockchain is the public record of truth), and controlled by the owner. What is it for? Providing ecosystem users and entities a portable, self-sovereign digital identity verifiable by any W3C DID-compatible third party without querying the SBOS server: the identity exists on the blockchain, not on the server. How is it used? When registering a user, bAuth can optionally create a DID on Besu and link it to the internal identity; the DID document is published on the blockchain; the user can present their DID as a credential to external systems; external systems verify the DID directly on the blockchain without contacting bAuth. Why? DIDs are the foundation of Self-Sovereign Identity (SSI) giving users control over their identity data independently of the provider; in the SBOS context, it enables interoperability with external ecosystems that accept DIDs. Standards: W3C DID Core Spec v1.0, W3C VC Data Model v2.0, DIF DIDComm, Ethereum EIP-1056.", "es": "Identidad Descentralizada (DID) · did. ¿Qué es? Implementación del estándar W3C DID (Decentralized Identifiers) para crear identidades digitales auto-soberanas: cada usuario o entidad del ecosistema puede tener un DID (identificador del tipo `did:besu:0x...`) anclado en la blockchain Besu, con su documento DID asociado que lista las claves públicas verificación, los métodos de autenticación soportados y los endpoints de servicio. Los DIDs son portables (no dependen del proveedor SBOS), verificables (la blockchain es el registro público de verdad) y controlados por el propietario. ¿Para qué sirve? Proveer a los usuarios y entidades del ecosistema una identidad digital portable y auto-soberana que puede ser verificada por cualquier tercero compatible con W3C DID sin necesidad de consultar al servidor SBOS: la identidad existe en la blockchain, no en el servidor. ¿Cómo se usa? Al registrar un usuario, bAuth puede crear opcionalmente un DID en Besu y vincularlo a la identidad interna; el DID document se publica en la blockchain; el usuario puede presentar su DID como credencial a sistemas externos; los sistemas externos verifican el DID directamente en la blockchain sin contactar a bAuth. ¿Por qué? Los DIDs son la base de la identidad auto-soberana (SSI) que da al usuario control sobre sus datos de identidad independientemente del proveedor; en el contexto SBOS, habilita interoperabilidad con ecosistemas externos que aceptan DIDs. Normas: W3C DID Core Spec v1.0, W3C VC Data Model v2.0, DIF DIDComm, Ethereum EIP-1056."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.did', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'did', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4b1-7013-bffd-6d0430439d43', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Physical Emergency Access", "es": "Acceso de Emergencia Física"}', '{"en": "Physical Emergency Access — NIST SP 800-116 R2 §5.4 · ISO 27001 A.7.3", "es": "Acceso de Emergencia Física — NIST SP 800-116 R2 §5.4 · ISO 27001 A.7.3"}', NULL, '{"en": "Physical Emergency Access · emergency. What is it? Last-resort physical access mechanism for real emergency situations (fire, medical evacuation, total power failure) that allows opening normally locked doors without normal authentication, recording the event with evidence: requester identity (if possible), reason, time, and immediate notification to the security team. Includes modalities: local panel opening, supervised physical master key, and remote opening by authorized operator. What is it for? Ensuring that physical access controls do not become obstacles for emergency evacuation or access by response teams, maintaining security by recording every emergency access event. How is it used? In a declared emergency, the security operator activates emergency mode for affected zones; the system records each opening; when the emergency ends, normal mode resumes with full audit of the emergency period. Why? Physical security cannot block evacuations or access by firefighters or paramedics; emergency access resolves the conflict between security and human life with full traceability. Standards: NIST SP 800-116 R2 §5.4, ISO 27001 A.7.3, NFPA 101:2021 §7.2, IEC 60839-11-5 §7.", "es": "Acceso de Emergencia Física · emergency. ¿Qué es? Mecanismo de acceso físico de último recurso para situaciones de emergencia real (incendio, evacuación médica, fallo total de energía) que permite abrir puertas normalmente bloqueadas sin autenticación normal, registrando el evento con evidencia: identidad del solicitante (si es posible), motivo, hora, y notificación inmediata al equipo de seguridad. Incluye modalidades: apertura por panel local, llave maestra física supervisada y apertura remota por operador autorizado. ¿Para qué sirve? Garantizar que los controles de acceso físico no se conviertan en obstáculos para la evacuación de emergencia o el acceso de equipos de respuesta, manteniendo la seguridad al registrar todo evento de acceso de emergencia. ¿Cómo se usa? Ante una emergencia declarada, el operador de seguridad activa el modo de emergencia para las zonas afectadas; el sistema registra cada apertura; al cesar la emergencia, se vuelve al modo normal con auditoría completa del período de emergencia. ¿Por qué? La seguridad física no puede bloquear evacuaciones ni el acceso de bomberos o paramédicos; el acceso de emergencia resuelve el conflicto entre seguridad y vida humana con trazabilidad total. Normas: NIST SP 800-116 R2 §5.4, ISO 27001 A.7.3, NFPA 101:2021 §7.2, IEC 60839-11-5 §7."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.emergency', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'emergency', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f514-7f17-8dcc-649e9952780e', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Assignment Periods", "es": "Períodos de Asignación"}', '{"en": "Assignment Periods — GTRBAC §4 · PostgreSQL 18 PERIOD · ISO 8601:2019", "es": "Períodos de Asignación — GTRBAC §4 · PostgreSQL 18 PERIOD · ISO 8601:2019"}', NULL, '{"en": "Assignment Periods · periods. What is it? Role assignment validity period management system with native non-overlap restriction support using PostgreSQL 18 PERIOD / WITHOUT OVERLAPS: a role can only be assigned to a user in one time period without overlap with another assignment of the same role. Manages: start date, end date, automatic renewal with prior notification, automatic expiration, and complete history of prior periods. What is it for? Ensuring role assignments have a defined validity and are not permanent by default, forcing periodic review and eliminating indefinitely assigned roles without review. How is it used? When assigning a role, a maximum validity period is mandatorily defined (6 months for BIZ_N1, 3 months for SYS, 30 days for project roles); the system notifies 15 days before expiry; if not explicitly renewed, the role expires automatically. Why? Assignments without a defined period are the origin of privilege creep: roles nobody reviewed because they \"never expire\"; mandatory periods force periodic attention to every assignment. Standards: GTRBAC §4, PostgreSQL 18 PERIOD, ISO 8601:2019, NIST SP 800-53 R5 AC-2(2).", "es": "Períodos de Asignación · periods. ¿Qué es? Sistema de gestión de períodos de validez de asignaciones de roles con soporte nativo de restricciones de no-solapamiento usando PostgreSQL 18 PERIOD / WITHOUT OVERLAPS: un rol solo puede estar asignado a un usuario en un período de tiempo sin solapamiento con otra asignación del mismo rol. Gestiona: fecha de inicio, fecha de fin, renovación automática con notificación previa, expiración automática y historial completo de períodos anteriores. ¿Para qué sirve? Garantizar que las asignaciones de roles tienen una vigencia definida y no son permanentes por defecto, forzando la revisión periódica y eliminando los roles asignados indefinidamente sin revisión. ¿Cómo se usa? Al asignar un rol, se define obligatoriamente un período de validez máximo (6 meses para BIZ_N1, 3 meses para SYS, 30 días para roles de proyecto); el sistema notifica 15 días antes del vencimiento; si no se renueva explícitamente, el rol expira automáticamente. ¿Por qué? Las asignaciones sin período definido son el origen del privilege creep: roles que nadie revisó porque \"nunca vencen\"; los períodos obligatorios fuerzan la atención periódica sobre cada asignación. Normas: GTRBAC §4, PostgreSQL 18 PERIOD, ISO 8601:2019, NIST SP 800-53 R5 AC-2(2)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.periods', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'periods', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5c0-7a22-9598-a94bfbc6a66f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Identity Threat Detection (ITDR)", "es": "Detección de Amenazas de Identidad (ITDR)"}', '{"en": "Identity Threat Detection (ITDR) — NIST SP 800-53 R5 SI-4 · CAEP 1.0 §5", "es": "Detección de Amenazas de Identidad (ITDR) — NIST SP 800-53 R5 SI-4 · CAEP 1.0 §5"}', NULL, '{"en": "Identity Threat Detection and Response (ITDR) · itdr. What is it? Identity control plane-specific threat detection and response engine: detection of Kerberos Golden Ticket and Silver Ticket (forged tokens), Pass-the-Hash and Pass-the-Ticket attacks, unauthorized privilege escalation (a user with BIZ_N1 role suddenly has SYS permissions), account enumeration, mass password reset attacks, and delegation abuse. Correlates signals from multiple sources to detect compound attack patterns. What is it for? Detecting the most sophisticated attacks operating within the identity system itself, not just simple credential attacks: ITDR is the immune system of the identity plane. How is it used? The ITDR engine consumes bAuth''s authentication and authorization event stream in real time; applies correlation rules and behavioral models to detect attack patterns; high-confidence detections trigger automatic response (immediate token revocation, account lockout, SIEM alert); medium-confidence ones generate alerts for human investigation. Why? Identity attacks like Golden Ticket do not generate authentication failures (the token is cryptographically valid), so traditional controls do not detect them; ITDR detects the behavioral anomaly that betrays them. Standards: NIST SP 800-53 R5 IR-4(3), ISO 27001 A.5.25, CIS Controls v8 §17, Gartner ITDR Framework.", "es": "Detección de Amenazas a la Identidad (ITDR) · itdr. ¿Qué es? Motor de detección y respuesta a amenazas específicas del plano de identidad (Identity Threat Detection and Response): detección de Golden Ticket y Silver Ticket de Kerberos (tokens forjados), ataques de Pass-the-Hash y Pass-the-Ticket, escalada de privilegios no autorizada (un usuario con rol BIZ_N1 de repente tiene permisos de SYS), enumeración de cuentas, ataques de reset de contraseña en masa, y abuso de delegación. Correlaciona señales de múltiples fuentes para detectar patrones de ataque compuestos. ¿Para qué sirve? Detectar los ataques más sofisticados que operan dentro del propio sistema de identidad, no solo los ataques de credenciales simples: el ITDR es el sistema inmunológico del plano de identidad. ¿Cómo se usa? El motor ITDR consume el stream de eventos de autenticación y autorización de bAuth en tiempo real; aplica reglas de correlación y modelos de comportamiento para detectar patrones de ataque; las detecciones de alta confianza desencadenan respuesta automática (revocación inmediata de tokens, bloqueo de cuenta, alerta a SIEM); las de media confianza generan alertas para investigación humana. ¿Por qué? Los ataques de identidad como Golden Ticket no generan fallos de autenticación (el token es criptográficamente válido), por lo que los controles tradicionales no los detectan; el ITDR detecta la anomalía de comportamiento que los delata. Normas: NIST SP 800-53 R5 IR-4(3), ISO 27001 A.5.25, CIS Controls v8 §17, Gartner ITDR Framework."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.itdr', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'itdr', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f57a-745c-bb93-7bd6513b7710', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "mTLS / CIDR Connection", "es": "Conexión mTLS / CIDR"}', '{"en": "mTLS / CIDR Connection — RFC 8705 §2 · NIST SP 800-52 R2", "es": "Conexión mTLS / CIDR — RFC 8705 §2 · NIST SP 800-52 R2"}', NULL, '{"en": "Connection State · connection. What is it? Monitor of the user''s current connection state: network type (LAN/WiFi/4G/5G/VPN), signal quality, latency and jitter, transport protocol (TLS 1.3, DTLS), channel encryption (negotiated cipher suite, TLS version, server certificate validity), and TLS session state (active, resumed with ticket, renegotiated). Detects anomalous channel degradations that may indicate a man-in-the-middle attack or a hijacked session. What is it for? Evaluating whether the current connection has the minimum security characteristics required for the attempted operation: high-value operations are only permitted over TLS 1.3 with approved cipher suites; connections with anomalously high latency may indicate an unauthorized intermediate proxy. How is it used? The context engine evaluates connection state on each request; if the channel does not meet the minimum requirements for the requested operation, access is degraded or denied; evaluation is continuous during the session, not only at initial authentication. Why? Real-time connection evaluations are part of the Zero Trust model: trust is continuously revalidated, not only at session start; a channel that degrades during the session is an indicator of ongoing compromise. Standards: NIST SP 800-207 §3.4, RFC 8446 TLS 1.3, NIST SP 800-52 R2, CIS Controls v8 §3.10.", "es": "Estado de Conexión · connection. ¿Qué es? Monitor del estado actual de la conexión del usuario: tipo de red (LAN/WiFi/4G/5G/VPN), calidad de señal, latencia y jitter, protocolo de transporte (TLS 1.3, DTLS), cifrado del canal (suite de cifrado negociada, versión TLS, validez del certificado del servidor) y estado de la sesión TLS (activa, reabierta con ticket, renegociada). Detecta degradaciones anómalas del canal que pueden indicar un ataque de man-in-the-middle o una sesión secuestrada. ¿Para qué sirve? Evaluar si la conexión actual tiene las características de seguridad mínimas requeridas para la operación que se intenta: operaciones de alto valor solo se permiten sobre TLS 1.3 con cipher suites aprobadas; conexiones con latencia anómalamente alta pueden indicar un proxy intermedio no autorizado. ¿Cómo se usa? El motor de contexto evalúa el estado de conexión en cada request; si el canal no cumple los requisitos mínimos de la operación solicitada, el acceso se degrada o deniega; la evaluación es continua durante la sesión, no solo en el momento de autenticación inicial. ¿Por qué? Las evaluaciones de conexión en tiempo real son parte del modelo Zero Trust: la confianza se revalida continuamente, no solo al inicio de la sesión; un canal que se degrada durante la sesión es un indicador de compromiso en curso. Normas: NIST SP 800-207 §3.4, RFC 8446 TLS 1.3, NIST SP 800-52 R2, CIS Controls v8 §3.10."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.connection', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'connection', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f59a-7ecc-8b64-605f0c3a7870', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "Micro-segmentation", "es": "Micro-segmentación"}', '{"en": "Micro-segmentation — NIST SP 800-207 §2.1 · ISO 27001 A.8.22", "es": "Micro-segmentación — NIST SP 800-207 §2.1 · ISO 27001 A.8.22"}', NULL, '{"en": "Network Segmentation · segmentation. What is it? Control of network segmentation policies defining which SBOS ecosystem microservices can communicate with each other and through which channels: bAuth is the only service that can issue tokens; biedata can only receive calls authenticated with a valid bAuth JWT; bkernel has no public endpoint; all daemons communicate exclusively via Unix sockets on the host (ADR-020). Segmentation is the technical implementation of the least privilege model at the network level. What is it for? Ensuring that a compromised microservice cannot move laterally to compromise other microservices or the database directly: segmentation limits the blast radius of a breach to a single service. How is it used? The segmentation matrix is defined in bAuth''s configuration and applied via Kong rules (PEP) and Unix socket restrictions; any communication attempt outside the matrix is rejected with an audit log; segmentation is periodically validated through automated tests. Why? Lateral movement between microservices is the most devastating attack pattern in distributed ecosystems; strict segmentation makes each microservice a sealed compartment limiting damage to the compromised service. Standards: NIST SP 800-207 §3, CIS Controls v8 §12, ISO 27001 A.8.22, SBOS-050 Port Catalog P9.", "es": "Segmentación de Red · segmentation. ¿Qué es? Control de las políticas de segmentación de red que definen qué microservicios del ecosistema SBOS pueden comunicarse entre sí y a través de qué canales: bAuth es el único servicio que puede emitir tokens; biedata solo puede recibir calls autenticadas con JWT válido de bAuth; bkernel no tiene endpoint público; todos los daemons se comunican exclusivamente por Unix sockets en el host (ADR-020). La segmentación es la implementación técnica del modelo de mínimo privilegio a nivel de red. ¿Para qué sirve? Garantizar que un microservicio comprometido no pueda moverse lateralmente para comprometer otros microservicios o la base de datos directamente: la segmentación limita el radio de impacto de una brecha a un único servicio. ¿Cómo se usa? La matriz de segmentación se define en la configuración de bAuth y se aplica mediante reglas de Kong (PEP) y restricciones de socket Unix; cualquier intento de comunicación fuera de la matriz se rechaza con log de auditoría; la segmentación se valida periódicamente mediante pruebas automatizadas. ¿Por qué? El movimiento lateral entre microservicios es el patrón de ataque más devastador en ecosistemas distribuidos; la segmentación estricta convierte cada microservicio en un compartimento estanco que limita el daño al servicio comprometido. Normas: NIST SP 800-207 §3, CIS Controls v8 §12, ISO 27001 A.8.22, SBOS-050 Port Catalog P9."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.segmentation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'segmentation', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5d7-7ee7-ba1f-b7ca8e2c007c', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Password Policy", "es": "Política de Contraseña"}', '{"en": "Password Policy — NIST SP 800-63B-4 §5.1.1 · OWASP ASVS v5 §2.1", "es": "Política de Contraseña — NIST SP 800-63B-4 §5.1.1 · OWASP ASVS v5 §2.1"}', NULL, '{"en": "NIST SP 800-63B Password Policy · password. What is it? Password policy engine compliant with NIST SP 800-63B Rev.4 (2024): minimum 8-character length (no artificial maximum), password verification against compromised password list (HaveIBeenPwned API or local database of 1B+ leaked passwords), trivial password screening (keyboard sequences, dictionary words, service name), Argon2id hashing (m=64MB, t=2, p=4), no arbitrary complexity requirements (no mandatory uppercase+special characters — NIST eliminated these as they increase reuse), and no mandatory periodic rotation except upon demonstrated compromise. What is it for? Implementing the most robust scientifically validated password policy available (NIST SP 800-63B-4 2024), which maximizes real user password entropy by rejecting weak ones, rather than arbitrary complexity policies that generate predictable passwords like \"Password1!\". How is it used? When creating or changing a password, the engine checks: minimum length, absence from the compromised blacklist, absence from the trivial list; if it passes, the password is hashed with Argon2id and stored; the plain-text password is never persisted or logged. Why? Arbitrary complexity policies generate passwords like \"P@ssw0rd1\" that are on every common password list; the NIST policy based on length and compromised screening generates much more real entropy. Standards: NIST SP 800-63B-4 §5.1.1, OWASP ASVS v5.0 §2.1, RFC 9106 Argon2.", "es": "Política de Contraseñas NIST SP 800-63B · password. ¿Qué es? Motor de política de contraseñas conforme al estándar NIST SP 800-63B Rev.4 (2024): longitud mínima 8 caracteres (sin máximo artificial), verificación de contraseña contra lista de contraseñas comprometidas (HaveIBeenPwned API o base local de 1B+ contraseñas filtradas), screening de contraseñas triviales (secuencias de teclado, palabras del diccionario, nombre del servicio), hash con Argon2id (m=64MB, t=2, p=4), sin requisitos de complejidad arbitrarios (sin obligar mayúsculas+especiales — NIST los eliminó por aumentar reutilización), y sin rotación periódica obligatoria salvo compromiso demostrado. ¿Para qué sirve? Implementar la política de contraseñas científicamente validada más robusta disponible (NIST SP 800-63B-4 2024), que maximiza la entropía real de las contraseñas de usuarios rechazando las débiles, en lugar de las políticas de complejidad artificial que generan contraseñas predecibles como \"Password1!\". ¿Cómo se usa? Al crear o cambiar la contraseña, el motor verifica: longitud mínima, ausencia en la lista negra de comprometidas, ausencia en la lista trivial; si pasa, la contraseña se hashea con Argon2id y se almacena; la contraseña en claro nunca se persiste ni se loguea. ¿Por qué? Las políticas de complejidad arbitrarias generan contraseñas como \"P@ssw0rd1\" que están en todas las listas de contraseñas comunes; la política NIST basada en longitud y screening de comprometidas genera mucha más entropía real. Normas: NIST SP 800-63B-4 §5.1.1, OWASP ASVS v5.0 §2.1, RFC 9106 Argon2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.password', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'password', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019fb185-5089-7719-96ea-2b97a5626d9e', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Physical Credential Registry", "es": "Credencial Física Canónica"}', '{"en": "Physical Credential Registry — NIST SP 800-116 R2 §3 · FIPS 201-3", "es": "Credencial Física Canónica — NIST SP 800-116 R2 §3 · FIPS 201-3"}', NULL, '{"en": "Physical Credential Registry · credentials. What is it? Physical-digital convergence catalog that formally links each issued physical credential (proximity badge, FIPS 201-3 PIV card, RFID/NFC token, BLE mobile credential, biometric token) to its digital identity holder (entidad_id) in bAuth. Each credential records its technology, card number, authorized facilities, validity period, and lifecycle status (ACTIVE → SUSPENDED → REVOKED → EXPIRED). What is it for? Solving the fundamental problem of physical access control integrated with IAM: when an OSDP reader reports a card swipe, the system needs to know WHO that person is in digital terms to evaluate their privileges, record the event in the audit trail, and apply logical session policies. Without this catalog, physical and digital access operate in silos without cross-traceability. How is it used? The security administrator issues credentials through the roles template tree (atom D02.credentials.issue, requires AAL3); the system links the physical card number to the entidad_id and defines allowed facilities; when the OSDP reader reports the card number, bAuth resolves it to the corresponding entidad_id to evaluate access and record the event; upon offboarding, the credential is revoked (D02.credentials.revoke) with reason and date recorded. Why? NIST SP 800-116 R2 §3 requires every physical credential to be issued to a specific individual with verified identity and its lifecycle formally managed; FIPS 201-3 requires cryptographic binding for PIV credentials; without this catalog it is impossible to fulfill NIST SP 800-53 R5 AC-19 (access control for mobile systems) and PS-4 (personnel termination — simultaneous physical access revocation with logical offboarding). Standards: NIST SP 800-116 R2 §3, FIPS 201-3, ISO 27001 A.7.2, NIST SP 800-53 R5 AC-19 · PS-4, SIA OSDP v2.2.2, ISO/IEC 24760-2:2025 §7.", "es": "Credencial Física Canónica · credentials. ¿Qué es? Catálogo de convergencia física-digital que vincula formalmente cada credencial física emitida (badge de proximidad, tarjeta PIV FIPS 201-3, token RFID/NFC, credencial móvil BLE, token biométrico) con su titular de identidad digital (entidad_id) en bAuth. Cada credencial registra su tecnología, número de tarjeta, instalaciones autorizadas, período de vigencia y estado del ciclo de vida (ACTIVO → SUSPENDIDO → REVOCADO → EXPIRADO). ¿Para qué sirve? Resolver el problema fundamental del control de acceso físico integrado con IAM: cuando un lector OSDP reporta un swipe de tarjeta, el sistema necesita saber QUIÉN es esa persona en términos digitales para evaluar sus privilegios, registrar el evento en auditoría y aplicar políticas de la sesión lógica. Sin este catálogo, el acceso físico y el digital operan en silos sin trazabilidad cruzada. ¿Cómo se usa? El administrador de seguridad emite credenciales a través del árbol de roles template (átomo D02.credentials.issue, requiere AAL3); el sistema vincula el número de tarjeta física al entidad_id y define las instalaciones permitidas; cuando el lector OSDP reporta el número de tarjeta, bAuth lo resuelve al entidad_id correspondiente para evaluar acceso y registrar evento; al desvincularse el empleado, la credencial se revoca (D02.credentials.revoke) con registro de motivo y fecha. ¿Por qué? NIST SP 800-116 R2 §3 exige que toda credencial física sea emitida a un individuo específico con identidad verificada y su ciclo de vida gestionado formalmente; FIPS 201-3 exige vinculación criptográfica en credenciales PIV; sin este catálogo es imposible cumplir NIST SP 800-53 R5 AC-19 (acceso a sistemas móviles) y PS-4 (terminación de empleo — revocación de acceso físico simultánea al offboarding lógico). Normas: NIST SP 800-116 R2 §3, FIPS 201-3, ISO 27001 A.7.2, NIST SP 800-53 R5 AC-19 · PS-4, SIA OSDP v2.2.2, ISO/IEC 24760-2:2025 §7."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.credentials', true, '1.0', '2026-07-30', NULL, '2026-07-30 05:35:31.975843+00', '2026-07-30 05:35:31.975843+00', 90, 'credentials', 'B09') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6ed-7cdb-89a8-85934031d07f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Merkle Proofs", "es": "Pruebas Merkle"}', '{"en": "Merkle Inclusion Proofs — RFC 6962 §2.1.1 · NIST SP 800-208 §3", "es": "Pruebas de Inclusión Merkle — RFC 6962 §2.1.1 · NIST SP 800-208 §3"}', NULL, '{"en": "Merkle Tree · merkle. What is it? Cryptographic data structure used by the blockchain anchoring engine to generate compact and verifiable summaries of large data sets: given a set of N audit events, the Merkle tree calculates a single root hash (Merkle root) representing the cryptographic fingerprint of the complete set. Any subset of events can be verified against the Merkle root with a Merkle proof of size O(log N) without needing to reveal the other events. What is it for? Enabling efficient integrity verification of audit record subsets: an auditor can verify that a specific event is part of the set anchored on the blockchain without downloading and verifying millions of events from the complete period. How is it used? The Merkle engine receives the list of event hashes for the period; builds the Merkle tree (pairs of hashes to the root); publishes the Merkle root on the blockchain; generates Merkle proofs for specific events on demand; audit reports include the Merkle proof of the relevant event along with the blockchain transaction reference. Why? Without the Merkle tree, blockchain anchoring would require publishing each event''s hash individually, which would be prohibitively expensive in blockchain fees; the Merkle tree condenses millions of events into a single hash with efficiently verifiable proofs. Standards: NIST SP 800-209 §4.3, RFC 6962 Certificate Transparency, Bitcoin Whitepaper §7, W3C VC Data Model §5.", "es": "Árbol de Merkle · merkle. ¿Qué es? Estructura de datos criptográfica usada por el motor de anclaje blockchain para generar resúmenes compactos y verificables de conjuntos grandes de datos: dado un conjunto de N eventos de auditoría, el árbol Merkle calcula un único hash raíz (Merkle root) que representa la huella criptográfica del conjunto completo. Cualquier subconjunto de eventos puede ser verificado contra el Merkle root con una Merkle proof de tamaño O(log N) sin necesidad de revelar los demás eventos. ¿Para qué sirve? Permitir la verificación eficiente de la integridad de subconjuntos de registros de auditoría: un auditor puede verificar que un evento específico forma parte del conjunto anclado en la blockchain sin necesidad de descargar y verificar los millones de eventos del período completo. ¿Cómo se usa? El motor de Merkle recibe la lista de hashes de eventos del período; construye el árbol Merkle (pares de hashes hasta la raíz); publica el Merkle root en la blockchain; genera Merkle proofs para eventos específicos bajo demanda; los informes de auditoría incluyen el Merkle proof del evento relevante junto con la referencia de la transacción blockchain. ¿Por qué? Sin el árbol Merkle, el anclaje blockchain requeriría publicar el hash de cada evento individualmente, lo que sería prohibitivamente costoso en fees de blockchain; el árbol Merkle condensa millones de eventos en un único hash con proofs verificables eficientemente. Normas: NIST SP 800-209 §4.3, RFC 6962 Certificate Transparency, Bitcoin Whitepaper §7, W3C VC Data Model §5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.merkle', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'merkle', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f724-7d76-99df-184136ae82c1', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "CA Certification Chain", "es": "Cadena de Certificación CA"}', '{"en": "CA Certification Chain — RFC 5280 §6 · ETSI EN 319 412", "es": "Cadena de Certificación CA — RFC 5280 §6 · ETSI EN 319 412"}', NULL, '{"en": "Digital Signature Certification · certification. What is it? Engine for obtaining, renewing, and validating digital signature certificates issued by recognized certification authorities for Bolivia: ADSIB certificates (Agency for the Development of the Information Society in Bolivia) for legally valid signatures before the Bolivian state, bAuth private CA certificates for internal ecosystem signing, and cross-trust certificates with internationally recognized CAs (ETSI eIDAS trusted list). Manages the complete lifecycle: request, issuance, renewal, expiration alert renewal, and revocation. What is it for? Providing users who need to sign documents with Bolivian legal validity (Law 164) with certificates issued by the state-recognized certification entity, enabling legal digital signing of contracts, electronic invoices, and public documents. How is it used? The user requests a signature certificate; bAuth initiates the ADSIB application process (prior IAL2, in-person identity verification); ADSIB issues the certificate; bAuth stores it in Vault linked to the user''s identity; signing operations use the ADSIB certificate for documents with external legal effects. Why? Without an ADSIB certificate, digital signatures have no legal validity before third parties in Bolivia; documents signed only with bAuth''s private CA have internal validity but are not recognized by the Bolivian public administration. Standards: Bolivia Law 164 Art. 12, ADSIB-FD-POLT-015 v2.3, RFC 5280, ETSI EN 319 412.", "es": "Certificación de Firma Digital · certification. ¿Qué es? Motor de obtención, renovación y validación de los certificados de firma digital emitidos por autoridades de certificación reconocidas para Bolivia: certificados ADSIB (Agencia para el Desarrollo de la Sociedad de la Información en Bolivia) para firma con validez jurídica ante el Estado boliviano, certificados de CA privada de bAuth para firma interna del ecosistema, y certificados de confianza cruzada con CAs internacionales reconocidas (ETSI eIDAS trusted list). Gestiona el ciclo de vida completo: solicitud, emisión, renovación, renovación por aviso de expiración y revocación. ¿Para qué sirve? Proveer a los usuarios que necesitan firmar documentos con validez jurídica boliviana (Ley 164) los certificados emitidos por la entidad certificadora reconocida por el Estado, habilitando la firma digital legal de contratos, facturas electrónicas y documentos públicos. ¿Cómo se usa? El usuario solicita un certificado de firma; bAuth inicia el proceso de solicitud ante ADSIB (IAL2 previo, verificación de identidad presencial); ADSIB emite el certificado; bAuth lo almacena en Vault vinculado a la identidad del usuario; las operaciones de firma usan el certificado ADSIB para documentos con efectos jurídicos externos. ¿Por qué? Sin certificado ADSIB, la firma digital no tiene validez jurídica ante terceros en Bolivia; los documentos firmados solo con la CA privada de bAuth tienen validez interna pero no son reconocidos por la administración pública boliviana. Normas: Ley 164 Bolivia Art. 12, ADSIB-FD-POLT-015 v2.3, RFC 5280, ETSI EN 319 412."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.certification', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'certification', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f41d-711b-8f5f-cfa1b7da54ea', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Role Entity", "es": "Entidad del Rol"}', '{"en": "Role Entity — ANSI INCITS 359-2004 §3.1 · ISO/IEC 24760-2:2025", "es": "Entidad de Rol — ANSI INCITS 359-2004 §3.1 · ISO/IEC 24760-2:2025"}', NULL, '{"en": "Role Entity · rol_entidad. What is it? Concrete instance of a role assigned to a specific user: actual 64-bit BitMask values, active permissions in the tenant, validity period with temporal restrictions, required assurance level (minimum AAL), applicable SoD constraints, signed change history, and identity of the assignment authorizer. It is the operational materialization of the role template for a specific subject. What is it for? Representing the current state of a user''s privileges in a form evaluable by the PDP engine in less than 0.5ms via AND/OR operations on the BitMask. How is it used? At login the engine builds the user''s BitmaskBundle by consolidating all their active role entities; the bundle is cached in Redis with TTL and is the PDP input for each request. Why? Separating the template (canonical mold) from the entity (instance with real values) allows modifying the template without affecting current assignments until the next recertification. Standards: ANSI INCITS 359-2004 §3.1, ISO/IEC 24760-2:2025 §6, NIST SP 800-53 R5 AC-3, NIST SP 800-162 §4.", "es": "Entidad de Rol · rol_entidad. ¿Qué es? Instancia concreta de un rol asignado a un usuario específico: valores reales del BitMask 64-bit, permisos activos en el tenant, período de validez con restricciones temporales, nivel de garantía requerido (AAL mínimo), restricciones SoD aplicables, historial de cambios firmado e identidad del autorizador de la asignación. Es la materialización operativa de la plantilla de rol para un sujeto concreto. ¿Para qué sirve? Representar el estado actual de privilegios de un usuario en forma evaluable por el motor PDP en menos de 0.5ms mediante operaciones AND/OR sobre el BitMask. ¿Cómo se usa? Al iniciar sesión el motor construye el BitmaskBundle del usuario consolidando todas sus entidades de rol activas; el bundle se cachea en Redis con TTL y es la entrada del PDP para cada request. ¿Por qué? Separar la plantilla (molde canónico) de la entidad (instancia con valores reales) permite modificar el molde sin afectar asignaciones vigentes hasta la próxima recertificación. Normas: ANSI INCITS 359-2004 §3.1, ISO/IEC 24760-2:2025 §6, NIST SP 800-53 R5 AC-3, NIST SP 800-162 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.rol_entidad', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'rol_entidad', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f52f-750f-b69e-f8931aee1706', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "Biometric Enrollment", "es": "Enrolamiento Biométrico"}', '{"en": "Biometric Enrollment — NIST SP 800-76-2 §4 · ISO/IEC 30107-1:2023 §5", "es": "Enrolamiento Biométrico — NIST SP 800-76-2 §4 · ISO/IEC 30107-1:2023 §5"}', NULL, '{"en": "Biometric Enrollment · enrollment. What is it? Controlled process of initial capture and registration of a person''s biometric template: multiple trait samples (fingerprint at 8 angles, bilateral iris, face at 5 poses), quality evaluation of each sample, minutiae or feature extraction, encrypted reference template generation, and secure storage in Vault linked to the user entity. Enrollment includes uniqueness verification (no one else has the same registered template) and presentation attack detection (PAD). What is it for? Capturing a high-quality biometric reference for the user that will be the comparison pattern for all future biometric authentications; enrollment quality directly determines false rejection and false acceptance rates. How is it used? A supervised operator performs enrollment under controlled conditions (lighting, distance, calibrated device); the system validates quality in real time and requests new captures if the threshold is not met; the template is encrypted with the user''s key in Vault before storage. Why? Poor enrollment generates false matches or high rejection rates; 90% of biometric authentication problems originate from low-quality or unsupervised enrollment. Standards: NIST SP 800-76-2 §4, ISO/IEC 30107-1:2023 §5, ISO/IEC 29794-1:2024, ISO/IEC 24745:2022.", "es": "Enrolamiento Biométrico · enrollment. ¿Qué es? Proceso controlado de captura inicial y registro del template biométrico de una persona: múltiples muestras del rasgo (huella en 8 ángulos, iris bilateral, cara en 5 poses), evaluación de calidad de cada muestra, extracción de minutiae o características, generación del template de referencia cifrado y almacenamiento seguro en Vault con vinculación a la entidad de usuario. El enrolamiento incluye verificación de unicidad (nadie más tiene el mismo template registrado) y detección de presentaciones de ataque (PAD). ¿Para qué sirve? Capturar una referencia biométrica de alta calidad del usuario que será el patrón de comparación para todas las autenticaciones biométricas futuras; la calidad del enrolamiento determina directamente la tasa de falsos rechazos y falsas aceptaciones. ¿Cómo se usa? Un operador supervisado realiza el enrolamiento en condiciones controladas (iluminación, distancia, dispositivo calibrado); el sistema valida la calidad en tiempo real y solicita nuevas capturas si no cumple el umbral; el template se cifra con la clave del usuario en Vault antes de almacenarse. ¿Por qué? Un enrolamiento deficiente genera falsas coincidencias o altas tasas de rechazo; el 90% de los problemas de autenticación biométrica tienen origen en un enrolamiento de baja calidad o sin supervisión. Normas: NIST SP 800-76-2 §4, ISO/IEC 30107-1:2023 §5, ISO/IEC 29794-1:2024, ISO/IEC 24745:2022."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.enrollment', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'enrollment', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f54b-7486-b1f7-a0088b51b98f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Geofences", "es": "Geocercas"}', '{"en": "Geofences — RFC 7946 GeoJSON §3.1 · OGC GeoSPARQL 1.1", "es": "Geocercas — RFC 7946 GeoJSON §3.1 · OGC GeoSPARQL 1.1"}', NULL, '{"en": "Security Geofences · geofencing. What is it? Definition and enforcement of virtual geographic perimeters that trigger automatic access control actions when a device or user enters or exits them: entering the main office (corporate geofence) can reduce MFA requirements; leaving the premises automatically blocks access to production systems; entering an airport or border activates enhanced MFA. Geofences are defined as GeoJSON polygons or circles with a radius in meters from a GPS point. What is it for? Dynamically adapting access policies based on the user''s physical location without them having to do anything: the policy adjusts automatically upon detecting entry to or exit from the geofence. How is it used? Geofences are defined in the geospatial configuration panel; actions are associated with entry and exit events of each geofence; the context engine monitors location on mobile devices and applies policy transitions automatically. Why? Geofences enable the \"context-adaptive trust\" principle: more trust when the user is physically in the office, less trust when detected in an unusual or high-risk location. Standards: NIST SP 800-207 §3.2, RFC 7946 GeoJSON, ISO 27001 A.8.22, NIST SP 800-53 R5 AC-17(3).", "es": "Geocercas de Seguridad · geofencing. ¿Qué es? Definición y aplicación de perímetros geográficos virtuales que desencadenan acciones automáticas de control de acceso cuando un dispositivo o usuario entra o sale de ellos: al entrar a la oficina principal (geocerca corporativa) el nivel de MFA puede reducirse; al salir de las instalaciones, el acceso a sistemas de producción se bloquea automáticamente; al entrar a un aeropuerto o frontera, se activa MFA reforzado. Las geocercas se definen como polígonos GeoJSON o círculos con radio en metros desde un punto GPS. ¿Para qué sirve? Adaptar dinámicamente las políticas de acceso según la ubicación física del usuario sin que éste deba hacer nada: la política se ajusta automáticamente al detectar el ingreso o salida de la geocerca. ¿Cómo se usa? Se definen las geocercas en el panel de configuración geoespacial; se asocian acciones a los eventos de entrada y salida de cada geocerca; el motor de contexto monitorea la ubicación en dispositivos móviles y aplica las transiciones de política automáticamente. ¿Por qué? Las geocercas permiten el principio de \"confianza adaptativa según contexto\": más confianza cuando el usuario está físicamente en la oficina, menos confianza al detectar que está en una ubicación inusual o de alto riesgo. Normas: NIST SP 800-207 §3.2, RFC 7946 GeoJSON, ISO 27001 A.8.22, NIST SP 800-53 R5 AC-17(3)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.geofencing', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'geofencing', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6d2-78de-a8fc-d64b893f3bdd', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Wallet Management", "es": "Gestión de Cartera"}', '{"en": "Blockchain Wallet Management — BIP-32/39/44 · EIP-712 · NIST SP 800-208", "es": "Gestión de Cartera Blockchain — BIP-32/39/44 · EIP-712 · NIST SP 800-208"}', NULL, '{"en": "Blockchain Wallet Management · wallet. What is it? SBOS ecosystem blockchain wallet management system: system wallets (for anchoring and governance operations — keys in Vault HSM, never exportable), user wallets (for self-sovereign identity and credential signing — public key in DID, private key custodied in Vault or on the user''s device), and smart contract wallets (address of the governance, anchoring, and DID registry contract). Manages the secure creation, backup, recovery, and destruction of key material. What is it for? Securely custodying the blockchain cryptographic material controlling decentralized identities and ecosystem assets: wallet keys must be accessible for authorized operations but unrecoverable by attackers even with physical server access. How is it used? System keys are generated in Vault HSM and never leave it (signing operations execute inside the HSM); user keys are generated on the user''s device and the private key never reaches the server; smart contracts have no private key (they are code deployed on the blockchain). Why? Blockchain wallet security is absolute: there is no recovery if the private key is lost or compromised without backup; correct HSM custody makes loss recovery possible and attacker compromise impossible. Standards: BIP-32 HD Wallets, EIP-55 Checksum Address, NIST SP 800-53 R5 SC-12, ISO 27001 A.5.17, FIPS 140-3 (HSM).", "es": "Gestión de Cartera (Blockchain Wallet) · wallet. ¿Qué es? Sistema de gestión de wallets blockchain del ecosistema SBOS: wallets de sistema (para operaciones de anclaje y gobernanza — claves en Vault HSM, nunca exportables), wallets de usuario (para identidad auto-soberana y firma de credenciales — clave pública en DID, clave privada custodiada en Vault o en el propio dispositivo del usuario), y wallets de contrato inteligente (dirección del contrato de gobernanza, anclaje y registro de DID). Gestiona la creación, backup, recuperación y destrucción segura de materiales de clave. ¿Para qué sirve? Custodiar de forma segura el material criptográfico blockchain que controla las identidades descentralizadas y los activos del ecosistema: las claves de wallet deben ser accesibles para operaciones autorizadas pero irrecuperables por atacantes incluso con acceso físico a los servidores. ¿Cómo se usa? Las claves de sistema se generan en el HSM de Vault y nunca salen de él (las operaciones de firma se ejecutan dentro del HSM); las claves de usuario se generan en el dispositivo del usuario y la clave privada nunca llega al servidor; los contratos inteligentes no tienen clave privada (son código desplegado en la blockchain). ¿Por qué? La seguridad de una wallet blockchain es absoluta: no existe recuperación si la clave privada se pierde o se compromete sin backup; la custodia correcta en HSM hace la recuperación ante pérdida posible y el compromiso ante atacante imposible. Normas: BIP-32 HD Wallets, EIP-55 Checksum Address, NIST SP 800-53 R5 SC-12, ISO 27001 A.5.17, FIPS 140-3 (HSM)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.wallet', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'wallet', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f619-7e4e-8078-fe17dcf065f4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "FIDO2 Passkeys", "es": "Llaves de Paso FIDO2"}', '{"en": "FIDO2 Passkeys — W3C WebAuthn L3 §6.3 · NIST SP 800-63B-4 §5.2.2", "es": "Claves de Acceso FIDO2 — W3C WebAuthn L3 §6.3 · NIST SP 800-63B-4 §5.2.2"}', NULL, '{"en": "FIDO2 Passkeys · passkey. What is it? Implementation of FIDO2/WebAuthn standard for passwordless authentication using public-private credentials bound to devices: the user registers their device (phone, computer with Windows Hello, or physical FIDO2 key) as an authenticator; on each login, the authenticator signs a challenge with its private key (which never leaves the device) and bAuth verifies the signature with the registered public key. Passkeys can be synced between same-ecosystem devices (iCloud Keychain, Google Password Manager) or device-bound (high-security FIDO2 hardware keys). What is it for? Providing AAL2 or AAL3 authentication without a password, eliminating phishing risk (the authenticator only responds for the exact origin it was registered to), credential stuffing (no password to steal from the database), and dictionary attacks. How is it used? During registration, the user''s FIDO2 authenticator generates the key pair; bAuth stores the public key; on each authentication, bAuth sends a signed challenge with its key; the user''s authenticator responds with the private key signature; bAuth verifies the signature. Why? Passkeys are the NIST SP 800-63B-4 approved password replacement that eliminates the three main password compromise vectors (phishing, reuse, database theft); they are more secure and easier to use. Standards: FIDO2 W3C §6, NIST SP 800-63B-4 §5.1.9, RFC 9700, ISO 27001 A.8.5.", "es": "Llaves de Paso FIDO2 (Passkeys) · passkey. ¿Qué es? Implementación del estándar FIDO2/WebAuthn para autenticación sin contraseña usando credenciales públicas-privadas vinculadas a dispositivos: el usuario registra su dispositivo (teléfono, ordenador con Windows Hello o FIDO2 key física) como autenticador; en cada inicio de sesión, el autenticador firma un desafío con su clave privada (que nunca sale del dispositivo) y bAuth verifica la firma con la clave pública registrada. Las passkeys son sincronizables entre dispositivos del mismo ecosistema (iCloud Keychain, Google Password Manager) o device-bound (FIDO2 hardware keys de alta seguridad). ¿Para qué sirve? Proporcionar autenticación AAL2 o AAL3 sin contraseña, eliminando el riesgo de phishing (el autenticador solo responde para el origen exacto al que fue registrado), credential stuffing (no hay contraseña que robar de la base de datos) y ataques de diccionario. ¿Cómo se usa? Durante el registro, el autenticador FIDO2 del usuario genera el par de claves; bAuth almacena la clave pública; en cada autenticación, bAuth envía un challenge firmado con su clave; el autenticador del usuario responde con la firma de la clave privada; bAuth verifica la firma. ¿Por qué? Las passkeys son el reemplazo de contraseñas aprobado por NIST SP 800-63B-4 que elimina los tres principales vectores de compromiso de contraseñas (phishing, reutilización, robo de base de datos); son más seguras y más fáciles de usar. Normas: FIDO2 W3C §6, NIST SP 800-63B-4 §5.1.9, RFC 9700, ISO 27001 A.8.5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.passkey', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'passkey', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5f4-779c-8631-0ee799d1730e', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Multi-Factor Authentication", "es": "Autenticación Multi-Factor"}', '{"en": "Multi-Factor Authentication — NIST SP 800-63B-4 §5.1 · ISO 27001 A.8.5", "es": "Autenticación Multi-Factor — NIST SP 800-63B-4 §5.1 · ISO 27001 A.8.5"}', NULL, '{"en": "Multi-Factor Authentication (MFA) · mfa. What is it? Orchestrator for bAuth''s 18 supported authentication methods, implementing the stepped authentication flow: the user presents the first factor (something they know: password); if the resource or risk requires it, the second factor is requested (something they have: TOTP, HOTP, push notification); if the resource is AAL3, the third factor is requested (something they are: biometric, FIDO2 hardware key). The orchestrator manages possible authentication paths (if TOTP is unavailable, offer SMS or recovery code) and incremental step-up without full re-authentication. What is it for? Ensuring access to sensitive resources requires the combination of at least two independent factors from different categories, making the compromise of a single factor (leaked password, stolen device) insufficient to authenticate. How is it used? The access evaluator determines the required AAL for the resource; if the current token does not meet the AAL, the MFA orchestrator initiates the step-up flow presenting available factor options for the user; the user completes the additional factor; the token is updated with the new AAL. Why? MFA reduces account compromise risk from stolen passwords or phishing by 99.9%; it is the security control with the highest return on investment in identity management. Standards: NIST SP 800-63B-4 §5, RFC 9470 Step-Up, FIDO2 W3C, ISO 27001 A.8.5.", "es": "Autenticación Multifactor (MFA) · mfa. ¿Qué es? Orquestador de los 18 métodos de autenticación soportados por bAuth, que implementa el flujo de autenticación escalonada: el usuario presenta el primer factor (lo que sabe: contraseña); si el recurso o el riesgo lo exige, se solicita el segundo factor (lo que tiene: TOTP, HOTP, push notification); si el recurso es AAL3, se solicita el tercer factor (lo que es: biométrico, FIDO2 hardware key). El orquestador gestiona las posibles rutas de autenticación (si TOTP no está disponible, ofrecer SMS o código de recuperación) y el step-up incremental sin re-autenticación completa. ¿Para qué sirve? Garantizar que el acceso a recursos sensibles requiere la combinación de al menos dos factores independientes de categorías diferentes, haciendo que el compromiso de un solo factor (contraseña filtrada, dispositivo robado) sea insuficiente para autenticar. ¿Cómo se usa? El evaluador de acceso determina el AAL requerido para el recurso; si el token actual no cumple el AAL, el orquestador MFA inicia el flujo de step-up presentando las opciones de factor disponibles para el usuario; el usuario completa el factor adicional; el token se actualiza con el nuevo AAL. ¿Por qué? El MFA reduce en un 99.9% el riesgo de compromiso de cuenta por contraseñas robadas o phishing; es el control de seguridad individual con mayor retorno de inversión en gestión de identidades. Normas: NIST SP 800-63B-4 §5, RFC 9470 Step-Up, FIDO2 W3C, ISO 27001 A.8.5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.mfa', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'mfa', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f601-78cb-9496-723e09a957db', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Credential Revocation", "es": "Revocación de Credencial"}', '{"en": "Credential Revocation — NIST SP 800-63B-4 §5.2.6 · ISO 27001 A.5.17", "es": "Revocación de Credencial — NIST SP 800-63B-4 §5.2.6 · ISO 27001 A.5.17"}', NULL, '{"en": "Credential Revocation · revocation. What is it? Immediate credential and token revocation engine upon security events: account lockout from excessive failed attempts, revocation by password change (invalidates all active user tokens), administrative revocation (disciplinary suspension, offboarding, security investigation), revocation by compromise detection (the system detects credentials being used by an attacker). Revocation is effective in under 1 second for all active tokens via the Redis revocation list (no waiting for natural JWT expiration). What is it for? Immediately neutralizing access from a compromised or suspended account: with instant revocation, the moment the compromise is detected or the administrative decision is made, the attacker or suspended employee loses access in under 1 second across all devices and active sessions simultaneously. How is it used? When the revocation event fires, bAuth adds the user ID to the Redis revocation list; all ecosystem microservices query Redis before processing a request with the user''s token; if the user is on the list, the request is rejected with 401. Why? JWTs with long TTLs are insecure because they cannot be revoked before natural expiration; the Redis revocation list solves this problem while maintaining efficiency (Redis query has microsecond latency). Standards: RFC 7009 Token Revocation, RFC 6960 OCSP, NIST SP 800-63B-4 §5.6, ISO 27001 A.8.18.", "es": "Revocación de Credenciales · revocation. ¿Qué es? Motor de revocación inmediata de credenciales y tokens ante eventos de seguridad: bloqueo de cuenta por intentos fallidos excesivos, revocación por cambio de contraseña (invalida todos los tokens activos del usuario), revocación administrativa (suspensión disciplinaria, offboarding, investigación de seguridad), revocación por detección de compromiso (el sistema detecta que las credenciales están siendo usadas por un atacante). La revocación es efectiva en menos de 1 segundo para todos los tokens activos mediante la lista de revocación en Redis (no se espera a la expiración natural del JWT). ¿Para qué sirve? Neutralizar inmediatamente el acceso de una cuenta comprometida o suspendida: con la revocación instantánea, en el momento en que se detecta el compromiso o se toma la decisión administrativa, el atacante o el empleado suspendido pierde el acceso en menos de 1 segundo en todos los dispositivos y sesiones activas simultáneamente. ¿Cómo se usa? Al dispararse el evento de revocación, bAuth añade el ID de usuario a la lista de revocación en Redis; todos los microservicios del ecosistema consultan Redis antes de procesar un request con el token del usuario; si el usuario está en la lista, el request es rechazado con 401. ¿Por qué? Los JWTs con TTL largo son inseguros porque no pueden ser revocados antes de su expiración natural; la lista de revocación en Redis resuelve este problema manteniendo la eficiencia (la consulta a Redis tiene latencia de microsegundos). Normas: RFC 7009 Token Revocation, RFC 6960 OCSP, NIST SP 800-63B-4 §5.6, ISO 27001 A.8.18."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.revocation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'revocation', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f443-7250-88f2-38288513189f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Federation Assurance Level", "es": "Nivel de Garantía de Federación"}', '{"en": "Federation Assurance Level — NIST SP 800-63-4 FAL1-3 · SAML 2.0", "es": "Nivel de Garantía de Federación — NIST SP 800-63-4 FAL1-3 · SAML 2.0"}', NULL, '{"en": "Federation Assurance Level · fal. What is it? Trust level assigned to identity assertions from an external federated provider: FAL1 (unencrypted assertion over secure channel), FAL2 (assertion encrypted with subscriber key), FAL3 (assertion cryptographically bound to authenticator hardware). Determines how much bAuth trusts the attributes and AAL declared by an external IdP via SAML 2.0 or OIDC. What is it for? Calibrating trust in third-party assertions and applying additional controls proportional to risk: the higher the FAL, the less additional verification required. How is it used? When receiving a federated token (SAML assertion or OIDC id_token), bAuth evaluates the FAL of the issuing IdP; if it does not meet the access policy minimum, direct re-authentication in bAuth is requested. Why? Without FAL, bAuth cannot distinguish between an assertion backed by hardware MFA and one based only on a password, exposing critical resources to insufficiently verified access. Standards: NIST SP 800-63-4 FAL1-3, SAML 2.0 §8, OpenID Connect Core §3, FICAM Federal Identity Framework.", "es": "Nivel de Garantía de Federación · fal. ¿Qué es? Nivel de confianza asignado a afirmaciones de identidad de un proveedor federado externo: FAL1 (afirmación sin cifrar vía canal seguro), FAL2 (afirmación cifrada con clave del suscriptor), FAL3 (afirmación ligada criptográficamente al hardware del autenticador). Determina cuánto confía bAuth en los atributos y AAL declarados por un IdP externo vía SAML 2.0 u OIDC. ¿Para qué sirve? Calibrar la confianza en afirmaciones de terceros y aplicar controles adicionales proporcionales al riesgo: a mayor FAL, menor verificación adicional requerida. ¿Cómo se usa? Al recibir un token federado (SAML assertion u OIDC id_token), bAuth evalúa el FAL del IdP emisor; si no cumple el mínimo de la política de acceso, solicita re-autenticación directa en bAuth. ¿Por qué? Sin FAL bAuth no puede distinguir entre una afirmación respaldada por MFA de hardware y una de solo contraseña, exponiendo recursos críticos a accesos insuficientemente verificados. Normas: NIST SP 800-63-4 FAL1-3, SAML 2.0 §8, OpenID Connect Core §3, FICAM Federal Identity Framework."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.fal', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 90, 'fal', 'B09') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f67a-79a5-af5d-740934028a9c', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Retention Policy", "es": "Política de Retención"}', '{"en": "Retention Policy — NIST SP 800-53 R5 AU-11 · GDPR Art. 5(e) · SOX §802", "es": "Política de Retención — NIST SP 800-53 R5 AU-11 · GDPR Art. 5(e) · SOX §802"}', NULL, '{"en": "Record Retention · retention. What is it? Audit record retention and disposition policy and engine: retention periods by event type and applicable regulation (7 years for SOX, 5 years for ASFI, 3 years for ordinary operations, 10 years for security events related to incidents), tiered storage (recent events in Redis for fast access, current year events in PostgreSQL, historical events in long-term immutable storage), and controlled disposition (records exceeding the retention period are archived or deleted in an audited manner). What is it for? Guaranteeing compliance with regulatory log retention requirements (SOX requires 7 years of financial audit records accessible within 24 hours) while also preventing indefinite log growth without a defined disposition policy. How is it used? When each event ingests, the engine automatically assigns the retention class based on event type and tenant; the retention manager periodically runs migration of events to the appropriate storage tier based on age; events approaching the disposition date generate a notification for review before deletion if there are related active incidents. Why? Without a retention policy, logs grow indefinitely (operational and cost problem); without retention minimums, the system cannot meet regulatory requirements for historical evidence in audits and litigation. Standards: SOX §802, ISO 27001 A.8.15, NIST SP 800-92 §4, PCI DSS 4.0 Req 10.7.", "es": "Retención de Registros · retention. ¿Qué es? Política y motor de retención y disposición de los registros de auditoría: períodos de retención por tipo de evento y regulación aplicable (7 años para SOX, 5 años para ASFI, 3 años para operaciones ordinarias, 10 años para eventos de seguridad relacionados con incidentes), almacenamiento por capas (eventos recientes en Redis para acceso rápido, eventos del año en PostgreSQL, eventos históricos en almacenamiento inmutable de largo plazo), y disposición controlada (los registros que superan el período de retención se archivan o eliminan de forma auditada). ¿Para qué sirve? Garantizar el cumplimiento de los requisitos regulatorios de retención de logs (SOX exige 7 años de registros de auditoría financiera accesibles en 24 horas) y, al mismo tiempo, evitar el crecimiento indefinido del log sin una política de disposición definida. ¿Cómo se usa? Al ingresar cada evento, el motor asigna automáticamente la clase de retención según el tipo de evento y el tenant; el gestor de retención ejecuta periódicamente la migración de eventos a la capa de almacenamiento apropiada según su antigüedad; los eventos próximos a la fecha de disposición generan notificación para revisión antes de eliminar si hay incidentes activos relacionados. ¿Por qué? Sin política de retención, los logs crecen indefinidamente (problema operativo y de costo); sin mínimos de retención, el sistema no puede cumplir los requerimientos regulatorios de evidencia histórica para auditorías y litigios. Normas: SOX §802, ISO 27001 A.8.15, NIST SP 800-92 §4, PCI DSS 4.0 Req 10.7."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.retention', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'retention', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f711-7631-bd85-8aa87770eda1', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Blockchain) — Hyperledger Besu QBFT · EIP-712", "es": "Registro de Zona de Negocio (Cadena de Bloques) — Hyperledger Besu QBFT · EIP-712"}', NULL, '{"en": "Business Zone Registry (Blockchain) · business_zone. What is it? Container organizing blockchain network interaction modules into controlled access zones: read zone (balance queries, smart contract reading — operational access), write zone (transaction submission, contract deployment — requires multi-signature), wallet administration zone (private key management — strict PAM access, requires HSM), and anchoring zone (audit hash publication — automated with dedicated key). What is it for? Segregating access to different blockchain operation levels, ensuring private transaction signing keys are never accessible from the same zone as data reading, and smart contract deployment requires multi-administrator approval. How is it used? Each blockchain domain module is assigned to its access zone; high-value private keys reside exclusively in the wallet administration zone (backed by Vault HSM); signing operations require the requester to be in the correct zone with appropriate permissions. Why? Blockchain private keys, unlike passwords, directly control assets; a compromised private key can drain a blockchain wallet in seconds with no possibility of reversal; strict zoning minimizes the attack surface on keys. Standards: NIST SP 800-53 R5 SC-12, ISO 27001 A.5.17, CIS Controls v8 §4, ETSI EN 319 401.", "es": "Registro de Zona de Negocio (Blockchain) · business_zone. ¿Qué es? Contenedor que organiza los módulos de interacción con redes blockchain en zonas de acceso controlado: zona de lectura (consulta de saldos, lectura de contratos inteligentes — acceso operativo), zona de escritura (envío de transacciones, despliegue de contratos — requiere firma multifirma), zona de administración de wallets (gestión de claves privadas — acceso PAM estricto, requiere HSM), y zona de anclaje (publicación de hashes de auditoría — automatizado con clave dedicada). ¿Para qué sirve? Segregar el acceso a los diferentes niveles de operación blockchain, garantizando que las claves privadas de firma de transacciones nunca son accesibles desde la misma zona que la lectura de datos, y que el despliegue de contratos inteligentes requiere la aprobación de múltiples administradores. ¿Cómo se usa? Cada módulo del dominio blockchain se asigna a su zona de acceso; las claves privadas de alta valor residen exclusivamente en la zona de administración de wallets (respaldada por HSM de Vault); las operaciones de firma requieren que el solicitante esté en la zona correcta con los permisos adecuados. ¿Por qué? Las claves privadas blockchain, a diferencia de las contraseñas, controlan activos directamente; una clave privada comprometida puede vaciar una wallet blockchain en segundos sin posibilidad de reversión; la zonificación estricta minimiza la superficie de ataque sobre las claves. Normas: NIST SP 800-53 R5 SC-12, ISO 27001 A.5.17, CIS Controls v8 §4, ETSI EN 319 401."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f592-7e2b-861a-f8a3b3595fd4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "Rate Limiting", "es": "Limitación de Velocidad"}', '{"en": "Rate Limiting — OWASP API Security 2023 §6 · RFC 6585 §4", "es": "Limitación de Velocidad — OWASP API Security 2023 §6 · RFC 6585 §4"}', NULL, '{"en": "Rate Limiting · rate. What is it? Request frequency limitation engine to prevent abuse: authentication attempts per user per minute (anti-brute force), API requests per OAuth client per second (anti-application DDoS), enrollment requests per IP per hour (registration anti-spam), and password recovery requests per account per day (anti-enumeration). Implements sliding windows with Redis for precision without overflows on traffic spikes. What is it for? Protecting the authentication service from brute force, credential stuffing, and layer 7 DDoS attacks without degrading the experience of legitimate users: rate limiting is only applied when the normal usage threshold is exceeded. How is it used? Each endpoint type has its own rate limiting policy configured in the network zone; when the limit is exceeded, the request receives HTTP 429 with the Retry-After header indicating when it can retry; persistent exceedances activate progressive blocking and security alerts. Why? Brute force and credential stuffing attacks are the most common account compromise vectors; rate limiting makes them computationally impractical by requiring years to try the necessary combinations at the limited rate. Standards: OWASP ASVS v5.0 §8.1.4, NIST SP 800-63B-4 §5.1.1.2, CIS Controls v8 §4.1, RFC 6585 §4.", "es": "Control de Tasa (Rate Limiting) · rate. ¿Qué es? Motor de limitación de frecuencia de peticiones para prevenir abusos: límite de autenticaciones por usuario por minuto (anti-fuerza bruta), límite de peticiones de API por cliente OAuth por segundo (anti-DDoS capa 7), límite de peticiones de enrolamiento por IP por hora (anti-spam de registro), y límite de peticiones de recuperación de contraseña por cuenta por día (anti-enumeración). Implementa ventanas deslizantes con Redis para precisión sin desbordamientos en picos de tráfico. ¿Para qué sirve? Proteger el servicio de autenticación de ataques de fuerza bruta, credential stuffing y DDoS de capa 7 sin degradar la experiencia del usuario legítimo: el rate limiting se aplica solo cuando se excede el umbral normal de uso. ¿Cómo se usa? Cada tipo de endpoint tiene su propia política de rate limiting configurada en la zona de red; al exceder el límite, el request recibe HTTP 429 con el header Retry-After indicando cuándo puede reintentar; los excesos persistentes activan bloqueo progresivo y alertas de seguridad. ¿Por qué? Los ataques de fuerza bruta y credential stuffing son los vectores de compromiso de cuenta más comunes; el rate limiting los vuelve computacionalmente impracticables al requerir años para probar las combinaciones necesarias al ritmo limitado. Normas: OWASP ASVS v5.0 §8.1.4, NIST SP 800-63B-4 §5.1.1.2, CIS Controls v8 §4.1, RFC 6585 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.rate', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'rate', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f422-7dcb-bf95-cc042f3257da', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "User Schema", "es": "Esquema del Usuario"}', '{"en": "User Schema — SCIM 2.0 RFC 7643 §4.1 · ISO/IEC 24760-2:2025", "es": "Esquema de Usuario — SCIM 2.0 RFC 7643 §4.1 · ISO/IEC 24760-2:2025"}', NULL, '{"en": "User Schema · usuario_esquema. What is it? Canonical mold defining the mandatory structure for every user: the 16 JSONB blocks of the UserTemplate contract (U01 basic identity, U02 credentials, U03 MFA, U04 roles, U05 extended attributes, U06 consent, U07 proofing, U08 session, U09 audit, U10 delegation, U11 physical access, U12 notifications, U13 preferences, U14 metadata, U15 recovery, U16 digital signature). What is it for? Ensuring all ecosystem users have the same data structure, enabling automatic validation on provisioning, cross-tenant migration, and SCIM synchronization with external systems. How is it used? When provisioning a user (manual, SCIM push, or JIT) the system validates each field against the schema; missing mandatory fields block creation; unknown fields are rejected. Why? Without a canonical schema the identity base fragments with inconsistent structures between tenants, making federated search, synchronization, and cross-tenant audit impossible. Standards: SCIM 2.0 RFC 7643 §4.1, ISO/IEC 24760-2:2025 §6, NIST SP 800-63-4 §5, NIST SP 800-53 R5 AC-2.", "es": "Esquema de Usuario · usuario_esquema. ¿Qué es? Molde canónico que define la estructura obligatoria de todo usuario: los 16 bloques JSONB del contrato UserTemplate (U01 identidad básica, U02 credenciales, U03 MFA, U04 roles, U05 atributos extendidos, U06 consentimiento, U07 proofing, U08 sesión, U09 auditoría, U10 delegación, U11 acceso físico, U12 notificaciones, U13 preferencias, U14 metadata, U15 recuperación, U16 firma digital). ¿Para qué sirve? Garantizar que todos los usuarios del ecosistema tienen la misma estructura de datos, habilitando validación automática en provisión, migración entre tenants y sincronización SCIM con sistemas externos. ¿Cómo se usa? Al provisionar un usuario (manual, SCIM push o JIT) el sistema valida cada campo contra el esquema; campos obligatorios ausentes bloquean la creación; campos desconocidos son rechazados. ¿Por qué? Sin esquema canónico la base de identidad se fragmenta con estructuras inconsistentes entre tenants, haciendo imposible la búsqueda federada, la sincronización y la auditoría cruzada. Normas: SCIM 2.0 RFC 7643 §4.1, ISO/IEC 24760-2:2025 §6, NIST SP 800-63-4 §5, NIST SP 800-53 R5 AC-2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.usuario_esquema', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'usuario_esquema', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f463-72ce-8a2d-a1127bb6ba77', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Role Lifecycle Management", "es": "Gestión del Ciclo de Vida de Roles"}', '{"en": "Role Lifecycle Management — ANSI INCITS 359-2004 §4.3 · ISO 27001 A.5.15", "es": "Gestión del Ciclo de Vida de Roles — ANSI INCITS 359-2004 §4.3 · ISO 27001 A.5.15"}', NULL, '{"en": "Role Lifecycle Management · roles. What is it? Engine controlling the complete lifecycle of a digital role through 7 formal states: DEFINED (template created, not assigned), ACTIVE (assigned and operational), SUSPENDED (temporarily disabled without deletion), UNDER_REVIEW (under recertification), RETIRED (no longer assignable to new users), ARCHIVED (historical, read-only), and DELETED (logical deletion with audit retention). State transitions require approval and generate auditable events. What is it for? Ensuring no role is assigned without passing through formal definition, nor eliminated without leaving historical evidence, fulfilling the principle of complete lifecycle traceability. How is it used? A role administrator defines the template (DEFINED state); an approver authorizes its activation (ACTIVE); periodic recertification can move it to UNDER_REVIEW; gradual retirement passes through SUSPENDED before RETIRED. Why? Without formal lifecycle management, roles accumulate uncontrolled, zombie roles proliferate (active but unused), and demonstrating traceability in an audit becomes impossible. Standards: ANSI INCITS 359-2004 §4.3, ISO 27001 A.5.15, NIST SP 800-53 R5 AC-2, ISO 9001:2015 §8.5.", "es": "Gestión del Ciclo de Vida de Roles · roles. ¿Qué es? Motor que controla el ciclo de vida completo de un rol digital a través de 7 estados formales: DEFINIDO (plantilla creada, no asignado), ACTIVO (asignado y operativo), SUSPENDIDO (temporalmente deshabilitado sin borrar), EN_REVISIÓN (bajo recertificación), RETIRADO (ya no asignable a nuevos usuarios), ARCHIVADO (histórico, solo lectura) y ELIMINADO (borrado lógico con retención de auditoría). Las transiciones entre estados requieren aprobación y generan eventos auditables. ¿Para qué sirve? Garantizar que ningún rol sea asignado sin pasar por definición formal, ni eliminado sin dejar evidencia histórica, cumpliendo el principio de trazabilidad completa del ciclo de vida. ¿Cómo se usa? Un administrador de roles define la plantilla (estado DEFINIDO); un aprobador autoriza su activación (ACTIVO); la recertificación periódica puede moverlo a EN_REVISIÓN; el retiro gradual pasa por SUSPENDIDO antes de RETIRADO. ¿Por qué? Sin gestión formal del ciclo de vida, los roles se acumulan sin control, proliferan los roles zombi (activos pero no usados) y es imposible demostrar trazabilidad ante una auditoría. Normas: ANSI INCITS 359-2004 §4.3, ISO 27001 A.5.15, NIST SP 800-53 R5 AC-2, ISO 9001:2015 §8.5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.roles', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'roles', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f562-7c71-9bb0-0a62894e8e4d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Fleet-Based Access", "es": "Acceso por Flota"}', '{"en": "Fleet-Based Access — ISO 6709:2022 · NIST SP 800-53 R5 AC-3(11)", "es": "Acceso Basado en Flota — ISO 6709:2022 · NIST SP 800-53 R5 AC-3(11)"}', NULL, '{"en": "Fleet Management (Mobile Devices) · fleet. What is it? Centralized inventory and control of mobile devices authorized to access tenant systems: IMEI/UDID/serial number registration, device status (active, suspended, revoked), OS version and patch status, device certificate issued by bAuth, and device historical geolocation. Each device has a cryptographic identity (X.509 certificate issued by bAuth PKI) that uniquely identifies it. What is it for? Ensuring that only registered corporate devices with valid certificates and adequate security posture (up-to-date patches, active disk encryption) can access corporate resources from outside the enterprise network. How is it used? When enrolling a device, bAuth issues a device certificate; at each authentication the device presents this certificate; bAuth verifies the certificate is not revoked, the device has the required health status, and the location is consistent with history. Why? 68% of enterprise data breaches involve unmanaged mobile devices; centralized fleet management eliminates this vector by ensuring only known devices with adequate security posture access resources. Standards: NIST SP 800-124 R2, RFC 5280 §4 (device certificates), ISO 27001 A.8.1, CIS Controls v8 §1.", "es": "Gestión de Flota (Dispositivos Móviles) · fleet. ¿Qué es? Inventario y control centralizado de los dispositivos móviles autorizados para acceder a los sistemas del tenant: registro de IMEI/UDID/número de serie, estado del dispositivo (activo, suspendido, revocado), versión del SO y estado de parches, certificado de dispositivo emitido por bAuth, y geo-localización histórica del dispositivo. Cada dispositivo tiene una identidad criptográfica (certificado X.509 emitido por la PKI de bAuth) que lo identifica de forma única. ¿Para qué sirve? Garantizar que solo dispositivos corporativos registrados, con certificado vigente y estado de seguridad adecuado (parches al día, cifrado de disco activo) pueden acceder a los recursos corporativos desde fuera de la red empresarial. ¿Cómo se usa? Al enrolar un dispositivo, bAuth emite un certificado de dispositivo; en cada autenticación el dispositivo presenta este certificado; bAuth verifica que el certificado no está revocado, el dispositivo tiene el estado de salud requerido y la ubicación es consistente con el historial. ¿Por qué? El 68% de las brechas de datos empresariales involucran dispositivos móviles no gestionados; la gestión centralizada de flota elimina este vector garantizando que solo dispositivos conocidos y con postura de seguridad adecuada acceden a los recursos. Normas: NIST SP 800-124 R2, RFC 5280 §4 (certificados dispositivo), ISO 27001 A.8.1, CIS Controls v8 §1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.fleet', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'fleet', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5ae-7849-bcd0-9dabe9f7aac0', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Continuous Risk Score", "es": "Puntuación de Riesgo Continuo"}', '{"en": "Continuous Risk Score — NIST SP 800-207 §3.3 · ISO 27001 A.8.16", "es": "Puntuación de Riesgo Continuo — NIST SP 800-207 §3.3 · ISO 27001 A.8.16"}', NULL, '{"en": "Session Risk Assessment · risk. What is it? Real-time risk scoring engine assigning a risk score (0-100) to each user session based on weighted aggregation of context signals: unusual geographic location (+20), unknown device (+30), out-of-pattern timing (+15), IP on negative reputation list (+40), suspiciously fast navigation speed (+25), and behavioral change from the user''s historical profile (+variable). The score updates on each request during the session, not only at the start. What is it for? Implementing adaptive authorization: the same credentials and roles have different access levels based on session contextual risk; low-risk access (office, known device, regular hours) has full access; high-risk access (foreign country, new device, early morning) has restricted access and requires step-up. How is it used? The risk engine calculates the score at session start and updates it continuously; the score is included in the JWT as a `risk_score` claim; resource policies define maximum score thresholds; if the score exceeds the threshold while the session is active, access is degraded without terminating the session. Why? Binary authorization (has permission or does not) does not reflect the real risk of each session; risk-adaptive authorization protects in high-risk contexts without adding friction to low-risk accesses. Standards: NIST SP 800-207 §3.2, ISO 27001 A.8.16, NIST SP 800-53 R5 IA-2(12), OWASP ASVS v5.0 §4.1.", "es": "Evaluación de Riesgo de Sesión · risk. ¿Qué es? Motor de puntuación de riesgo en tiempo real que asigna un score de riesgo (0-100) a cada sesión de usuario basado en la agregación ponderada de señales de contexto: ubicación geográfica inusual (+20), dispositivo desconocido (+30), horario fuera de patrón habitual (+15), IP en lista de reputación negativa (+40), velocidad de navegación sospechosamente alta (+25), y cambio de comportamiento respecto al perfil histórico del usuario (+variable). El score se actualiza en cada request durante la sesión, no solo al inicio. ¿Para qué sirve? Implementar la autorización adaptativa: las mismas credenciales y roles tienen diferentes niveles de acceso según el riesgo contextual de la sesión; un acceso de bajo riesgo (oficina, dispositivo conocido, horario habitual) tiene acceso completo; un acceso de alto riesgo (país extranjero, dispositivo nuevo, madrugada) tiene acceso restringido y requiere step-up. ¿Cómo se usa? El motor de riesgo calcula el score al inicio de la sesión y lo actualiza continuamente; el score se incluye en el JWT como claim `risk_score`; las políticas de recursos definen umbrales de score máximo; si el score supera el umbral mientras la sesión está activa, el acceso se degrada sin terminar la sesión. ¿Por qué? La autorización binaria (tiene permiso o no tiene permiso) no refleja el riesgo real de cada sesión; la autorización adaptativa por riesgo protege en contextos de alto riesgo sin friccionar los accesos de bajo riesgo. Normas: NIST SP 800-207 §3.2, ISO 27001 A.8.16, NIST SP 800-53 R5 IA-2(12), OWASP ASVS v5.0 §4.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.risk', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'risk', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f736-7709-a3db-a3c529040b11', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "EUDI Wallet (eIDAS 2.0)", "es": "Cartera EUDI (eIDAS 2.0)"}', '{"en": "EUDI Wallet (eIDAS 2.0) — EU 2024/1183 §5a · ARF 1.4", "es": "Cartera de Identidad Digital Europea (eIDAS 2.0) — UE 2024/1183 §5a · ARF 1.4"}', NULL, '{"en": "EUDI Wallet (eIDAS 2.0) · eudi_wallet. What is it? Implementation of the EUDI Wallet (European Digital Identity Wallet — eIDAS 2.0 Regulation) standard defining how citizens and entities can store and present digital verifiable credentials: the EUDI Wallet stores verifiable identity credentials (W3C VC) such as digital national ID, university degrees, professional certificates, and driving licenses in digital format signed by the issuing entity. The user controls which credentials they present to each service without revealing more data than necessary (selective disclosure). What is it for? Enabling identity interoperability with the eIDAS 2.0 European ecosystem and with any system accepting W3C VC verifiable credentials, allowing SBOS users to present their digital credentials to European external services and vice versa. How is it used? The user installs the EUDI Wallet on their device; bAuth can issue verifiable credentials in W3C VC format (e.g., \"active employee of tenant X with role Y\") that the user stores in their wallet; when accessing an external service accepting EUDI, the user presents the credential from their wallet; the service verifies bAuth''s signature on the credential. Why? EUDI Wallet is the EU digital identity standard for 2026+; systems not supporting it will be excluded from interoperability with the European ecosystem; SBOS advances implementation to prepare its tenants. Standards: eIDAS 2.0 Regulation (EU) 2024/1183, ARF EUDI Wallet §3, W3C VC Data Model v2.0, ISO 18013-5 mDL.", "es": "Cartera EUDI (eIDAS 2.0) · eudi_wallet. ¿Qué es? Implementación del estándar EUDI Wallet (European Digital Identity Wallet — eIDAS 2.0 Regulation) que define cómo los ciudadanos y entidades pueden almacenar y presentar credenciales verificables digitales: la EUDI Wallet almacena credenciales de identidad verificables (W3C VC) como el DNI digital, títulos universitarios, certificados profesionales y permisos de conducir en formato digital firmado por la entidad emisora. El usuario controla qué credenciales presenta a cada servicio sin revelar más datos de los necesarios (divulgación selectiva). ¿Para qué sirve? Habilitar la interoperabilidad de identidad con el ecosistema europeo eIDAS 2.0 y con cualquier sistema que acepte credenciales verificables W3C VC, permitiendo a los usuarios de SBOS presentar sus credenciales digitales a servicios externos europeos y viceversa. ¿Cómo se usa? El usuario instala la EUDI Wallet en su dispositivo; bAuth puede emitir credenciales verificables en formato W3C VC (ej: \"empleado activo del tenant X con rol Y\") que el usuario almacena en su wallet; al acceder a un servicio externo que acepta EUDI, el usuario presenta la credencial de su wallet; el servicio verifica la firma de bAuth sobre la credencial. ¿Por qué? La EUDI Wallet es el estándar de identidad digital de la UE para 2026+; los sistemas que no la soportan quedarán excluidos de interoperabilidad con el ecosistema europeo; SBOS adelanta la implementación para preparar a sus tenants. Normas: eIDAS 2.0 Regulation (EU) 2024/1183, ARF EUDI Wallet §3, W3C VC Data Model v2.0, ISO 18013-5 mDL."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.eudi_wallet', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'eudi_wallet', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7a2-7a31-8723-3ae7e3fb20a5', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c96-7b9f-b9bc-e68dff0080fe', 'block', '{"en": "Atom Catalog", "es": "Catálogo de Átomos"}', '{"en": "Atom Catalog — NIST SP 800-162 §4.2 · ISO/IEC 24760-2:2025 §7", "es": "Catálogo de Átomos — NIST SP 800-162 §4.2 · ISO/IEC 24760-2:2025 §7"}', NULL, '{"en": "Enterprise Role Catalog · catalog. What is it? The centralized registry of all SBOS ecosystem role definitions: 368 roles in 7 tiers (SU, SYS, BIZ_N1-N5, EXT_N0, M2M, VISITOR), 66 pre-built base templates for the most common sectors (banking, health, education, government, commerce, manufacturing), 21 SIN CAEB sectors, and 186 inheritance DAG dependency edges. Each catalog entry defines: role name, tier, capability BitMask, SoD restrictions, prerequisites, temporal and geographic restrictions, and the JWT claims template it includes. What is it for? Being the single source of truth for all ecosystem role definitions: any module needing to know what a given role can do queries the catalog; tenants create their roles by instantiating catalog templates, not creating roles from scratch. How is it used? When configuring a new tenant, the administrator selects catalog templates appropriate for the tenant''s sector and instantiates them in the tenant context; the BitMask engine reads the catalog to resolve role inheritance; the SoD validator queries the catalog to verify proposed assignments do not violate restrictions. Why? Without a centralized catalog, each tenant defines its roles independently and roles from similar sectors are inconsistent, incompatible, and difficult to audit; the catalog ensures standardized, well-defined, and auditable roles. Standards: ANSI INCITS 359-2004 §4, NIST SP 800-53 R5 AC-3, ISO 27001 A.5.15, NIST SP 800-162 §4.", "es": "Catálogo de Roles Empresariales · catalog. ¿Qué es? El registro centralizado de todas las definiciones de roles del ecosistema SBOS: 368 roles en 7 tiers (SU, SYS, BIZ_N1-N5, EXT_N0, M2M, VISITANTE), 66 plantillas base pre-construidas para los sectores más comunes (bancario, salud, educación, gobierno, comercio, manufactura), 21 sectores CAEB SIN y 186 aristas de dependencia del DAG de herencia. Cada entrada del catálogo define: nombre del rol, tier, BitMask de capacidades, restricciones SoD, prerequisitos, restricciones temporales y geográficas, y la plantilla de claims que incluye en el JWT. ¿Para qué sirve? Ser la fuente de verdad única para la definición de todos los roles del ecosistema: cualquier módulo que necesite saber qué puede hacer un rol determinado consulta el catálogo; los tenants crean sus roles instanciando las plantillas del catálogo, no creando roles desde cero. ¿Cómo se usa? Al configurar un nuevo tenant, el administrador selecciona las plantillas del catálogo apropiadas para el sector del tenant y las instancia en el contexto del tenant; el motor de BitMask lee el catálogo para resolver la herencia de roles; el validador de SoD consulta el catálogo para verificar que las asignaciones propuestas no violan las restricciones. ¿Por qué? Sin un catálogo centralizado, cada tenant define sus roles de forma independiente y los roles de sectores similares son inconsistentes, incompatibles y difíciles de auditar; el catálogo garantiza roles estandarizados, bien definidos y auditables. Normas: ANSI INCITS 359-2004 §4, NIST SP 800-53 R5 AC-3, ISO 27001 A.5.15, NIST SP 800-162 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D98.catalog', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'catalog', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-7578-a56d-097defc9c40a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Blockchain Anchoring", "es": "Anclaje Blockchain"}', '{"en": "Blockchain Anchoring", "es": "Anclaje en Cadena de Bloques"}', NULL, '{"en": "Blockchain Anchoring · blockchain. What is it? SBOS integration with Hyperledger Besu (private permissioned network with QBFT consensus, ECDSA secp256k1 signatures), anchoring Merkle hashes of critical audit event blocks on the blockchain as independent cryptographic proof of integrity. Manages: on-chain wallets with ECDSA keys in Vault HSM, Besu transactions (creation, signing, submission, confirmation), event Merkle trees (root hash anchored on-chain), Merkle inclusion proofs (proving a specific event exists without revealing the others), and decentralized identities (W3C DID, did:sbos). What is it for? Providing a cryptographic source of truth independent of the SBOS database for audit log integrity, eliminating the argument that the organization could have altered its own records. How is it used? Every N audit events, a Merkle tree is built; the root hash is anchored in Besu as a signed transaction public within the permissioned network; in litigation, the Merkle proof is presented along with the on-chain reference. Why? In legal disputes, evidence stored only in the organization own database is questionable; blockchain anchoring provides independent temporal existence proof verifiable by any party. Standards: W3C DID Core 1.0, W3C VC Data Model 2.0, EIP-712, RFC 6962 (Certificate Transparency), Hyperledger Besu QBFT spec, Bolivia Law 164 Art. 20.", "es": "Anclaje Blockchain · blockchain. ¿Qué es? La integración del SBOS con Hyperledger Besu (red privada permisionada con consenso QBFT, firmas ECDSA secp256k1), que ancla hashes Merkle de bloques de eventos críticos de auditoría en la cadena de bloques como prueba criptográfica independiente de integridad. Gestiona: wallets on-chain con claves ECDSA en Vault HSM, transacciones Besu (creación, firma, envío, confirmación), árboles Merkle de eventos (root hash anclado en cadena), pruebas de inclusión Merkle (demostrar que un evento específico existe sin revelar los demás) e identidades descentralizadas (DID W3C, did:sbos). ¿Para qué sirve? Proveer una fuente de verdad criptográfica independiente de la base de datos del SBOS para la integridad del log de auditoría, eliminando el cuestionamiento de que la organización pudo alterar sus propios registros. ¿Cómo se usa? Cada N eventos de auditoría se construye un árbol Merkle; el root hash se ancla en Besu como transacción firmada y pública dentro de la red permisionada; en un litigio se presenta la prueba Merkle junto con la referencia on-chain. ¿Por qué? En disputas legales, la evidencia guardada solo en la base de datos propia es cuestionable; el anclaje blockchain provee prueba de existencia temporal independiente y verificable por cualquier parte. Normas: W3C DID Core 1.0, W3C VC Data Model 2.0, EIP-712, RFC 6962 (Certificate Transparency), Hyperledger Besu QBFT spec, Ley 164 Bolivia Art. 20."}', '{}', NULL, NULL, NULL, false, NULL, 12, 1, 0, 'skull.D12', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1400, 'blockchain', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f433-736c-ad88-bf9b08928c97', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "Privacy Consent", "es": "Consentimiento de Privacidad"}', '{"en": "Privacy Consent — GDPR Art. 6-7 · ISO/IEC 29184:2020", "es": "Consentimiento de Privacidad — GDPR Art. 6-7 · ISO/IEC 29184:2020"}', NULL, '{"en": "Privacy Consent · consentimiento. What is it? Record of the informed, specific, free, and unambiguous consent of the data subject for each processing purpose: policy text at time of consent (version and SHA-256 hash), purpose, legal basis, grant date, capture channel, source IP, and revocation status. What is it for? Meeting legal consent obligations before processing personal data and demonstrating to any regulator that consent was validly obtained for each declared purpose. How is it used? Before processing personal data the system verifies that valid consent exists for that specific purpose; if revoked or absent, processing is DENY and the reason is recorded in audit. Why? GDPR Art. 7 requires the controller to demonstrate the data subject provided consent; absence of evidence carries fines up to 4% of global business volume. Standards: GDPR Art. 6/7/17, ISO/IEC 29184:2020 §6, NIST SP 800-188 §3, Brazil LGPD Art. 8.", "es": "Consentimiento de Privacidad · consentimiento. ¿Qué es? Registro del consentimiento informado, específico, libre e inequívoco del titular de datos para cada finalidad de tratamiento: texto de la política en el momento del consentimiento (versión y hash SHA-256), propósito, base legal, fecha de otorgamiento, canal de captura, IP de origen y estado de revocación. ¿Para qué sirve? Cumplir obligaciones legales de consentimiento antes de tratar datos personales y demostrar ante cualquier regulador que el consentimiento fue obtenido válidamente para cada finalidad declarada. ¿Cómo se usa? Antes de procesar datos personales el sistema verifica que existe consentimiento vigente para ese propósito específico; si fue revocado o no existe, el tratamiento es DENY y se registra el motivo en auditoría. ¿Por qué? GDPR Art. 7 exige que el responsable pueda demostrar que el interesado prestó consentimiento; la ausencia de evidencia conlleva multas de hasta 4% del volumen de negocio global. Normas: GDPR Art. 6/7/17, ISO/IEC 29184:2020 §6, NIST SP 800-188 §3, LGPD Art. 8 Brasil."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.consentimiento', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'consentimiento', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f46b-7a27-b7a9-bc2de15b434f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Application Zone Enforcement", "es": "Cumplimiento de Zonas de Aplicación"}', '{"en": "Application Zone Enforcement — NIST SP 800-207 §3 · ISO 27001 A.8.2", "es": "Cumplimiento de Zonas de Aplicación — NIST SP 800-207 §3 · ISO 27001 A.8.2"}', NULL, '{"en": "Application Zone Enforcement · zones. What is it? Enforcement engine validating that a role or user operates within the application zones they are authorized for, blocking access attempts to unpermitted zones even if the role''s BitMask would enable it in another zone. An application zone is a logical grouping of resources with shared policies: HR module, accounting module, client portal. What is it for? Adding an isolation layer between system modules that prevents a misconfiguration in one module from exposing data from another module. How is it used? Each request specifies the target zone; the zone engine verifies that the user''s role includes the zone in its authorized zone list; if not, the request is DENY even if the BitMask indicates sufficient permissions. Why? Without zone enforcement, permissions from one module can be unexpectedly used in another; zones implement the domain separation principle at the logical access level. Standards: NIST SP 800-207 §3, ISO 27001 A.8.2, NIST SP 800-53 R5 AC-4, XACML 3.0 §10.", "es": "Cumplimiento de Zonas de Aplicación · zones. ¿Qué es? Motor de enforcement que valida que un rol o usuario opera dentro de las zonas de aplicación a las que está autorizado, bloqueando intentos de acceso a zonas no permitidas incluso si el BitMask del rol lo habilitaría en otra zona. Una zona de aplicación es una agrupación lógica de recursos con políticas compartidas: módulo de RRHH, módulo contable, portal de clientes. ¿Para qué sirve? Añadir una capa de aislamiento entre módulos del sistema que impide que un error de configuración en un módulo exponga datos de otro módulo. ¿Cómo se usa? Cada request indica la zona objetivo; el motor de zonas verifica que el rol del usuario incluye la zona en su lista de zonas autorizadas; si no, el request es DENY aunque el BitMask indique permisos suficientes. ¿Por qué? Sin enforcement de zonas, los permisos de un módulo pueden usarse inesperadamente en otro; las zonas implementan el principio de separación de dominios a nivel de acceso lógico. Normas: NIST SP 800-207 §3, ISO 27001 A.8.2, NIST SP 800-53 R5 AC-4, XACML 3.0 §10."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.zones', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'zones', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4f7-71e6-bf95-edfee93e707f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Fraud Detection", "es": "Detección de Fraude"}', '{"en": "Fraud Detection — PCI DSS 4.0 Req 10.7 · ISO 37001 §8.6", "es": "Detección de Fraude — PCI DSS 4.0 Req 10.7 · ISO 37001 §8.6"}', NULL, '{"en": "Fraud Detection · fraud. What is it? Engine for analyzing anomalous patterns in financial transactions using statistical rules, thresholds, and heuristics: anomalous velocity detection (many transactions in a short time), deviation from the user''s historical profile (unusually large transaction for that profile), suspicious geographic patterns (simultaneous incompatible location transactions), and operation combinations that historically precede fraud. Generates real-time alerts and can preventively block the operation. What is it for? Detecting and blocking fraudulent operations in real or near-real time before the damage is irreversible, reducing financial impact and meeting PCI DSS and ASFI fraud detection requirements. How is it used? Each financial transaction passes through the detection engine before execution; the engine assigns a fraud risk score; if it exceeds the configurable threshold, the transaction is blocked and an alert is generated for manual review. Why? Systems without active fraud detection are preferred targets for internal and external fraud; real-time detection is between 10 and 100 times more effective than post-hoc detection in auditing. Standards: PCI DSS 4.0 Req 10.7, ISO 37001:2016 §8.6, NIST SP 800-53 R5 SI-4, ISO 27001 A.8.16.", "es": "Detección de Fraude · fraud. ¿Qué es? Motor de análisis de patrones anómalos en transacciones financieras usando reglas estadísticas, umbrales y heurísticas: detección de velocidad anómala (muchas transacciones en poco tiempo), desviación del perfil histórico del usuario (transacción inusualmente grande para ese perfil), patrones geográficos sospechosos (transacciones desde ubicaciones simultáneas incompatibles) y combinaciones de operaciones que históricamente preceden fraudes. Genera alertas en tiempo real y puede bloquear la operación preventivamente. ¿Para qué sirve? Detectar y bloquear operaciones fraudulentas en tiempo real o cuasi-real antes de que el daño sea irreversible, reduciendo el impacto financiero y cumpliendo los requisitos de detección de fraude de PCI DSS y la ASFI. ¿Cómo se usa? Cada transacción financiera pasa por el motor de detección antes de ejecutarse; el motor asigna un score de riesgo de fraude; si supera el umbral configurable, la transacción se bloquea y se genera alerta para revisión manual. ¿Por qué? Los sistemas sin detección de fraude activa son objetivos preferentes de fraude interno y externo; la detección en tiempo real es entre 10 y 100 veces más efectiva que la detección post-hoc en auditoría. Normas: PCI DSS 4.0 Req 10.7, ISO 37001:2016 §8.6, NIST SP 800-53 R5 SI-4, ISO 27001 A.8.16."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.fraud', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'fraud', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f573-7ba1-94fd-f7f438edd1f8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Geospatial) — RFC 7946 §3 · ISO 6709:2022", "es": "Registro de Zona de Negocio (Geoespacial) — RFC 7946 §3 · ISO 6709:2022"}', NULL, '{"en": "Business Zone Registry (Geospatial) · business_zone. What is it? Container organizing system operations and resources into geographic zones with location-dependent access restrictions: metropolitan zone (within the tenant''s main city radius), national zone (within Bolivian territory), authorized branch zone (list of enabled GPS coordinates), emergency zone (geographically unrestricted only with approval), and blocked zone (countries or regions from which access is never accepted). What is it for? Applying access controls based on the user''s geographic location at the time of request, limiting access to sensitive systems exclusively from physical locations authorized by the tenant. How is it used? Each sensitive operation is associated with its permitted geographic zone; the access evaluator verifies in real time that the request location (geolocated IP or mobile device GPS) falls within a valid zone; zones are configured as GeoJSON polygons or radii from a central point. Why? Without geographic zoning, stolen credentials can be used from anywhere in the world; with geographic zones, stolen credentials used from a different country are blocked even if all other factors are correct. Standards: NIST SP 800-53 R5 AC-17(3), ISO 27001 A.7.1, RFC 7946 GeoJSON.", "es": "Registro de Zona de Negocio (Geoespacial) · business_zone. ¿Qué es? Contenedor que organiza las operaciones y los recursos del sistema en zonas geográficas con restricciones de acceso dependientes de la ubicación: zona metropolitana (dentro del radio de la ciudad principal del tenant), zona nacional (dentro del territorio boliviano), zona de sucursales autorizadas (lista de coordenadas GPS de sedes habilitadas), zona de emergencia (libre de restricción geográfica solo con aprobación) y zona bloqueada (países o regiones de los que nunca se acepta acceso). ¿Para qué sirve? Aplicar controles de acceso basados en la ubicación geográfica del usuario en el momento de la solicitud, limitando el acceso a sistemas sensibles exclusivamente desde ubicaciones físicas autorizadas por el tenant. ¿Cómo se usa? Cada operación sensitiva se asocia a su zona geográfica permitida; el evaluador de acceso verifica en tiempo real que la ubicación del request (IP geolocalizada o GPS de dispositivo móvil) cae dentro de alguna zona válida; las zonas se configuran como polígonos GeoJSON o radios desde un punto central. ¿Por qué? Sin zonificación geográfica, las credenciales robadas pueden usarse desde cualquier lugar del mundo; con zonas geográficas, una credencial robada usada desde un país diferente es bloqueada aunque los demás factores sean correctos. Normas: NIST SP 800-53 R5 AC-17(3), ISO 27001 A.7.1, RFC 7946 GeoJSON."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'business_zone', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4b4-77a4-ae67-465b05d646f7', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Evacuation & Muster", "es": "Evacuación y Conteo"}', '{"en": "Evacuation & Muster — ISO 27001 A.7.4 · NFPA 101:2021 §7.7", "es": "Evacuación y Conteo — ISO 27001 A.7.4 · NFPA 101:2021 §7.7"}', NULL, '{"en": "Evacuation & Muster · mustering. What is it? Emergency evacuation management system that uses physical access control data to know in real time who is inside each building or zone: list of persons present (based on recorded entries and exits), muster points assigned by zone, personnel count at each muster point, and verification that all occupants have evacuated. What is it for? Ensuring that in an emergency, evacuation officers can objectively confirm with data whether all occupants have exited the facility, without relying on manual roll calls. How is it used? Upon declaring an evacuation, the system generates the list of people who should be in the building based on entry records; evacuation officers at each muster point confirm presence using the mustering app; the system shows in real time who is missing. Why? Without real-time occupancy data, evacuation relies on manual counting, which in large emergencies is slow and imprecise; digital mustering reduces total evacuation confirmation time from minutes to seconds. Standards: ISO 27001 A.7.4, NFPA 101:2021 §7.7, ISO 45001:2018 §8.2 (emergencies), IEC 60839-11-5 §9.", "es": "Evacuación y Conteo · mustering. ¿Qué es? Sistema de gestión de evacuaciones de emergencia que utiliza los datos del control de acceso físico para saber en tiempo real quién está dentro de cada edificio o zona: lista de personas presentes (basada en entradas y salidas registradas), puntos de reunión asignados por zona, conteo de personal en cada punto de reunión y verificación de que todos los presentes han evacuado. ¿Para qué sirve? Garantizar que, en una emergencia, los responsables de evacuación pueden confirmar con datos objetivos si todos los ocupantes han salido de las instalaciones, sin depender de llamados manuales. ¿Cómo se usa? Al declararse una evacuación, el sistema genera la lista de personas que debían estar en el edificio según los registros de entrada; los responsables de evacuación en cada punto de reunión confirman la presencia usando la app de mustering; el sistema muestra en tiempo real quién falta. ¿Por qué? Sin datos de ocupación en tiempo real, la evacuación depende de recuento manual, que en emergencias grandes es lento e impreciso; el mustering digital reduce el tiempo de confirmación de evacuación total de minutos a segundos. Normas: ISO 27001 A.7.4, NFPA 101:2021 §7.7, ISO 45001:2018 §8.2 (emergencias), IEC 60839-11-5 §9."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.mustering', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'mustering', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4ab-773f-892f-7ce7acad8188', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Visitor Access Management", "es": "Gestión de Acceso de Visitantes"}', '{"en": "Visitor Access Management — ISO 27001 A.7.2 · NIST SP 800-116 R2 §5", "es": "Gestión de Acceso de Visitantes — ISO 27001 A.7.2 · NIST SP 800-116 R2 §5"}', NULL, '{"en": "Visitor Access Management · visitors. What is it? Module for registering, approving, and controlling temporary physical access for non-employee persons: visitors, suppliers, external auditors, contractors. Manages: prior registration (name, company, document, reason, host, validity period), temporary credential issuance (badge with RFID programmed for authorized zones during the declared period), mandatory escort in restricted zones, and automatic revocation upon expiry or final exit. What is it for? Controlling and recording third-party access to facilities while maintaining the same audit level as for employees, without giving them access to zones not necessary for their visit. How is it used? The host registers the visit in advance; the visitor identifies themselves at reception with an official document; receives the temporary badge; the system records all their movements through authorized zones; upon exit the badge is automatically deactivated. Why? Unregistered visitors are an uncontrolled physical access vector; formal visitor management closes this gap and provides evidence in security incidents occurring during the visit. Standards: ISO 27001 A.7.2, NIST SP 800-116 R2 §5, ISO 9001:2015 §8.4.3 (external provider control).", "es": "Gestión de Acceso de Visitantes · visitors. ¿Qué es? Módulo de registro, aprobación y control de acceso físico temporal para personas que no son empleados del tenant: visitantes, proveedores, auditores externos, contratistas. Gestiona: registro previo (nombre, empresa, documento, motivo, anfitrión, período de validez), emisión de credencial temporal (badge con RFID programado para las zonas autorizadas durante el período declarado), acompañamiento obligatorio en zonas restringidas y revocación automática al expirar o al salir definitivamente. ¿Para qué sirve? Controlar y registrar el acceso de terceros a las instalaciones manteniendo el mismo nivel de auditoría que para empleados, sin darles acceso a zonas no necesarias para su visita. ¿Cómo se usa? El anfitrión registra la visita con antelación; el visitante se identifica en recepción con documento oficial; recibe el badge temporal; el sistema registra todos sus movimientos por las zonas autorizadas; al salir el badge se desactiva automáticamente. ¿Por qué? Los visitantes sin registro son un vector de acceso físico no controlado; la gestión formal de visitas cierra este gap y proporciona evidencia ante incidentes de seguridad que ocurran durante la visita. Normas: ISO 27001 A.7.2, NIST SP 800-116 R2 §5, ISO 9001:2015 §8.4.3 (control de proveedores externos)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.visitors', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'visitors', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f72c-77c4-b51e-8657ee5dc8d7', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "OCSP / CRL Revocation", "es": "Revocación OCSP / CRL"}', '{"en": "OCSP / CRL Revocation — RFC 6960 §2 · RFC 5280 §5", "es": "Revocación por OCSP / CRL — RFC 6960 §2 · RFC 5280 §5"}', NULL, '{"en": "Digital Certificate Revocation · revocation. What is it? Lifecycle management of digital certificate revocation issued by bAuth: publication of Certificate Revocation List (CRL — RFC 5280) updated periodically, real-time OCSP service (RFC 6960) allowing individual certificate status verification without downloading the entire CRL, and immediate revocation upon key compromise (OCSP revocation reflects in seconds, no need to wait for the next CRL). Standard X.509 revocation reasons are supported: keyCompromise, cACompromise, affiliationChanged, superseded, cessationOfOperation, certificateHold. What is it for? Immediately neutralizing trust in a digital certificate whose private key was compromised or whose holder is no longer authorized: without revocation, an attacker with a stolen private key can continue signing documents with apparent validity for years. How is it used? Upon detecting certificate compromise (holder reports it, ITDR detects it, or holder changes role/exits the organization), bAuth updates the CRL and OCSP status immediately; verifiers querying OCSP receive the revocation response in under 1 second; the next published CRL will include the revoked certificate. Why? A certificate issued by a trusted CA is valid before any system trusting that CA until it expires; revocation is the only mechanism to invalidate it before natural expiration when the key is compromised. Standards: RFC 5280 §5 (CRL), RFC 6960 OCSP, RFC 6818, eIDAS 2.0 Art. 22, ETSI EN 319 411-1.", "es": "Revocación de Certificado Digital · revocation. ¿Qué es? Gestión del ciclo de vida de la revocación de certificados digitales emitidos por bAuth: publicación de Lista de Revocación de Certificados (CRL — RFC 5280) actualizada periódicamente, servicio OCSP en tiempo real (RFC 6960) que permite verificar el estado de un certificado individual sin descargar la CRL completa, y revocación inmediata ante compromiso de clave (la revocación OCSP se refleja en segundos, no hay que esperar la siguiente CRL). Los motivos de revocación estándar X.509 están soportados: keyCompromise, cACompromise, affiliationChanged, superseded, cessationOfOperation, certificateHold. ¿Para qué sirve? Neutralizar inmediatamente la confianza en un certificado digital cuya clave privada fue comprometida o cuyo titular ya no está autorizado: sin revocación, un atacante con la clave privada robada puede continuar firmando documentos con validez aparente durante años. ¿Cómo se usa? Al detectar el compromiso de un certificado (el titular lo reporta, el ITDR lo detecta, o el titular cambia de rol/salida de la organización), bAuth actualiza la CRL y el estado OCSP inmediatamente; los verificadores que consultan OCSP reciben la respuesta de revocación en menos de 1 segundo; la próxima CRL publicada incluirá el certificado revocado. ¿Por qué? Un certificado emitido por una CA confiable es válido ante cualquier sistema que confíe en esa CA hasta que expire; la revocación es el único mecanismo para invalidarlo antes de la expiración natural cuando la clave es comprometida. Normas: RFC 5280 §5 (CRL), RFC 6960 OCSP, RFC 6818, eIDAS 2.0 Art. 22, ETSI EN 319 411-1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.revocation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'revocation', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f72a-7554-bb10-58ab0392d0d3', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "Signature Verification", "es": "Verificación de Firma"}', '{"en": "Digital Signature Verification — ETSI EN 319 102-1 §5 · RFC 5280", "es": "Verificación de Firma Digital — ETSI EN 319 102-1 §5 · RFC 5280"}', NULL, '{"en": "Digital Signature Verification · verification. What is it? Digital signature verification engine validating the authenticity and integrity of signed documents: verifies the cryptographic signature (EdDSA or RSA depending on type), validates that the signer''s certificate was valid at the time of signing (not just now), verifies the certificate was not revoked at the time of signing (historical OCSP or CRL at the time), and validates the trust chain to a trusted root CA. Supports simple, advanced, qualified signatures, and electronic seals. What is it for? Providing complete and standard verification of digital signatures received from any source: SBOS system documents, documents signed by external ADSIB systems, EUDI-signed documents, and W3C VC verifiable credentials. How is it used? The module presents the document and its signature to the verification engine; the engine extracts the signer''s certificate, verifies the cryptographic signature against the certificate''s public key, validates the certificate''s revocation status at the time of signing and the trust chain; returns VALID/INVALID with detail of each verification result and its evidence. Why? Incorrect signature verification (accepting a signature without checking revocation or without validating the complete trust chain) is a critical vulnerability allowing fraudulent documents with apparently valid signatures; the verification engine implements the complete process without skipping steps. Standards: RFC 5280 §6 (path validation), RFC 6960 OCSP, eIDAS 2.0 Art. 37, ETSI EN 319 102-1.", "es": "Verificación de Firma Digital · verification. ¿Qué es? Motor de verificación de firmas digitales que valida la autenticidad e integridad de documentos firmados: verifica la firma criptográfica (EdDSA o RSA según el tipo), valida que el certificado del firmante era válido en el momento de la firma (no solo ahora), verifica que el certificado no estaba revocado en el momento de la firma (OCSP histórico o CRL del momento), y valida la cadena de confianza hasta una CA raíz de confianza. Soporta firmas simples, avanzadas, calificadas y sellos electrónicos. ¿Para qué sirve? Proporcionar una verificación completa y estándar de firmas digitales recibidas de cualquier fuente: documentos del sistema SBOS, documentos firmados por sistemas externos ADSIB, documentos con firmas EUDI, y credenciales verificables W3C VC. ¿Cómo se usa? El módulo presenta el documento y su firma al motor de verificación; el motor extrae el certificado del firmante, verifica la firma criptográfica contra la clave pública del certificado, valida el estado de revocación del certificado en el momento de la firma y la cadena de confianza; retorna VÁLIDA/INVÁLIDA con detalle del resultado de cada verificación y su evidencia. ¿Por qué? La verificación incorrecta de firmas (aceptar una firma sin verificar revocación o sin validar la cadena de confianza completa) es una vulnerabilidad crítica que permite documentos falsos con firma aparentemente válida; el motor de verificación implementa el proceso completo sin omitir pasos. Normas: RFC 5280 §6 (path validation), RFC 6960 OCSP, eIDAS 2.0 Art. 37, ETSI EN 319 102-1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.verification', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'verification', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f43b-7795-92b3-551f14c9dd54', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "W3C Verifiable Credential", "es": "Credencial Verificable W3C"}', '{"en": "W3C Verifiable Credential — W3C VC Data Model 2.0 · ISO/IEC 18013-5:2021", "es": "Credencial Verificable W3C — W3C VC Data Model 2.0 · ISO/IEC 18013-5:2021"}', NULL, '{"en": "W3C Verifiable Credential · verifiable_credential. What is it? Implementation of the W3C Verifiable Credentials Data Model 2.0 standard for issuing, storing, and verifying cryptographically signed digital credentials: academic degrees, professional certifications, verified identity attributes, health credentials. Each VC includes: issuer (DID), subject (DID), verified attributes, issuance and expiration dates, Ed25519 signature, and revocation status queryable without contacting the issuer. What is it for? Enabling attribute evidence presentation without real-time issuer queries and with selective disclosure (the user chooses which attributes to reveal from each VC). How is it used? bAuth (issuer) signs the VC with Ed25519; the user stores it in their EUDI or local wallet; when presenting, the verifier checks the signature and revocation status in a decentralized way. Why? VCs eliminate issuer runtime dependency, reduce personal data exposure to the minimum necessary, and enable interoperability across heterogeneous identity ecosystems. Standards: W3C VC Data Model 2.0, W3C DID Core 1.0, ISO/IEC 18013-5:2021, eIDAS 2.0 Art. 3(55), JSON-LD 1.1.", "es": "Credencial Verificable W3C · verifiable_credential. ¿Qué es? Implementación del estándar W3C Verifiable Credentials Data Model 2.0 para emitir, almacenar y verificar credenciales digitales firmadas criptográficamente: títulos académicos, certificaciones profesionales, atributos de identidad verificados, credenciales de salud. Cada VC incluye: emisor (DID), sujeto (DID), atributos verificados, fechas de emisión y vencimiento, firma Ed25519 y estado de revocación consultable sin contactar al emisor. ¿Para qué sirve? Permitir presentación de evidencia de atributos sin consulta en tiempo real al emisor y con divulgación selectiva (el usuario elige qué atributos revelar de cada VC). ¿Cómo se usa? bAuth (emisor) firma la VC con Ed25519; el usuario la almacena en su wallet EUDI o local; al presentarla, el verificador comprueba la firma y el estado de revocación de forma descentralizada. ¿Por qué? Las VCs eliminan la dependencia del emisor en runtime, reducen la exposición de datos personales al mínimo necesario y permiten interoperabilidad entre ecosistemas de identidad heterogéneos. Normas: W3C VC Data Model 2.0, W3C DID Core 1.0, ISO/IEC 18013-5:2021, eIDAS 2.0 Art. 3(55), JSON-LD 1.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.verifiable_credential', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'verifiable_credential', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f525-7893-8dcc-823b1d6a965e', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Schedule Exceptions", "es": "Excepciones de Horario"}', '{"en": "Schedule Exceptions — NIST SP 800-53 R5 AC-17(1) · ISO 27001 A.5.18", "es": "Excepciones de Horario — NIST SP 800-53 R5 AC-17(1) · ISO 27001 A.5.18"}', NULL, '{"en": "Schedule Exceptions · exceptions. What is it? Management system for exceptions to standard temporal restrictions: when a user needs access outside their normal schedule (night shift, incident response, holiday work), they request an exception with reason, period, approver, and required supervision level. Exceptions are temporary, traced, and require hierarchical approval; recorded as high-priority audit events. What is it for? Maintaining business operability in unforeseen situations without permanently removing temporal controls; exceptions are the formal mechanism to operate outside hours with authorization and complete traceability. How is it used? The user requests the exception specifying period and justification; their supervisor approves it (or escalates if risk is high); the system enables access exclusively for the approved period; upon expiry, restrictions are automatically restored without intervention. Why? Without a formal exception mechanism, users pressure to permanently remove restrictions; with controlled exceptions, controls remain intact and after-hours work is documented and approved. Standards: NIST SP 800-53 R5 AC-17(1), ISO 27001 A.5.18, ISO 9001:2015 §8.5.", "es": "Excepciones de Horario · exceptions. ¿Qué es? Sistema de gestión de excepciones a las restricciones temporales estándar: cuando un usuario necesita acceder fuera de su horario habitual (guardia nocturna, respuesta a incidente, trabajo en feriado), solicita una excepción con motivo, período, aprobador y nivel de supervisión requerido. Las excepciones son temporales, trazadas y requieren aprobación jerárquica; se registran como eventos de auditoría de alta prioridad. ¿Para qué sirve? Mantener la operatividad del negocio ante situaciones imprevistas sin eliminar los controles temporales de forma permanente; las excepciones son el mecanismo formal para operar fuera de horario con autorización y trazabilidad completa. ¿Cómo se usa? El usuario solicita la excepción especificando período y justificación; su supervisor la aprueba (o se escala si el riesgo es alto); el sistema habilita el acceso exclusivamente para el período aprobado; al expirar, las restricciones se restauran automáticamente sin intervención. ¿Por qué? Sin un mecanismo de excepción formal, los usuarios presionan para eliminar restricciones permanentes; con excepciones controladas, los controles se mantienen íntegros y el trabajo fuera de horario queda documentado y aprobado. Normas: NIST SP 800-53 R5 AC-17(1), ISO 27001 A.5.18, ISO 9001:2015 §8.5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.exceptions', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'exceptions', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f745-7cae-b123-ca12dee28fc4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Just-in-Time Access (JIT)", "es": "Acceso Justo a Tiempo (JIT)"}', '{"en": "Just-in-Time Access (JIT) — NIST SP 800-53 R5 AC-6(9) · CIS Controls v8 §5.4", "es": "Acceso Justo a Tiempo (JIT) — NIST SP 800-53 R5 AC-6(9) · CIS Controls v8 §5.4"}', NULL, '{"en": "Just-in-Time Access (JIT) · jit. What is it? Privileged access paradigm where elevated accounts and permissions are granted only for the exact moment they are needed, with minimum possible exposure time: instead of maintaining a permanently active administrator account, the user requests privileged access for a specific task with estimated duration (e.g., \"SSH access to production server DB01 for 30 minutes to apply patch X\"); the system grants access at exactly that moment and automatically revokes it upon expiry. What is it for? Reducing the privilege exposure window to the absolute minimum: a privilege existing only 30 minutes a day has 48 times less exposure than a permanent privilege; JIT converts privileges from \"always available\" to \"available only when needed and justified.\" How is it used? The administrator requests JIT access specifying: the target system, the task to perform, the estimated time, and required approval; the approval workflow completes in seconds for low-risk accesses and minutes for critical ones; access activates exactly at the approved time; expires automatically without user action; the audit log records the request, approval, and complete session. Why? Permanent privileges are the primary lateral movement vector in APT attacks; JIT eliminates the risk of permanent privilege abuse because they simply do not exist outside approved usage windows. Standards: NIST SP 800-53 R5 AC-6(9), CIS Controls v8 §5.4, ISO 27001 A.8.2, PCI DSS 4.0 Req 7.2.", "es": "Acceso Justo a Tiempo (JIT) · jit. ¿Qué es? Paradigma de acceso privilegiado donde las cuentas y permisos elevados se conceden solo para el momento exacto en que se necesitan, con el mínimo tiempo de exposición posible: en lugar de mantener una cuenta de administrador permanentemente activa, el usuario solicita acceso privilegiado para una tarea específica con duración estimada (ej: \"acceso SSH al servidor de producción DB01 durante 30 minutos para aplicar el parche X\"); el sistema concede el acceso exactamente en ese momento y lo revoca automáticamente al expirar. ¿Para qué sirve? Reducir la ventana de exposición de privilegios al mínimo absoluto: un privilegio que existe solo durante 30 minutos al día tiene 48 veces menos exposición que un privilegio permanente; el JIT convierte los privilegios de \"siempre disponibles\" a \"disponibles solo cuando se necesitan y se justifican\". ¿Cómo se usa? El administrador solicita acceso JIT especificando: el sistema objetivo, la tarea a realizar, el tiempo estimado y la aprobación requerida; el workflow de aprobación se completa en segundos para accesos de bajo riesgo y minutos para accesos críticos; el acceso se activa exactamente a la hora aprobada; expira automáticamente sin acción del usuario; el log de auditoría registra la solicitud, la aprobación y la sesión completa. ¿Por qué? Los privilegios permanentes son el principal vector de movimiento lateral en ataques APT; el JIT elimina el riesgo de abuso de privilegios permanentes porque simplemente no existen fuera de las ventanas de uso aprobadas. Normas: NIST SP 800-53 R5 AC-6(9), CIS Controls v8 §5.4, ISO 27001 A.8.2, PCI DSS 4.0 Req 7.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.jit', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'jit', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f50c-7754-80ba-7f9b8cdc7732', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Financial) — COSO 2013 CC6 · PCI DSS 4.0 Req 7", "es": "Registro de Zona de Negocio (Financiero) — COSO 2013 CC6 · PCI DSS 4.0 Req 7"}', NULL, '{"en": "Business Zone Registry (Financial) · business_zone. What is it? Container organizing financial modules and submodules into control zones with their own transactional limits, approval requirements, and SoD restrictions: accounts payable zone, accounts receivable zone, treasury zone, payroll zone, accounting consolidation zone. Each financial zone defines who can initiate, approve, and reconcile operations within it. What is it for? Implementing financial segregation at the zone level: the role that can initiate payments in the AP zone cannot approve or reconcile them, fulfilling the principle of financial responsibility separation. How is it used? Each ERP financial module is mapped to its financial zone in bAuth; zone policies automatically determine applicable controls without needing to configure each operation individually. Why? Without financial zoning, controls must be configured operation by operation; financial zones allow inheriting controls from the container, reducing the risk of uncontrolled operations from configuration omission. Standards: COSO 2013 CC6, PCI DSS 4.0 Req 7, SOX §404, ISO 27001 A.5.3.", "es": "Registro de Zona de Negocio (Financiero) · business_zone. ¿Qué es? Contenedor que organiza los módulos y submódulos financieros en zonas de control con sus propios límites transaccionales, requerimientos de aprobación y restricciones SoD: zona de cuentas por pagar, zona de cuentas por cobrar, zona de tesorería, zona de nómina, zona de consolidación contable. Cada zona financiera define quién puede iniciar, aprobar y conciliar operaciones dentro de ella. ¿Para qué sirve? Implementar la segregación financiera a nivel de zona: el rol que puede iniciar pagos en la zona de CxP no puede aprobarlos ni conciliarlos, cumpliendo el principio de separación de responsabilidades financieras. ¿Cómo se usa? Cada módulo financiero del ERP se mapea a su zona financiera en bAuth; las políticas de la zona determinan automáticamente los controles aplicables sin necesidad de configurar cada operación individualmente. ¿Por qué? Sin zonificación financiera los controles deben configurarse operación por operación; las zonas financieras permiten heredar controles del contenedor, reduciendo el riesgo de operaciones sin control por omisión de configuración. Normas: COSO 2013 CC6, PCI DSS 4.0 Req 7, SOX §404, ISO 27001 A.5.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 90, 'business_zone', 'B09') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f78a-7c6a-9c98-254dadd062d0', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "SPIFFE / SPIRE Attestation", "es": "Atestación SPIFFE / SPIRE"}', '{"en": "SPIFFE / SPIRE Attestation — SPIFFE Spec v1.0 §8 · NIST SP 800-204A §4", "es": "Atestación SPIFFE / SPIRE — SPIFFE Spec v1.0 §8 · NIST SP 800-204A §4"}', NULL, '{"en": "Workload Identity Attestation · attestation. What is it? Cryptographic process verifying the identity of a workload (process, container, pod, serverless function) at startup, before granting credentials: the attestation agent (SPIRE Agent) verifies workload identity using execution environment evidence (binary signature, pod namespace, container labels, TPM boot measurement) and issues an SVID (SPIFFE Verifiable Identity Document — short-lived X.509 certificate) only if the evidence matches the declared identity. What is it for? Ensuring only legitimate workloads, with the correct code in the correct environment, receive identity credentials to communicate with other services: a compromised or modified container fails attestation and receives no credentials, remaining isolated. How is it used? When a workload initializes, the host''s SPIRE Agent evaluates workload evidence (container image digest SHA256, pod ServiceAccount, namespace); if it matches the configured selector for that identity, it issues the SVID; the workload uses the SVID to authenticate via mTLS in its calls to other services; the SVID has a short TTL and is automatically rotated while the workload is active. Why? Workload attestation is the equivalent of \"who are you?\" for processes: without attestation, any process on the host can steal another''s credentials; with attestation, credentials are only issued to the workload that proves it is who it claims to be. Standards: SPIFFE/SPIRE §4 (Attestation), NIST SP 800-207 §3.3, RFC 8555 ACME §6, FIPS 140-3.", "es": "Atestación de Identidad de Carga de Trabajo · attestation. ¿Qué es? Proceso criptográfico de verificación de la identidad de una carga de trabajo (proceso, contenedor, pod, función serverless) en el momento de su arranque, antes de concederle credenciales: el agente de atestación (SPIRE Agent) verifica la identidad de la carga de trabajo usando evidencia del entorno de ejecución (firma del binario, namespace del pod, etiquetas del contenedor, medición del boot TPM) y emite un SVID (SPIFFE Verifiable Identity Document — certificado X.509 de vida corta) solo si la evidencia coincide con la identidad declarada. ¿Para qué sirve? Garantizar que solo las cargas de trabajo legítimas, con el código correcto y en el entorno correcto, reciben credenciales de identidad para comunicarse con otros servicios: un contenedor comprometido o modificado falla la atestación y no recibe credenciales, quedando aislado. ¿Cómo se usa? Al inicializarse una carga de trabajo, el SPIRE Agent del host evalúa la evidencia de la carga (image digest SHA256 del contenedor, ServiceAccount del pod, namespace); si coincide con el selector configurado para esa identidad, emite el SVID; la carga usa el SVID para autenticarse vía mTLS en sus llamadas a otros servicios; el SVID tiene TTL corto y se rota automáticamente mientras la carga esté activa. ¿Por qué? La atestación de carga de trabajo es el equivalente a \"¿quién eres?\" para procesos: sin atestación, cualquier proceso en el host puede robar credenciales de otro; con atestación, las credenciales se emiten solo a la carga que prueba ser quien dice ser. Normas: SPIFFE/SPIRE §4 (Attestation), NIST SP 800-207 §3.3, RFC 8555 ACME §6, FIPS 140-3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.attestation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'attestation', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f59e-70bd-926b-fd5b924342be', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "DPI / DLP Inspection", "es": "Inspección DPI / DLP"}', '{"en": "DPI / DLP Inspection — NIST SP 800-53 R5 SI-3 · ISO 27001 A.8.12", "es": "Inspección DPI / DLP — NIST SP 800-53 R5 SI-3 · ISO 27001 A.8.12"}', NULL, '{"en": "Traffic Inspection (DPI) · inspection. What is it? Deep Packet Inspection engine analyzing network packets in depth to detect malicious patterns in authenticated traffic: data exfiltration (unusually large volume transfers), remote control commands hidden in legitimate traffic, SQL injections or XSS in API requests, and fingerprinting of known attack tools. DPI operates on decrypted traffic after the TLS termination point, maintaining channel privacy with the user. What is it for? Detecting abuse of legitimate sessions: a user with valid credentials attempting to exfiltrate data or execute malicious commands through the API; DPI complements the static BitMask authorization with dynamic analysis of request content. How is it used? Traffic from authenticated sessions passes through the DPI engine after the Kong PEP; detection rules are updated with the latest IOCs (indicators of compromise); detected anomalies generate high-priority alerts and can interrupt the session. Why? Traditional authorization systems only verify whether the user has permission for the endpoint, not the content of what they send; DPI detects attacks operating within the user''s legitimate permissions. Standards: NIST SP 800-53 R5 SI-3(1), ISO 27001 A.8.16, CIS Controls v8 §13.7, OWASP API Security §1.", "es": "Inspección de Tráfico (DPI) · inspection. ¿Qué es? Motor de análisis de paquetes de red en profundidad (Deep Packet Inspection) para detectar patrones maliciosos en el tráfico autenticado: exfiltración de datos (transferencias de volumen inusualmente grande), comandos de control remoto ocultos en tráfico legítimo, inyecciones SQL o XSS en peticiones de API, y fingerprinting de herramientas de ataque conocidas. El DPI opera sobre el tráfico descifrado después del punto de terminación TLS, manteniendo la privacidad del canal con el usuario. ¿Para qué sirve? Detectar el abuso de sesiones legítimas: un usuario con credenciales válidas que intenta exfiltrar datos o ejecutar comandos maliciosos a través de la API; el DPI complementa la autorización estática del BitMask con análisis dinámico del contenido de las peticiones. ¿Cómo se usa? El tráfico de las sesiones autenticadas pasa por el motor DPI después del PEP de Kong; las reglas de detección se actualizan con los IOC (indicadores de compromiso) más recientes; las anomalías detectadas generan alertas de alta prioridad y pueden interrumpir la sesión. ¿Por qué? Los sistemas de autorización tradicionales solo verifican si el usuario tiene permiso para el endpoint, no el contenido de lo que envía; el DPI detecta ataques que operan dentro de los permisos legítimos del usuario. Normas: NIST SP 800-53 R5 SI-3(1), ISO 27001 A.8.16, CIS Controls v8 §13.7, OWASP API Security §1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.inspection', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'inspection', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f73f-7c83-9c94-f817f67d0e95', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Credential Vaulting", "es": "Bóveda de Credenciales"}', '{"en": "Credential Vaulting — NIST SP 800-53 R5 IA-5(7) · CIS Controls v8 §5.3", "es": "Bóveda de Credenciales — NIST SP 800-53 R5 IA-5(7) · CIS Controls v8 §5.3"}', NULL, '{"en": "Credential Vaulting · vaulting. What is it? Centralized storage and management system for privileged secrets (implemented with HashiCorp Vault): service account passwords, server SSH keys, API tokens, database connection strings, private certificates, and any privileged access credential. The vault has fine-grained access control (per-secret policy), complete auditing of every access, automatic secret rotation, and encryption at rest with HSM master key. What is it for? Eliminating insecure storage of privileged credentials in configuration files, environment variables, scripts, and code repositories: centralizing all secrets in the vault with precise access control, automatic rotation, and complete auditing. How is it used? Applications and scripts needing privileged credentials call the Vault API with their service identity (AppRole or SPIFFE SVID); Vault verifies the identity, authorizes access per the secret''s policy, and returns the secret directly to memory (never to disk); the secret has a short TTL and is automatically rotated; access is recorded in Vault''s audit log. Why? 60% of infrastructure breaches originate from hardcoded credentials or credentials stored in plain files; the vault eliminates this vector by being the only place privileged credentials reside, with all access controls and auditing applied. Standards: NIST SP 800-53 R5 AC-3, CIS Controls v8 §16, ISO 27001 A.5.17, FIPS 140-3 (HSM for master key).", "es": "Bóveda de Credenciales (Vaulting) · vaulting. ¿Qué es? Sistema centralizado de almacenamiento y gestión de secretos privilegiados (implementado con HashiCorp Vault): contraseñas de cuentas de servicio, claves SSH de servidores, tokens de API, cadenas de conexión de bases de datos, certificados privados y cualquier credencial de acceso privilegiado. El vault tiene control de acceso de grano fino (política por secreto), auditoría completa de cada acceso, rotación automática de secretos y cifrado en reposo con clave maestra en HSM. ¿Para qué sirve? Eliminar el almacenamiento inseguro de credenciales privilegiadas en archivos de configuración, variables de entorno, scripts y repositorios de código: centralizar todos los secretos en el vault con control de acceso preciso, rotación automática y auditoría completa. ¿Cómo se usa? Las aplicaciones y scripts que necesitan credenciales privilegiadas llaman a la API de Vault con su identidad de servicio (AppRole o SPIFFE SVID); Vault verifica la identidad, autoriza el acceso según la política del secreto, y retorna el secreto directamente en memoria (nunca en disco); el secreto tiene TTL corto y se rota automáticamente; el acceso queda registrado en el log de auditoría del Vault. ¿Por qué? El 60% de las brechas en infraestructura tienen origen en credenciales hardcodeadas o almacenadas en archivos planos; el vault elimina este vector al ser el único lugar donde las credenciales privilegiadas residen, con todos los controles de acceso y auditoría aplicados. Normas: NIST SP 800-53 R5 AC-3, CIS Controls v8 §16, ISO 27001 A.5.17, FIPS 140-3 (HSM para clave maestra)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.vaulting', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'vaulting', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f545-728d-9147-7b24bee38d72', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Biometric) — ISO/IEC 19794-1:2011 · NIST SP 800-76-2", "es": "Registro de Zona de Negocio (Biométrico) — ISO/IEC 19794-1:2011 · NIST SP 800-76-2"}', NULL, '{"en": "Business Zone Registry (Biometric) · business_zone. What is it? Container organizing biometric capture points and resources requiring biometric authentication by security zones: fingerprint access zone (AAL2), iris access zone (AAL3), 1:N identification zone for surveillance, controlled enrollment zone. Each biometric zone defines the accepted trait type, minimum match threshold, and whether liveness detection is required. What is it for? Segregating biometric operations by security level and trait type, ensuring low-quality sensors cannot be used to access zones requiring high-precision sensors. How is it used? Biometric readers are assigned to their zone; the zone defines the minimum comparison parameters required; a fingerprint reading from a low-end sensor may be valid for the attendance control zone but not for the data center zone. Why? Without biometric zoning, the system cannot differentiate sensor quality or zone requirements; the same policy is applied to all readers regardless of their capability. Standards: ISO/IEC 19794-1:2011 §5, NIST SP 800-76-2, ISO/IEC 30107-3:2023 §4.", "es": "Registro de Zona de Negocio (Biométrico) · business_zone. ¿Qué es? Contenedor que organiza los puntos de captura biométrica y los recursos que requieren autenticación biométrica por zonas de seguridad: zona de acceso con huella (AAL2), zona de acceso con iris (AAL3), zona de identificación 1:N para vigilancia, zona de enrollamiento controlado. Cada zona biométrica define el tipo de rasgo aceptado, el umbral mínimo de coincidencia y si se requiere detección de vivacidad. ¿Para qué sirve? Segregar las operaciones biométricas por nivel de seguridad y tipo de rasgo, garantizando que los sensores de baja calidad no puedan ser usados para acceder a zonas que requieren sensores de alta precisión. ¿Cómo se usa? Los lectores biométricos se asignan a su zona; la zona define los parámetros de comparación mínimos exigidos; una lectura de huella de un sensor de gama baja puede ser válida para la zona de control de asistencia pero no para la zona del data center. ¿Por qué? Sin zonificación biométrica, el sistema no puede diferenciar la calidad de los sensores ni los requisitos por zona; se aplica la misma política a todos los lectores independientemente de su capacidad. Normas: ISO/IEC 19794-1:2011 §5, NIST SP 800-76-2, ISO/IEC 30107-3:2023 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f597-77cb-9ecd-fc5781bc5dd6', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "Network Posture", "es": "Postura de Red"}', '{"en": "Network Posture — NIST SP 800-207 §3.3 · CIS Controls v8 §13", "es": "Postura de Red — NIST SP 800-207 §3.3 · CIS Controls v8 §13"}', NULL, '{"en": "Device Security Posture · posture. What is it? Real-time evaluation of the security status of the device from which the user accesses: OS version and security update status, antivirus status (active, updated signatures), active full disk encryption (BitLocker/LUKS), local firewall status, boot integrity (Secure Boot, TPM attestation), and presence of unauthorized high-risk applications (credential extraction tools, RATs). Generates a posture score of 0-100 that influences the access decision. What is it for? Ensuring access to corporate resources is only granted from devices with a minimum acceptable security posture: a compromised device (no antivirus, no encryption, with active malware) cannot access critical resources even if the user has correct credentials. How is it used? The posture agent installed on the device reports its status to bAuth''s posture engine on each access request; the resulting score is combined with network zone policies; below the minimum threshold, access is denied or restricted to low-risk resources. Why? 40% of corporate breaches involve compromised endpoint devices; without posture evaluation, an infected device can be used as a pivot to attack infrastructure even with the user''s legitimate credentials. Standards: NIST SP 800-53 R5 CA-8, NIST SP 800-207 §3.2, CIS Controls v8 §4, FIDO2 §8 (attestation).", "es": "Postura de Seguridad del Dispositivo · posture. ¿Qué es? Evaluación en tiempo real del estado de seguridad del dispositivo desde el que el usuario accede: versión del SO y estado de actualizaciones de seguridad, estado del antivirus (activo, firmas actualizadas), cifrado de disco completo activo (BitLocker/LUKS), estado del firewall local, integridad del boot (Secure Boot, TPM attestation), y presencia de aplicaciones no autorizadas de alto riesgo (herramientas de extracción de credenciales, RATs). Genera un score de postura de 0-100 que influye en la decisión de acceso. ¿Para qué sirve? Garantizar que el acceso a recursos corporativos solo se concede desde dispositivos con una postura de seguridad mínima aceptable: un dispositivo comprometido (sin antivirus, sin cifrado, con malware activo) no puede acceder a recursos críticos aunque el usuario tenga las credenciales correctas. ¿Cómo se usa? El agente de postura instalado en el dispositivo reporta su estado al motor de postura de bAuth en cada solicitud de acceso; el score resultante se combina con las políticas de la zona de red; por debajo del umbral mínimo, el acceso se deniega o se restringe a recursos de bajo riesgo. ¿Por qué? El 40% de las brechas corporativas involucran dispositivos de endpoint comprometidos; sin evaluación de postura, un dispositivo infectado puede ser usado como pivot para atacar la infraestructura incluso con credenciales legítimas del usuario. Normas: NIST SP 800-53 R5 CA-8, NIST SP 800-207 §3.2, CIS Controls v8 §4, FIDO2 §8 (attestation)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.posture', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'posture', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f74f-7edb-8620-7dc46a78391b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Privilege Review", "es": "Revisión de Privilegios"}', '{"en": "Privilege Review — NIST SP 800-53 R5 AC-2(7) · ISO 27001 A.8.2", "es": "Revisión de Privilegios — NIST SP 800-53 R5 AC-2(7) · ISO 27001 A.8.2"}', NULL, '{"en": "Privileged Access Review · review. What is it? Periodic review process for active privileged accounts and permissions in the ecosystem, with greater frequency and rigor than ordinary access review: monthly review of SYS and SU accounts (the most powerful), quarterly review of privileged service accounts and M2M accounts with production access, and immediate review after any privileged access-related security incident. Each reviewed privileged account requires documented business justification and CISO or equivalent approval. What is it for? Ensuring administrative privileges are reviewed with the frequency and scrutiny level their risk requires: a production database administrator privilege deserves more periodic attention than a read permission in a reporting module. How is it used? The PAM review manager generates a monthly list of privileged accounts to review; each account owner must actively certify that the account is still necessary, with the current scope and the correct people; accounts without active certification expire automatically; the CISO receives the review report with modified, revoked accounts and justified exceptions. Why? Privileged accesses have the highest potential impact if abused; more frequent review than ordinary accesses is proportional to the risk: an administrator who should no longer have privileges but retains them by inertia is a high-impact risk. Standards: NIST SP 800-53 R5 AC-2(4), CIS Controls v8 §5.2, ISO 27001 A.8.2, PCI DSS 4.0 Req 7.2.4.", "es": "Revisión de Accesos Privilegiados · review. ¿Qué es? Proceso periódico de revisión de las cuentas y permisos privilegiados activos del ecosistema, con mayor frecuencia y rigor que la revisión de accesos ordinarios: revisión mensual de cuentas SYS y SU (las más poderosas), revisión trimestral de cuentas de servicio privilegiadas y de cuentas M2M con acceso a producción, y revisión inmediata tras cualquier incidente de seguridad relacionado con acceso privilegiado. Cada cuenta privilegiada revisada requiere justificación de negocio documentada y aprobación del CISO o equivalente. ¿Para qué sirve? Garantizar que los privilegios administrativos son revisados con la frecuencia y el nivel de escrutinio que su riesgo requiere: un privilegio de administrador de base de datos de producción merece más atención periódica que un permiso de lectura en un módulo de reporting. ¿Cómo se usa? El gestor de revisión PAM genera mensualmente la lista de cuentas privilegiadas a revisar; cada propietario de cuenta debe certificar activamente que la cuenta sigue siendo necesaria, con el alcance actual y con las personas correctas; las cuentas sin certificación activa expiran automáticamente; el CISO recibe el informe de revisión con las cuentas modificadas, revocadas y las excepciones justificadas. ¿Por qué? Los accesos privilegiados tienen el mayor impacto potencial si son abusados; la revisión más frecuente que los accesos ordinarios es proporcional al riesgo: un administrador que ya no debería tener privilegios pero los mantiene por inercia es un riesgo de alto impacto. Normas: NIST SP 800-53 R5 AC-2(4), CIS Controls v8 §5.2, ISO 27001 A.8.2, PCI DSS 4.0 Req 7.2.4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.review', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'review', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5b2-7e98-be60-8fe26a371ee4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Device Posture", "es": "Postura del Dispositivo"}', '{"en": "Device Posture — NIST SP 800-124 R2 §4 · CIS Controls v8 §4", "es": "Postura del Dispositivo — NIST SP 800-124 R2 §4 · CIS Controls v8 §4"}', NULL, '{"en": "Device Context · device. What is it? Collection and evaluation of attributes of the device from which authentication is performed: unique device identifier (spoof-resistant cryptographic fingerprint), device type (corporate desktop, personal BYOD mobile, M2M server), device trust level (known and managed, known but unmanaged, unknown), device usage history with this account (is it usual for this user?), and device certificate issued by bAuth PKI. What is it for? Incorporating device identity as one of the factors in the Zero Trust model: the same credential presented from a known corporate device has higher trust than from an unknown device, even if all other factors are identical. How is it used? The context engine extracts the device context from the request (TLS client cert, User-Agent, browser fingerprint); combines it with the user''s device registry; generates a device trust score; this score is combined in policy evaluation to determine the required additional MFA level. Why? Device context is the third pillar of the Zero Trust model (user + network + device); without it, the same password has the same access level regardless of whether it comes from a secure corporate device or a cybercafé. Standards: NIST SP 800-207 §3.2, FIDO2 §5 (device attestation), RFC 8705 mTLS, CIS Controls v8 §1.", "es": "Contexto de Dispositivo · device. ¿Qué es? Colección y evaluación de los atributos del dispositivo desde el que se realiza la autenticación: identificador único del dispositivo (fingerprint criptográfico resistente a spoofing), tipo de dispositivo (desktop corporativo, móvil personal BYOD, servidor M2M), nivel de confianza del dispositivo (conocido y gestionado, conocido pero no gestionado, desconocido), historial de uso del dispositivo con esta cuenta (¿es habitual para este usuario?), y certificado de dispositivo emitido por la PKI de bAuth. ¿Para qué sirve? Incorporar la identidad del dispositivo como uno de los factores del modelo Zero Trust: la misma credencial presentada desde un dispositivo corporativo conocido tiene mayor confianza que desde un dispositivo desconocido, aunque los demás factores sean idénticos. ¿Cómo se usa? El motor de contexto extrae el contexto de dispositivo del request (TLS client cert, User-Agent, fingerprint de navegador); lo combina con el registro de dispositivos del usuario; genera un score de confianza de dispositivo; este score se combina en la evaluación de políticas para determinar el nivel de MFA adicional requerido. ¿Por qué? El contexto de dispositivo es el tercer pilar del modelo Zero Trust (usuario + red + dispositivo); sin él, la misma contraseña tiene el mismo nivel de acceso independientemente de si viene de un dispositivo corporativo seguro o de un cibercafé. Normas: NIST SP 800-207 §3.2, FIDO2 §5 (device attestation), RFC 8705 mTLS, CIS Controls v8 §1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.device', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'device', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f482-7642-8797-7b6fd71e7339', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Dynamic ABAC Policy", "es": "Política Dinámica ABAC"}', '{"en": "Dynamic ABAC Policy — NIST SP 800-162 §5 · XACML 3.0 §4", "es": "Política Dinámica ABAC — NIST SP 800-162 §5 · XACML 3.0 §4"}', NULL, '{"en": "Dynamic ABAC Policy · dynamic_policy. What is it? Attribute-Based Access Control (ABAC) policy evaluation engine that combines in real time: subject attributes (role, department, IAL, AAL), resource attributes (classification, owner, sensitivity), environment attributes (time, location, risk score, device posture), and declarative rules in XACML or native format. Unlike pure RBAC, ABAC decisions can vary for the same user depending on the context of each request. What is it for? Implementing contextual and adaptive access policies that static RBAC cannot express: \"doctor X can view patient Y''s record only if they are in hospital Z during shift hours and the session risk score is low.\" How is it used? ABAC rules are defined in the policy catalog; the engine evaluates them in parallel with the RBAC BitMask; the final result is the intersection of both evaluations. Why? Pure RBAC cannot express dynamic contextual conditions; dynamic ABAC reduces role proliferation by capturing conditions in the policy rather than creating a role for each combination. Standards: NIST SP 800-162 §5, XACML 3.0 §4, NIST SP 800-53 R5 AC-3(7), ISO 27001 A.5.15.", "es": "Política Dinámica ABAC · dynamic_policy. ¿Qué es? Motor de evaluación de políticas de control de acceso basado en atributos (ABAC) que combina en tiempo real: atributos del sujeto (rol, departamento, IAL, AAL), atributos del recurso (clasificación, propietario, sensibilidad), atributos del entorno (hora, ubicación, score de riesgo, postura del dispositivo) y reglas declarativas en formato XACML o nativo. A diferencia del RBAC puro, las decisiones ABAC pueden variar para el mismo usuario según el contexto de cada request. ¿Para qué sirve? Implementar políticas de acceso contextuales y adaptativas que el RBAC estático no puede expresar: \"el médico X puede ver el historial del paciente Y solo si está en el hospital Z durante el horario de guardia y el score de riesgo de la sesión es bajo\". ¿Cómo se usa? Las reglas ABAC se definen en el catálogo de políticas; el motor las evalúa en paralelo con el BitMask RBAC; el resultado final es la intersección de ambas evaluaciones. ¿Por qué? El RBAC puro no puede expresar condiciones contextuales dinámicas; el ABAC dinámico reduce la proliferación de roles al capturar condiciones en la política en vez de crear un rol para cada combinación. Normas: NIST SP 800-162 §5, XACML 3.0 §4, NIST SP 800-53 R5 AC-3(7), ISO 27001 A.5.15."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.dynamic_policy', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'dynamic_policy', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f450-7a7b-a79d-3ab1edacb78d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "PDP Policy Evaluation", "es": "Evaluación PDP"}', '{"en": "PDP Policy Evaluation — XACML 3.0 §7 · NIST SP 800-53 R5 AC-3", "es": "Evaluación de Política de Decisión — XACML 3.0 §7 · NIST SP 800-53 R5 AC-3"}', NULL, '{"en": "PDP Policy Evaluation · authorization. What is it? Core of the PDP (Policy Decision Point) engine: evaluates each access request applying NIST RBAC Level 3 with Dual 64-bit BitMask. The evaluation combines: user role BitMask (AND with resource BitMask), active ABAC conditions (time, location, risk, device), and applicable SoD restrictions. Responds PERMIT, DENY, or INDETERMINATE with auditable reason in less than 0.5ms. What is it for? Being the central arbiter of all digital access decisions in the ecosystem, ensuring no access occurs without policy evaluation. How is it used? The PEP (Kong) intercepts each request, builds the authorization message with ctx_id, and sends it to the PDP over the Unix socket; the PDP responds synchronously before Kong forwards or rejects the request. Why? Centralizing the decision in a single PDP guarantees consistency: the same user with the same context always receives the same decision, regardless of which PEP intercepted the request. Standards: XACML 3.0 §7, NIST SP 800-53 R5 AC-3, NIST SP 800-162 §4.2, OWASP ASVS v5 §4.1, ISO 27001 A.5.15.", "es": "Evaluación de Política de Decisión · authorization. ¿Qué es? Núcleo del motor PDP (Policy Decision Point): evalúa cada solicitud de acceso aplicando NIST RBAC Nivel 3 con BitMask Dual 64-bit. La evaluación combina: BitMask del rol del usuario (AND con BitMask del recurso), condiciones ABAC activas (hora, ubicación, riesgo, dispositivo) y restricciones SoD vigentes. Responde PERMIT, DENY o INDETERMINATE con motivo auditable en menos de 0.5ms. ¿Para qué sirve? Ser el árbitro central de todas las decisiones de acceso digital del ecosistema, garantizando que ningún acceso ocurra sin evaluación de política. ¿Cómo se usa? El PEP (Kong) intercepta cada request, construye el mensaje de autorización con ctx_id y lo envía al PDP por Unix socket; el PDP responde sincrónicamente antes de que Kong reenvíe o rechace el request. ¿Por qué? Centralizar la decisión en un PDP único garantiza consistencia: el mismo usuario con el mismo contexto siempre recibe la misma decisión, independientemente del PEP que interceptó el request. Normas: XACML 3.0 §7, NIST SP 800-53 R5 AC-3, NIST SP 800-162 §4.2, OWASP ASVS v5 §4.1, ISO 27001 A.5.15."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.authorization', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'authorization', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f609-79f5-b7ab-f3fb371f6cfd', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Authenticator Binding", "es": "Vinculación de Autenticador"}', '{"en": "Authenticator Binding — FIDO2 §6.1 · NIST SP 800-63B-4 §5.2.5", "es": "Vinculación de Autenticador — FIDO2 §6.1 · NIST SP 800-63B-4 §5.2.5"}', NULL, '{"en": "Token-to-Device Binding · binding. What is it? Mechanism that cryptographically binds an access token to a specific device or private key, so the token is only valid when presented by the legitimate owner of the device or key. Implements: mTLS certificate binding (the token is only valid with the specific TLS certificate with which it was obtained — RFC 8705), DPoP binding (the token carries the hash of the ephemeral public key; the client proves possession of the private key on each request — RFC 9449). Prevents the token replay attack where a stolen token from traffic can be reused by an attacker. What is it for? Ensuring access tokens are useless to an attacker who intercepts them: without the bound private key (cryptographic material that never travels the network), the token cannot be used even if extracted from traffic or device memory. How is it used? For confidential clients (servers): the token is bound to the server''s mTLS certificate; Kong PEP verifies the binding on each request. For public clients (SPA, mobile): the client generates an ephemeral key pair; includes the public key in the token request; presents proof of private key possession on each request via DPoP header. Why? Bearer tokens (without binding) are \"bearer instruments\": anyone who has them can use them; binding converts tokens into \"personal instruments\" that only work for who obtained them. Standards: RFC 9449 DPoP, RFC 8705 mTLS Binding, NIST SP 800-63B-4 §5.1.9, OAuth 2.0 Security BCP RFC 9700.", "es": "Vinculación de Token a Dispositivo · binding. ¿Qué es? Mecanismo que ata criptográficamente un token de acceso a un dispositivo o clave privada específicos, de forma que el token solo es válido cuando es presentado por el titular legítimo del dispositivo o la clave. Implementa: mTLS certificate binding (el token solo es válido con el certificado TLS específico con el que se obtuvo — RFC 8705), DPoP binding (el token lleva el hash de la clave pública efímera; el cliente prueba posesión de la clave privada en cada request — RFC 9449). Previene el ataque de token replay donde un token robado del tráfico puede ser reutilizado por un atacante. ¿Para qué sirve? Garantizar que los tokens de acceso son inútiles para un atacante que los intercepta: sin la clave privada vinculada (material criptográfico que nunca viaja por la red), el token no puede ser usado aunque sea extraído del tráfico o de la memoria del dispositivo. ¿Cómo se usa? Para clientes confidenciales (servidores): el token se vincula al certificado mTLS del servidor; el PEP de Kong verifica la vinculación en cada request. Para clientes públicos (SPA, móvil): el cliente genera un par de claves efímero; incluye la clave pública en la solicitud de token; presenta prueba de posesión de la clave privada en cada request vía DPoP header. ¿Por qué? Los tokens bearer (sin binding) son \"billetes al portador\": cualquiera que los tenga puede usarlos; el binding convierte los tokens en \"billetes personales\" que solo funcionan para quien los obtuvo. Normas: RFC 9449 DPoP, RFC 8705 mTLS Binding, NIST SP 800-63B-4 §5.1.9, OAuth 2.0 Security BCP RFC 9700."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.binding', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'binding', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f48b-7948-b8d5-861b0c59a101', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Logical Access) — NIST SP 800-162 §4 · XACML 3.0", "es": "Registro de Zona de Negocio (Acceso Lógico) — NIST SP 800-162 §4 · XACML 3.0"}', NULL, '{"en": "Business Zone Registry (Logical Access) · business_zone. What is it? Structural container organizing the Logical Access domain blocks into logical application zones with their own access control parameters: which roles are valid in each zone, which resources it contains, which policies apply, and what minimum assurance level is required to operate within the zone. What is it for? Grouping digital resources into cohesive access control units, allowing a zone policy to apply to multiple resources simultaneously without duplicating rules. How is it used? Each digital resource is assigned to a zone; access evaluation checks zone restrictions first before evaluating individual resource restrictions, reducing permission matrix complexity. Why? Without application zones each resource requires its own complete policy; with zones, hundreds of resources share a common zone policy plus specific overrides, drastically reducing the administration surface. Standards: NIST SP 800-162 §4.2, XACML 3.0 §10, NIST SP 800-207 §3, ISO 27001 A.8.2.", "es": "Registro de Zona de Negocio (Acceso Lógico) · business_zone. ¿Qué es? Contenedor estructural que organiza los bloques del dominio Acceso Lógico en zonas de aplicación lógicas con sus propios parámetros de control de acceso: qué roles son válidos en cada zona, qué recursos contiene, qué políticas se aplican, y qué nivel de garantía mínimo se requiere para operar dentro de la zona. ¿Para qué sirve? Agrupar recursos digitales en unidades de control de acceso cohesivas, permitiendo que una política de zona aplique a múltiples recursos simultáneamente sin duplicar reglas. ¿Cómo se usa? Cada recurso digital se asigna a una zona; la evaluación de acceso comprueba primero las restricciones de la zona antes de evaluar las del recurso individual, reduciendo la complejidad de la matriz de permisos. ¿Por qué? Sin zonas de aplicación cada recurso requiere su propia política completa; con zonas, cientos de recursos comparten una política común de zona más overrides específicos, reduciendo drásticamente la superficie de administración. Normas: NIST SP 800-162 §4.2, XACML 3.0 §10, NIST SP 800-207 §3, ISO 27001 A.8.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 90, 'business_zone', 'B09') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5b5-78cf-a801-54df158603e9', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Context Break-glass", "es": "Acceso de Emergencia de Contexto"}', '{"en": "Context Break-glass — NIST SP 800-53 R5 CP-2(8) · ISO 27001 A.5.29", "es": "Acceso de Emergencia de Contexto — NIST SP 800-53 R5 CP-2(8) · ISO 27001 A.5.29"}', NULL, '{"en": "Emergency Context Access · emergency. What is it? Emergency access protocol allowing a high-privilege role to access critical systems when normal authentication mechanisms are unavailable (MFA provider unavailability, sole administrator access loss): emergency access requires multiple synchronous approvals from higher-level administrators, is fully logged in an external append-only log, and the emergency session is time-limited (maximum 2 hours) and scope-limited (only systems declared in the emergency request). What is it for? Ensuring operational continuity during catastrophic identity infrastructure failures without creating permanent backdoors: emergency access is exceptional, traceable, and has automatic expiration. How is it used? The administrator requests emergency access specifying the system and justification; at least two independent administrators synchronously approve; the system issues a time-limited emergency token with a special emergency ctx_id; the entire session is recorded and the token is non-renewable. Why? Without a defined emergency procedure, administrators create informal backdoors during emergencies; informal backdoors are not documented, do not expire, and become permanent vulnerabilities. Standards: NIST SP 800-53 R5 AC-2(5), ISO 27001 A.5.18, CIS Controls v8 §5.4, NIST SP 800-63B-4 §5.4.", "es": "Acceso de Emergencia de Contexto · emergency. ¿Qué es? Protocolo de acceso de emergencia que permite a un rol de alto privilegio acceder a sistemas críticos cuando los mecanismos normales de autenticación no están disponibles (indisponibilidad del proveedor MFA, pérdida de acceso del administrador único): el acceso de emergencia requiere múltiples aprobaciones síncronas de administradores de nivel superior, se registra íntegramente en un log append-only externo, y la sesión de emergencia está limitada temporalmente (máximo 2 horas) y en alcance (solo los sistemas declarados en la solicitud de emergencia). ¿Para qué sirve? Garantizar la continuidad operativa ante fallos catastróficos de infraestructura de identidad sin crear backdoors permanentes: el acceso de emergencia es excepcional, rastreable y tiene fecha de expiración automática. ¿Cómo se usa? El administrador solicita acceso de emergencia especificando el sistema y la justificación; al menos dos administradores independientes aprueban síncronamente; el sistema emite un token de emergencia de vida limitada con ctx_id especial de emergencia; toda la sesión se graba y el token no es renovable. ¿Por qué? Sin procedimiento de emergencia definido, los administradores crean backdoors informales ante una emergencia; los backdoors informales no se documentan, no expiran y se convierten en vulnerabilidades permanentes. Normas: NIST SP 800-53 R5 AC-2(5), ISO 27001 A.5.18, CIS Controls v8 §5.4, NIST SP 800-63B-4 §5.4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.emergency', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'emergency', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f629-75b4-9d63-26d220ccd177', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Delegation Management", "es": "Gestión de Delegaciones"}', '{"en": "Delegation Management — RFC 8693 §3 · NIST SP 800-53 R5 AC-2(5)", "es": "Gestión de Delegaciones — RFC 8693 §3 · NIST SP 800-53 R5 AC-2(5)"}', NULL, '{"en": "Authority Delegation · delegation. What is it? Formal system for delegating permissions from one user to another user or service to act on their behalf, temporarily and with limited scope: the delegator (user with permissions) authorizes the delegatee (another user or service) to exercise a specific subset of their permissions during a defined period, without the delegatee acquiring the delegator''s full role. Examples: the CFO delegates signing of payment orders under $5,000 to their assistant during vacation; a service delegates balance consultation to an analytics app for 24 hours. What is it for? Enabling workflows where the absence of a key person does not block operations, in a controlled and audited manner: delegation has automatic expiration and exact scope, unlike permanent role assignment. How is it used? The delegator defines in the delegation portal: the delegatee, exact scope (delegated operations), period, and sub-delegation limit (whether the delegatee can further delegate); the system issues a delegation token with the delegator''s claims restricted to the scope; upon expiry, the delegation token automatically becomes invalid. Why? Without formal delegation, users share passwords to cover absences — the most dangerous practice in identity management; controlled delegation eliminates the need to share credentials. Standards: RFC 8693 Token Exchange §4.1, NIST SP 800-53 R5 AC-3(7), ISO 27001 A.5.18, OAuth 2.0 §4.", "es": "Delegación de Autoridad · delegation. ¿Qué es? Sistema formal de delegación de permisos de un usuario a otro usuario o servicio para actuar en su nombre, de forma temporal y con scope limitado: el delegante (usuario con permisos) autoriza al delegatario (otro usuario o servicio) a ejercer un subconjunto específico de sus permisos durante un período definido, sin que el delegatario adquiera el rol completo del delegante. Ejemplos: el Director Financiero delega la firma de órdenes de pago menores a 5.000 USD a su asistente durante sus vacaciones; un servicio delega la consulta de saldos a una app de análisis durante 24 horas. ¿Para qué sirve? Habilitar flujos de trabajo donde la ausencia de una persona clave no bloquea la operación, de forma controlada y auditada: la delegación tiene fecha de expiración automática y scope exacto, a diferencia de la asignación permanente de roles. ¿Cómo se usa? El delegante define en el portal de delegación el delegatario, el scope exacto (operaciones delegadas), el período y el límite de sub-delegación (si el delegatario puede a su vez delegar); el sistema emite un token de delegación con los claims del delegante restringidos al scope; al expirar, el token de delegación deja de ser válido automáticamente. ¿Por qué? Sin delegación formal, los usuarios comparten contraseñas para cubrir ausencias — la práctica más peligrosa en gestión de identidades; la delegación controlada elimina la necesidad de compartir credenciales. Normas: RFC 8693 Token Exchange §4.1, NIST SP 800-53 R5 AC-3(7), ISO 27001 A.5.18, OAuth 2.0 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.delegation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'delegation', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f473-706c-b56b-2fcf890f1e3a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Access Contracts", "es": "Contratos de Acceso"}', '{"en": "Access Contracts — NIST SP 800-53 R5 AC-17 · ISO 27001 A.5.20", "es": "Contratos de Acceso — NIST SP 800-53 R5 AC-17 · ISO 27001 A.5.20"}', NULL, '{"en": "Access Contracts · contracts. What is it? Formally digitally-signed agreements between a subject (user or service) and a resource or system, establishing: the exact acceptable use conditions, subject obligations, accessible resources, and consequences of non-compliance. The contract is signed with the user''s digital signature and recorded as binding evidence in the WORM audit log. What is it for? Creating a legal and technical link between the granted access and the user''s explicit commitment to use it in accordance with policy, especially for access to sensitive or high-criticality data. How is it used? When assigning roles that access sensitive data (HR, financial, medical), the system requires the user to sign the corresponding access contract before activating permissions; refusal blocks the assignment. Why? Signing access contracts is an explicit requirement of ISO 27001 A.5.20 for external personnel and suppliers; it also creates evidence of informed consent in legal liability situations. Standards: NIST SP 800-53 R5 AC-17, ISO 27001 A.5.20, GDPR Art. 28, ISO 9001:2015 §8.4.", "es": "Contratos de Acceso · contracts. ¿Qué es? Acuerdos formales firmados digitalmente entre un sujeto (usuario o servicio) y un recurso o sistema, que establecen: las condiciones exactas de uso aceptable, las obligaciones del sujeto, los recursos accesibles y las consecuencias del incumplimiento. El contrato se firma con la firma digital del usuario y queda registrado como evidencia vinculante en el log de auditoría WORM. ¿Para qué sirve? Crear un vínculo jurídico y técnico entre el acceso concedido y el compromiso explícito del usuario de usarlo conforme a la política, especialmente para accesos a datos sensibles o de alta criticidad. ¿Cómo se usa? Al asignar roles que acceden a datos sensibles (RRHH, financieros, médicos), el sistema exige que el usuario firme el contrato de acceso correspondiente antes de activar los permisos; la negativa bloquea la asignación. ¿Por qué? La firma de contratos de acceso es un requisito explícito de ISO 27001 A.5.20 para personal externo y proveedores; además crea evidencia de consentimiento informado ante responsabilidades legales. Normas: NIST SP 800-53 R5 AC-17, ISO 27001 A.5.20, GDPR Art. 28, ISO 9001:2015 §8.4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.contracts', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'contracts', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5fa-7483-acfb-cc6a2dcbe43d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "X.509 Certificates", "es": "Certificados X.509"}', '{"en": "X.509 Certificates — RFC 5280 §4 · NIST SP 800-57 Pt1 R5", "es": "Certificados X.509 — RFC 5280 §4 · NIST SP 800-57 Pt1 R5"}', NULL, '{"en": "Digital Certificates (PKI) · certificates. What is it? Complete lifecycle management of X.509 certificates issued by bAuth''s internal PKI (Vault as intermediate CA under ADSIB root CA or self-signed for internal use): user certificates (for document signing and TLS client authentication), device certificates (for mTLS on corporate devices), service certificates (SVIDs for SPIFFE/SPIRE microservices), revocation management (CRL and real-time OCSP), and automatic renewal before expiration. What is it for? Providing verifiable cryptographic identity to users, devices, and services within the SBOS ecosystem, enabling mTLS, digital document signing with Bolivian legal validity (Law 164), and high-assurance X.509 mTLS authentication as an AAL3 method. How is it used? When enrolling a user or device, bAuth requests certificate issuance from Vault-CA; the certificate is delivered to the subject and registered in the LDAP directory; in each mTLS authentication the service verifies the certificate against the CRL/OCSP; certificates are automatically renewed 30 days before expiry. Why? X.509 certificates are the most robust form of cryptographic identity: verifiable without contact with the issuer (while not revoked), phishing-resistant (the attacker cannot forge a certificate from the private CA), and legally valid in Bolivia. Standards: RFC 5280 X.509, RFC 6960 OCSP, RFC 5652 CMS, Bolivia Law 164 Art. 15, ETSI EN 319 412.", "es": "Certificados Digitales (PKI) · certificates. ¿Qué es? Gestión del ciclo de vida completo de certificados X.509 emitidos por la PKI interna de bAuth (Vault como CA intermedia bajo la CA raíz ADSIB o autofirmada para uso interno): emisión de certificados de usuario (para firma de documentos y autenticación cliente TLS), certificados de dispositivo (para mTLS de dispositivos corporativos), certificados de servicio (SVIDs para microservicios SPIFFE/SPIRE), gestión de revocación (CRL y OCSP en tiempo real), y renovación automática antes de la expiración. ¿Para qué sirve? Proveer identidad criptográfica verificable a usuarios, dispositivos y servicios dentro del ecosistema SBOS, habilitando mTLS, firma digital de documentos con validez legal boliviana (Ley 164), y autenticación de alta garantía X.509 mTLS como método de autenticación AAL3. ¿Cómo se usa? Al enrolar un usuario o dispositivo, bAuth solicita la emisión de un certificado a Vault-CA; el certificado se entrega al sujeto y se registra en el directorio LDAP; en cada autenticación mTLS el servicio verifica el certificado contra la CRL/OCSP; los certificados se renuevan automáticamente 30 días antes de expirar. ¿Por qué? Los certificados X.509 son la forma más robusta de identidad criptográfica: son verificables sin contacto con el emisor (mientras no estén revocados), resistentes a phishing (el atacante no puede falsificar un certificado de la CA privada) y tienen validez legal en Bolivia. Normas: RFC 5280 X.509, RFC 6960 OCSP, RFC 5652 CMS, Ley 164 Bolivia Art. 15, ETSI EN 319 412."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.certificates', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'certificates', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f604-72d7-bb87-c954ae7661b3', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Account Recovery", "es": "Recuperación de Cuenta"}', '{"en": "Account Recovery — NIST SP 800-63B-4 §6.1 · OWASP ASVS v5 §2.5", "es": "Recuperación de Cuenta — NIST SP 800-63B-4 §6.1 · OWASP ASVS v5 §2.5"}', NULL, '{"en": "Credential Recovery · recovery. What is it? Set of access recovery mechanisms when the user loses their primary credential or MFA factor: single-use recovery codes generated at enrollment (Diceware 6 words, stored hashed, valid only once), recovery via verified alternate channel (recovery email with short-lived OTP link), administrator-assisted recovery with in-person identity verification (IAL2), and backup MFA recovery (second FIDO2 authenticator registered as \"rescue key\"). What is it for? Ensuring a user does not permanently lose access to their account by losing a device or MFA factor, through secure recovery mechanisms that do not create backdoors exploitable by attackers through social engineering. How is it used? The user activates the recovery flow; the system identifies which recovery mechanisms are available; the user completes the lowest-risk available mechanism; after recovery, the system forces configuration of new MFA factors before restoring full access; the event is logged as a high-priority audit. Why? Account recovery is the most effective social engineering attack vector; weak recovery mechanisms (security questions, email only) are routinely exploited for account takeover; robust recovery mechanisms are as important as primary authentication. Standards: NIST SP 800-63B-4 §5.1.2, OWASP ASVS v5.0 §2.6, ISO 27001 A.5.17.", "es": "Recuperación de Credenciales · recovery. ¿Qué es? Conjunto de mecanismos de recuperación de acceso cuando el usuario pierde su credencial principal o su factor MFA: códigos de recuperación de un solo uso generados en el enrolamiento (Diceware 6 palabras, almacenados hasheados, válidos solo una vez), recuperación por canal alternativo verificado (email de recuperación con enlace OTP de vida corta), recuperación asistida por administrador con verificación de identidad presencial (IAL2), y recuperación por MFA de respaldo (segundo autenticador FIDO2 registrado como \"rescue key\"). ¿Para qué sirve? Garantizar que un usuario no pierde permanentemente el acceso a su cuenta por perder un dispositivo o factor MFA, mediante mecanismos de recuperación seguros que no crean puertas traseras explotables por atacantes mediante ingeniería social. ¿Cómo se usa? El usuario activa el flujo de recuperación; el sistema identifica qué mecanismos de recuperación tiene disponibles; el usuario completa el mecanismo de menor riesgo disponible; tras la recuperación, el sistema fuerza la configuración de nuevos factores MFA antes de restaurar el acceso completo; el evento se registra como auditoría de alta prioridad. ¿Por qué? La recuperación de cuenta es el vector de ataque de ingeniería social más efectivo; mecanismos de recuperación débiles (preguntas de seguridad, solo email) son explotados rutinariamente para tomar el control de cuentas; los mecanismos de recuperación robustos son tan importantes como la autenticación primaria. Normas: NIST SP 800-63B-4 §5.1.2, OWASP ASVS v5.0 §2.6, ISO 27001 A.5.17."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.recovery', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'recovery', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5fe-7e36-84ec-bfd65c35040c', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Access Tokens", "es": "Tokens de Acceso"}', '{"en": "Access Tokens — RFC 7519 JWT §4 · OAuth 2.0 RFC 6749 §5", "es": "Tokens de Acceso — RFC 7519 JWT §4 · OAuth 2.0 RFC 6749 §5"}', NULL, '{"en": "OAuth 2.0 Token Management · tokens. What is it? Complete OAuth 2.0 token lifecycle management engine: access tokens (EdDSA Ed25519 signed JWT, 15-minute TTL), refresh tokens (opaque, 90-day TTL, rotation on each use — RFC 6749 §10.4), ID tokens (OIDC JWT with user identity claims — OpenID Connect §2.1.3), authorization codes (mandatory PKCE — RFC 7636, 60-second TTL, single use), device tokens (Device Authorization Grant — RFC 8628), and exchange tokens (Token Exchange — RFC 8693 for controlled impersonation and delegation). What is it for? Managing the complete OAuth 2.0 token lifecycle with current security best practices: automatic refresh token rotation, token binding to devices (DPoP/mTLS), token issuance with minimum necessary scope (NIST SP 800-53 R5 AC-6), and immediate revocation. How is it used? Registered OAuth clients request tokens through standard endpoints (/oauth2/token, /oauth2/authorize, /oauth2/device); bAuth validates client credentials, requested scope, and security requirements (PKCE, DPoP) and issues the corresponding tokens; tokens are stored with audit metadata in Redis. Why? OAuth 2.0 is the most globally adopted authorization delegation protocol; correct implementation with refresh token rotation and access token binding eliminates the main token theft and abuse vectors. Standards: RFC 6749 OAuth 2.0, RFC 7519 JWT, RFC 7636 PKCE, RFC 8693 Token Exchange, RFC 9700 Security BCP.", "es": "Gestión de Tokens OAuth 2.0 · tokens. ¿Qué es? Motor de gestión del ciclo de vida completo de tokens OAuth 2.0: access tokens (JWT firmado con EdDSA Ed25519, TTL 15 minutos), refresh tokens (opaco, TTL 90 días, rotación en cada uso — RFC 6749 §10.4), ID tokens (JWT OIDC con claims de identidad del usuario — OpenID Connect §2.1.3), authorization codes (PKCE obligatorio — RFC 7636, TTL 60 segundos, un solo uso), tokens de dispositivo (Device Authorization Grant — RFC 8628), y tokens de intercambio (Token Exchange — RFC 8693 para impersonación y delegación controlada). ¿Para qué sirve? Gestionar el ciclo de vida completo de los tokens OAuth 2.0 con las mejores prácticas de seguridad actuales: rotación automática de refresh tokens, binding de tokens a dispositivos (DPoP/mTLS), emisión de tokens con mínimo scope necesario (NIST SP 800-53 R5 AC-6), y revocación inmediata. ¿Cómo se usa? Los clientes OAuth registrados solicitan tokens a través de los endpoints estándar (/oauth2/token, /oauth2/authorize, /oauth2/device); bAuth valida las credenciales del cliente, el scope solicitado y los requisitos de seguridad (PKCE, DPoP) y emite los tokens correspondientes; los tokens se almacenan con metadatos de auditoría en Redis. ¿Por qué? OAuth 2.0 es el protocolo de delegación de autorización más adoptado a nivel mundial; una implementación correcta con rotación de refresh tokens y binding de access tokens elimina los principales vectores de robo y abuso de tokens. Normas: RFC 6749 OAuth 2.0, RFC 7519 JWT, RFC 7636 PKCE, RFC 8693 Token Exchange, RFC 9700 Security BCP."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.tokens', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'tokens', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f478-7268-ab46-06819da08c74', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Logical Session", "es": "Sesión Lógica"}', '{"en": "Logical Session — NIST SP 800-53 R5 AC-12 · OWASP ASVS v5 §3.3", "es": "Sesión Lógica — NIST SP 800-53 R5 AC-12 · OWASP ASVS v5 §3.3"}', NULL, '{"en": "Logical Session · session. What is it? Unit of authenticated interaction between a user and the system, with a unique ctx_id, tier-configurable maximum lifetime (30 min for SU, 8h for BIZ_N1), inactivity timeout, mandatory re-authentication when escalating AAL, and complete record of start, activity, close, and termination reason. The logical session is the authentication state container the PDP consults in each request. What is it for? Delimiting the period during which an authenticated user can operate without re-authenticating, limiting the exposure window against session theft or compromised device. How is it used? Upon successful authentication the system creates the logical session with its ctx_id; each request carries the ctx_id; the PDP verifies the session is active and has not expired before evaluating the access policy. Why? Sessions without a lifetime are a critical risk: a stolen token remains valid indefinitely; the inactivity timeout limits damage from credential theft or an unattended device. Standards: NIST SP 800-53 R5 AC-12, OWASP ASVS v5 §3.3, NIST SP 800-63B-4 §7.1, PCI DSS 4.0 Req 8.2.8.", "es": "Sesión Lógica · session. ¿Qué es? Unidad de interacción autenticada entre un usuario y el sistema, con un ctx_id único, tiempo máximo de vida configurable por tier (30 min para SU, 8h para BIZ_N1), timeout de inactividad, re-autenticación obligatoria al escalar AAL, y registro completo del inicio, actividad, cierre y motivo de terminación. La sesión lógica es el contenedor del estado de autenticación que el PDP consulta en cada request. ¿Para qué sirve? Delimitar el período durante el cual un usuario autenticado puede operar sin re-autenticarse, limitando la ventana de exposición ante robo de sesión o dispositivo comprometido. ¿Cómo se usa? Al autenticarse exitosamente el sistema crea la sesión lógica con su ctx_id; cada request lleva el ctx_id; el PDP verifica que la sesión está activa y no ha expirado antes de evaluar la política de acceso. ¿Por qué? Las sesiones sin tiempo de vida son un riesgo crítico: un token robado permanece válido indefinidamente; el timeout de inactividad limita el daño ante robo de credencial o dispositivo desatendido. Normas: NIST SP 800-53 R5 AC-12, OWASP ASVS v5 §3.3, NIST SP 800-63B-4 §7.1, PCI DSS 4.0 Req 8.2.8."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.session', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'session', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4be-7f93-b436-e5d2f92031a9', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Physical Access) — IEC 60839-11-5 · ISO 27001 A.7.1", "es": "Registro de Zona de Negocio (Acceso Físico) — IEC 60839-11-5 · ISO 27001 A.7.1"}', NULL, '{"en": "Business Zone Registry (Physical Access) · business_zone. What is it? Container organizing physical facilities into security zones with their own classification (public zone, restricted zone, high security zone, maximum security zone) and defining for each zone: the readers delimiting it, authorized roles, required authentication level (card only, card + PIN, biometric), and special rules (dual presence, anti-passback). What is it for? Modeling the organization''s physical security floor plan in the access control system, enabling differentiated access policies by area sensitivity level. How is it used? The physical security administrator defines zones in the system, links them with physical OSDP readers, and assigns authorized roles to each zone; changes propagate automatically to OSDP control panels. Why? Without physical zoning all spaces would have the same protection level; with zones, defense-in-depth is applied: concentric security layers where the most sensitive access requires more controls. Standards: IEC 60839-11-5:2020 §5, ISO 27001 A.7.1, NIST SP 800-116 R2 §4, EN 50133.", "es": "Registro de Zona de Negocio (Acceso Físico) · business_zone. ¿Qué es? Contenedor que organiza las instalaciones físicas en zonas de seguridad con clasificación propia (zona pública, zona restringida, zona de alta seguridad, zona de máxima seguridad) y define para cada zona: los lectores que la delimitan, los roles autorizados, el nivel de autenticación requerido (tarjeta sola, tarjeta + PIN, biométrico) y las reglas especiales (doble presencia, anti-passback). ¿Para qué sirve? Modelar el plano de seguridad física de la organización en el sistema de control de acceso, habilitando políticas de acceso diferenciadas por nivel de sensibilidad del área. ¿Cómo se usa? El administrador de seguridad física define las zonas en el sistema, las vincula con los lectores OSDP físicos y asigna los roles autorizados a cada zona; los cambios se propagan automáticamente a los paneles de control OSDP. ¿Por qué? Sin zonificación física todos los espacios tendrían el mismo nivel de protección; con zonas se aplica defensa en profundidad: capas concéntricas de seguridad donde el acceso más sensible requiere más controles. Normas: IEC 60839-11-5:2020 §5, ISO 27001 A.7.1, NIST SP 800-116 R2 §4, EN 50133."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'business_zone', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6a3-76fb-b964-73615a63a5c6', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Periodic Review", "es": "Revisión Periódica"}', '{"en": "Periodic Audit Review — NIST SP 800-53 R5 AU-6 · ISO 27001 A.5.35", "es": "Revisión Periódica de Auditoría — NIST SP 800-53 R5 AU-6 · ISO 27001 A.5.35"}', NULL, '{"en": "Access Review · review. What is it? Periodic and systematic review process for the active access rights of all tenant users: for each user, the system generates a report of active roles, last recorded activity with each role, operations performed in the period, and an automatic privilege creep risk assessment (assigned roles unused for more than 90 days). The report is presented to the user''s supervisor to certify or revoke each access. What is it for? Detecting and eliminating unnecessary access right accumulation (privilege creep) through periodic review with a human responsible: a supervisor certifying their subordinate needs each assigned role must actively think about each assignment instead of leaving it by default. How is it used? The review process runs automatically every quarter (configurable); generates a review list per supervisor with their subordinates'' roles; the supervisor approves or rejects each role; rejected or unresponded roles within the deadline expire automatically; results are included in the tenant''s compliance report. Why? Privilege creep is the internal risk hardest to detect without active review: roles accumulate gradually and each individually appears legitimate; only the consolidated view of all a user''s roles reveals the problem. Standards: NIST SP 800-53 R5 AC-2(4), ISO 27001 A.5.18, SOX §404, PCI DSS 4.0 Req 7.2.4.", "es": "Revisión de Accesos · review. ¿Qué es? Proceso periódico y sistemático de revisión de los derechos de acceso activos de todos los usuarios del tenant: para cada usuario, el sistema genera un informe de los roles activos, la última actividad registrada con cada rol, las operaciones realizadas en el período y una evaluación automática de riesgo de privilege creep (roles asignados que no se han usado en más de 90 días). El informe se presenta al supervisor del usuario para que certifique o revoque cada acceso. ¿Para qué sirve? Detectar y eliminar acumulación de derechos de acceso innecesarios (privilege creep) mediante revisión periódica con responsable humano: un supervisor que certifica que su subordinado necesita cada rol asignado tiene que pensar activamente en cada asignación, en lugar de dejarla por defecto. ¿Cómo se usa? El proceso de revisión se ejecuta automáticamente cada trimestre (configurable); genera una lista de revisión por supervisor con los roles de sus subordinados; el supervisor aprueba o rechaza cada rol; los roles rechazados o no respondidos en el plazo expiran automáticamente; los resultados se incluyen en el informe de cumplimiento del tenant. ¿Por qué? El privilege creep es el riesgo interno más difícil de detectar sin revisión activa: los roles se acumulan gradualmente y cada uno individualmente parece legítimo; solo la vista consolidada de todos los roles de un usuario revela el problema. Normas: NIST SP 800-53 R5 AC-2(4), ISO 27001 A.5.18, SOX §404, PCI DSS 4.0 Req 7.2.4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.review', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'review', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6cc-7672-b37d-f9bd794f4966', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Besu Transactions", "es": "Transacciones Besu"}', '{"en": "Besu Transactions — Hyperledger Besu §6 · EIP-1559 · EIP-712", "es": "Transacciones Besu — Hyperledger Besu §6 · EIP-1559 · EIP-712"}', NULL, '{"en": "Blockchain Transactions · transactions. What is it? Transaction lifecycle management engine for the ecosystem''s Besu network: transaction construction (to, value, data, gas, nonce), signing with the corresponding wallet''s private key (stored in Vault HSM), submission to the network and tracking until confirmation (waiting N blocks to consider the transaction finalized), error handling (transactions failed due to insufficient gas, contract reverts), and network interruption recovery (resubmission with gas bumping if the transaction is in mempool unconfirmed). What is it for? Providing a reliable abstraction layer over blockchain transaction complexity: identity and audit modules invoke blockchain operations as if they were ordinary function calls, and the engine manages the complexity of nonces, gas, confirmations, and retries. How is it used? A module invokes a blockchain operation (e.g., anchoring a Merkle root); the engine builds the transaction, signs it with the wallet key, sends it to Besu, and waits for confirmation; returns the confirmed txHash or a detailed error if the transaction fails; the txHash is stored in the audit log as the blockchain operation reference. Why? Blockchain transactions have unique characteristics (sequential nonces, gas fees, confirmation latency, reorganization possibility) requiring a specialized engine to manage correctly; without this engine, nonce or gas errors would leave blockchain operations in an undefined state. Standards: Ethereum Yellow Paper §5, EIP-1559 Gas Fees, NIST SP 800-53 R5 SC-28, ISO 27001 A.5.17.", "es": "Transacciones Blockchain · transactions. ¿Qué es? Motor de gestión del ciclo de vida de transacciones en la red Besu del ecosistema: construcción de la transacción (to, value, data, gas, nonce), firma con la clave privada del wallet correspondiente (almacenada en Vault HSM), envío a la red y seguimiento hasta confirmación (espera de N bloques para considerar la transacción finalizada), manejo de errores (transacciones fallidas por gas insuficiente, reverts de contratos), y recuperación ante interrupciones de red (reenvío con gas bumping si la transacción está en mempool sin confirmar). ¿Para qué sirve? Proporcionar una capa de abstracción confiable sobre la complejidad de las transacciones blockchain: los módulos de identidad y auditoría invocan operaciones blockchain como si fueran llamadas a funciones ordinarias, y el motor gestiona la complejidad de nonces, gas, confirmaciones y reintentos. ¿Cómo se usa? Un módulo invoca una operación blockchain (ej: anclar un Merkle root); el motor construye la transacción, la firma con la clave del wallet, la envía a Besu y espera la confirmación; retorna el txHash confirmado o un error detallado si la transacción falla; el txHash se almacena en el log de auditoría como referencia de la operación blockchain. ¿Por qué? Las transacciones blockchain tienen características únicas (nonces secuenciales, gas fees, latencia de confirmación, posibilidad de reorganización) que requieren un motor especializado para gestionar correctamente; sin este motor, los errores de nonce o gas dejarían operaciones blockchain en estado indefinido. Normas: Ethereum Yellow Paper §5, EIP-1559 Gas Fees, NIST SP 800-53 R5 SC-28, ISO 27001 A.5.17."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.transactions', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'transactions', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f490-7638-b575-0ddc4ec9bc71', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Physical Facilities", "es": "Instalaciones Físicas"}', '{"en": "Physical Facilities — ISO 27001 A.7.1 · IEC 60839-11-5:2020", "es": "Instalaciones Físicas — ISO 27001 A.7.1 · IEC 60839-11-5:2020"}', NULL, '{"en": "Physical Facilities · facilities. What is it? Master catalog of all physical assets controlled by the access system: buildings (with address, floor plan, number of floors), floors, rooms, server racks, network cabinets, and any physical access control point. Each facility has a security classification, owner, capacity, installed equipment, and operational status. What is it for? Maintaining an updated and auditable inventory of all physical spaces the system protects, the base for assigning readers, defining zones, and managing evacuation capacities. How is it used? The administrator registers each physical facility with its classification; OSDP readers are linked to the facility where they are installed; access events carry the facility reference for geolocation in audit logs. Why? Without a centralized physical facilities catalog, access events are just a reader ID without geographic context; the catalog converts logs into readable and actionable evidence. Standards: ISO 27001 A.7.1, IEC 60839-11-5:2020, ISO 55001:2014 (asset management), NIST SP 800-116 R2 §3.", "es": "Instalaciones Físicas · facilities. ¿Qué es? Catálogo maestro de todos los activos físicos controlados por el sistema de acceso: edificios (con dirección, plano, número de pisos), plantas, salas, servidores rack, armarios de red y cualquier punto de control de acceso físico. Cada instalación tiene clasificación de seguridad, propietario, capacidad, equipos instalados y estado operativo. ¿Para qué sirve? Mantener un inventario actualizado y auditable de todos los espacios físicos que el sistema protege, base para asignar lectores, definir zonas y gestionar capacidades de evacuación. ¿Cómo se usa? El administrador registra cada instalación física con su clasificación; los lectores OSDP se vinculan a la instalación donde están instalados; los eventos de acceso llevan la referencia de la instalación para geolocalización en los logs de auditoría. ¿Por qué? Sin un catálogo centralizado de instalaciones físicas, los eventos de acceso son solo un ID de lector sin contexto geográfico; el catálogo convierte los logs en evidencia legible y accionable. Normas: ISO 27001 A.7.1, IEC 60839-11-5:2020, ISO 55001:2014 (gestión de activos), NIST SP 800-116 R2 §3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.facilities', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'facilities', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f648-701e-96ad-bd9494fc0528', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Chain Delegation", "es": "Delegación en Cadena"}', '{"en": "Chain Delegation — RFC 8693 §2 · ANSI INCITS 359-2004 §4.5", "es": "Delegación en Cadena — RFC 8693 §2 · ANSI INCITS 359-2004 §4.5"}', NULL, '{"en": "Audit Custody Chain (Hash Chain) · chain. What is it? Audit log integrity mechanism via hash chain: each audit event includes the SHA-256 hash of the previous event in the chain, creating a blockchain-like structure where modifying any event invalidates all subsequent events and is mathematically detectable. Each event''s hash is calculated over: event content + previous event hash + timestamp. Periodically, chain checkpoints are anchored to an external record (public blockchain or timestamping service) to make the chain irrefutable. What is it for? Guaranteeing the mathematical and irrefutable integrity of the audit log: not even the system administrator can modify or delete a past audit event without the change being immediately detectable by any verifier validating the hash chain. How is it used? When writing each audit event, the engine calculates the new event''s hash including the previous event''s hash; periodically an independent process verifies the integrity of the complete chain; if a break in the chain is detected, a high-priority alert is generated for log tampering investigation. Why? Traditional audit logs (files, SQL tables) can be modified by an attacker with storage access; the hash chain makes any modification detectable without requiring storage access controls. Standards: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-10, RFC 3161 Timestamping, NIST SP 800-209 §4.3.", "es": "Cadena de Custodia de Auditoría (Hash Chain) · chain. ¿Qué es? Mecanismo de integridad del log de auditoría mediante cadena de hashes: cada evento de auditoría incluye el hash SHA-256 del evento anterior en la cadena, creando una estructura similar a una blockchain donde la modificación de cualquier evento invalida todos los eventos posteriores y es detectable matemáticamente. El hash de cada evento se calcula sobre: contenido del evento + hash del evento anterior + timestamp. Periódicamente se anclan checkpoints de la cadena a un registro externo (blockchain pública o servicio de timestamping) para hacer la cadena irrefutable. ¿Para qué sirve? Garantizar la integridad matemática e irrefutable del log de auditoría: ni siquiera el administrador del sistema puede modificar o borrar un evento de auditoría pasado sin que el cambio sea inmediatamente detectable por cualquier verificador que valide la cadena de hashes. ¿Cómo se usa? Al escribir cada evento de auditoría, el motor calcula el hash del nuevo evento incluyendo el hash del anterior; periódicamente un proceso independiente verifica la integridad de la cadena completa; si detecta una rotura en la cadena, genera alerta de alta prioridad para investigación de manipulación del log. ¿Por qué? Los logs de auditoría tradicionales (archivos, tablas SQL) pueden ser modificados por un atacante con acceso al almacenamiento; la hash chain hace que cualquier modificación sea detectable sin necesidad de controles de acceso al almacenamiento. Normas: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-10, RFC 3161 Timestamping, NIST SP 800-209 §4.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.chain', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'chain', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f681-78a9-af4c-6846c22ceaa8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Hash-Chain Integrity", "es": "Integridad Hash-Chain"}', '{"en": "Hash-Chain Integrity — NIST SP 800-53 R5 AU-9 · RFC 6962", "es": "Integridad de Cadena Hash — NIST SP 800-53 R5 AU-9 · RFC 6962"}', NULL, '{"en": "Audit Data Integrity · integrity. What is it? Set of mechanisms guaranteeing the completeness, accuracy, and authenticity of audit data: SHA-256 hash of each event (ensures content was not altered), hash chain between consecutive events (ensures no events were deleted), digital signature of event sets by period (ensures the complete sequence was emitted by bAuth), completeness validation (sequence counters ensure no missing events in the chain), and RFC 3161 signed timestamps (ensures the exact moment of each event). What is it for? Providing mathematical, not just organizational, proof that audit records are complete and have not been altered: any independent verifier can validate log integrity without trusting the system administrator''s word. How is it used? When writing each event, the engine calculates and stores the content hash and event signature; periodically the integrity verification engine traverses the entire chain and validates each link; the verification result is published on the tenant''s compliance dashboard; integrity certificates are automatically generated for audit periods. Why? \"The log says what happened\" is not sufficient evidence if the log can be modified; cryptographic integrity converts the log into admissible forensic evidence that can be verified by independent third parties. Standards: NIST SP 800-53 R5 AU-10, RFC 3161 Timestamping, ISO 27001 A.8.15, NIST SP 800-209 §4.", "es": "Integridad de Datos de Auditoría · integrity. ¿Qué es? Conjunto de mecanismos que garantizan la completitud, exactitud y autenticidad de los datos de auditoría: hash SHA-256 de cada evento (garantiza que el contenido no fue alterado), hash chain entre eventos consecutivos (garantiza que no se eliminaron eventos), firma digital del conjunto de eventos por períodos (garantiza que la secuencia completa fue emitida por bAuth), validación de completitud (los contadores de secuencia garantizan que no hay eventos faltantes en la cadena), y timestamps firmados con RFC 3161 (garantiza el momento exacto de cada evento). ¿Para qué sirve? Proveer prueba matemática, no solo organizacional, de que los registros de auditoría son completos y no han sido alterados: cualquier verificador independiente puede validar la integridad del log sin confiar en la palabra del administrador del sistema. ¿Cómo se usa? Al escribir cada evento, el motor calcula y almacena el hash del contenido y la firma del evento; periódicamente el motor de verificación de integridad recorre toda la cadena y valida cada eslabón; el resultado de la verificación se publica en el panel de cumplimiento del tenant; los certificados de integridad se generan automáticamente para los períodos de auditoría. ¿Por qué? \"El log dice lo que pasó\" no es evidencia suficiente si el log puede ser modificado; la integridad criptográfica convierte el log en evidencia forense admisible que puede ser verificada por terceros independientes. Normas: NIST SP 800-53 R5 AU-10, RFC 3161 Timestamping, ISO 27001 A.8.15, NIST SP 800-209 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.integrity', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'integrity', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4cb-765f-a907-27baa07d9295', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Dual Approval / Quorum", "es": "Aprobación Dual / Quórum"}', '{"en": "Dual Approval / Quorum — COSO 2013 CC6.3 · ISO 27001 A.5.3 · SOX §302", "es": "Aprobación Dual / Quórum — COSO 2013 CC6.3 · ISO 27001 A.5.3 · SOX §302"}', NULL, '{"en": "Dual Approval / Quorum · approvals. What is it? Multi-party approval engine implementing the four-eyes principle and k-of-N quorum: a high-value financial operation requires approval from at least k approvers from a set of N authorized, where no approver can be the same initiator of the operation. Supports: sequential approval (A approves, then B), parallel (A and B approve in any order), and conditional (second approver only required if amount exceeds threshold). What is it for? Ensuring no critical financial operation can be executed by a single person, eliminating the risk of internal fraud by a single actor. How is it used? The operation arrives at the engine; it determines the approval flow based on amount, type, and initiator role; notifies designated approvers; collects approvals with digital signature; executes the operation only when the quorum is completed within the defined deadline. Why? 85% of internal frauds are committed by a single individual with excessive access; the dual approval principle eliminates this vector by requiring complicity of at least two people. Standards: COSO 2013 CC6.3, ISO 27001 A.5.3, SOX §302, PCI DSS 4.0 Req 8.2.", "es": "Aprobación Dual / Quórum · approvals. ¿Qué es? Motor de aprobación multi-parte que implementa el principio de cuatro ojos y quórum k-de-N: una operación financiera de alto valor requiere la aprobación de al menos k aprobadores de un conjunto de N autorizados, donde ningún aprobador puede ser el mismo iniciador de la operación. Soporta: aprobación secuencial (A aprueba, luego B), paralela (A y B aprueban en cualquier orden) y condicional (solo se requiere segundo aprobador si el monto supera el umbral). ¿Para qué sirve? Garantizar que ninguna operación financiera crítica pueda ser ejecutada por una sola persona, eliminando el riesgo de fraude interno por actor único. ¿Cómo se usa? La operación llega al motor; este determina el flujo de aprobación según el monto, tipo y rol del iniciador; notifica a los aprobadores designados; recoge las aprobaciones con firma digital; ejecuta la operación solo cuando se completa el quórum en el plazo definido. ¿Por qué? El 85% de los fraudes internos son cometidos por un solo individuo con acceso excesivo; el principio de doble aprobación elimina este vector al requerir complicidad de al menos dos personas. Normas: COSO 2013 CC6.3, ISO 27001 A.5.3, SOX §302, PCI DSS 4.0 Req 8.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.approvals', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'approvals', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4de-77be-9e9c-a0a6b32180fc', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Electronic Invoicing", "es": "Facturación Electrónica"}', '{"en": "Electronic Invoicing — SIN RND 102100000011 · ISO 20022 · UBL 2.1", "es": "Facturación Electrónica — SIN RND 102100000011 · ISO 20022 · UBL 2.1"}', NULL, '{"en": "Electronic Invoicing · billing. What is it? Engine for generating and transmitting electronic fiscal documents in compliance with Bolivia SIN regulations (SIAT): CUIS (Unique System Start Code), CUFD (Unique Daily Invoicing Code), invoice generation with QR verification code, digital signature with ADSIB certificate, SIAT online submission or offline contingency mode with subsequent synchronization. Integrates the complete cycle: issuance, signing, transmission, receipt verification, and cancellation. What is it for? Complying with fiscal obligations for electronic invoice issuance for commercial transactions within Bolivia, enabling tax deduction and automatic accounting records. How is it used? Each completed commercial transaction triggers the invoice generator; the engine applies SIAT encoding, signs with ADSIB, and transmits to SIN; the result (SIAT control code) is stored linked to the transaction. Why? Bolivia Law 843 and SIN RND 102100000011 require electronic invoicing for all commercial transactions; without this active block the system cannot operate commercially in Bolivia. Standards: SIN RND 102100000011, Bolivia Law 843 Art. 70, ISO 20022, UBL 2.1, Law 164 Art. 15 (digital signature).", "es": "Facturación Electrónica · billing. ¿Qué es? Motor de generación y transmisión de documentos fiscales electrónicos conforme a la normativa SIN Bolivia (SIAT): CUIS (Código Único de Inicio de Sistema), CUFD (Código Único de Facturación Diaria), generación de facturas con código QR de verificación, firma digital con certificado ADSIB, envío al SIAT en línea o modo contingencia offline con sincronización posterior. Integra el ciclo completo: emisión, firma, transmisión, verificación de recepción y anulación. ¿Para qué sirve? Cumplir con las obligaciones fiscales de emisión de facturas electrónicas para transacciones comerciales dentro de Bolivia, habilitando la deducción fiscal y el registro contable automático. ¿Cómo se usa? Cada transacción comercial completada activa el generador de factura; el motor aplica la codificación SIAT, firma con ADSIB y transmite al SIN; el resultado (código de control SIAT) se almacena vinculado a la transacción. ¿Por qué? La Ley 843 Bolivia y el SIN RND 102100000011 exigen factura electrónica para toda transacción comercial; sin este bloque activo el sistema no puede operar comercialmente en Bolivia. Normas: SIN RND 102100000011, Ley 843 Bolivia Art. 70, ISO 20022, UBL 2.1, Ley 164 Art. 15 (firma digital)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.billing', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'billing', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f72f-727e-b070-f6dffafb4297', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "LTV Preservation", "es": "Preservación LTV"}', '{"en": "Long-Term Validation (LTV) — ETSI EN 319 102-2 §5.6 · RFC 3161 §3", "es": "Validación a Largo Plazo (LTV) — ETSI EN 319 102-2 §5.6 · RFC 3161 §3"}', NULL, '{"en": "Long-Term Validity (LTV) · long_term. What is it? Mechanism guaranteeing the validity and verifiability of digital signatures long-term (beyond the validity period of the original signing certificate): packages the digital signature with the complete certificate chain (to the root CA), non-revocation evidence at the time of signing (OCSP response or CRL snapshot), and a periodically nested RFC 3161 timestamp over the set (Archive Timestamp — ETSI EN 319 122). When original cryptographic algorithms weaken over time, a new timestamp with stronger algorithms is added before the previous ones become vulnerable. What is it for? Ensuring a document signed today can be cryptographically verified in 20 or 50 years, even if the original RSA-2048 algorithm were considered vulnerable in the future, by having the timestamp with the document hash signed with stronger algorithms. How is it used? When generating a digital signature with long-term legal effects, the LTV engine automatically adds the certificate chain, OCSP snapshot, and first timestamp; a periodic automatic process checks whether the algorithms used are near obsolescence and adds a new timestamp with current algorithms if needed. Why? Legal documents (contracts, deeds, judgments) have effects for decades; without LTV, a valid signature today may be invalid in 10 years if the CA certificate expired; with LTV, the signature maintains its evidentiary validity indefinitely. Standards: ETSI EN 319 102-2 §4, RFC 4998/6283 Evidence Record, RFC 3161 Timestamping, eIDAS 2.0 Annex I.", "es": "Conservación a Largo Plazo (LTV) · long_term. ¿Qué es? Mecanismo que garantiza la validez y verificabilidad de las firmas digitales a largo plazo (más allá del período de validez del certificado de firma original): empaqueta la firma digital con la cadena completa de certificados (hasta la CA raíz), la evidencia de no-revocación al momento de la firma (respuesta OCSP o CRL snapshot), y un sello de tiempo RFC 3161 anidado periódicamente sobre el conjunto (Archive Timestamp — ETSI EN 319 122). Cuando los algoritmos criptográficos originales se debilitan con el tiempo, se añade un nuevo sello de tiempo con algoritmos más fuertes antes de que los anteriores sean vulnerables. ¿Para qué sirve? Garantizar que un documento firmado hoy pueda ser verificado criptográficamente dentro de 20 o 50 años, incluso si el algoritmo RSA-2048 original fuera considerado vulnerable en el futuro, al tener el sello de tiempo con el hash del documento firmado con algoritmos más fuertes. ¿Cómo se usa? Al generar una firma digital con efectos jurídicos a largo plazo, el motor LTV añade automáticamente la cadena de certificados, el OCSP snapshot y el primer sello de tiempo; un proceso automático periódico verifica si los algoritmos usados están próximos a ser obsoletos y añade un nuevo sello de tiempo con algoritmos actuales si es necesario. ¿Por qué? Los documentos legales (contratos, escrituras, sentencias) tienen efectos durante décadas; sin LTV, una firma válida hoy puede ser inválida en 10 años si el certificado de la CA expiró; con LTV, la firma mantiene su validez probatoria indefinidamente. Normas: ETSI EN 319 102-2 §4, RFC 4998/6283 Evidence Record, RFC 3161 Timestamping, eIDAS 2.0 Annex I."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.long_term', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'long_term', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f73b-7fe8-8bee-27b70955c0b7', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Privileged Account Inventory", "es": "Inventario de Cuentas Privilegiadas"}', '{"en": "Privileged Account Inventory — NIST SP 800-53 R5 AC-2(7) · CIS Controls v8 §5.1", "es": "Inventario de Cuentas Privilegiadas — NIST SP 800-53 R5 AC-2(7) · CIS Controls v8 §5.1"}', NULL, '{"en": "Privileged Account Discovery · discovery. What is it? Inventory and automatic discovery engine for elevated-privilege accounts in the SBOS ecosystem and systems under its management: periodically scans databases, servers, applications, and devices to detect administrator-permission accounts (root accounts, service accounts with production access, users with SSH access to critical servers, Oracle SYSDBA accounts, SQL Server SA accounts) not registered in the PAM inventory and under bAuth control. What is it for? Ensuring no \"shadow\" privileged accounts exist outside PAM system control: uninventoried privileged accounts are the most dangerous because they have no password rotation, no session monitoring, and are not subject to privileged access controls. How is it used? The discovery engine runs periodic scans (weekly for critical systems); uses read-only audit credentials to enumerate accounts; compares results with the current PAM inventory; generates an \"orphan accounts\" report — privileged but outside PAM; the security team reviews and onboards each discovered account into PAM. Why? No organization can secure what it does not know; uninventoried privileged accounts represent invisible attack vectors; periodic discovery ensures the PAM inventory reflects the reality of all existing privileges. Standards: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5.1, ISO 27001 A.8.1, PCI DSS 4.0 Req 7.1.", "es": "Descubrimiento de Cuentas Privilegiadas · discovery. ¿Qué es? Motor de inventario y descubrimiento automático de cuentas con privilegios elevados en el ecosistema SBOS y los sistemas bajo su gestión: escanea periódicamente las bases de datos, servidores, aplicaciones y dispositivos para detectar cuentas con permisos de administrador (cuentas root, cuentas de servicio con acceso a producción, usuarios con acceso SSH a servidores críticos, cuentas Oracle SYSDBA, cuentas SA de SQL Server) que no estén registradas en el inventario PAM y bajo control de bAuth. ¿Para qué sirve? Garantizar que no existen cuentas privilegiadas \"en la sombra\" fuera del control del sistema PAM: las cuentas privilegiadas no inventariadas son las más peligrosas porque no tienen rotación de contraseñas, no tienen monitoreo de sesiones y no están sujetas a los controles de acceso privilegiado. ¿Cómo se usa? El motor de descubrimiento ejecuta escaneos periódicos (semanales para sistemas críticos); usa credenciales de auditoría de solo lectura para enumerar cuentas; compara el resultado con el inventario PAM actual; genera un informe de \"cuentas huérfanas\" — privilegiadas pero fuera del PAM; el equipo de seguridad revisa y onboarda cada cuenta descubierta al PAM. ¿Por qué? Ninguna organización puede asegurar lo que no conoce; las cuentas privilegiadas no inventariadas representan vectores de ataque invisibles; el descubrimiento periódico garantiza que el inventario PAM refleja la realidad de todos los privilegios existentes. Normas: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5.1, ISO 27001 A.8.1, PCI DSS 4.0 Req 7.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.discovery', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'discovery', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4c5-7161-8a3b-99d52485a5d0', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Transactional Limits", "es": "Límites Transaccionales"}', '{"en": "Transactional Limits — PCI DSS 4.0 Req 8.2 · NIST SP 800-53 R5 AC-2(6)", "es": "Límites Transaccionales — PCI DSS 4.0 Req 8.2 · NIST SP 800-53 R5 AC-2(6)"}', NULL, '{"en": "Transactional Limits · limits. What is it? Configurable matrix of monetary and frequency limits by role, operation type, channel, and period: per-transaction limit (maximum 10,000 USD per operation), daily limit (maximum 50,000 USD/day), monthly limit, counterparty type limit, and channel limit (transfer, check, card). Limits are hierarchical: the role limit can never exceed the tier limit, nor the tier limit the tenant limit. What is it for? Bounding the maximum possible damage from a compromised credential or human error: even if the attacker controls the account, they cannot extract more than the configured limit without triggering alerts or requiring additional approval. How is it used? Before executing a financial operation, the engine verifies the initiator''s role limits across all dimensions (amount, frequency, channel); if any is exceeded, the operation is blocked or escalated for approval. Why? Transactional limits are the primary financial damage containment mechanism; without them a compromised credential can drain an account in seconds. Standards: PCI DSS 4.0 Req 8.2, NIST SP 800-53 R5 AC-2(6), SWIFT CSCF v2024 §6, ISO 27001 A.5.15.", "es": "Límites Transaccionales · limits. ¿Qué es? Matriz configurable de límites monetarios y de frecuencia por rol, tipo de operación, canal y período: límite por transacción única (máximo 10.000 USD por operación), límite diario (máximo 50.000 USD/día), límite mensual, límite por tipo de contraparte y límite por canal (transferencia, cheque, tarjeta). Los límites son jerárquicos: el límite del rol nunca puede superar el límite del tier, ni el del tier el del tenant. ¿Para qué sirve? Acotar el daño máximo posible ante una credencial comprometida o un error humano: aunque el atacante controle la cuenta, no puede extraer más del límite configurado sin activar alertas o requerir aprobación adicional. ¿Cómo se usa? Antes de ejecutar una operación financiera, el motor verifica los límites del rol del iniciador en todas las dimensiones (monto, frecuencia, canal); si alguno se supera, la operación se bloquea o escala a aprobación. ¿Por qué? Los límites transaccionales son el principal mecanismo de contención de daños financieros; sin ellos una credencial comprometida puede vaciar una cuenta en segundos. Normas: PCI DSS 4.0 Req 8.2, NIST SP 800-53 R5 AC-2(6), SWIFT CSCF v2024 §6, ISO 27001 A.5.15."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.limits', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'limits', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f703-7fae-9a16-ba78c09e60d4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "QBFT Consensus", "es": "Consenso QBFT"}', '{"en": "QBFT Consensus — Hyperledger Besu §4 · EIP-225", "es": "Consenso QBFT — Hyperledger Besu §4 · EIP-225"}', NULL, '{"en": "Blockchain Consensus & Governance · consensus. What is it? Management of the SBOS node''s participation in the ecosystem''s Besu network consensus mechanism: validator node configuration (IBFT 2.0 — Istanbul BFT, tolerant up to f=(n-1)/3 byzantine nodes), node validation key management (ECDSA secp256k1 key stored in HSM), consensus state monitoring (rounds, proposals, votes, finalized blocks), and on-chain governance participation (voting to add or remove validators from quorum). What is it for? Maintaining the SBOS ecosystem''s participation in the private blockchain network consensus backing decentralized identities and audit anchors: validator node health determines the availability of ecosystem blockchain operations. How is it used? The consensus monitor periodically verifies the node''s state in the Besu network; if the node loses consensus participation (does not receive block proposals), it generates an alert and activates network diagnostics; governance decisions (adding new validators) require multi-administrator approval and execute via governance contract. Why? Without active consensus participation, the SBOS node becomes a passive observer without ability to influence validation of transactions affecting ecosystem identities; active governance ensures the ecosystem maintains its technical sovereignty. Standards: IBFT 2.0 §4, Ethereum Yellow Paper §11, NIST SP 800-53 R5 SC-28, CIS Controls v8 §4.", "es": "Consenso y Gobernanza Blockchain · consensus. ¿Qué es? Gestión de la participación del nodo SBOS en el mecanismo de consenso de la red Besu del ecosistema: configuración del nodo validador (IBFT 2.0 — Istanbul BFT, tolerante a hasta f=(n-1)/3 nodos byzantinos), gestión de las claves de validación del nodo (clave ECDSA secp256k1 almacenada en HSM), monitoreo del estado de consenso (rondas, propuestas, votos, bloques finalizados), y participación en la gobernanza on-chain (votación para añadir o expulsar validadores del quórum). ¿Para qué sirve? Mantener la participación del ecosistema SBOS en el consenso de la red blockchain privada que respalda las identidades descentralizadas y los anclajes de auditoría: la salud del nodo validador determina la disponibilidad de las operaciones blockchain del ecosistema. ¿Cómo se usa? El monitor de consenso verifica periódicamente el estado del nodo en la red Besu; si el nodo pierde participación en el consenso (no recibe propuestas de bloque), genera alerta y activa el diagnóstico de red; las decisiones de gobernanza (añadir nuevos validadores) requieren aprobación multi-administrador y se ejecutan vía contrato de gobernanza. ¿Por qué? Sin participación activa en el consenso, el nodo SBOS pasa a ser un observador pasivo sin capacidad de influir en la validación de las transacciones que afectan a las identidades del ecosistema; la gobernanza activa garantiza que el ecosistema mantiene su soberanía técnica. Normas: IBFT 2.0 §4, Ethereum Yellow Paper §11, NIST SP 800-53 R5 SC-28, CIS Controls v8 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.consensus', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'consensus', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f71c-70dc-990a-dbebf6784e4d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "Document Signing", "es": "Firma de Documentos"}', '{"en": "Document Signing — PAdES EN 319 132 · CAdES EN 319 122 · XAdES EN 319 132", "es": "Firma de Documentos — PAdES EN 319 132 · CAdES EN 319 122 · XAdES EN 319 132"}', NULL, '{"en": "Digital Signature Engine · signing. What is it? Digital signature engine implementing the two SBOS ecosystem signature engines: internal engine (EdDSA Ed25519 with Vault as HSM — for JWTs, verifiable credentials, and blockchain anchors) and external engine (RSA-SHA256 with ADSIB certificate — for electronic invoices, contracts with Bolivian legal validity Law 164, and public administration documents). The engine automatically selects the appropriate signature engine based on document type and destination. What is it for? Providing secure digital signature operations for all ecosystem use cases: internal EdDSA Ed25519 signing offers superior performance and long-term quantum resistance; external RSA-SHA256 signing with ADSIB provides legal validity before the Bolivian state. How is it used? The requesting module indicates the required signature type (internal/external) and content to sign; the engine accesses the corresponding key in Vault (never extracts the key — the signature is calculated inside the HSM); returns the signature and signer certificate; the module attaches both to the document. Why? The two signature engines serve two different audiences: internal signing is for the SBOS ecosystem and systems trusting bAuth''s CA; external signing is for the Bolivian regulatory world that recognizes only ADSIB-authorized CAs. Standards: RFC 8037 EdDSA, RFC 4055 RSA-SHA256, Bolivia Law 164 Art. 15, ADSIB-FD-POLT-015, ETSI EN 319 132.", "es": "Motor de Firma Digital · signing. ¿Qué es? Motor de firma digital que implementa los dos motores de firma del ecosistema SBOS: motor interno (EdDSA Ed25519 con Vault como HSM — para JWTs, credenciales verificables y anclajes blockchain) y motor externo (RSA-SHA256 con certificado ADSIB — para facturas electrónicas, contratos con validez jurídica boliviana Ley 164 y documentos ante la administración pública). El motor selecciona automáticamente el motor de firma apropiado según el tipo de documento y su destino. ¿Para qué sirve? Proporcionar operaciones de firma digital seguras para todos los casos de uso del ecosistema: la firma interna EdDSA Ed25519 ofrece rendimiento superior y resistencia cuántica a largo plazo; la firma externa RSA-SHA256 con ADSIB proporciona validez jurídica ante el Estado boliviano. ¿Cómo se usa? El módulo solicitante indica el tipo de firma requerida (interna/externa) y el contenido a firmar; el motor accede a la clave correspondiente en Vault (nunca extrae la clave — la firma se calcula dentro del HSM); retorna la firma y el certificado del firmante; el módulo adjunta ambos al documento. ¿Por qué? Los dos motores de firma atienden a dos audiencias distintas: la firma interna es para el ecosistema SBOS y los sistemas que confían en la CA de bAuth; la firma externa es para el mundo regulatorio boliviano que reconoce únicamente las CAs autorizadas por ADSIB. Normas: RFC 8037 EdDSA, RFC 4055 RSA-SHA256, Ley 164 Bolivia Art. 15, ADSIB-FD-POLT-015, ETSI EN 319 132."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.signing', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'signing', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f74b-7708-82d5-fef6591b467a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Privileged Session Brokering", "es": "Mediación de Sesión Privilegiada"}', '{"en": "Privileged Session Brokering — NIST SP 800-53 R5 AC-17(9) · ISO 27001 A.5.18", "es": "Mediación de Sesión Privilegiada — NIST SP 800-53 R5 AC-17(9) · ISO 27001 A.5.18"}', NULL, '{"en": "Identity Brokering · brokering. What is it? Identity federation engine acting as intermediary between external identity providers (IdP) and SBOS ecosystem services: when an external user wants to access an SBOS resource using their Google, Microsoft Entra, ADSIB, or other external IdP identity, the broker receives the external IdP token, validates it, maps external identities and claims to the SBOS identity structure, and issues a standard SBOS JWT for the user. What is it for? Allowing users with identities at external providers to access SBOS ecosystem resources without creating a native SBOS account, mapping their external roles and attributes to the SBOS identity structure in a controlled and audited manner. How is it used? The administrator configures the external IdP as a \"trusted broker\" indicating claim mapping (the external IdP `email` claim maps to the SBOS `upn` attribute); when the user logs in with their external IdP, the broker receives the callback, validates the external token, applies the mapping, and issues the equivalent SBOS JWT; the audit log records federated access with the original external identity. Why? Organizations have multiple identity systems; brokering allows integrating all identity sources without forcing users to maintain multiple passwords, while SBOS maintains complete control over which roles are assigned to federated identities. Standards: OpenID Connect Core §5, SAML 2.0 §4, RFC 7591 Dynamic Client Registration, NIST SP 800-63B-4 §5.3.", "es": "Intermediación de Identidad (Brokering) · brokering. ¿Qué es? Motor de federación de identidad que actúa como intermediario entre los proveedores de identidad externos (IdP — Identity Providers) y los servicios del ecosistema SBOS: cuando un usuario externo quiere acceder a un recurso SBOS usando su identidad de Google, Microsoft Entra, ADSIB u otro IdP externo, el broker recibe el token del IdP externo, lo valida, mapea las identidades y claims externos a la estructura de identidad SBOS, y emite un JWT SBOS estándar para el usuario. ¿Para qué sirve? Permitir que usuarios con identidades en proveedores externos puedan acceder a recursos del ecosistema SBOS sin necesidad de crear una cuenta SBOS nativa, mapeando sus roles y atributos externos a la estructura de identidad SBOS de forma controlada y auditada. ¿Cómo se usa? El administrador configura el IdP externo como \"trusted broker\" indicando el mapping de claims (el claim `email` del IdP externo se mapea al atributo `upn` de SBOS); cuando el usuario inicia sesión con su IdP externo, el broker recibe el callback, valida el token externo, aplica el mapping y emite el JWT SBOS equivalente; el log de auditoría registra el acceso federado con la identidad externa original. ¿Por qué? Las organizaciones tienen múltiples sistemas de identidad; el brokering permite integrar todas las fuentes de identidad sin forzar a los usuarios a mantener múltiples contraseñas, mientras SBOS mantiene control completo sobre qué roles se asignan a las identidades federadas. Normas: OpenID Connect Core §5, SAML 2.0 §4, RFC 7591 Dynamic Client Registration, NIST SP 800-63B-4 §5.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.brokering', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'brokering', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f75e-7f85-b33b-bd3cfd2f244a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Session Recording", "es": "Grabación de Sesión"}', '{"en": "Privileged Session Recording — NIST SP 800-53 R5 AU-14 · ISO 27001 A.8.20", "es": "Grabación de Sesión Privilegiada — NIST SP 800-53 R5 AU-14 · ISO 27001 A.8.20"}', NULL, '{"en": "Privileged Session Recording · session_recording. What is it? Complete recording system for privileged access sessions: capture of all session traffic (keystrokes, commands, server responses, file transfers) in a reproducible format that can be reviewed by the audit team; recording is automatic, cannot be disabled by the privileged user, and is hash-sealed upon completion to guarantee integrity. Sessions can be replayed frame by frame to reconstruct exactly what the administrator did. What is it for? Creating an inviolable record of exactly what actions each administrator took during each privileged session: session recording is the primary forensic investigation tool for a security incident involving privileged access and the primary deterrent against privilege abuse by administrators. How is it used? All privileged access sessions go through bAuth''s PAM proxy; the proxy records traffic in real time to the recording store; recordings are indexed by user, system, date, and duration; the auditor can search recordings by criteria and replay them; recordings are retained per retention policy (minimum 1 year, SOX 7 years for financial sessions). Why? Without session recording, \"what did the administrator do during the incident?\" has no objective answer; with complete recording, forensic analysis can determine exactly which commands, files, and data the administrator affected. Standards: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5.5, ISO 27001 A.8.15, PCI DSS 4.0 Req 10.2.", "es": "Grabación de Sesiones Privilegiadas · session_recording. ¿Qué es? Sistema de grabación completa de las sesiones de acceso privilegiado: captura de todo el tráfico de la sesión (keystrokes, comandos, respuestas del servidor, transferencias de archivos) en formato reproducible que puede ser revisado por el equipo de auditoría; la grabación es automática, no puede ser desactivada por el usuario privilegiado, y es sellada con hash al finalizar para garantizar su integridad. Las sesiones se pueden reproducir frame a frame para reconstruir exactamente qué hizo el administrador. ¿Para qué sirve? Crear un registro inviolable de exactamente qué acciones tomó cada administrador durante cada sesión privilegiada: la grabación de sesiones es la principal herramienta de investigación forense ante un incidente de seguridad que involucre acceso privilegiado y el principal disuasivo contra el abuso de privilegios por parte de administradores. ¿Cómo se usa? Toda sesión de acceso privilegiado va a través del proxy PAM de bAuth; el proxy graba el tráfico en tiempo real en el almacén de grabaciones; la grabación se indexa por usuario, sistema, fecha y duración; el auditor puede buscar grabaciones por criterio y reproducirlas; las grabaciones se retienen según la política de retención (mínimo 1 año, SOX 7 años para sesiones financieras). ¿Por qué? Sin grabación de sesiones, \"¿qué hizo el administrador durante el incidente?\" no tiene respuesta objetiva; con grabación completa, el análisis forense puede determinar exactamente qué comandos, qué archivos y qué datos afectó el administrador. Normas: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5.5, ISO 27001 A.8.15, PCI DSS 4.0 Req 10.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.session_recording', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'session_recording', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f76b-714e-aebf-c6b012420a96', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "Service Accounts", "es": "Cuentas de Servicio"}', '{"en": "Service Accounts — NIST SP 800-53 R5 AC-2(9) · CIS Controls v8 §5.6", "es": "Cuentas de Servicio — NIST SP 800-53 R5 AC-2(9) · CIS Controls v8 §5.6"}', NULL, '{"en": "Service Account · service_account. What is it? Non-human identity assigned to an SBOS ecosystem service, process, or application to authenticate and perform operations on its behalf: each service account has a canonical name (e.g., `svc-biedata-readonly`), a responsible human owner, a declared minimum access scope (access only to resources the service needs to function), and automatically rotated credentials. Service accounts differ from user accounts: they have no password a human knows, cannot be used in interactive interfaces, and have a much more limited operational scope. What is it for? Giving each ecosystem process its own identity so its actions are attributable to that specific process in the audit log, and so the least privilege principle applies at the process level: biedata does not need the same permissions as bkernel. How is it used? When deploying a new service, its service account is created in bAuth with the minimum necessary scope; the service authenticates using Vault AppRole or its SPIFFE SVID; Vault manages and automatically rotates credentials; the audit log attributes each service operation to its service account, not to \"system\" generically. Why? Processes authenticating as human users contaminate the audit log (it is impossible to distinguish what the human did from what the automated process did); service accounts separate human from automated traceability. Standards: NIST SP 800-53 R5 IA-2(6), SPIFFE/SPIRE §3, CIS Controls v8 §5.6, ISO 27001 A.8.1.", "es": "Cuenta de Servicio · service_account. ¿Qué es? Identidad no humana asignada a un servicio, proceso o aplicación del ecosistema SBOS para autenticarse y realizar operaciones en su nombre: cada cuenta de servicio tiene un nombre canónico (ej: `svc-biedata-readonly`), un propietario humano responsable, un scope de acceso declarado y mínimo (acceso solo a los recursos que el servicio necesita para funcionar), y credenciales rotadas automáticamente. Las cuentas de servicio son diferentes de las cuentas de usuario: no tienen contraseña que un humano conozca, no se pueden usar en interfaces interactivas, y tienen scope operativo mucho más limitado. ¿Para qué sirve? Dar identidad propia a cada proceso del ecosistema para que sus acciones sean atribuibles a ese proceso específico en el log de auditoría, y para que el principio de mínimo privilegio se aplique a nivel de proceso: biedata no necesita los mismos permisos que bkernel. ¿Cómo se usa? Al desplegar un nuevo servicio, se crea su cuenta de servicio en bAuth con el scope mínimo necesario; el servicio se autentica usando AppRole de Vault o su SVID SPIFFE; las credenciales las gestiona Vault y las rota automáticamente; el log de auditoría atribuye cada operación del servicio a su cuenta de servicio, no a \"sistema\" de forma genérica. ¿Por qué? Los procesos que se autentican como usuarios humanos contaminan el log de auditoría (es imposible distinguir qué hizo el humano de lo que hizo el proceso automatizado); las cuentas de servicio separan la trazabilidad humana de la automatizada. Normas: NIST SP 800-53 R5 IA-2(6), SPIFFE/SPIRE §3, CIS Controls v8 §5.6, ISO 27001 A.8.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.service_account', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'service_account', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f727-75f9-b5d8-5d334e1f70c3', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "Timestamp (TSA)", "es": "Sello de Tiempo (TSA)"}', '{"en": "Timestamp Authority (TSA) — RFC 3161 §2 · ETSI EN 319 421 · Ley 164 Art. 20", "es": "Autoridad de Sello de Tiempo (TSA) — RFC 3161 §2 · ETSI EN 319 421 · Ley 164 Art. 20"}', NULL, '{"en": "Timestamping · timestamping. What is it? Trusted Stamp Authority (TSA) timestamping service compliant with RFC 3161: given the hash of a document or event, the TSA issues a timestamp token containing the hash, the TSA-certified issuance time, and the TSA''s digital signature over both. The timestamp is cryptographic proof that the document existed in its current form at the indicated moment, independently of the document signature itself. What is it for? Providing irrefutable proof of the exact moment a document was created, signed, or processed: the RFC 3161 timestamp token issued by an accredited TSA (such as ADSIB) has evidentiary validity before Bolivian courts and can be verified by any third party without internal system access. How is it used? When generating a legally effective document or writing a critical audit event, the engine requests a timestamp from the TSA over the document hash; the TSA returns the stamp token (SignedData); the token is attached to the document or event; audit reports and legal documents include the token for independent verification. Why? Without a timestamp, a defendant can claim the document was modified or created post-hoc; the accredited TSA timestamp closes this possibility by mathematically proving the document in its current form existed before the stamp date. Standards: RFC 3161 TSP, ETSI EN 319 422, Bolivia Law 164 Art. 12, ETSI EN 319 401 §4.", "es": "Sellado de Tiempo · timestamping. ¿Qué es? Servicio de sellado de tiempo confiable (TSA — Trusted Stamp Authority) conforme a RFC 3161: dado el hash de un documento o evento, la TSA emite un token de sello de tiempo que contiene el hash, el tiempo de emisión certificado por la TSA, y la firma digital de la TSA sobre ambos. El sello de tiempo es prueba criptográfica de que el documento existía en su forma actual en el momento indicado, independientemente de la firma del documento mismo. ¿Para qué sirve? Proveer prueba irrefutable del momento exacto en que un documento fue creado, firmado o procesado: el sello de tiempo RFC 3161 emitido por una TSA acreditada (como ADSIB) tiene validez probatoria ante tribunales bolivianos y puede ser verificado por cualquier tercero sin acceso al sistema interno. ¿Cómo se usa? Al generar un documento con efectos jurídicos o al escribir un evento de auditoría crítico, el motor solicita a la TSA un sello de tiempo sobre el hash del documento; la TSA retorna el token de sello (SignedData); el token se adjunta al documento o evento; los informes de auditoría y los documentos legales incluyen el token para su verificación independiente. ¿Por qué? Sin sello de tiempo, un demandado puede alegar que el documento fue modificado o creado post-hoc; el sello de tiempo con TSA acreditada cierra esta posibilidad al probar matemáticamente que el documento en su forma actual existía antes de la fecha del sello. Normas: RFC 3161 TSP, ETSI EN 319 422, Ley 164 Bolivia Art. 12, ETSI EN 319 401 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.timestamping', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'timestamping', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f504-7b23-9dac-52b8ffe4137b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Open Banking / FAPI 2.0", "es": "Banca Abierta / FAPI 2.0"}', '{"en": "Open Banking / FAPI 2.0 — FAPI 2.0 Security Profile · RFC 9449 · PSD2 Art. 98", "es": "Banca Abierta / FAPI 2.0 — FAPI 2.0 Security Profile · RFC 9449 · PSD2 Art. 98"}', NULL, '{"en": "Open Banking / FAPI 2.0 · open_banking. What is it? Implementation of the FAPI 2.0 (Financial-grade API Security Profile) for exposing financial APIs to authorized third parties (TPP — Third Party Providers) under the PSD2/Open Finance open banking model: TPP authentication with mTLS (RFC 8705), user authorization with DPoP (RFC 9449), granular consent by data type and financial operation, and complete traceability of each third-party access. What is it for? Allowing the tenant to expose their financial data to user-authorized third-party applications (account aggregators, payment apps) securely and audited, complying with open banking regulations. How is it used? The TPP registers as an OAuth client with an OIDC certificate; the user granularly consents to which data they share and for how long; each TPP call carries mTLS + DPoP; the system records all TPP accesses in the audit log. Why? Without FAPI 2.0, third-party integrations are insecure or fail to comply with open banking regulations; FAPI 2.0 is the financial industry standard for high-risk APIs. Standards: FAPI 2.0 Security Profile, RFC 9449 DPoP, RFC 8705 mTLS, PSD2 Art. 98, ISO 20022.", "es": "Banca Abierta / FAPI 2.0 · open_banking. ¿Qué es? Implementación del perfil de seguridad FAPI 2.0 (Financial-grade API Security Profile) para exposición de APIs financieras a terceros autorizados (TPP — Third Party Providers) bajo el modelo de banca abierta PSD2/Open Finance: autenticación del TPP con mTLS (RFC 8705), autorización del usuario con DPoP (RFC 9449), consentimiento granular por tipo de dato y operación financiera, y trazabilidad completa de cada acceso de tercero. ¿Para qué sirve? Permitir que el tenant exponga sus datos financieros a aplicaciones de terceros autorizados por el usuario (agregadores de cuentas, apps de pagos) de forma segura y auditada, cumpliendo regulaciones de banca abierta. ¿Cómo se usa? El TPP se registra como cliente OAuth con certificado OIDC; el usuario consiente granularmente qué datos comparte y por cuánto tiempo; cada llamada del TPP lleva mTLS + DPoP; el sistema registra todos los accesos del TPP en el log de auditoría. ¿Por qué? Sin FAPI 2.0, las integraciones con terceros son inseguras o no cumplen las regulaciones de banca abierta; FAPI 2.0 es el estándar de la industria financiera para APIs de alto riesgo. Normas: FAPI 2.0 Security Profile, RFC 9449 DPoP, RFC 8705 mTLS, PSD2 Art. 98, ISO 20022."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.open_banking', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'open_banking', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f778-7ba1-85f8-7e586b534955', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "AI Agent Identity", "es": "Identidad de Agentes IA"}', '{"en": "AI Agent Identity — NIST AI RMF 1.0 §3 · CSA NHI Security 2025", "es": "Identidad de Agentes de Inteligencia Artificial — NIST AI RMF 1.0 §3 · CSA NHI Security 2025"}', NULL, '{"en": "AI/Automation Agent Identity · agent. What is it? Identity and access control for AI agents and automation processes acting on behalf of human users or autonomously: each AI agent has a registered non-human identity (with its own attributes, declared capabilities, and restrictions), an agent token with explicit declared scope (the agent can only do what its scope declares, nothing more), and a record of all actions taken by the agent (complete traceability of autonomous decisions). The agent can act on behalf of a human user with a delegation token, or autonomously with its own identity. What is it for? Applying identity and access control principles to AI and RPA (Robotic Process Automation) agents operating within the SBOS ecosystem, ensuring no agent has more permissions than declared in its registry and all its actions are traceable. How is it used? When registering an agent, its capabilities and maximum requestable scope are declared; the agent authenticates with its own identity (SPIFFE certificate or rotating API key); requests tokens with the minimum necessary scope for each task; the audit log records each agent action with its identity and the task''s ctx_id. Why? AI agents without identity control are privilege escalation vectors: an agent that can act on behalf of any user, with any permission, without leaving a trace, is a catastrophic risk; agent identity applies the same controls as to humans. Standards: NIST SP 800-53 R5 AC-2, NIST AI RMF 1.0 §2.6, SPIFFE/SPIRE §3, OAuth 2.0 Client Credentials.", "es": "Agente de Identidad (AI/Automatización) · agent. ¿Qué es? Identidad y control de acceso para agentes de IA y procesos de automatización que actúan en nombre de usuarios humanos o de forma autónoma: cada agente de IA tiene una identidad no-humana registrada (con sus propios atributos, capacidades declaradas y restricciones), un token de agente con scope declarado explícito (el agente solo puede hacer lo que su scope declara, nada más), y un registro de todas las acciones tomadas por el agente (trazabilidad completa de decisiones autónomas). El agente puede actuar en nombre de un usuario humano con token de delegación, o de forma autónoma con su identidad propia. ¿Para qué sirve? Aplicar los principios de identidad y control de acceso a los agentes de IA y RPA (Robotic Process Automation) que operan dentro del ecosistema SBOS, garantizando que ningún agente tiene más permisos de los declarados en su registro y que todas sus acciones son trazables. ¿Cómo se usa? Al registrar un agente, se declaran sus capacidades y el scope máximo que puede solicitar; el agente se autentica con su identidad propia (certificado SPIFFE o API key rotativa); solicita tokens con el scope mínimo necesario para cada tarea; el log de auditoría registra cada acción del agente con su identidad y el ctx_id de la tarea. ¿Por qué? Los agentes de IA sin control de identidad son vectores de escalada de privilegios: un agente que puede actuar en nombre de cualquier usuario, con cualquier permiso, sin dejar rastro, es un riesgo catastrófico; la identidad de agente aplica los mismos controles que a humanos. Normas: NIST SP 800-53 R5 AC-2, NIST AI RMF 1.0 §2.6, SPIFFE/SPIRE §3, OAuth 2.0 Client Credentials."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.agent', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'agent', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f785-7e6e-9072-0e2961596c99', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "Automatic Rotation", "es": "Rotación Automática"}', '{"en": "Automatic Credential Rotation — NIST SP 800-57 Pt1 R5 §5.3 · CIS Controls v8 §4.4", "es": "Rotación Automática de Credenciales — NIST SP 800-57 Pt1 R5 §5.3 · CIS Controls v8 §4.4"}', NULL, '{"en": "Service Credential Rotation · rotation. What is it? Automatic credential rotation engine for non-human identities per configurable policies by type: service account passwords (automatic daily rotation without service interruption), external integration API tokens (rotation with overlap: the new token is created, distributed, and activated before revoking the previous one), server SSH keys (monthly rotation with 24-hour grace period for dependent system updates), and SPIFFE SVIDs (hourly rotation — automatic, managed by the SPIRE agent without intervention). What is it for? Limiting the useful life of each compromised credential to the rotation period: if a service credential is extracted from traffic or memory, the attacker will have it for at most the rotation period before it loses validity. How is it used? The rotation engine maintains the rotation calendar for each NHI; executes rotation automatically on the configured period; for high-availability credentials, rotation is atomic (the new secret is registered in Vault before invalidating the previous one); systems using the credential read it dynamically from Vault on each use (never cache it permanently). Why? Static credentials that never rotate are the most vulnerable: if they leaked a year ago in a breach nobody detected, they are still valid today; rotation ensures any compromised credential has a limited usage window. Standards: NIST SP 800-63B-4 §5.6, CIS Controls v8 §5.3, ISO 27001 A.5.17, PCI DSS 4.0 Req 8.3.9.", "es": "Rotación de Credenciales de Servicio · rotation. ¿Qué es? Motor de rotación automática de credenciales de identidades no humanas según políticas configurables por tipo: contraseñas de cuentas de servicio (rotación diaria automática sin interrupción del servicio), tokens de API de integraciones externas (rotación con overlap: el nuevo token se crea, se distribui y se activa antes de revocar el anterior), claves SSH de servidores (rotación mensual con período de gracia de 24h para actualización de sistemas dependientes), y SVIDs SPIFFE (rotación cada hora — automática, el agente SPIRE la gestiona sin intervención). ¿Para qué sirve? Limitar la vida útil de cada credencial comprometida al período de rotación: si una credencial de servicio es extraída del tráfico o de la memoria, el atacante la tendrá durante como máximo el período de rotación antes de que pierda validez. ¿Cómo se usa? El motor de rotación mantiene el calendario de rotación de cada NHI; ejecuta la rotación automáticamente en el período configurado; para credenciales de alta disponibilidad, la rotación es atómica (el nuevo secreto se registra en Vault antes de invalidar el anterior); los sistemas que usan la credencial la leen dinámicamente de Vault en cada uso (nunca la cachean permanentemente). ¿Por qué? Las credenciales estáticas que nunca rotan son las más vulnerables: si se filtraron hace un año en un breach que nadie detectó, siguen siendo válidas hoy; la rotación garantiza que cualquier credencial comprometida tiene una ventana de uso limitada. Normas: NIST SP 800-63B-4 §5.6, CIS Controls v8 §5.3, ISO 27001 A.5.17, PCI DSS 4.0 Req 8.3.9."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.rotation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'rotation', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f78e-7e11-af85-128f98769153', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "NHI Identity Governance", "es": "Gobierno de Identidades NHI"}', '{"en": "NHI Identity Governance — CSA NHI Security 2025 §4 · CIS Controls v8 §5", "es": "Gobierno de Identidades No Humanas — CSA NHI Security 2025 §4 · CIS Controls v8 §5"}', NULL, '{"en": "Non-Human Identity Governance · governance. What is it? Policy, process, and control framework governing the complete lifecycle of Non-Human Identities (NHI): centralized inventory of all ecosystem NHIs (name, responsible human owner, system it belongs to, active credentials, last rotation date, access scope), orphaned NHI detection (without active owner or unused for more than 90 days), periodic NHI access review (same as for humans but more frequently), and deprovisioning policy when the system or process the NHI belongs to is retired. What is it for? Ensuring no service identity, process account, or M2M integration exists without a responsible human owner who is accountable for its actions and credentials: orphaned NHIs are the preferred attack vector because nobody monitors them. How is it used? The NHI inventory updates automatically when identities are created or revoked; each NHI has an \"owner\" field that is an active human identity; if the owner leaves the organization, their NHIs enter urgent review; the quarterly governance process reviews all NHIs with the responsible owner to confirm they are still necessary. Why? NHIs without governance are the primary long-term access vector for attackers who compromise a system: an old unreviewed service credential can have production access for years after the original service was retired. Standards: NIST SP 800-53 R5 AC-2, CIS Controls v8 §5, ISO 27001 A.8.1, CIS Benchmark for NHI §3.", "es": "Gobernanza de Identidades No Humanas · governance. ¿Qué es? Marco de políticas, procesos y controles que gobiernan el ciclo de vida completo de las identidades no humanas (NHI): inventario centralizado de todas las NHI del ecosistema (nombre, propietario humano responsable, sistema al que pertenece, credenciales activas, fecha de última rotación, scope de acceso), detección de NHI huérfanas (sin propietario activo o sin uso en más de 90 días), revisión periódica de accesos de NHI (igual que para humanos pero con más frecuencia), y política de deprovisioning cuando el sistema o proceso al que pertenece la NHI es retirado. ¿Para qué sirve? Garantizar que ninguna identidad de servicio, cuenta de proceso o integración M2M existe sin un propietario humano responsable que sea accountable de sus acciones y credenciales: las NHI huérfanas son el vector de ataque preferido porque nadie las monitoriza. ¿Cómo se usa? El inventario de NHI se actualiza automáticamente al crear o revocar identidades; cada NHI tiene un campo \"propietario\" que es una identidad humana activa; si el propietario deja la organización, sus NHI entran en revisión urgente; el proceso de gobernanza trimestral revisa todas las NHI con el propietario responsable para confirmar que siguen siendo necesarias. ¿Por qué? Las NHI sin gobernanza son el principal vector de acceso a largo plazo para atacantes que comprometen un sistema: una credencial de servicio antigua sin revisar puede tener acceso a producción durante años después de que el servicio original fue retirado. Normas: NIST SP 800-53 R5 AC-2, CIS Controls v8 §5, ISO 27001 A.8.1, CIS Benchmark for NHI §3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.governance', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'governance', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7ab-781e-8c64-6bb0ab1692c1', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c96-7b9f-b9bc-e68dff0080fe', 'block', '{"en": "Tree Version Control", "es": "Control de Versiones del Árbol"}', '{"en": "Tree Version Control — ISO 9001:2015 §7.5 · ISO/IEC 24760-2:2025 §7", "es": "Control de Versiones del Árbol — ISO 9001:2015 §7.5 · ISO/IEC 24760-2:2025 §7"}', NULL, '{"en": "Catalog Versioning · versioning. What is it? Version control system for the role catalog and identity tree schema: each change in a role definition, addition of a new block, or schema modification generates a new catalog version with a semantic version number (MAJOR.MINOR.PATCH), change record (what was modified, who modified it, why, with what approval), and rollback capability to any previous version in under 5 minutes. Tenants can indicate which catalog version they are synchronized to. What is it for? Ensuring changes in the role catalog (affecting permissions of all ecosystem users) are traceable, approved, reversible, and coordinated: a change in the BIZ_N3 role definition affects hundreds of users; versioning ensures it can be reverted if it has unintended effects. How is it used? The catalog administrator proposes a change; the dual approval process validates it; the system generates the new catalog version with complete change record; all tenants receive change notification and have 24 hours to indicate if they have incompatibilities before the change propagates to production; if a tenant reports a problem, rollback executes in under 5 minutes. Why? Without catalog versioning, a change in a role definition can have cascading effects on all ecosystem tenants without possibility of diagnosis or fast reversion; versioning makes changes safe and coordinated. Standards: NIST SP 800-53 R5 CM-3, ISO 9001:2015 §7.5, ISO 27001 A.8.32, semver.org.", "es": "Versionado del Catálogo · versioning. ¿Qué es? Sistema de control de versiones del catálogo de roles y el esquema del árbol de identidad: cada cambio en la definición de un rol, la adición de un nuevo bloque o la modificación del esquema genera una nueva versión del catálogo con número de versión semántico (MAJOR.MINOR.PATCH), registro del cambio (qué se modificó, quién lo modificó, por qué, con qué aprobación), y capacidad de rollback a cualquier versión anterior en menos de 5 minutos. Los tenants pueden indicar a qué versión del catálogo están sincronizados. ¿Para qué sirve? Garantizar que los cambios en el catálogo de roles (que afectan a los permisos de todos los usuarios del ecosistema) son trazables, aprobados, reversibles y coordinados: un cambio en la definición del rol BIZ_N3 afecta a cientos de usuarios; el versionado garantiza que puede ser revertido si tiene efectos no deseados. ¿Cómo se usa? El administrador del catálogo propone un cambio; el proceso de aprobación dual lo valida; el sistema genera la nueva versión del catálogo con registro completo del cambio; todos los tenants reciben notificación del cambio y tienen 24 horas para indicar si tienen incompatibilidades antes de que el cambio se propague a producción; si algún tenant reporta un problema, el rollback se ejecuta en menos de 5 minutos. ¿Por qué? Sin versionado del catálogo, un cambio en la definición de un rol puede tener efectos en cascada sobre todos los tenants del ecosistema sin posibilidad de diagnóstico ni reversión rápida; el versionado hace los cambios seguros y coordinados. Normas: NIST SP 800-53 R5 CM-3, ISO 9001:2015 §7.5, ISO 27001 A.8.32, semver.org."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D98.versioning', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'versioning', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7e6-7a29-8ba1-8521a3f76569', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "Global Notifications", "es": "Notificaciones Globales"}', '{"en": "Global System Notifications — NIST SP 800-53 R5 SI-12 · ISO 27001 A.5.2", "es": "Notificaciones Globales del Sistema — NIST SP 800-53 R5 SI-12 · ISO 27001 A.5.2"}', NULL, '{"en": "Identity System Notifications · notifications. What is it? Identity plane notification engine distributing security alerts, notices, and communications to the correct recipients through appropriate channels: critical security notifications to users (login from new device, password change, new MFA enrolled — real-time via push/email), administration notifications to supervisors (role nearing expiration, pending access approval request), SOC alerts (anomaly detection, active brute force attempt), and compliance notifications to CISO (exception nearing expiration, compliance gap detected). What is it for? Keeping all relevant actors informed in real time of identity events requiring their attention or action, ensuring fast incident response times and continuous visibility of the identity plane security state. How is it used? bAuth''s event engine publishes events to Redis Streams; the notification engine consumes the stream, evaluates who should be notified for each event and through which channel (push via bNotify, email, SIEM webhook), and distributes the notification with the event''s ctx_id for traceability; critical notifications require read confirmation. Why? Identity plane security events without notification are useless for incident response: an administrator who does not know there is an active brute force attempt cannot respond; real-time notifications are the bridge between detection and response. Standards: NIST SP 800-53 R5 IR-6, ISO 27001 A.5.24, CIS Controls v8 §17, RFC 8417 SET (Security Event Token).", "es": "Notificaciones del Sistema de Identidad · notifications. ¿Qué es? Motor de notificaciones del plano de identidad que distribuye alertas, avisos y comunicaciones de seguridad a los destinatarios correctos a través de los canales apropiados: notificaciones de seguridad críticas al usuario (inicio de sesión desde nuevo dispositivo, cambio de contraseña, nuevo MFA enrollado — en tiempo real por push/email), notificaciones de administración al supervisor (rol próximo a expirar, solicitud de acceso pendiente de aprobación), alertas al SOC (detección de anomalía, intento de fuerza bruta activo), y notificaciones de cumplimiento al CISO (excepción próxima a expirar, brecha de cumplimiento detectada). ¿Para qué sirve? Mantener a todos los actores relevantes informados en tiempo real de los eventos de identidad que requieren su atención o acción, garantizando tiempos de respuesta rápidos ante incidentes y visibilidad continua del estado de seguridad del plano de identidad. ¿Cómo se usa? El motor de eventos de bAuth publica eventos en Redis Streams; el motor de notificaciones consume el stream, evalúa a quién corresponde notificar para cada evento y por qué canal (push vía bNotify, email, webhook al SIEM), y distribuye la notificación con el ctx_id del evento para trazabilidad; las notificaciones críticas tienen confirmación de lectura requerida. ¿Por qué? Los eventos de seguridad del plano de identidad sin notificación son inútiles para la respuesta a incidentes: un administrador que no sabe que hay un intento de fuerza bruta activo no puede responder; las notificaciones en tiempo real son el puente entre la detección y la respuesta. Normas: NIST SP 800-53 R5 IR-6, ISO 27001 A.5.24, CIS Controls v8 §17, RFC 8417 SET (Security Event Token)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.notifications', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'notifications', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7d2-79e6-90f5-00dd05c6cf59', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "Global Users", "es": "Usuarios Globales"}', '{"en": "Global System Users — NIST SP 800-53 R5 AC-2 · ISO 27001 A.5.16", "es": "Usuarios Globales del Sistema — NIST SP 800-53 R5 AC-2 · ISO 27001 A.5.16"}', NULL, '{"en": "Global User Management · users. What is it? User account administration module at the ecosystem level (above the individual tenant level): ecosystem super-administrators (SU roles — maximum 3 people with global access), tenant administrators (SYS roles — can administer their own tenant but not others), global account policy configuration applicable to all tenants (global minimum password length, maximum inactivity period before automatic deactivation, maximum concurrent sessions by tier), and ecosystem entity directory management (ecosystem-level LDAP/SCIM for synchronization with external systems). What is it for? Managing user accounts and policies transcending the individual tenant level and affecting the entire ecosystem: global account policies establish the minimum security floor all tenants must meet; tenants can be stricter than the global but not more permissive. How is it used? The ecosystem super-administrator configures global account policies that propagate automatically to all tenants; tenant administrators can override policies only by making them more restrictive; when a user is deactivated at ecosystem level (e.g., a compromised administrator), the deactivation affects all tenants where the user has presence simultaneously. Why? Without a global user administration level, each tenant manages its users independently; when an administrator with access to multiple tenants must be emergency-suspended, it requires N manual operations in N tenants; global management makes this operation atomic and complete. Standards: NIST SP 800-53 R5 AC-2, SCIM 2.0 RFC 7644, ISO 27001 A.5.16, NIST SP 800-63B-4 §4.", "es": "Gestión de Usuarios Globales · users. ¿Qué es? Módulo de administración de las cuentas de usuario a nivel de ecosistema (por encima del nivel de tenant individual): super-administradores del ecosistema (roles SU — máximo 3 personas con acceso global), administradores de tenant (roles SYS — pueden administrar su propio tenant pero no otros), configuración de políticas de cuenta globales aplicables a todos los tenants (longitud mínima de contraseña global, período máximo de inactividad antes de desactivación automática, número máximo de sesiones simultáneas por tier), y gestión del directorio de entidades del ecosistema (LDAP/SCIM de nivel ecositema para sincronización con sistemas externos). ¿Para qué sirve? Gestionar las cuentas y políticas de usuario que trascienden el nivel de tenant individual y afectan a todo el ecosistema: las políticas de cuenta global establecen el piso mínimo de seguridad que todos los tenants deben cumplir; los tenants pueden ser más estrictos que el global pero no más permisivos. ¿Cómo se usa? El super-administrador del ecosistema configura las políticas globales de cuenta que se propagan automáticamente a todos los tenants; los administradores de tenant pueden sobrescribir las políticas solo haciéndolas más restrictivas; cuando un usuario es desactivado a nivel de ecosistema (ej: un administrador comprometido), la desactivación afecta a todos los tenants en los que el usuario tiene presencia simultáneamente. ¿Por qué? Sin un nivel de administración de usuarios global, cada tenant gestiona sus usuarios de forma independiente; cuando un administrador con acceso a múltiples tenants debe ser suspendido de emergencia, requiere N operaciones manuales en N tenants; la gestión global hace esta operación atómica y completa. Normas: NIST SP 800-53 R5 AC-2, SCIM 2.0 RFC 7644, ISO 27001 A.5.16, NIST SP 800-63B-4 §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.users', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'users', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-7537-8755-7cc582e1da21', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Audit & Compliance", "es": "Auditoría y Cumplimiento"}', '{"en": "Audit & Compliance", "es": "Auditoría y Cumplimiento"}', NULL, '{"en": "Audit & Compliance · audit. What is it? The immutable and verifiable record of all ecosystem identity operations. Captures every event (successful or failed authentication, role change, delegation, PERMIT or DENY access, break-glass, revocation) in WORM format (Write Once Read Many) with SHA-256 hash-chain integrity: each event includes the hash of the previous event, making it impossible to modify or delete records without breaking the chain. Manages: data class retention policy (1-10 years per regulation), active monitoring with real-time alerts, structured SIEM export (Wazuh), and formal periodic log review. What is it for? Providing verifiable evidence that all access controls worked correctly, detecting incidents in real time, and demonstrating compliance to external auditors. How is it used? Each microservice emits audit events via the event bus; the capture module digitally signs, chains, and stores them; the SIEM processes them in real time; auditors access the log viewer for periodic review. Why? Auditing is the only mechanism to demonstrate to a regulator, judge, or external auditor that controls worked; without documented evidence there is no compliance. Standards: ISO 27001:2022 A.8.15, SOX §302/§404/§802, NIST SP 800-53 R5.2 AU-2/AU-3/AU-9/AU-11, GDPR Art. 30, PCI DSS 4.0 Req 10, ISO 9001:2015 §9.1.", "es": "Auditoría y Cumplimiento · audit. ¿Qué es? El registro inmutable y verificable de todas las operaciones de identidad del ecosistema. Captura cada evento (autenticación exitosa o fallida, cambio de rol, delegación, acceso PERMIT o DENY, break-glass, revocación) en formato WORM (Write Once Read Many) con integridad hash-chain SHA-256: cada evento incluye el hash del evento anterior, haciendo imposible modificar o eliminar registros sin romper la cadena. Gestiona: política de retención por clase de dato (1-10 años según regulación), monitoreo activo con alertas en tiempo real, exportación estructurada al SIEM (Wazuh) y revisión periódica formal de logs. ¿Para qué sirve? Proveer evidencia verificable de que todos los controles de acceso funcionaron correctamente, detectar incidentes en tiempo real y demostrar cumplimiento ante auditores externos. ¿Cómo se usa? Cada microservicio emite eventos de auditoría vía el bus de eventos; el módulo de captura los firma digitalmente, los encadena y los almacena; el SIEM los procesa en tiempo real; los auditores acceden al visor de logs para revisión periódica. ¿Por qué? La auditoría es el único mecanismo para demostrar ante un regulador, juez o auditor externo que los controles funcionaron; sin evidencia documentada no hay cumplimiento. Normas: ISO 27001:2022 A.8.15, SOX §302/§404/§802, NIST SP 800-53 R5.2 AU-2/AU-3/AU-9/AU-11, GDPR Art. 30, PCI DSS 4.0 Req 10, ISO 9001:2015 §9.1."}', '{}', NULL, NULL, NULL, false, NULL, 11, 1, 0, 'skull.D11', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1300, 'audit', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f666-7261-b5a2-1cb99287d3b4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Delegation) — RFC 8693 · NIST SP 800-53 R5 AC-2(5)", "es": "Registro de Zona de Negocio (Delegación) — RFC 8693 · NIST SP 800-53 R5 AC-2(5)"}', NULL, '{"en": "Business Zone Registry (Delegation) · business_zone. What is it? Container organizing authority delegation and advanced token issuance modules into control zones: internal delegation zone (between roles within the same tenant), external delegation zone (from a tenant to a third-party application), token exchange zone (Token Exchange RFC 8693 — a service exchanges its token for one with higher/lower scope), and rich authorization zone (Rich Authorization Requests — RFC 9396 with detailed claims of what is authorized). What is it for? Separating the responsibilities of different delegation mechanisms and ensuring authority delegation only occurs between entities authorized for it: only certain roles can delegate, and only to roles with lesser or equal privilege (anti-escalation principle). How is it used? A module needing to act on a user''s behalf requests a delegation token in the corresponding delegation zone; the zone evaluates whether the delegator has permission to delegate that scope to the delegatee; the delegation is logged in the audit log with the exact delegated scope and validity period. Why? Without delegation zoning, any service can request tokens with arbitrary scope on behalf of any user; zoning ensures delegation is limited to what the user explicitly authorized. Standards: RFC 8693 Token Exchange, RFC 9396 RAR, OAuth 2.0 §4, NIST SP 800-53 R5 AC-3(7).", "es": "Registro de Zona de Negocio (Delegación) · business_zone. ¿Qué es? Contenedor que organiza los módulos de delegación de autoridad y emisión de tokens avanzados en zonas de control: zona de delegación interna (entre roles dentro del mismo tenant), zona de delegación externa (de un tenant a una aplicación tercera), zona de intercambio de tokens (Token Exchange RFC 8693 — un servicio intercambia su token por un token con mayor/menor scope), y zona de autorización enriquecida (Rich Authorization Requests — RFC 9396 con claims detallados de lo que se autoriza). ¿Para qué sirve? Separar las responsabilidades de los diferentes mecanismos de delegación y garantizar que la delegación de autoridad solo ocurre entre entidades autorizadas para ello: solo ciertos roles pueden delegar, y solo hacia roles con menor o igual privilegio (principio anti-escalada). ¿Cómo se usa? Un módulo que necesita actuar en nombre de un usuario solicita un token de delegación en la zona de delegación correspondiente; la zona evalúa si el delegante tiene permiso para delegar ese scope al delegatario; la delegación se registra en el log de auditoría con el scope exacto delegado y el período de validez. ¿Por qué? Sin zonificación de delegación, cualquier servicio puede solicitar tokens con scope arbitrario en nombre de cualquier usuario; la zonificación garantiza que la delegación está limitada a lo que el usuario autorizó explícitamente. Normas: RFC 8693 Token Exchange, RFC 9396 RAR, OAuth 2.0 §4, NIST SP 800-53 R5 AC-3(7)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f77f-70da-9041-b035041b5ccb', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "Machine Secrets", "es": "Secretos de Máquina"}', '{"en": "Machine Secrets — NIST SP 800-57 Pt1 R5 §5.3 · CIS Controls v8 §18.5", "es": "Secretos de Máquina — NIST SP 800-57 Pt1 R5 §5.3 · CIS Controls v8 §18.5"}', NULL, '{"en": "Workload Secrets Management · secrets. What is it? Runtime secret injection and management system for workloads, without secrets touching the container''s disk or environment variables: the Vault agent (Vault Agent Sidecar or Secrets Store CSI Driver) injects secrets directly into the container''s in-memory filesystem (`/dev/shm/secrets/`) or temporary environment variables that only exist during the process lifetime; secrets automatically renew when rotated in Vault without restarting the container. What is it for? Ensuring workload secrets (DB passwords, API keys, certificates) never reside on the host filesystem, in environment variables persisted in the container manifest, or in container images: secrets are ephemeral and only exist in the memory of the process using them. How is it used? The container manifest declares what secrets it needs (referencing Vault paths, not values); the Vault operator injects the real values into the container at startup using the pod''s SPIFFE identity to authenticate; the secret is mounted in the container''s `/dev/shm/`; the process reads from there; never persisted to disk or logged. Why? Secrets in environment variables are visible in `docker inspect`, `kubectl describe pod`, startup logs, and any process on the same host; in-memory injection ensures they are invisible outside the process using them. Standards: NIST SP 800-53 R5 SC-28, CIS Kubernetes Benchmark §4.1, ISO 27001 A.5.17, SPIFFE/SPIRE §5.", "es": "Gestión de Secretos de Cargas de Trabajo · secrets. ¿Qué es? Sistema de inyección y gestión de secretos en cargas de trabajo en tiempo de ejecución, sin que los secretos toquen el disco o las variables de entorno del contenedor: el agente de Vault (Vault Agent Sidecar o Secrets Store CSI Driver) inyecta los secretos directamente en el sistema de archivos en memoria del contenedor (`/dev/shm/secrets/`) o en variables de entorno temporales que solo existen durante la vida del proceso; los secretos se renuevan automáticamente cuando rotan en Vault sin reiniciar el contenedor. ¿Para qué sirve? Garantizar que los secretos de las cargas de trabajo (contraseñas de BD, claves de API, certificados) nunca residen en el sistema de archivos del host, en variables de entorno persistidas en el manifiesto del contenedor o en imágenes de contenedor: los secretos son efímeros y solo existen en la memoria del proceso que los usa. ¿Cómo se usa? El manifiesto del contenedor declara qué secretos necesita (referenciando paths de Vault, no valores); el operador de Vault inyecta los valores reales en el contenedor al arrancarlo usando la identidad SPIFFE del pod para autenticarse; el secreto se monta en `/dev/shm/` del contenedor; el proceso lo lee de allí; nunca se persiste en disco ni en el log. ¿Por qué? Los secretos en variables de entorno son visibles en `docker inspect`, `kubectl describe pod`, logs de arranque y cualquier proceso del mismo host; la inyección en memoria garantiza que son invisibles fuera del proceso que los usa. Normas: NIST SP 800-53 R5 SC-28, CIS Kubernetes Benchmark §4.1, ISO 27001 A.5.17, SPIFFE/SPIRE §5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.secrets', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'secrets', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7be-7c86-9668-494b03b8b51b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c96-7b9f-b9bc-e68dff0080fe', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Structural) — ISO/IEC 24760-2:2025 §6 · NIST SP 800-162 §4", "es": "Registro de Zona de Negocio (Estructural) — ISO/IEC 24760-2:2025 §6 · NIST SP 800-162 §4"}', NULL, '{"en": "Business Zone Registry (Structural Registry) · business_zone. What is it? Container organizing role catalog and identity tree schema management modules into strict control zones: catalog read zone (any authorized module can read the role catalog and its definitions), schema modification zone (only the SCHEMA_ADMIN role can modify the tree structure — high-sensitivity operation affecting the entire ecosystem), versioning zone (catalog change records with prior approval and rollback), and import zone (loading new role templates from the canonical repository). What is it for? Protecting the integrity of the role catalog and identity tree schema, which are the ecosystem''s \"security data model\": an unauthorized change in a role definition can massively grant or revoke permissions involuntarily. How is it used? Ecosystem operational modules access the catalog in read mode from the read zone; only the catalog maintenance process (with SCHEMA_ADMIN role and dual approval) can modify the schema in the modification zone; any change is automatically versioned and can be reverted in under 5 minutes. Why? The role tree is the source of truth for permissions; if it can be modified by any process with database access, an attacker who compromises a microservice can escalate privileges by modifying role definitions. Standards: NIST SP 800-53 R5 CM-3, ISO 27001 A.8.32, ANSI INCITS 359-2004 §5, NIST SP 800-128.", "es": "Registro de Zona de Negocio (Registros Estructurales) · business_zone. ¿Qué es? Contenedor que organiza los módulos de gestión del catálogo de roles y el esquema del árbol de identidad en zonas de control estricto: zona de lectura del catálogo (cualquier módulo autorizado puede leer el catálogo de roles y sus definiciones), zona de modificación de esquema (solo el rol SCHEMA_ADMIN puede modificar la estructura del árbol — operación de alta sensibilidad que afecta a todo el ecosistema), zona de versionado (registro de cambios en el catálogo con aprobación previa y rollback), y zona de importación (carga de nuevas plantillas de roles desde el repositorio canónico). ¿Para qué sirve? Proteger la integridad del catálogo de roles y el esquema del árbol de identidad, que son el \"modelo de datos de seguridad\" del ecosistema: un cambio no autorizado en la definición de un rol puede conceder o revocar permisos masivamente de forma involuntaria. ¿Cómo se usa? Los módulos operativos del ecosistema acceden al catálogo en modo lectura de la zona de lectura; solo el proceso de mantenimiento del catálogo (con rol SCHEMA_ADMIN y doble aprobación) puede modificar el esquema en la zona de modificación; cualquier cambio se versiona automáticamente y puede ser revertido en menos de 5 minutos. ¿Por qué? El árbol de roles es la fuente de verdad de los permisos; si puede ser modificado por cualquier proceso con acceso a la base de datos, un atacante que comprometa un microservicio puede escalar privilegios modificando la definición de roles. Normas: NIST SP 800-53 R5 CM-3, ISO 27001 A.8.32, ANSI INCITS 359-2004 §5, NIST SP 800-128."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D98.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'business_zone', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4fd-7a56-9d31-68eff6bac77f', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Automatic Reconciliation", "es": "Conciliación Automática"}', '{"en": "Automatic Reconciliation — ISO 20022 §5 · COSO 2013 CC6.6", "es": "Conciliación Automática — ISO 20022 §5 · COSO 2013 CC6.6"}', NULL, '{"en": "Automatic Reconciliation · reconciliation. What is it? Engine that periodically compares internal transaction records with external account statements (bank, payment gateway, ERP) to detect discrepancies: transactions recorded but not processed externally, external transactions not recorded internally, mismatched amounts, or duplicate transactions. Discrepancies generate alerts and resolution flows with an assigned responsible and defined deadline. What is it for? Detecting processing errors, fraud, and system mismatches before they consolidate into financial statements, guaranteeing the integrity and accuracy of accounting records. How is it used? The engine runs reconciliation on configured schedules (daily for high-operation accounts, weekly for auxiliaries); compares records using unique transaction identifiers; generates a difference report with attached evidence for the accounting team. Why? Without automatic reconciliation, errors and fraud can remain hidden for weeks or months until manual audit; daily reconciliation reduces the detection window to 24 hours. Standards: ISO 20022 §5, COSO 2013 CC6.6, SOX §404, IFRS 7, ISO 9001:2015 §9.1.", "es": "Conciliación Automática · reconciliation. ¿Qué es? Motor que compara periódicamente los registros de transacciones internas con los estados de cuenta externos (banco, pasarela de pagos, ERP) para detectar discrepancias: transacciones registradas pero no procesadas externamente, transacciones externas no registradas internamente, montos que no coinciden o transacciones duplicadas. Las discrepancias generan alertas y flujos de resolución con responsable asignado y plazo definido. ¿Para qué sirve? Detectar errores de procesamiento, fraudes y desfases entre sistemas antes de que se consoliden en los estados financieros, garantizando la integridad y exactitud de los registros contables. ¿Cómo se usa? El motor ejecuta la conciliación en los horarios configurados (diaria para cuentas de alta operación, semanal para auxiliares); compara registros usando identificadores únicos de transacción; genera informe de diferencias con evidencia adjunta para el equipo contable. ¿Por qué? Sin conciliación automática los errores y fraudes pueden permanecer ocultos por semanas o meses hasta la auditoría manual; la conciliación diaria reduce la ventana de detección a 24 horas. Normas: ISO 20022 §5, COSO 2013 CC6.6, SOX §404, IFRS 7, ISO 9001:2015 §9.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.reconciliation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'reconciliation', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5a8-7e46-8d6e-7512cdb188b8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Network) — NIST SP 800-207 §3 · ISO 27001 A.8.22", "es": "Registro de Zona de Negocio (Red) — NIST SP 800-207 §3 · ISO 27001 A.8.22"}', NULL, '{"en": "Business Zone Registry (Network) · business_zone. What is it? Container organizing network resources and systems into network trust zones: high trust zone (internal corporate network, authenticated VPN), medium trust zone (corporate WiFi with NAC), low trust zone (external access, public network, internet client), zero zone (production network, access only with strong MFA and device certificate). Defines minimum authentication and authorization requirements for accessing resources from each network zone. What is it for? Implementing Zero Trust architecture: no network is inherently trusted; trust is granted based on access security posture, not IP address or network of origin. How is it used? Each resource is assigned to its network zone; the zone defines the minimum required controls (low zone: mandatory MFA; medium zone: device certificate; high zone: recent active session); the evaluator combines the network zone with the BitMask for the final decision. Why? The \"internal network = trusted\" model was invalidated by lateral movement attacks; network zone-based access ensures that even an attacker inside the internal network cannot access critical systems without passing through production zone controls. Standards: NIST SP 800-207 §3, NIST SP 800-53 R5 SC-7(21), CIS Controls v8 §12, ISO 27001 A.8.20.", "es": "Registro de Zona de Negocio (Red) · business_zone. ¿Qué es? Contenedor que organiza los recursos de red y sistemas en zonas de confianza de red: zona de confianza alta (red interna corporativa, VPN autenticada), zona de confianza media (red WiFi corporativa con NAC), zona de confianza baja (acceso externo, red pública, cliente en internet), zona cero (red de producción, acceso solo con MFA fuerte y certificado dispositivo). Define los requisitos de autenticación y autorización mínimos para acceder a recursos desde cada zona de red. ¿Para qué sirve? Implementar la arquitectura Zero Trust: ninguna red es inherentemente confiable; la confianza se otorga según la postura de seguridad del acceso, no según la dirección IP o la red de origen. ¿Cómo se usa? Cada recurso se asigna a su zona de red; la zona define el conjunto mínimo de controles exigidos (zona baja: MFA obligatorio; zona media: certificado dispositivo; zona alta: sesión activa reciente); el evaluador combina la zona de red con el BitMask para la decisión final. ¿Por qué? El modelo de \"red interna = confiada\" fue invalidado por los ataques de movimiento lateral; el acceso basado en zona de red garantiza que incluso un atacante dentro de la red interna no accede a sistemas críticos sin pasar por los controles de la zona de producción. Normas: NIST SP 800-207 §3, NIST SP 800-53 R5 SC-7(21), CIS Controls v8 §12, ISO 27001 A.8.20."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'business_zone', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4f1-7f1b-9a72-9d6d3dc06caf', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Regulatory Reporting", "es": "Reportes Regulatorios"}', '{"en": "Regulatory Reporting — SOX §302/§404 · IFRS 7 · ISO 20022 MX", "es": "Reportes Regulatorios — SOX §302/§404 · IFRS 7 · ISO 20022 MX"}', NULL, '{"en": "Regulatory Reporting · reporting. What is it? Engine for automated generation of financial reports required by regulators: IFRS financial statements, suspicious activity reports (SAR) for the FIU, tax declarations (VAT, IT) for the SIN, solvency and liquidity reports for ASFI, and any periodic report required by sector regulatory bodies. Reports are generated with digital signature, generation log, and integrity hash. What is it for? Automating compliance with regulatory reporting obligations, reducing the risk of non-compliance fines and the manual effort of preparing audited reports. How is it used? The engine collects period data directly from source systems via audited queries; applies the specific regulator''s business rules; generates the report in the required format (XML, XBRL, PDF/A) with digital signature and transmits it to the regulator or makes it available to the compliance team. Why? Manual regulatory reports are error-prone and difficult to audit; automation guarantees consistency, traceability, and drastically reduces regulatory closing time. Standards: SOX §302/§404, IFRS 7, ISO 20022 MX, Bolivia Law 1670 (ASFI), Bolivia Law 843.", "es": "Reportes Regulatorios · reporting. ¿Qué es? Motor de generación automatizada de reportes financieros exigidos por reguladores: estados financieros IFRS/NIIF, reportes de operaciones sospechosas (ROS) para la UIF, declaraciones de impuestos (IVA, IT, RC-IVA) para el SIN, reportes de solvencia y liquidez para la ASFI, y cualquier informe periódico requerido por entes reguladores del sector. Los reportes se generan con firma digital, log de generación y hash de integridad. ¿Para qué sirve? Automatizar el cumplimiento de las obligaciones de reporte regulatorio, reduciendo el riesgo de multas por incumplimiento y el esfuerzo manual de preparación de reportes auditados. ¿Cómo se usa? El motor recoge los datos del período directamente de los sistemas fuente mediante consultas auditadas; aplica las reglas de negocio del regulador específico; genera el reporte en el formato exigido (XML, XBRL, PDF/A) con firma digital y lo transmite al regulador o lo pone a disposición del equipo de cumplimiento. ¿Por qué? Los reportes regulatorios manuales son propensos a errores y difíciles de auditar; la automatización garantiza consistencia, trazabilidad y reduce drásticamente el tiempo de cierre regulatorio. Normas: SOX §302/§404, IFRS 7, ISO 20022 MX, Ley 1670 Bolivia (ASFI), Ley 843 Bolivia."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.reporting', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'reporting', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f519-7b2e-a06c-7334f7901950', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Calendar & Holidays", "es": "Calendario y Feriados"}', '{"en": "Calendar & Holidays — RFC 5545 iCalendar §3 · ISO 8601:2019", "es": "Calendario y Feriados — RFC 5545 iCalendar §3 · ISO 8601:2019"}', NULL, '{"en": "Calendar & Holidays · calendar. What is it? Catalog of work calendars by country, region, and tenant: business days, national holidays (from official sources), regional holidays, government-declared suspension days, and accounting close periods. Calendars are dynamic: updated annually with official decrees and customizable by the tenant for their own closure days. What is it for? Providing all temporal restriction modules the reference base for which days are business days in each jurisdiction, to correctly calculate deadlines, schedule restrictions, and approval windows. How is it used? The temporal zone engine consults the tenant calendar to determine if the current day is a business day; reconciliation and approval modules use the calendar to calculate deadlines; out-of-hours access restrictions activate on holidays automatically. Why? Without a centralized calendar, each module implements its own business day logic, generating inconsistencies: one module may process operations on a day another considers a holiday. Standards: RFC 5545 iCalendar §3, ISO 8601:2019, ISO 20022 §5.10 (financial calendars).", "es": "Calendario y Feriados · calendar. ¿Qué es? Catálogo de calendarios laborales por país, región y tenant: días hábiles, feriados nacionales (con fuente oficial), feriados regionales, días de suspensión de operaciones decretados y períodos de cierre contable. Los calendarios son dinámicos: se actualizan anualmente con los decretos oficiales y pueden ser personalizados por el tenant para sus propios días de cierre. ¿Para qué sirve? Proveer a todos los módulos de restricción temporal la base de referencia de qué días son hábiles en cada jurisdicción, para calcular correctamente plazos, restricciones de horario y ventanas de aprobación. ¿Cómo se usa? El motor de zonas temporales consulta el calendario del tenant para determinar si el día actual es hábil; los módulos de conciliación y aprobación usan el calendario para calcular plazos; las restricciones de acceso fuera de horario se activan en feriados automáticamente. ¿Por qué? Sin un calendario centralizado, cada módulo implementa su propia lógica de días hábiles, generando inconsistencias: un módulo puede procesar operaciones el día que otro considera feriado. Normas: RFC 5545 iCalendar §3, ISO 8601:2019, ISO 20022 §5.10 (calendarios financieros)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.calendar', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'calendar', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f774-7390-a199-8720ae3244fc', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "Workload Identity", "es": "Identidad de Carga de Trabajo"}', '{"en": "Workload Identity (SPIFFE/SPIRE) — SPIFFE Spec v1.0 §5 · NIST SP 800-204A §3", "es": "Identidad de Carga de Trabajo (SPIFFE/SPIRE) — SPIFFE Spec v1.0 §5 · NIST SP 800-204A §3"}', NULL, '{"en": "Workload Identity (SPIFFE/SPIRE) · workload. What is it? Implementation of the SPIFFE (Secure Production Identity Framework For Everyone) standard for workload identity management in production environments: each SBOS ecosystem service, container, or process has a SPIFFE ID (URI of type `spiffe://sbos.local/biedata/prod`) uniquely identifying it; the SPIRE Server issues SVIDs (short-lived X.509 certificates, 1-hour TTL) to each workload after verifying its identity via attestation; SVIDs enable automatic mTLS between all microservices without manual certificate configuration. What is it for? Eliminating manual certificate management between ecosystem microservices: with SPIFFE/SPIRE, each microservice has verifiable cryptographic identity, certificates rotate automatically every hour, and mTLS between services is always active without any team having to manage certificates manually. How is it used? The SPIRE Server is deployed as an ecosystem infrastructure component; SPIRE Agents run on each host; when a workload starts, the host agent attests it and issues an SVID; the workload uses the SVID to authenticate in all its calls to other services via mTLS; the SVID is automatically rotated every hour without interrupting the service. Why? Microservice identities based on IPs or hostnames are fragile and spoofable; SPIFFE/SPIRE provides robust, automatic cryptographic identity to each process without manual PKI management. Standards: SPIFFE Core Specification v1.0, SPIRE §5, NIST SP 800-207 §3.3, RFC 8705 mTLS.", "es": "Identidad de Carga de Trabajo (SPIFFE/SPIRE) · workload. ¿Qué es? Implementación del estándar SPIFFE (Secure Production Identity Framework For Everyone) para gestión de identidades de cargas de trabajo en entornos de producción: cada servicio, contenedor o proceso del ecosistema SBOS tiene un SPIFFE ID (URI del tipo `spiffe://sbos.local/biedata/prod`) que lo identifica de forma única; el SPIRE Server emite SVIDs (certificados X.509 de vida corta, TTL 1 hora) a cada carga de trabajo tras verificar su identidad mediante atestación; los SVIDs habilitan mTLS automático entre todos los microservicios sin configuración manual de certificados. ¿Para qué sirve? Eliminar la gestión manual de certificados entre microservicios del ecosistema: con SPIFFE/SPIRE, cada microservicio tiene identidad criptográfica verificable, los certificados se rotan automáticamente cada hora, y el mTLS entre servicios está siempre activo sin que ningún equipo tenga que gestionar los certificados manualmente. ¿Cómo se usa? El SPIRE Server se despliega como componente de infraestructura del ecosistema; los SPIRE Agents se ejecutan en cada host; al arrancar una carga de trabajo, el agente del host la atestigua y emite un SVID; la carga usa el SVID para autenticarse en todas sus llamadas a otros servicios vía mTLS; el SVID se rota automáticamente cada hora sin interrumpir el servicio. ¿Por qué? Las identidades de microservicio basadas en IPs o hostnames son frágiles y falsificables; SPIFFE/SPIRE provee identidad criptográfica robusta y automática a cada proceso, sin gestión manual de PKI. Normas: SPIFFE Core Specification v1.0, SPIRE §5, NIST SP 800-207 §3.3, RFC 8705 mTLS."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.workload', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'workload', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f46f-7ae7-8643-1e4998c68685', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Field-Level Access", "es": "Acceso a Nivel de Campo"}', '{"en": "Field-Level Access — NIST SP 800-53 R5 AC-3(10) · OWASP ASVS v5 §4.1", "es": "Acceso a Nivel de Campo — NIST SP 800-53 R5 AC-3(10) · OWASP ASVS v5 §4.1"}', NULL, '{"en": "Field-Level Access · fields. What is it? Granular access control determining which specific fields of a data entity (DB table, JSON object, form) each role can view or modify, independent of access to the complete entity. Implements Column-Level Security (CLS) at the identity layer: a user may have access to the employee table but only see name and department, not salary or document number. What is it for? Implementing the principle of minimum data exposure: revealing only the fields strictly necessary for the user''s task, reducing the risk of sensitive data leakage within legitimate accesses. How is it used? Each sensitive field has an associated BitMask mask; the PDP evaluates which fields of the requested object are visible for the user''s role and returns only those; remaining fields are omitted or masked (partial tokenization). Why? Entity-level access is not sufficient to protect data within complex records; without CLS an auditor accessing employee records also sees salaries even if not needed. Standards: NIST SP 800-53 R5 AC-3(10), OWASP ASVS v5 §4.1, GDPR Art. 5(1)(c) minimization, PCI DSS 4.0 Req 3.3.", "es": "Acceso a Nivel de Campo · fields. ¿Qué es? Control granular de acceso que determina qué campos específicos de una entidad de datos (tabla de BD, objeto JSON, formulario) puede ver o modificar cada rol, independientemente del acceso a la entidad completa. Implementa Column-Level Security (CLS) en la capa de identidad: un usuario puede tener acceso a la tabla de empleados pero solo ver nombre y departamento, no salario ni número de documento. ¿Para qué sirve? Implementar el principio de mínima exposición de datos: revelar únicamente los campos estrictamente necesarios para la tarea del usuario, reduciendo el riesgo de fuga de datos sensibles dentro de accesos legítimos. ¿Cómo se usa? Cada campo sensible tiene una máscara de BitMask asociada; el PDP evalúa qué campos del objeto solicitado son visibles para el rol del usuario y devuelve solo esos; los campos restantes se omiten o se enmascaran (tokenización parcial). ¿Por qué? El acceso a nivel de entidad no es suficiente para proteger datos dentro de registros complejos; sin CLS un auditor que accede a historiales de empleados ve también los salarios aunque no los necesite. Normas: NIST SP 800-53 R5 AC-3(10), OWASP ASVS v5 §4.1, GDPR Art. 5(1)(c) minimización, PCI DSS 4.0 Req 3.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.fields', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'fields', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f55d-70d6-a314-797c984245bf', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Data Sovereignty & Residency", "es": "Soberanía de Datos y Residencia"}', '{"en": "Data Sovereignty & Residency — GDPR Art. 44-49 · ISO 3166-1 · Ley 1174 Bolivia", "es": "Soberanía de Datos y Residencia — GDPR Art. 44-49 · ISO 3166-1 · Ley 1174 Bolivia"}', NULL, '{"en": "Data Residency and Sovereignty · residency. What is it? Engine guaranteeing that tenant data remains in the client''s sovereign jurisdiction (Bolivia): each stored datum is labeled with its residency jurisdiction; replication, backup, or transfer operations verify that the destination is a jurisdiction permitted by the tenant policy; Bolivian-residency data is never processed on servers outside the territory. Maintains an audit record of data flows between jurisdictions to demonstrate regulatory compliance. What is it for? Complying with Bolivia Law 164 (digital sovereignty) and data protection provisions requiring that certain data types (financial, health, identification) reside exclusively on servers in national territory. How is it used? Each data entity is labeled with its residency category at creation; the residency engine verifies in each transfer or replication operation that the destination complies with the policy; any attempt to move data to an unauthorized jurisdiction generates an alert and blockage. Why? Without data residency control, automatic backups or cloud service integrations can send sensitive data outside the country undetected, violating Bolivian regulation and client commitments. Standards: Bolivia Law 164 Art. 78, GDPR Art. 44-49 (international transfers), ISO 27001 A.5.33.", "es": "Residencia y Soberanía de Datos · residency. ¿Qué es? Motor que garantiza que los datos del tenant permanecen en la jurisdicción soberana del cliente (Bolivia): cada dato almacenado tiene etiquetada su jurisdicción de residencia; las operaciones de replicación, backup o transferencia verifican que el destino es una jurisdicción permitida por la política del tenant; los datos de residencia boliviana nunca se procesan en servidores fuera del territorio. Mantiene el registro de auditoría de flujos de datos entre jurisdicciones para demostrar cumplimiento regulatorio. ¿Para qué sirve? Cumplir con la Ley 164 Bolivia (soberanía digital) y con las disposiciones de protección de datos que exigen que ciertos tipos de datos (financieros, sanitarios, de identificación) residan exclusivamente en servidores en territorio nacional. ¿Cómo se usa? Cada entidad de datos se etiqueta con su categoría de residencia al crearse; el motor de residencia verifica en cada operación de transferencia o replicación que el destino cumple la política; cualquier intento de mover datos a una jurisdicción no autorizada genera alerta y bloqueo. ¿Por qué? Sin control de residencia de datos, los backups automáticos o las integraciones con servicios cloud pueden enviar datos sensibles fuera del país sin que nadie lo detecte, violando la regulación boliviana y los compromisos con el cliente. Normas: Ley 164 Bolivia Art. 78, GDPR Art. 44-49 (transferencias internacionales), ISO 27001 A.5.33."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.residency', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'residency', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5b8-765e-962f-57e0efe41114', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Active Assurance Level", "es": "Nivel de Garantía Activo"}', '{"en": "Active Assurance Level — NIST SP 800-63B-4 §4 AAL1-3 · RFC 9470 §3", "es": "Nivel de Garantía Activo — NIST SP 800-63B-4 §4 AAL1-3 · RFC 9470 §3"}', NULL, '{"en": "Authentication Assurance Level · assurance. What is it? Formal classification of the level of certainty the system has about the user''s identity in the current session, per NIST SP 800-63B-4: AAL1 (password alone or single factor — low assurance), AAL2 (password + MFA second factor — medium assurance), AAL3 (cryptographic factor with verified physical presence, hardware bound — high assurance). The current session AAL is included in the JWT and determines which operations the user can perform without step-up. What is it for? Establishing a standard identity assurance language between all system components: Kong PEP can verify the token carries AAL2 before permitting access to an endpoint requiring it, without needing to reimport factor evaluation logic. How is it used? Upon completing authentication, bAuth evaluates the presented factors and assigns the resulting AAL to the token; sensitive resources declare their minimum required AAL in their policy; if the token does not reach the required AAL, the step-up flow (RFC 9470) is initiated to elevate the current session''s AAL. Why? Without an explicit assurance level in the token, each service must infer the authentication level from present claims, generating inconsistencies; the standardized AAL eliminates that ambiguity and enables precise access policies. Standards: NIST SP 800-63B-4 §4, RFC 9470 Step-Up, ISO 29115:2013 §5, NIST SP 800-53 R5 IA-2.", "es": "Nivel de Garantía de Autenticación · assurance. ¿Qué es? Clasificación formal del nivel de certeza que el sistema tiene sobre la identidad del usuario en la sesión actual, según el estándar NIST SP 800-63B-4: AAL1 (contraseña sola o factor único — baja garantía), AAL2 (contraseña + segundo factor MFA — garantía media), AAL3 (factor criptográfico con presencia física verificada, hardware bound — garantía alta). El AAL actual de la sesión se incluye en el JWT y determina qué operaciones puede realizar el usuario sin step-up. ¿Para qué sirve? Establecer un lenguaje estándar de garantía de identidad entre todos los componentes del sistema: Kong PEP puede verificar que el token lleva AAL2 antes de permitir el acceso a un endpoint que lo requiera, sin necesidad de reimplementar la lógica de evaluación de factores. ¿Cómo se usa? Al completar la autenticación, bAuth evalúa los factores presentados y asigna el AAL resultante al token; los recursos sensibles declaran su AAL mínimo requerido en su política; si el token no alcanza el AAL exigido, se inicia el flujo de step-up (RFC 9470) para elevar el AAL de la sesión actual. ¿Por qué? Sin un nivel de garantía explícito en el token, cada servicio debe inferir el nivel de autenticación a partir de los claims presentes, generando inconsistencias; el AAL estandarizado elimina esa ambigüedad y permite políticas de acceso precisas. Normas: NIST SP 800-63B-4 §4, RFC 9470 Step-Up, ISO 29115:2013 §5, NIST SP 800-53 R5 IA-2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.assurance', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'assurance', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7f4-730c-b8b5-00c9e75ce0af', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Global Admin) — ISO 9001:2015 §5.1 · NIST SP 800-53 R5 PL-2", "es": "Registro de Zona de Negocio (Administración Global) — ISO 9001:2015 §5.1 · NIST SP 800-53 R5 PL-2"}', NULL, '{"en": "Business Zone Registry (Global Administration) · business_zone. What is it? Container organizing ecosystem global administration modules into maximum access control zones: global configuration zone (parameters affecting all tenants — SU only with dual approval), tenant management zone (tenant creation, removal, modification — SYS only with authorization), global compliance zone (regulatory policy configuration applicable to all tenants — CISO+Compliance only), incidents zone (security incident management affecting multiple tenants — SOC team), and support zone (diagnostic access with minimum scope and full auditing). What is it for? Applying the ecosystem''s strictest controls to operations with global impact: an incorrect configuration in the global configuration zone affects all ecosystem tenants simultaneously; zoning ensures multiple approvals and complete auditing for these operations. How is it used? Global administrators access their corresponding zone with AAL3 authentication (FIDO2 hardware key + biometric); each operation in the global zone requires dual approval from independent administrators; all sessions are recorded; the global zone audit log has restricted access and is only exportable for the ecosystem governance body. Why? Global administration operations are the ecosystem''s \"nervous system\"; their compromise has the highest possible blast radius; the strictest controls are proportional to that extreme risk. Standards: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5, ISO 27001 A.5.18, SOX §302.", "es": "Registro de Zona de Negocio (Administración Global) · business_zone. ¿Qué es? Contenedor que organiza los módulos de administración global del ecosistema en zonas de control de acceso máximo: zona de configuración global (parámetros que afectan a todos los tenants — solo SU con aprobación dual), zona de gestión de tenants (alta, baja, modificación de tenants — solo SYS con autorización), zona de cumplimiento global (configuración de políticas regulatorias aplicables a todos los tenants — solo CISO+Compliance), zona de incidentes (gestión de incidentes de seguridad que afectan a múltiples tenants — equipo SOC), y zona de soporte (acceso de diagnóstico con scope mínimo y auditoría total). ¿Para qué sirve? Aplicar los controles más estrictos del ecosistema a las operaciones que tienen impacto global: una configuración errónea en la zona de configuración global afecta a todos los tenants del ecosistema simultáneamente; la zonificación garantiza múltiples aprobaciones y auditoría completa para estas operaciones. ¿Cómo se usa? Los administradores globales acceden a su zona correspondiente con autenticación AAL3 (FIDO2 hardware key + biometría); cada operación en la zona global requiere doble aprobación de administradores independientes; todas las sesiones están grabadas; el log de auditoría de la zona global es de acceso restringido y solo exportable para el órgano de gobierno del ecosistema. ¿Por qué? Las operaciones de administración global son el \"sistema nervioso\" del ecosistema; su compromiso tiene el mayor radio de impacto posible; los controles más estrictos son proporcionales a ese riesgo extremo. Normas: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5, ISO 27001 A.5.18, SOX §302."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7ee-7aa3-b1db-e495bd025c36', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "Compliance Map", "es": "Mapa de Conformidad"}', '{"en": "Regulatory Compliance Map — ISO 19600:2014 §6 · NIST SP 800-53 R5 CA-2", "es": "Mapa de Cumplimiento Regulatorio — ISO 19600:2014 §6 · NIST SP 800-53 R5 CA-2"}', NULL, '{"en": "Regulatory Compliance · compliance. What is it? Continuous compliance evaluation engine for the SBOS ecosystem against applicable regulatory frameworks: ISO 27001:2022 (information security management), PCI DSS 4.0 (payment data security), SOX (financial internal controls), NIST SP 800-53 R5 (U.S. government security controls — adopted as reference), and applicable Bolivian regulations (Law 164, ASFI, SIN regulations). The engine maps each control of each framework to the bAuth technical mechanisms satisfying it and generates automatic compliance evidence. What is it for? Automating regulatory compliance assessment that normally requires costly manual audits: the engine generates a real-time updated compliance report showing which controls are satisfied, which are partially satisfied, and which have gaps, with attached technical evidence. How is it used? The compliance administrator selects the regulatory frameworks applicable to the tenant; the engine evaluates each control''s status based on current configuration and audit events; generates the compliance report with the percentage of satisfied controls; compliance gaps generate remediation tasks with an assigned responsible and deadline. Why? Manual compliance audits are costly, slow, and only provide a snapshot; the continuous compliance engine reduces audit cost by 80% and keeps compliance status visible in real time, allowing corrections before the formal audit. Standards: ISO 27001:2022 §9.1, NIST SP 800-53 R5 CA-7, PCI DSS 4.0 Req 12, SOX §404.", "es": "Cumplimiento Regulatorio · compliance. ¿Qué es? Motor de evaluación continua del nivel de cumplimiento del ecosistema SBOS contra los marcos regulatorios aplicables: ISO 27001:2022 (gestión de seguridad de la información), PCI DSS 4.0 (seguridad de datos de pago), SOX (controles internos financieros), NIST SP 800-53 R5 (controles de seguridad del gobierno de EE.UU. — adoptado como referencia), y las regulaciones bolivianas aplicables (Ley 164, regulaciones ASFI, SIN). El motor mapea cada control de cada marco a los mecanismos técnicos de bAuth que lo satisfacen y genera evidencia automática de cumplimiento. ¿Para qué sirve? Automatizar la evaluación de cumplimiento regulatorio que normalmente requiere auditorías manuales costosas: el motor genera un informe de cumplimiento actualizado en tiempo real que muestra qué controles están satisfechos, cuáles están parcialmente satisfechos y cuáles tienen brechas, con evidencia técnica adjunta. ¿Cómo se usa? El administrador de cumplimiento selecciona los marcos regulatorios aplicables al tenant; el motor evalúa el estado de cada control basándose en la configuración actual y los eventos de auditoría; genera el informe de cumplimiento con el porcentaje de controles satisfechos; las brechas de cumplimiento generan tareas de remediación con responsable asignado y plazo. ¿Por qué? Las auditorías manuales de cumplimiento son costosas, lentas y solo proveen una foto puntual del estado; el motor de cumplimiento continuo reduce el costo de la auditoría en un 80% y mantiene el estado de cumplimiento visible en tiempo real, permitiendo correcciones antes de la auditoría formal. Normas: ISO 27001:2022 §9.1, NIST SP 800-53 R5 CA-7, PCI DSS 4.0 Req 12, SOX §404."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.compliance', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'compliance', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7eb-79c1-9e3a-d2fc7d680f95', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "Cryptographic Parameters", "es": "Parámetros Criptográficos"}', '{"en": "Global Cryptographic Parameters — NIST SP 800-131A R2 §3 · ISO 27001 A.8.24", "es": "Parámetros Criptográficos Globales — NIST SP 800-131A R2 §3 · ISO 27001 A.8.24"}', NULL, '{"en": "Cryptographic Governance · cryptography. What is it? Lifecycle management framework for all ecosystem cryptographic materials: active key inventory (type, algorithm, length, purpose, custodian, creation date, next expiration date), cryptographic agility policy (ability to migrate all algorithms without downtime when an algorithm is declared obsolete), post-quantum migration planning (preparation for transition to NIST PQC post-quantum algorithms — CRYSTALS-Kyber, CRYSTALS-Dilithium), and cryptographic material access management (HSM, Vault, key encryption keys). What is it for? Ensuring the SBOS ecosystem maintains a robust and adaptable cryptographic posture: when NIST declares an algorithm compromised (as happened with MD5, SHA-1, and RSA-1024), the ecosystem can migrate all uses of that algorithm in an orderly manner without interruptions. How is it used? The cryptographic inventory updates automatically when creating, rotating, or revoking any cryptographic material; the agility engine periodically evaluates whether any algorithm in use is near being declared obsolete (per NIST and BSI recommendations); if risk is detected, it generates a migration plan with ordered dependencies; the cryptography administrator approves and executes the migration. Why? Systems without cryptographic agility become trapped in obsolete algorithms: if RSA-2048 were compromised tomorrow by quantum computing, an ecosystem without cryptographic agility could not migrate without months of emergency manual work. Standards: NIST SP 800-175B R1 §3, NIST PQC FIPS 203/204/205, BSI TR-02102, ISO 11568-1:2005 (key management), CNSA 2.0.", "es": "Gobernanza Criptográfica · cryptography. ¿Qué es? Marco de gestión del ciclo de vida de todos los materiales criptográficos del ecosistema: inventario de claves activas (tipo, algoritmo, longitud, propósito, custodio, fecha de creación, fecha de expiración próxima), política de agility criptográfica (capacidad de migrar todos los algoritmos sin tiempo de inactividad cuando un algoritmo sea declarado obsoleto), planificación de migración post-cuántica (preparación para la transición a algoritmos post-cuánticos NIST PQC — CRYSTALS-Kyber, CRYSTALS-Dilithium), y gestión del acceso a los materiales criptográficos (HSM, Vault, claves de encriptación de claves). ¿Para qué sirve? Garantizar que el ecosistema SBOS mantiene una postura criptográfica robusta y adaptable: cuando NIST declare un algoritmo como comprometido (como ocurrió con MD5, SHA-1 y RSA-1024), el ecosistema puede migrar todos los usos de ese algoritmo de forma ordenada sin interrupciones. ¿Cómo se usa? El inventario criptográfico se actualiza automáticamente al crear, rotar o revocar cualquier material criptográfico; el motor de agility evalúa periódicamente si algún algoritmo en uso está próximo a ser declarado obsoleto (según las recomendaciones de NIST y BSI); si detecta riesgo, genera plan de migración con las dependencias ordenadas; el administrador de criptografía aprueba y ejecuta la migración. ¿Por qué? Los sistemas sin agility criptográfica quedan atrapados en algoritmos obsoletos: si RSA-2048 fuera comprometido mañana por computación cuántica, un ecosistema sin agility criptográfica no podría migrar sin meses de trabajo manual de emergencia. Normas: NIST SP 800-175B R1 §3, NIST PQC FIPS 203/204/205, BSI TR-02102, ISO 11568-1:2005 (key management), CNSA 2.0."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.cryptography', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'cryptography', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7f1-71d1-8dba-8268bc0acdfd', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "SBOM Supply Chain", "es": "Cadena de Suministro SBOM"}', '{"en": "Software Supply Chain (SBOM) — NTIA SBOM 2021 · NIST SP 800-53 R5 SA-12", "es": "Cadena de Suministro de Software (SBOM) — NTIA SBOM 2021 · NIST SP 800-53 R5 SA-12"}', NULL, '{"en": "Software Supply Chain Security · supply_chain. What is it? Security control framework applied to the software dependencies and components forming the SBOS ecosystem: SBOM (Software Bill of Materials — inventory of all dependencies with verified version and hash), third-party binary signature verification before deployment, dependency vulnerability monitoring (automatic CVE watch on versions in use), dependency update policy with risk analysis, and CI/CD pipeline integrity verification (deployed images must match those built by the verified pipeline). What is it for? Protecting the ecosystem from supply chain attacks like SolarWinds or XZ Utils: an attacker who compromises an ecosystem dependency can access all systems using it; supply chain controls detect these compromises before reaching production. How is it used? CI/CD generates the SBOM on each build; the CVE watch engine continuously checks if any SBOM dependency has published critical CVEs; if it detects a critical CVE in an active dependency, it generates an immediate alert and blocks future deployments until the dependency is updated; container images are signed with Cosign and the signature is verified before deployment. Why? 62% of infrastructure attacks in 2024 were supply chain attacks; supply chain controls are the only effective defense against an attacker compromising the tools we use to build the ecosystem. Standards: SLSA Framework §3, NIST SP 800-204D §4, NIST SP 800-161 R1 §3, CIS Controls v8 §16, OWASP SCVS v1.0.", "es": "Seguridad de la Cadena de Suministro de Software · supply_chain. ¿Qué es? Marco de controles de seguridad aplicados a las dependencias y componentes de software que forman el ecosistema SBOS: SBOM (Software Bill of Materials — inventario de todas las dependencias con versión y hash verificado), verificación de firmas de los binarios de terceros antes de desplegarlos, monitoreo de vulnerabilidades en dependencias (CVE watch automático sobre las versiones en uso), política de actualización de dependencias con análisis de riesgo, y verificación de integridad del pipeline de CI/CD (las imágenes desplegadas deben coincidir con las construidas por el pipeline verificado). ¿Para qué sirve? Proteger el ecosistema de ataques de cadena de suministro como SolarWinds o XZ Utils: un atacante que compromete una dependencia del ecosistema puede tener acceso a todos los sistemas que la usan; los controles de supply chain detectan estas compromisos antes de que lleguen a producción. ¿Cómo se usa? El CI/CD genera el SBOM en cada build; el motor de CVE watch verifica continuamente si alguna dependencia del SBOM tiene CVEs críticos publicados; si detecta un CVE crítico en una dependencia activa, genera alerta inmediata y bloquea futuros despliegues hasta que la dependencia sea actualizada; las imágenes de contenedor se firman con Cosign y se verifica la firma antes de desplegar. ¿Por qué? El 62% de los ataques a infraestructura en 2024 fueron supply chain attacks; los controles de cadena de suministro son la única defensa efectiva contra un atacante que compromete las herramientas que usamos para construir el ecosistema. Normas: SLSA Framework §3, NIST SP 800-204D §4, NIST SP 800-161 R1 §3, CIS Controls v8 §16, OWASP SCVS v1.0."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.supply_chain', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'supply_chain', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-777a-81e9-61a09beb7c67', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Global Administration", "es": "Administración Global"}', '{"en": "Global Administration", "es": "Administración Global"}', NULL, '{"en": "Global Administration · administrative_global. What is it? The highest operational-level domain of the SBOS tenant: manages users with cross-tenant access (SU super-administrators, external auditors, first-level support operators), global-scope system notifications, exceptions requiring mandatory human oversight (HITL — Human-in-the-Loop: when the automatic engine cannot decide with certainty it escalates to the human team), global cryptographic parameters (signing algorithms, minimum key lengths, minimum TLS protocol, allowed cipher suites), the regulatory compliance map (which standards are mandatory for this tenant based on sector, country, and size, and which controls they automatically activate), and the software supply chain (SBOM: inventory of all dependencies with their CVEs). What is it for? Providing the highest-level governance of the ecosystem: ensuring global parameters are correct, that decisions the automatic engine cannot make with certainty escalate to a human, and that the tenant complies with all applicable standards. How is it used? A change to cryptographic parameters requires HITL approval and compatibility proof with existing systems; the compliance map automatically activates GDPR controls if the tenant declares EU users. Why? Global administration centralizes strategic security decisions affecting the entire ecosystem and ensures no insecure configuration goes unnoticed. Standards: ISO 9001:2015 §5.1/§9.1, ISO/IEC 27001:2022 A.5.2, NIST SP 800-53 R5.2 SA-12/CA-7, NTIA SBOM Minimum Elements 2021, NIST SP 800-131A R2, ISO 19600:2014 (compliance management), NIST AI RMF 1.0.", "es": "Administración Global · administrative_global. ¿Qué es? El dominio de más alto nivel operativo del tenant SBOS: gestiona los usuarios con acceso transversal a todos los tenants (superadministradores SU, auditores externos, operadores de soporte de primer nivel), las notificaciones del sistema de alcance global, las excepciones que requieren supervisión humana obligatoria (HITL — Human-in-the-Loop: cuando el motor automático no puede decidir con certeza escala al equipo humano), los parámetros criptográficos globales del tenant (algoritmos de firma, longitudes de clave mínimas, protocolo TLS mínimo, suites de cifrado permitidas), el mapa de conformidad regulatoria (qué normas son obligatorias para este tenant según su sector, país y tamaño, y qué controles activan automáticamente) y la cadena de suministro de software (SBOM: inventario de todas las dependencias con sus CVEs). ¿Para qué sirve? Proveer el gobierno de más alto nivel del ecosistema: asegurar que los parámetros globales sean correctos, que las decisiones que el motor automático no puede tomar con certeza escalen a un humano, y que el tenant cumpla con todas las normas aplicables. ¿Cómo se usa? Un cambio en los parámetros criptográficos requiere aprobación HITL y prueba de compatibilidad con los sistemas existentes; el mapa de conformidad activa automáticamente los controles GDPR si el tenant declara usuarios en la UE. ¿Por qué? La administración global centraliza las decisiones estratégicas de seguridad que afectan a todo el ecosistema y garantiza que ninguna configuración insegura pase desapercibida. Normas: ISO 9001:2015 §5.1/§9.1, ISO/IEC 27001:2022 A.5.2, NIST SP 800-53 R5.2 SA-12/CA-7, NTIA SBOM Minimum Elements 2021, NIST SP 800-131A R2, ISO 19600:2014 (compliance management), NIST AI RMF 1.0."}', '{}', NULL, NULL, NULL, false, NULL, 99, 1, 0, 'skull.D99', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 9900, 'administrative_global', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f497-7850-9cf1-8a351d5c1c36', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Dual Presence / Mantrap", "es": "Presencia Dual / Exclusa de Seguridad"}', '{"en": "Dual Presence / Mantrap — NIST SP 800-116 R2 §4.2 · IEC 60839-11-3", "es": "Presencia Dual / Exclusa de Seguridad — NIST SP 800-116 R2 §4.2 · IEC 60839-11-3"}', NULL, '{"en": "Dual Presence / Mantrap · presence. What is it? Physical access control requiring the simultaneous presence of two authorized persons to open a high-security door (dual presence principle), or verification that only one person at a time can pass through an airlock (mantrap): the outer door opens, the person enters the chamber, the outer door closes, identity is verified inside the chamber, and only then does the inner door open. What is it for? Protecting maximum-security zones (data centers, server rooms, vaults) against unauthorized access even if someone obtains a valid credential, and against individual-level tailgating. How is it used? Mantrap readers communicate door status to the controller; the system ensures the two doors are never open simultaneously and that the weight/presence inside the chamber corresponds to exactly one person. Why? An attacker with a stolen credential can bypass a normal anti-passback; the security airlock physically prevents more than one person from passing and allows biometric verification inside the chamber before granting access. Standards: NIST SP 800-116 R2 §4.2, IEC 60839-11-3, ISO 27001 A.7.1, UL 294.", "es": "Presencia Dual / Exclusa de Seguridad · presence. ¿Qué es? Control de acceso físico que requiere la presencia simultánea de dos personas autorizadas para abrir una puerta de alta seguridad (principio de doble presencia), o la verificación de que solo una persona a la vez puede pasar por una exclusa (mantrap / airlock): se abre la puerta exterior, la persona entra a la cámara, se cierra la puerta exterior, se verifica la identidad dentro de la cámara, y solo entonces se abre la puerta interior. ¿Para qué sirve? Proteger zonas de máxima seguridad (data centers, salas de servidores, bóvedas) contra accesos no autorizados incluso si alguien obtiene una credencial válida, y contra el tailgating a nivel individual. ¿Cómo se usa? Los lectores del mantrap comunican el estado de las puertas al controlador; el sistema garantiza que las dos puertas nunca estén abiertas simultáneamente y que el peso/presencia dentro de la cámara corresponde a exactamente una persona. ¿Por qué? Un atacante con credencial robada puede forzar un anti-passback normal; la exclusa de seguridad impide físicamente el paso de más de una persona y permite verificar biometría dentro de la cámara antes de conceder acceso. Normas: NIST SP 800-116 R2 §4.2, IEC 60839-11-3, ISO 27001 A.7.1, UL 294."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.presence', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'presence', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f520-74fe-8c78-48d4404c1ff4', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Shift Rotation", "es": "Rotación de Turnos"}', '{"en": "Shift Rotation — NIST SP 800-53 R5 AC-2(2) · GTRBAC §5", "es": "Rotación de Turnos — NIST SP 800-53 R5 AC-2(2) · GTRBAC §5"}', NULL, '{"en": "Shift Rotation · schedules. What is it? Rotating staff shift management engine that automatically updates access time windows when an employee''s assigned shift changes: morning shift (06:00-14:00), afternoon shift (14:00-22:00), night shift (22:00-06:00), and special shifts (24h guard, on-call). Shift changes automatically update the employee''s logical and physical access permissions without manual intervention. What is it for? Synchronizing access controls with HR shift planning, ensuring a morning-shift employee cannot access facilities or systems during the night shift, even if their role has general permissions. How is it used? The HR module publishes the shift calendar to bAuth via API; bAuth updates the temporal windows for each affected employee at the start of the period; urgent shift changes are managed with the exceptions module. Why? Without shift integration, temporal controls are static and do not reflect operational reality; an employee who stopped working the night shift retains night access until someone manually reviews it. Standards: NIST SP 800-53 R5 AC-2(2), GTRBAC §5, ISO 9001:2015 §7.1.2.", "es": "Rotación de Turnos · schedules. ¿Qué es? Motor de gestión de turnos rotativos de personal que actualiza automáticamente las ventanas temporales de acceso cuando cambia el turno asignado a un empleado: turno mañana (06:00-14:00), turno tarde (14:00-22:00), turno noche (22:00-06:00) y turnos especiales (guardia 24h, on-call). El cambio de turno actualiza los permisos de acceso lógico y físico del empleado automáticamente sin intervención manual. ¿Para qué sirve? Sincronizar los controles de acceso con la planificación de turnos de RRHH, garantizando que un empleado de turno mañana no pueda acceder a las instalaciones ni a los sistemas durante el turno noche, incluso si su rol tiene permisos generales. ¿Cómo se usa? El módulo de RRHH publica el calendario de turnos en bAuth vía API; bAuth actualiza las ventanas temporales de cada empleado afectado al inicio del período; los cambios de turno de urgencia se gestionan con el módulo de excepciones. ¿Por qué? Sin integración de turnos, los controles temporales son estáticos y no reflejan la realidad operativa; un empleado que dejó de trabajar el turno noche mantiene acceso nocturno hasta que alguien lo revise manualmente. Normas: NIST SP 800-53 R5 AC-2(2), GTRBAC §5, ISO 9001:2015 §7.1.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.schedules', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'schedules', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f58e-7c7b-aae5-2b531cedb15b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "DPoP / PKCE Tokens", "es": "Tokens DPoP / PKCE"}', '{"en": "DPoP / PKCE Tokens — RFC 9449 §4 · RFC 7636 §4", "es": "Tokens DPoP / PKCE — RFC 9449 §4 · RFC 7636 §4"}', NULL, '{"en": "Network Tokens · tokens. What is it? Management of short-lived network authentication tokens used in the data plane: SPIFFE SVIDs (service identity X.509 for mTLS between microservices), network session tokens (NTK), Kong API proxy tokens (APT), and context propagation tokens (CPT) accompanying each request between ecosystem daemons. Each token has an issuer, audience, signature, and minimum TTL. What is it for? Providing cryptographic identity to every microservice call, ensuring no service can impersonate another and that every request between daemons is signed and bound to the original user''s session. How is it used? bAuth issues SVIDs for each daemon at startup; each daemon automatically renews its SVID before expiry; in each inter-daemon call, the caller includes its SVID plus the context propagation token; the receiver validates both before processing the request. Why? Without service cryptographic identity, a malicious process inside the host can impersonate any daemon and receive tokens and data that do not belong to it; SVIDs ensure only processes with verified identity receive responses. Standards: SPIFFE/SPIRE §3, RFC 8705 (mTLS), NIST SP 800-207 §3.3, RFC 7519 JWT §4.", "es": "Tokens de Red · tokens. ¿Qué es? Gestión de los tokens de autenticación de red de corta vida usados en el plano de datos: SPIFFE SVID (X.509 de identidad de servicio para mTLS entre microservicios), tokens de sesión de red (NTK — Network Token), tokens de acceso de Kong (APT — API Proxy Token) y tokens de propagación de contexto (CPT — Context Propagation Token) que acompañan cada request entre daemons del ecosistema. Cada token tiene emisor, audiencia, firma y TTL mínimo. ¿Para qué sirve? Proveer identidad criptográfica a cada llamada entre microservicios, garantizando que ningún servicio puede hacerse pasar por otro y que cada request entre daemons está firmado y vinculado a la sesión del usuario original. ¿Cómo se usa? bAuth emite los SVIDs para cada daemon al arrancar; cada daemon renueva su SVID automáticamente antes de expirar; en cada llamada inter-daemon, el llamante incluye su SVID más el token de propagación de contexto; el receptor valida ambos antes de procesar el request. ¿Por qué? Sin identidad criptográfica de servicio, un proceso malicioso dentro del host puede hacerse pasar por cualquier daemon y recibir tokens y datos que no le corresponden; los SVIDs garantizan que solo los procesos con identidad verificada reciben respuestas. Normas: SPIFFE/SPIRE §3, RFC 8705 (mTLS), NIST SP 800-207 §3.3, RFC 7519 JWT §4."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.tokens', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'tokens', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f739-77dc-85ee-b038c3aadd05', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-760b-ba59-755ed11ea74b', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Digital Signature) — ETSI EN 319 102 · Ley 164 Bolivia", "es": "Registro de Zona de Negocio (Firma Digital) — ETSI EN 319 102 · Ley 164 Bolivia"}', NULL, '{"en": "Business Zone Registry (Digital Signature) · business_zone. What is it? Container organizing digital signature modules into security zones according to assurance level and signature type: simple electronic signature zone (low-value documents — session key), advanced signature zone (legally effective documents — CA-certified key), qualified signature zone (maximum legal validity documents — key in Qualified Signature Creation Device QSCD, such as HSM), and timestamping zone (RFC 3161 temporal anchoring for proof of existence). What is it for? Segregating access to different digital signature levels, ensuring low-value signing operations have no access to high-value signing keys (where loss of key control would be catastrophic), and QSCDs are only accessible from the qualified signature zone with the strictest PAM controls. How is it used? The document to sign is routed to the appropriate signature zone based on its type and legal value; within the zone, the signature engine accesses the corresponding key (in Vault or QSCD HSM); the zone logs each signature operation in the audit log with the signer''s ctx_id. Why? A compromised qualified signature key can invalidate trust in all documents signed with it; strict zoning reduces the attack surface on highest legal-value keys. Standards: eIDAS 2.0 Art. 26/28, Bolivia Law 164 Art. 12, ETSI EN 319 401, ISO 27001 A.5.17.", "es": "Registro de Zona de Negocio (Firma Digital) · business_zone. ¿Qué es? Contenedor que organiza los módulos de firma digital en zonas de seguridad según el nivel de garantía y el tipo de firma: zona de firma simple electrónica (documentos de bajo valor — clave de sesión), zona de firma avanzada (documentos con efectos jurídicos — clave certificada por CA), zona de firma calificada (documentos con máxima validez jurídica — clave en dispositivo seguro de creación de firma QSCD, como HSM), y zona de sellado de tiempo (anclaje temporal RFC 3161 para prueba de existencia). ¿Para qué sirve? Segregar el acceso a los diferentes niveles de firma digital, garantizando que las operaciones de firma de bajo valor no tienen acceso a las claves de firma de alto valor (donde la pérdida de control de la clave sería catastrófica), y que los QSCD solo son accesibles desde la zona de firma calificada con los controles PAM más estrictos. ¿Cómo se usa? El documento a firmar se enruta a la zona de firma apropiada según su tipo y valor jurídico; dentro de la zona, el motor de firma accede a la clave correspondiente (en Vault o QSCD HSM); la zona registra cada operación de firma en el log de auditoría con el ctx_id del firmante. ¿Por qué? Una clave de firma calificada comprometida puede invalidar la confianza en todos los documentos firmados con ella; la zonificación estricta reduce la superficie de ataque sobre las claves de mayor valor jurídico. Normas: eIDAS 2.0 Art. 26/28, Ley 164 Bolivia Art. 12, ETSI EN 319 401, ISO 27001 A.5.17."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D13.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'business_zone', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f79a-796c-b36d-e6ad5dc4de74', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-76b3-ad3e-3a360429c21d', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (NHI) — SPIFFE Spec v1.0 · CIS Controls v8 §5.4", "es": "Registro de Zona de Negocio (Identidad No Humana) — SPIFFE Spec v1.0 · CIS Controls v8 §5.4"}', NULL, '{"en": "Business Zone Registry (Non-Human Identity) · business_zone. What is it? Container organizing non-human entity identities and accesses in the ecosystem into zones by privilege level and type: service accounts zone (internal ecosystem processes — credentials rotated every 24h), workloads zone (containers and pods — identity by SPIFFE attestation), AI agents zone (autonomous processes — declared and audited scope), M2M connectors zone (external integrations — mTLS client certificates, 90-day TTL), and device identity zone (IoT/hardware — long-lived certificates in device HSM). What is it for? Applying differentiated controls based on privilege level and nature of each non-human identity type: credentials of a production service account require more controls than a low-risk read connector; zoning ensures each NHI (Non-Human Identity) type has exactly the controls appropriate to its risk. How is it used? Each non-human identity registers in the zone corresponding to its type; the zone defines the maximum credential lifetime, rotation frequency, required authentication mechanism (AppRole, SPIFFE, mTLS), and maximum requestable scope; the PAM engine automatically applies zone controls without individual configuration. Why? Non-human identities outnumber human ones in any modern ecosystem; without zoning, managing them individually is unmanageable and error-prone; NHI zones allow managing hundreds of service identities with coherent zone policies. Standards: SPIFFE/SPIRE §3, NIST SP 800-53 R5 IA-2(6), CIS Controls v8 §4, ISO 27001 A.8.1.", "es": "Registro de Zona de Negocio (Identidad No Humana) · business_zone. ¿Qué es? Contenedor que organiza las identidades y accesos de entidades no humanas del ecosistema en zonas según su nivel de privilegio y tipo: zona de cuentas de servicio (procesos internos del ecosistema — credenciales rotadas cada 24h), zona de cargas de trabajo (contenedores y pods — identidad por atestación SPIFFE), zona de agentes de IA (procesos autónomos — scope declarado y auditado), zona de conectores M2M (integraciones externas — certificados de cliente mTLS, TTL 90 días), y zona de identidades de dispositivo (IoT/hardware — certificados de larga vida en HSM del dispositivo). ¿Para qué sirve? Aplicar controles diferenciados según el nivel de privilegio y la naturaleza de cada tipo de identidad no humana: las credenciales de una cuenta de servicio de producción requieren más controles que las de un conector de lectura de bajo riesgo; la zonificación garantiza que cada tipo de NHI (Non-Human Identity) tiene exactamente los controles apropiados a su riesgo. ¿Cómo se usa? Cada identidad no humana se registra en la zona correspondiente a su tipo; la zona define la vida máxima de sus credenciales, la frecuencia de rotación, el mecanismo de autenticación requerido (AppRole, SPIFFE, mTLS) y el scope máximo solicitabe; el motor PAM aplica automáticamente los controles de la zona sin configuración individual. ¿Por qué? Las identidades no humanas superan en número a las humanas en cualquier ecosistema moderno; sin zonificación, gestionarlas individualmente es inmanejable y propenso a errores; las zonas NHI permiten gestionar cientos de identidades de servicio con políticas de zona coherentes. Normas: SPIFFE/SPIRE §3, NIST SP 800-53 R5 IA-2(6), CIS Controls v8 §4, ISO 27001 A.8.1."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D15.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 80, 'business_zone', 'B08') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f765-785d-b9c3-b79d04b5c1e8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-766b-befb-df5991d984dc', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (PAM) — NIST SP 800-53 R5 AC-6(5) · CIS Controls v8 §5", "es": "Registro de Zona de Negocio (Acceso Privilegiado) — NIST SP 800-53 R5 AC-6(5) · CIS Controls v8 §5"}', NULL, '{"en": "Business Zone Registry (Privileged Access) · business_zone. What is it? Container organizing Privileged Access Management (PAM) modules into maximum security zones: system administrative access zone (SYS administrators only with FIDO2 hardware MFA and recorded session), secrets and keys access zone (Vault — PAM roles only with documented justification and approval), emergency access zone (break-glass — maximum 2 people simultaneously, fully recorded), and privileged M2M access zone (service accounts with elevated permissions — automatic credential rotation). What is it for? Applying the ecosystem''s strictest controls exactly where most needed: privileged accesses are the primary attacker target (80% of breaches involve compromised privileged access); PAM zones ensure no privileged access occurs without multiple authentication, recording, and approval. How is it used? Administrators access the corresponding PAM zone with their high-assurance credentials (FIDO2 hardware key); the PAM engine initiates the recorded session; access to the target system is through the PAM proxy (never direct access); upon session end, the recording is sealed with a hash and archived in the audit log. Why? Unmanaged privileged access is the cause of 80% of enterprise breaches; PAM controls make privileged access the hardest to abuse, not the easiest. Standards: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5, ISO 27001 A.8.2, PCI DSS 4.0 Req 8.2.", "es": "Registro de Zona de Negocio (Acceso Privilegiado) · business_zone. ¿Qué es? Contenedor que organiza los módulos de acceso privilegiado (PAM — Privileged Access Management) en zonas de seguridad máxima: zona de acceso administrativo a sistemas (solo administradores SYS con MFA hardware FIDO2 y sesión grabada), zona de acceso a secretos y claves (Vault — solo roles PAM con justificación documentada y aprobación), zona de acceso de emergencia (break-glass — máximo 2 personas simultáneas, completamente grabado), y zona de acceso M2M privilegiado (cuentas de servicio con permisos elevados — rotación automática de credenciales). ¿Para qué sirve? Aplicar los controles más estrictos del ecosistema exactamente donde más se necesitan: los accesos privilegiados son el objetivo principal de los atacantes (el 80% de las brechas involucran acceso privilegiado comprometido); las zonas PAM garantizan que ningún acceso privilegiado ocurre sin múltiple autenticación, grabación y aprobación. ¿Cómo se usa? Los administradores acceden a la zona PAM correspondiente con sus credenciales de alta garantía (FIDO2 hardware key); el motor PAM inicia la sesión grabada; el acceso al sistema objetivo es a través del proxy PAM (nunca acceso directo); al terminar la sesión, la grabación se sella con hash y se archiva en el log de auditoría. ¿Por qué? El acceso privilegiado no gestionado es la causa del 80% de las brechas empresariales; los controles PAM convierten el acceso privilegiado en el acceso más difícil de abusar, no el más fácil. Normas: NIST SP 800-53 R5 AC-2(1), CIS Controls v8 §5, ISO 27001 A.8.2, PCI DSS 4.0 Req 8.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D14.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f64f-7133-9e7a-f4eea83f86c0', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Delegation Auditability", "es": "Auditabilidad de Delegación"}', '{"en": "Delegation Auditability — ISO 27001 A.8.15 · NIST SP 800-53 R5 AU-2", "es": "Auditabilidad de Delegación — ISO 27001 A.8.15 · NIST SP 800-53 R5 AU-2"}', NULL, '{"en": "Audit Log · audit. What is it? Append-only recording system for all relevant security events from the identity plane: successful and failed authentications (with ctx_id, IP, device, achieved AAL), permission and role changes (what changed, who changed it, when), sensitive resource accesses (with the exact BitMask state at the time of access), revocation and suspension events, and anomaly detections. Each record includes: microsecond timestamp, operation ctx_id, previous event hash (integrity chain), and digital signature with bAuth''s audit key. What is it for? Providing an irrefutable source of truth about what happened in the identity plane for forensic investigations, compliance audits (ISO 27001, SOX, PCI DSS), and incident detection. How is it used? Events are written to the audit log synchronously with the operation (cannot operate without recording); the log is read-only for all roles except the auditor role with read-only access; events are retained per retention policy (minimum 7 years for SOX); replicated to Wazuh SIEM in real time. Why? Without an inviolable audit log, incident investigations have no reliable evidence; attackers who delete logs destroy forensic response capability; append-only with hash chain makes it computationally impossible to delete events without being detected. Standards: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-2, SOX §404, PCI DSS 4.0 Req 10.", "es": "Registro de Auditoría · audit. ¿Qué es? Sistema de registro append-only de todos los eventos de seguridad relevantes del plano de identidad: autenticaciones exitosas y fallidas (con ctx_id, IP, dispositivo, AAL alcanzado), cambios de permisos y roles (qué cambió, quién lo cambió, cuándo), accesos a recursos sensibles (con el estado exacto del BitMask en el momento del acceso), eventos de revocación y suspensión, y detecciones de anomalías. Cada registro incluye: timestamp con microsegundos, ctx_id de la operación, hash del evento anterior (cadena de integridad), y firma digital con la clave de auditoría de bAuth. ¿Para qué sirve? Proveer una fuente de verdad irrefutable sobre qué ocurrió en el plano de identidad para investigaciones forenses, auditorías de cumplimiento (ISO 27001, SOX, PCI DSS) y detección de incidentes. ¿Cómo se usa? Los eventos se escriben en el log de auditoría sincrónicamente con la operación (no se puede operar sin registrar); el log es de solo lectura para todos los roles excepto el rol de auditor con acceso de solo lectura; los eventos se retienen según la política de retención (mínimo 7 años para SOX); se replican a Wazuh SIEM en tiempo real. ¿Por qué? Sin registro de auditoría inviolable, las investigaciones de incidentes no tienen evidencia confiable; los atacantes que borran logs destruyen la capacidad de respuesta forense; el append-only con hash chain hace computacionalmente imposible borrar eventos sin ser detectado. Normas: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-2, SOX §404, PCI DSS 4.0 Req 10."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.audit', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'audit', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f79d-75a6-9983-c0065421eca0', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c96-7b9f-b9bc-e68dff0080fe', 'block', '{"en": "Attribute Schema", "es": "Esquema de Atributos"}', '{"en": "Attribute Schema — SCIM 2.0 RFC 7643 §4 · ISO/IEC 24760-1:2019 §5", "es": "Esquema de Atributos — SCIM 2.0 RFC 7643 §4 · ISO/IEC 24760-1:2019 §5"}', NULL, '{"en": "Identity Tree Schema · schema. What is it? The structural definition of the SBOS hierarchical identity tree: root (skull), 18 depth-1 domains (D00–D15, D98, D99), up to 10 blocks per domain at depth 2, and application zones and individual applications at depths 3 and 4. The schema defines: valid node types (domain, block, policy, application), mandatory JSONB fields by type (key, name, help, bitmask, restrictions), insertion rules (a node can only be inserted under its valid parent type), and uniqueness constraints (the path is unique throughout the tree). What is it for? Defining and enforcing the structural rules of the identity tree: schema validators ensure no process can insert incorrectly typed nodes, create invalid inheritance paths, or violate uniqueness constraints that guarantee tree integrity. How is it used? The schema is loaded at database initialization and validated on every write operation on the tree; any attempt to insert or modify a node that violates the schema is rejected with a descriptive error; schema migrations follow the catalog versioning process with dual approval. Why? An identity tree without a validated schema can gradually corrupt with mistyped nodes, duplicate paths, or circular inheritances that cause undefined behaviors in the BitMask engine; the schema is the only guarantee of structural integrity of the tree. Standards: ISO/IEC 13335-1:2004 §6, ANSI INCITS 359-2004 §4.1, NIST SP 800-53 R5 CM-2, PostgreSQL JSONB Schema Validation.", "es": "Esquema del Árbol de Identidad · schema. ¿Qué es? La definición estructural del árbol jerárquico de identidad SBOS: raíz (skull), 18 dominios de profundidad 1 (D00–D15, D98, D99), hasta 10 bloques por dominio de profundidad 2, y las zonas de aplicación y aplicaciones individuales en profundidades 3 y 4. El esquema define: tipos de nodo válidos (dominio, bloque, politica, aplicacion), campos JSONB obligatorios por tipo (clave, name, help, bitmask, restricciones), reglas de inserción (un nodo solo puede insertarse bajo su tipo padre válido), y constraints de unicidad (el path es único en todo el árbol). ¿Para qué sirve? Definir y hacer cumplir las reglas estructurales del árbol de identidad: los validadores del esquema garantizan que ningún proceso puede insertar nodos de tipo incorrecto, crear caminos de herencia inválidos o violar las constraints de unicidad que garantizan la integridad del árbol. ¿Cómo se usa? El esquema se carga al inicializar la base de datos y se valida en cada operación de escritura sobre el árbol; cualquier intento de insertar o modificar un nodo que viole el esquema es rechazado con un error descriptivo; las migraciones de esquema siguen el proceso de versionado del catálogo con doble aprobación. ¿Por qué? Un árbol de identidad sin esquema validado puede corromperse gradualmente con nodos mal tipados, paths duplicados o herencias circulares que causen comportamientos indefinidos en el motor de BitMask; el esquema es la única garantía de integridad estructural del árbol. Normas: ISO/IEC 13335-1:2004 §6, ANSI INCITS 359-2004 §4.1, NIST SP 800-53 R5 CM-2, PostgreSQL JSONB Schema Validation."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D98.schema', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'schema', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f47b-7cf0-aced-88b6b53b7250', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-703f-b259-eb318efed879', 'block', '{"en": "Access Recertification", "es": "Recertificación de Accesos"}', '{"en": "Access Recertification — NIST SP 800-53 R5 AC-2(7) · ISO 27001 A.5.18", "es": "Recertificación de Accesos — NIST SP 800-53 R5 AC-2(7) · ISO 27001 A.5.18"}', NULL, '{"en": "Access Recertification · certification. What is it? Periodic and formal review process of all active role and permission assignments to confirm they remain necessary, appropriate, and current. Generates recertification campaigns with specific approval managers, defined deadlines, automatic escalation, and records the decision (confirm / revoke / modify) as permanent audit evidence. What is it for? Detecting and eliminating permissions accumulated over time (privilege creep) and meeting the periodic access review requirement of security and audit standards. How is it used? The system automatically generates quarterly recertification campaigns for BIZ roles and semi-annual for SYS; each manager reviews their subordinates'' roles and approves, revokes, or escalates; roles without a decision within the deadline are automatically revoked. Why? 60% of excessive privilege risk comes from roles accumulated after position changes; recertification is the control that guarantees the principle of least privilege over time. Standards: NIST SP 800-53 R5 AC-2(7), ISO 27001 A.5.18, PCI DSS 4.0 Req 7.2.3, SOX §404.", "es": "Recertificación de Accesos · certification. ¿Qué es? Proceso periódico y formal de revisión de todas las asignaciones de roles y permisos activos para confirmar que siguen siendo necesarios, apropiados y vigentes. Genera campañas de recertificación con gestores de aprobación específicos, plazos definidos, escalación automática y registra la decisión (confirmar / revocar / modificar) como evidencia de auditoría permanente. ¿Para qué sirve? Detectar y eliminar permisos acumulados por el paso del tiempo (privilege creep) y cumplir el requisito de revisión periódica de accesos de las normas de seguridad y auditoría. ¿Cómo se usa? El sistema genera automáticamente campañas de recertificación trimestrales para roles BIZ y semestrales para SYS; cada gestor revisa los roles de sus subordinados y aprueba, revoca o escala; los roles sin decisión en el plazo son revocados automáticamente. ¿Por qué? El 60% del riesgo de privilegios excesivos proviene de roles acumulados tras cambios de puesto; la recertificación es el control que garantiza el principio de mínimo privilegio en el tiempo. Normas: NIST SP 800-53 R5 AC-2(7), ISO 27001 A.5.18, PCI DSS 4.0 Req 7.2.3, SOX §404."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D01.certification', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'certification', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4a2-7b09-8345-bf17c1d29856', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-70b7-af8d-a4e2793bca11', 'block', '{"en": "Anti-Passback", "es": "Prevención de Re-entrada"}', '{"en": "Anti-Passback — IEC 60839-11-1 §6.4 · ISO 27001 A.7.2", "es": "Prevención de Re-entrada — IEC 60839-11-1 §6.4 · ISO 27001 A.7.2"}', NULL, '{"en": "Anti-Passback · antipassback. What is it? Physical control preventing a credential already used to enter a zone from being used again to enter that same zone without having first registered a valid exit. Detects tailgating (two people passing with one credential) and credential sharing between personnel. Can be temporal (the credential cannot re-enter for N minutes) or absolute (requires a registered exit without exception). What is it for? Preventing a person from entering a secure zone by following another without passing through the reader (tailgating), or sharing their credential with another person so both can enter together. How is it used? The OSDP controller records each entry and exit; before PERMIT on an entry, it verifies that the last event for the credential was an exit; if it was an entry, it denies and generates an alert. Why? Tailgating and credential lending are the most common vectors of unauthorized physical access in office environments; anti-passback is the technical control that eliminates them. Standards: IEC 60839-11-1 §6.4, ISO 27001 A.7.2, SIA OSDP v2.2.2, NIST SP 800-116 R2.", "es": "Prevención de Re-entrada · antipassback. ¿Qué es? Control físico que impide que una credencial que ya se usó para entrar a una zona pueda usarse de nuevo para entrar a esa misma zona sin haber registrado antes una salida válida. Detecta el \"tailgating\" (paso de dos personas con una sola credencial) y el préstamo de credenciales entre personal. Puede ser temporal (la credencial no puede re-ingresar durante N minutos) o absoluto (requiere salida registrada sin excepción). ¿Para qué sirve? Prevenir que una persona entre a una zona segura siguiendo a otra sin pasar por el lector (tailgating) o que comparta su credencial con otra persona para que entren los dos juntos. ¿Cómo se usa? El controlador OSDP registra cada entrada y salida; antes de PERMIT en una entrada, verifica que el último evento de la credencial fue una salida; si fue una entrada, deniega y genera alerta. ¿Por qué? El tailgating y el préstamo de credencial son los vectores más comunes de acceso físico no autorizado en entornos de oficina; el anti-passback es el control técnico que los elimina. Normas: IEC 60839-11-1 §6.4, ISO 27001 A.7.2, SIA OSDP v2.2.2, NIST SP 800-116 R2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D02.antipassback', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'antipassback', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f7e9-722d-8c80-abfbedfe4a19', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-777a-81e9-61a09beb7c67', 'block', '{"en": "HITL Exceptions", "es": "Excepciones HITL"}', '{"en": "Human-in-the-Loop Exceptions — NIST AI RMF 1.0 §3.6 · ISO 27001 A.5.29", "es": "Excepciones con Supervisión Humana — NIST AI RMF 1.0 §3.6 · ISO 27001 A.5.29"}', NULL, '{"en": "Global Policy Exceptions · exceptions. What is it? Exception management system for global ecosystem security policies: when a tenant or module has a legitimate business requirement conflicting with a global policy (e.g., the banking tenant needs to retain logs for 10 years when the global policy is 7 years, or a legacy module does not support TLS 1.3 and needs to temporarily use TLS 1.2), they can request a formal exception that is evaluated, approved by the CISO, and documented with its justification, validity period, and remediation plan. What is it for? Providing a formal and transparent mechanism to manage security policy exceptions without them becoming permanent informal deviations: each exception has an expiration date and remediation plan, ensuring they are temporary and do not accumulate indefinitely. How is it used? The requester submits the exception request with: the policy being excepted, the business reason, the estimated residual risk, proposed compensating controls, and remediation timeline; the security team evaluates the request; the CISO approves or rejects; the approved exception is registered with active compensating controls and expiration date; the exception monitor alerts when expiration approaches to force renewal or remediation. Why? Without a formal exception process, policy deviations occur informally and become permanent without documentation; the formal process ensures visibility, accountability, and a deadline for each exception. Standards: ISO 27001:2022 §6.1.3 (risk treatment), NIST SP 800-53 R5 CA-2(2), ISO 9001:2015 §8.7, PCI DSS 4.0 Req 12.3.", "es": "Excepciones de Política Global · exceptions. ¿Qué es? Sistema de gestión de excepciones a las políticas de seguridad globales del ecosistema: cuando un tenant o módulo tiene un requerimiento de negocio legítimo que entra en conflicto con una política global (ej: el tenant bancario necesita retener logs por 10 años cuando la política global es 7 años, o un módulo legacy no soporta TLS 1.3 y necesita usar TLS 1.2 temporalmente), puede solicitar una excepción formal que es evaluada, aprobada por el CISO y documentada con su justificación, período de validez y plan de remediación. ¿Para qué sirve? Proveer un mecanismo formal y transparente para gestionar las excepciones a las políticas de seguridad sin que estas excepciones se conviertan en desviaciones informales permanentes: cada excepción tiene fecha de expiración y plan de remediación, garantizando que son temporales y no se acumulan indefinidamente. ¿Cómo se usa? El solicitante envía la solicitud de excepción con: la política que se exceptúa, el motivo de negocio, el riesgo residual estimado, los controles compensatorios propuestos y el plazo de remediación; el equipo de seguridad evalúa la solicitud; el CISO aprueba o rechaza; la excepción aprobada se registra con los controles compensatorios activos y la fecha de expiración; el monitor de excepciones alerta cuando se aproxima la expiración para forzar la renovación o remediación. ¿Por qué? Sin un proceso formal de excepciones, las desviaciones de política ocurren de forma informal y se vuelven permanentes sin documentación; el proceso formal garantiza visibilidad, responsabilidad y fecha límite para cada excepción. Normas: ISO 27001:2022 §6.1.3 (risk treatment), NIST SP 800-53 R5 CA-2(2), ISO 9001:2015 §8.7, PCI DSS 4.0 Req 12.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D99.exceptions', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'exceptions', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c98-7ebd-ad96-88a315478d98', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Organizational Identity", "es": "Identidad Organizacional"}', '{"en": "Organizational Identity", "es": "Identidad Organizacional"}', NULL, '{"en": "Organizational Identity · identity_organizational. What is it? The master domain and foundation of the SBOS identity tree: contains the canonical Role schema (66 templates, 368 roles, 7 tiers), User schema (16 JSONB blocks), extended attributes, identity proofing (IAL1-3), GDPR/LGPD consent, W3C verifiable credentials, and federation assurance levels (FAL1-3). What is it for? Defines the data structures used as reference by every identity operation; without this domain there is no foundation on which to build roles, permissions, or users. How is it used? Every role, user, or credential is validated against D00 schemas before being accepted by the identity engine; any attribute outside the schema is rejected. Why? Without a canonical identity model, all other domains would operate with inconsistent definitions, creating security gaps and audit failures. Standards: ISO/IEC 24760-2:2025 §6-8, ISO/IEC 24760-1:2019, ANSI INCITS 359-2004, NIST SP 800-63-4, SCIM 2.0 RFC 7643, W3C VC Data Model 2.0, GDPR Art. 4/6/7, ISO 9001:2015 §3.2.4.", "es": "Identidad Organizacional · identity_organizational. ¿Qué es? El dominio maestro y cimiento del árbol de identidad SBOS: contiene el esquema canónico del Rol (66 plantillas, 368 roles, 7 tiers), el esquema del Usuario (16 bloques JSONB), atributos extendidos, verificación de identidad (IAL1-3), consentimiento GDPR/LGPD, credenciales verificables W3C y niveles de garantía de federación (FAL1-3). ¿Para qué sirve? Define las estructuras de datos que toda operación de identidad utiliza como referencia; sin este dominio no existe base sobre la que construir roles, permisos ni usuarios. ¿Cómo se usa? Todo rol, usuario o credencial se valida contra los esquemas de D00 antes de ser aceptado por el motor de identidad; cualquier atributo fuera del esquema es rechazado. ¿Por qué? Sin un modelo canónico de identidad, los demás dominios operarían con definiciones inconsistentes, generando brechas de seguridad y fallos de auditoría. Normas: ISO/IEC 24760-2:2025 §6-8, ISO/IEC 24760-1:2019, ANSI INCITS 359-2004, NIST SP 800-63-4, SCIM 2.0 RFC 7643, W3C VC Data Model 2.0, GDPR Art. 4/6/7, ISO 9001:2015 §3.2.4."}', '{}', NULL, NULL, NULL, false, NULL, 0, 1, 0, 'skull.D00', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 200, 'identity_organizational', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-766b-befb-df5991d984dc', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Privileged Access Management (PAM)", "es": "Gestión de Acceso Privilegiado (PAM)"}', '{"en": "Privileged Access Management (PAM)", "es": "Gestión de Acceso Privilegiado (PAM)"}', NULL, '{"en": "Privileged Access Management (PAM) · privileged_access. What is it? The control system for the highest-privilege accounts in the ecosystem: root, DBA, sysadmin, domain accounts, and critical service accounts. Manages the complete lifecycle: automatic privileged account inventory and discovery (including unknown or forgotten accounts), credential vaulting with automatic rotation after each use (one-time password pattern, Vault HSM), Just-in-Time access (no standing privileges: activated only when needed for the minimum required time), SSH/RDP session brokering and complete recording (command log, video, indexed search), periodic privilege review, and privilege creep detection. What is it for? Eliminating the risk of always-active privileged accounts, which are the primary target of advanced attackers and the most damaging breach vector. How is it used? An administrator needs production access: requests JIT access specifying task and duration; system approves (automatic if low risk, HITL if high risk); credentials are activated; SSH/RDP session recorded entirely; when time expires credentials are automatically rotated. Why? 74% of data breaches involve privileged credential abuse (Verizon DBIR 2024); JIT access with no standing privileges reduces risk to minimum. Standards: NIST SP 800-53 R5.2 AC-2(7)/AC-6(5)/AU-14, ISO 27001:2022 A.5.18, PCI DSS 4.0 Req 7-8, CyberArk PAM Framework, CIS Controls v8 §5, SWIFT CSCF v2024.", "es": "Gestión de Acceso Privilegiado (PAM) · privileged_access. ¿Qué es? El sistema de control de las cuentas con los privilegios más altos del ecosistema: root, DBA, sysadmin, cuentas de dominio y cuentas de servicio críticas. Gestiona el ciclo de vida completo: inventario y descubrimiento automático de cuentas privilegiadas (incluyendo cuentas desconocidas u olvidadas), bóveda de credenciales con rotación automática tras cada uso (one-time password pattern, Vault HSM), acceso Just-in-Time o Justo a Tiempo (sin privilegios permanentes: se activan solo cuando se necesitan y por el tiempo mínimo requerido), mediación y grabación completa de sesiones SSH/RDP (log de comandos, video, búsqueda indexada), revisión periódica de privilegios y detección de privilege creep. ¿Para qué sirve? Eliminar el riesgo de cuentas privilegiadas siempre activas, que son el objetivo principal de los atacantes avanzados y el vector más dañino de una brecha. ¿Cómo se usa? Un administrador necesita acceso a producción: solicita acceso JIT especificando tarea y duración; el sistema aprueba (automático si riesgo bajo, HITL si alto); las credenciales se activan; la sesión SSH/RDP se registra íntegramente; al vencer el tiempo las credenciales se rotan automáticamente. ¿Por qué? El 74% de las brechas de datos involucra abuso de credenciales privilegiadas (Verizon DBIR 2024); el acceso JIT sin standing privileges reduce el riesgo al mínimo. Normas: NIST SP 800-53 R5.2 AC-2(7)/AC-6(5)/AU-14, ISO 27001:2022 A.5.18, PCI DSS 4.0 Req 7-8, CyberArk PAM Framework, CIS Controls v8 §5, SWIFT CSCF v2024."}', '{}', NULL, NULL, NULL, false, NULL, 14, 1, 0, 'skull.D14', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1600, 'privileged_access', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5ce-7e5a-aba5-0fdea6e61111', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-73b3-a6f3-eebc42cfa13d', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Context) — NIST SP 800-207 §3 · W3C Trace Context v2", "es": "Registro de Zona de Negocio (Contexto) — NIST SP 800-207 §3 · W3C Trace Context v2"}', NULL, '{"en": "Business Zone Registry (Context/Session) · business_zone. What is it? Container organizing session management and dynamic context evaluation modules into functional zones: initial authentication zone (where primary tokens are generated), continuous authorization zone (where context is re-evaluated on each request), step-up zone (where assurance level is elevated without full re-authentication), and risk context zone (where risk signals trigger adaptive policies). What is it for? Separating session management module responsibilities and ensuring each module operates in the appropriate context: the step-up module has no access to primary token storage; the session audit module is read-only. How is it used? Session modules are assigned to their functional zone at initialization; zone policies determine what operations each module can perform; session functional zones intersect with network zones to determine applicable controls. Why? Without functional session zoning, any module can read and modify any token, creating a privilege escalation risk internal to the session engine itself. Standards: NIST SP 800-63B-4 §7, NIST SP 800-207 §3, ISO 27001 A.8.18, RFC 6749 §10.", "es": "Registro de Zona de Negocio (Contexto/Sesión) · business_zone. ¿Qué es? Contenedor que organiza los módulos de gestión de sesiones y evaluación de contexto dinámico en zonas funcionales: zona de autenticación inicial (donde se generan los tokens primarios), zona de autorización continua (donde se re-evalúa el contexto en cada request), zona de step-up (donde se eleva el nivel de garantía sin re-autenticar completamente) y zona de contexto de riesgo (donde las señales de riesgo disparan políticas adaptativas). ¿Para qué sirve? Separar las responsabilidades de los módulos de gestión de sesiones y garantizar que cada módulo opera en el contexto apropiado: el módulo de step-up no tiene acceso al almacenamiento de tokens primarios; el módulo de auditoría de sesiones es de solo lectura. ¿Cómo se usa? Los módulos de sesión se asignan a su zona funcional al inicializarse; las políticas de la zona determinan qué operaciones puede realizar cada módulo; las zonas funcionales de sesión se intersectan con las zonas de red para determinar los controles aplicables. ¿Por qué? Sin zonificación funcional de sesiones, cualquier módulo puede leer y modificar cualquier token, creando un riesgo de escalada de privilegios interna al propio motor de sesiones. Normas: NIST SP 800-63B-4 §7, NIST SP 800-207 §3, ISO 27001 A.8.18, RFC 6749 §10."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D08.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f510-7e37-aff4-8bc707221503', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Time Windows", "es": "Ventanas de Tiempo"}', '{"en": "Time Windows — GTRBAC §3.2 · NIST SP 800-53 R5 AC-3(7)", "es": "Ventanas de Tiempo — GTRBAC §3.2 · NIST SP 800-53 R5 AC-3(7)"}', NULL, '{"en": "Time Windows · windows. What is it? Granular definition of time slots during which a specific role or function can be exercised: permitted days of week, start and end times with minute precision, time zones by tenant (for multinational organizations), and additional validity conditions (business days only, exclude national holidays of region X). Windows are inheritable: a role inherits time windows from its temporal zone but can further restrict them. What is it for? Defining with surgical precision when each function is accessible, implementing the principle of minimum temporal exposure: the function is only available when genuinely needed. How is it used? The access evaluator queries the windows defined for the user''s role in the current tenant; verifies that the request date/time (in the tenant''s time zone) falls within a valid window; if no valid window is active, access is DENY even if the BitMask enables it. Why? Precise time windows reduce the overnight attack window: if an attacker with a stolen credential attempts to connect at 03:00, temporal windows block access even if the BitMask indicates correct permissions. Standards: GTRBAC §3.2, NIST SP 800-53 R5 AC-3(7), ISO 8601:2019, RFC 5545 §3.3.5.", "es": "Ventanas de Tiempo · windows. ¿Qué es? Definición granular de las franjas horarias en que un rol o función específica puede ser ejercida: días de la semana permitidos, horas de inicio y fin con minuto de precisión, zonas horarias por tenant (para organizaciones multinacionales), y condiciones adicionales de validez (solo en días hábiles, excluir feriados nacionales de la región X). Las ventanas son heredables: un rol hereda las ventanas de su zona temporal pero puede restringirlas adicionalmente. ¿Para qué sirve? Definir con precisión quirúrgica cuándo cada función es accesible, implementando el principio de mínima exposición temporal: la función solo está disponible cuando realmente se necesita. ¿Cómo se usa? El evaluador de acceso consulta las ventanas definidas para el rol del usuario en el tenant actual; verifica que la fecha/hora del request (en la zona horaria del tenant) cae dentro de alguna ventana válida; si no hay ventana válida activa, el acceso es DENY aunque el BitMask lo habilite. ¿Por qué? Las ventanas de tiempo precisas reducen la ventana de ataque nocturna: si un atacante con credencial robada intenta conectarse a las 03:00, las ventanas temporales bloquean el acceso aunque el BitMask indique permisos correctos. Normas: GTRBAC §3.2, NIST SP 800-53 R5 AC-3(7), ISO 8601:2019, RFC 5545 §3.3.5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.windows', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'windows', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f536-7287-97d6-9dc7e1fb38b9', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "Liveness Detection (PAD)", "es": "Detección de Vivacidad (PAD)"}', '{"en": "Liveness Detection (PAD) — ISO/IEC 30107-3:2023 §5 · FIDO2 §8.8", "es": "Detección de Vivacidad (PAD) — ISO/IEC 30107-3:2023 §5 · FIDO2 §8.8"}', NULL, '{"en": "Liveness Detection (PAD) · liveness. What is it? Presentation Attack Detection (PAD) engine verifying that the biometric sample comes from a physically present live person and not an artifact (printed photo, video screen, 3D mask, silicone finger). Implements: skin texture analysis (micro thermal and reflectance variations), spontaneous eye movement detection (active liveness: ask to blink), 3D depth analysis with infrared camera, and artifact detection via near-infrared (NIR) spectrum. What is it for? Ensuring the biometric factor cannot be falsified with easily accessible materials, maintaining the integrity of AAL3 assurance level. How is it used? Every biometric capture first passes through the PAD module before comparison against the template; if PAD detects a presentation attack, authentication fails with a specific error code and a security alert is generated. Why? Without PAD, an attacker can print a photo of the user and use it to bypass biometric control; PAD is mandatory for biometrics to reach NIST SP 800-63B-4 AAL3 level. Standards: ISO/IEC 30107-3:2023 §5, FIDO2 §8.8, NIST SP 800-76-2 §3.1.3, ISO/IEC 30107-1:2023.", "es": "Detección de Vivacidad (PAD) · liveness. ¿Qué es? Motor de detección de ataques de presentación (Presentation Attack Detection) que verifica que la muestra biométrica proviene de una persona viva presente físicamente y no de un artefacto (foto impresa, pantalla con video, máscara 3D, dedo de silicona). Implementa: análisis de textura de piel (micro-variaciones térmicas y de reflectancia), detección de movimiento ocular espontáneo (liveness activo: pedir parpadear), análisis de profundidad 3D con cámara infrarroja y detección de artefactos por espectro infrarrojo cercano (NIR). ¿Para qué sirve? Garantizar que el factor biométrico no puede ser falsificado con materiales fácilmente accesibles, manteniendo la integridad del nivel de garantía AAL3. ¿Cómo se usa? Toda captura biométrica pasa primero por el módulo PAD antes de la comparación contra el template; si el PAD detecta un ataque de presentación, la autenticación falla con código de error específico y se genera alerta de seguridad. ¿Por qué? Sin PAD, un atacante puede imprimir una foto del usuario y usarla para superar el control biométrico; el PAD es obligatorio para que la biometría alcance el nivel NIST SP 800-63B-4 AAL3. Normas: ISO/IEC 30107-3:2023 §5, FIDO2 §8.8, NIST SP 800-76-2 §3.1.3, ISO/IEC 30107-1:2023."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.liveness', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'liveness', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f53f-7b9d-9439-63391b6b25a7', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "Biometric Template Revocation", "es": "Revocación de Template Biométrico"}', '{"en": "Biometric Template Revocation — ISO/IEC 24745:2022 §6 · NIST SP 800-76-2 §6", "es": "Revocación de Plantilla Biométrica — ISO/IEC 24745:2022 §6 · NIST SP 800-76-2 §6"}', NULL, '{"en": "Biometric Template Revocation · revocation. What is it? Process of permanent and irrecoverable invalidation of a registered biometric template upon compromise or trait change events: compromised fingerprint (attacker has a copy), injury permanently altering the trait, natural biometric change (cataracts altering iris), or user privacy request. Unlike a password, a compromised biometric template cannot simply be \"changed\" — it requires re-enrollment with reinforced verification. What is it for? Immediately neutralizing a compromised template''s ability to authenticate an attacker, and ensuring the user can recover biometric authentication capability with a new validated enrollment. How is it used? When a compromise is detected or reported, the system invalidates the template (marks as revoked in the template database), initiates the re-enrollment protocol with in-person identity verification, and generates a security alert for incident investigation. Why? Unlike passwords, biometric traits cannot be arbitrarily changed; controlled revocation and supervised re-enrollment are the only technical response to a compromised template. Standards: ISO/IEC 24745:2022 §6, NIST SP 800-76-2 §6, ISO/IEC 30107-1:2023 §7, GDPR Art. 17 (right to erasure).", "es": "Revocación de Plantilla Biométrica · revocation. ¿Qué es? Proceso de invalidación permanente e irrecuperable de un template biométrico registrado ante eventos de compromiso o cambio del rasgo: huella comprometida (el atacante tiene una copia), lesión que altera el rasgo permanentemente, cambio biométrico natural (cataratas que alteran el iris), o solicitud del usuario por privacidad. A diferencia de una contraseña, un template biométrico comprometido no puede ser simplemente \"cambiado\" — requiere re-enrolamiento con verificación reforzada. ¿Para qué sirve? Neutralizar inmediatamente la capacidad de un template comprometido de autenticar a un atacante, y garantizar que el usuario pueda recuperar su capacidad de autenticación biométrica con un nuevo enrolamiento validado. ¿Cómo se usa? Al detectar o reportar un compromiso, el sistema invalida el template (marca como revocado en la base de templates), inicia el protocolo de re-enrolamiento con verificación de identidad presencial y genera alerta de seguridad para investigación del incidente. ¿Por qué? A diferencia de contraseñas, los rasgos biométricos no pueden ser cambiados arbitrariamente; la revocación controlada y el re-enrolamiento supervisado son la única respuesta técnica ante un template comprometido. Normas: ISO/IEC 24745:2022 §6, NIST SP 800-76-2 §6, ISO/IEC 30107-1:2023 §7, GDPR Art. 17 (derecho al olvido)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.revocation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'revocation', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f550-7d57-b295-f489157ec07b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Location Validation", "es": "Validación de Ubicación"}', '{"en": "Location Validation — RFC 7946 §3 · NIST SP 800-53 R5 AC-3(11)", "es": "Validación de Ubicación — RFC 7946 §3 · NIST SP 800-53 R5 AC-3(11)"}', NULL, '{"en": "Location Restrictions · location. What is it? Conditional access policy evaluation engine based on the declared or detected user location: allowed country whitelist, blocked country blacklist (OFAC, high-risk financial countries), city restrictions (access only from cities where the tenant has presence), GPS-IP consistency validation (IP indicates one country and GPS indicates another — possible evasive VPN). What is it for? Applying regulatory jurisdiction restrictions (certain financial operations can only be performed from Bolivian territory) and reducing access risk from countries with high cyberthreat incidence. How is it used? The access evaluator extracts the request location (IP → MaxMind GeoIP2, mobile device GPS); queries the restriction rules for the requested resource''s zone; if location does not comply, access is DENY with specific error code and audit log. Why? Location restrictions are the first line of defense against unauthorized external access; they block 90% of botnet and attacker access attempts from high-risk countries before reaching the authentication engine. Standards: NIST SP 800-53 R5 AC-17(3), ISO 27001 A.6.7, OFAC SDN List, FATF High-Risk Jurisdictions.", "es": "Restricciones por Ubicación · location. ¿Qué es? Motor de evaluación de políticas de acceso condicionales basadas en la ubicación declarada o detectada del usuario: lista blanca de países permitidos, lista negra de países bloqueados (OFAC, países de alto riesgo financiero), restricciones por ciudad (solo acceso desde ciudades donde el tenant tiene presencia), validación de consistencia GPS-IP (la IP indica un país y el GPS indica otro — posible VPN evasiva). ¿Para qué sirve? Aplicar restricciones regulatorias de jurisdicción (ciertas operaciones financieras solo pueden realizarse desde el territorio boliviano) y reducir el riesgo de acceso desde países con alta incidencia de amenazas cibernéticas. ¿Cómo se usa? El evaluador de acceso extrae la ubicación del request (IP → MaxMind GeoIP2, GPS del dispositivo móvil); consulta las reglas de restricción de la zona del recurso solicitado; si la ubicación no cumple, el acceso es DENY con código de error específico y log de auditoría. ¿Por qué? Las restricciones de ubicación son la primera línea de defensa contra accesos no autorizados desde el exterior; bloquean el 90% de los intentos de acceso de botnets y atacantes en países de alto riesgo antes de llegar al motor de autenticación. Normas: NIST SP 800-53 R5 AC-17(3), ISO 27001 A.6.7, OFAC SDN List, FATF High-Risk Jurisdictions."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.location', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 20, 'location', 'B02') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f5a1-7dfd-ae05-beefd001bde8', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7379-a1c1-278de324cdbb', 'block', '{"en": "Context Propagation", "es": "Propagación de Contexto"}', '{"en": "Context Propagation — W3C Trace Context v2 · OpenTelemetry §5", "es": "Propagación de Contexto — W3C Trace Context v2 · OpenTelemetry §5"}', NULL, '{"en": "Context Propagation · propagation. What is it? System for transmitting the ctx_id and security context attributes through call chains between SBOS ecosystem internal microservices: when bAuth authenticates a user, it generates a ctx_id that travels in each subsequent call between biedata, bkernel, bsearch, and other daemons, maintaining complete traceability of the request origin through the entire processing chain. Implements W3C Trace Context (traceparent/tracestate) and OpenTelemetry Baggage for standard propagation. What is it for? Ensuring that any operation performed by any microservice can be traced back to the user who originated it and the authentication context with which it was performed, enabling end-to-end auditing in a microservices ecosystem. How is it used? When issuing the JWT, bAuth includes the ctx_id; each ecosystem daemon extracts the ctx_id from the incoming JWT, logs it, and propagates it in its outgoing calls without modifying it; bAuth can query the propagation tree to reconstruct the complete trace of an operation. Why? Without context propagation, each microservice''s logs are isolated islands impossible to correlate; with propagated ctx_id, a single identifier ties the logs of all services involved in an operation, enabling complete forensic auditing. Standards: W3C Trace Context Recommendation, OpenTelemetry §5, NIST SP 800-92 §3, SBOS-049 Context Plane.", "es": "Propagación de Contexto · propagation. ¿Qué es? Sistema de transmisión del ctx_id y los atributos de contexto de seguridad a través de las cadenas de llamadas entre microservicios internos del ecosistema SBOS: cuando bAuth autentica a un usuario, genera un ctx_id que viaja en cada llamada subsiguiente entre biedata, bkernel, bsearch y los demás daemons, manteniendo la trazabilidad completa del origen del request a través de toda la cadena de procesamiento. Implementa W3C Trace Context (traceparent/tracestate) y OpenTelemetry Baggage para la propagación estándar. ¿Para qué sirve? Garantizar que cualquier operación realizada por cualquier microservicio puede ser trazada hasta el usuario que la originó y el contexto de autenticación con que se realizó, habilitando la auditoría de extremo a extremo en un ecosistema de microservicios. ¿Cómo se usa? Al emitir el JWT, bAuth incluye el ctx_id; cada daemon del ecosistema extrae el ctx_id del JWT entrante, lo registra en sus logs y lo propaga en sus llamadas salientes sin modificarlo; bAuth puede consultar el árbol de propagación para reconstruir el trace completo de una operación. ¿Por qué? Sin propagación de contexto, los logs de cada microservicio son islas aisladas imposibles de correlacionar; con ctx_id propagado, un único identificador une los logs de todos los servicios involucrados en una operación, habilitando la auditoría forense completa. Normas: W3C Trace Context Recommendation, OpenTelemetry §5, NIST SP 800-92 §3, SBOS-049 Context Plane."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D07.propagation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'propagation', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f625-74d9-92a4-da91492db51a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Credentials) — NIST SP 800-63B-4 §5 · ISO 27001 A.5.17", "es": "Registro de Zona de Negocio (Credenciales) — NIST SP 800-63B-4 §5 · ISO 27001 A.5.17"}', NULL, '{"en": "Business Zone Registry (Credentials) · business_zone. What is it? Container organizing credential management modules into differentiated security zones: creation zone (where new credentials are generated and enrolled — strictly controlled access), verification zone (where presented credentials are validated — normal operational access), recovery zone (where lost access recovery processes are managed — supervised access), credential audit zone (where usage records are reviewed — restricted read-only access). What is it for? Applying the least privilege principle at the module level: the credential verification engine does not need access to the creation zone; the audit module does not need access to the recovery zone; functional segregation reduces the impact of a compromised module. How is it used? Each credential management module registers in its zone at initialization; zone policies determine what operations each module can perform; transitions between zones (e.g., verification calling the recovery module) require explicit authorization. Why? Without credential engine zoning, a vulnerability in the verification module could allow an attacker to access the entire credential store; zoning isolates each function in its own security perimeter. Standards: NIST SP 800-63B-4 §5, ISO 27001 A.5.17, NIST SP 800-53 R5 IA-5, OWASP ASVS v5.0 §2.", "es": "Registro de Zona de Negocio (Credenciales) · business_zone. ¿Qué es? Contenedor que organiza los módulos de gestión de credenciales en zonas de seguridad diferenciadas: zona de creación (donde se generan y enrolan credenciales nuevas — acceso estrictamente controlado), zona de verificación (donde se validan las credenciales presentadas — acceso operativo normal), zona de recuperación (donde se gestionan los procesos de recuperación de acceso perdido — acceso supervisado), zona de auditoría de credenciales (donde se revisan los registros de uso — acceso de solo lectura restringido). ¿Para qué sirve? Aplicar el principio de mínimo privilegio a nivel de módulo: el motor de verificación de credenciales no necesita acceso a la zona de creación; el módulo de auditoría no necesita acceso a la zona de recuperación; la segregación funcional reduce el impacto de un módulo comprometido. ¿Cómo se usa? Cada módulo de gestión de credenciales se registra en su zona al inicializarse; las políticas de zona determinan qué operaciones puede realizar cada módulo; las transiciones entre zonas (ej: la verificación llama al módulo de recuperación) requieren autorización explícita. ¿Por qué? Sin zonificación del motor de credenciales, una vulnerabilidad en el módulo de verificación podría permitir a un atacante acceder al almacén de credenciales completo; la zonificación aísla cada función en su propio perímetro de seguridad. Normas: NIST SP 800-63B-4 §5, ISO 27001 A.5.17, NIST SP 800-53 R5 IA-5, OWASP ASVS v5.0 §2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 100, 'business_zone', 'B10') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f61d-7934-ac0a-6b8574268bed', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74a6-b3c2-e98d39e04678', 'block', '{"en": "Token Introspection", "es": "Introspección de Token"}', '{"en": "Token Introspection — RFC 7662 §2 · OAuth 2.0 RFC 6749 §7", "es": "Introspección de Token — RFC 7662 §2 · OAuth 2.0 RFC 6749 §7"}', NULL, '{"en": "Token Introspection · introspection. What is it? RFC 7662 endpoint allowing a protected service to verify the current state of an opaque token (non-JWT) or validate a JWT''s claims without needing to verify the signature locally: the service calls bAuth''s introspection endpoint with the token; bAuth responds whether the token is active and returns the current claims (which may differ from the JWT''s if permissions changed since issuance). What is it for? Allowing token verification in services that do not have the public key to verify JWTs locally, and ensuring services that can verify JWTs locally can still know the current token state (if it was revoked after issuance). How is it used? The protected service receives the token from the client; calls `POST /oauth2/introspect` with the token; bAuth verifies the token, queries Redis to check the revocation list, and returns `{\"active\": true, \"sub\": \"...\", \"scope\": \"...\"}` or `{\"active\": false}`; the service makes the access decision based on the response. Why? Locally verifiable JWTs are efficient but have a problem: if revoked before expiry, the service verifying locally does not know; introspection solves this by querying the real state in bAuth instead of trusting only the signature. Standards: RFC 7662 Token Introspection, RFC 6749 §3.1, NIST SP 800-53 R5 IA-7, OAuth 2.0 Security BCP RFC 9700.", "es": "Introspección de Token · introspection. ¿Qué es? Endpoint RFC 7662 que permite a un servicio protegido verificar el estado actual de un token opaco (no JWT) o validar los claims de un JWT sin necesidad de verificar la firma local: el servicio llama al endpoint de introspección de bAuth con el token; bAuth responde si el token está activo y retorna los claims vigentes en ese momento (que pueden diferir de los del JWT si los permisos cambiaron desde la emisión). ¿Para qué sirve? Permitir la verificación de tokens en servicios que no tienen la clave pública para verificar JWTs localmente, y garantizar que los servicios que sí pueden verificar JWTs localmente aún así puedan conocer el estado actual del token (si fue revocado después de ser emitido). ¿Cómo se usa? El servicio protegido recibe el token del cliente; llama a `POST /oauth2/introspect` con el token; bAuth verifica el token, consulta Redis para ver si está en la lista de revocación, y retorna `{\"active\": true, \"sub\": \"...\", \"scope\": \"...\"}` o `{\"active\": false}`; el servicio toma la decisión de acceso basándose en la respuesta. ¿Por qué? Los JWTs verificables localmente son eficientes pero tienen un problema: si se revocan antes de expirar, el servicio que los verifica localmente no lo sabe; la introspección resuelve este problema al consultar el estado real en bAuth en lugar de confiar solo en la firma. Normas: RFC 7662 Token Introspection, RFC 6749 §3.1, NIST SP 800-53 R5 IA-7, OAuth 2.0 Security BCP RFC 9700."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D09.introspection', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 90, 'introspection', 'B09') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6ac-7541-bdcb-4eac3d602793', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Audit) — ISO 27001 A.8.15 · SOX §802", "es": "Registro de Zona de Negocio (Auditoría) — ISO 27001 A.8.15 · SOX §802"}', NULL, '{"en": "Business Zone Registry (Audit) · business_zone. What is it? Container organizing audit system modules into differentiated access zones: event write zone (only the audit engine can write — write-only access, no module can read what it just wrote), audit read zone (audit team and external auditors can query events — read-only access, no module can modify), export zone (regulatory log export to external systems — restricted and audited access), and real-time monitoring zone (security alerts based on event stream — stream read-only, no access to historical log). What is it for? Implementing the separation between who writes the log (the operating system) and who reads it (the auditors): the engine generating events cannot read them (prevents self-certification); auditors reading the log cannot write to it or modify it. How is it used? Each audit module registers in its zone at initialization and can only perform operations permitted by its zone; zone policies are verified by Kong PEP on each operation; audit zones have no emergency exceptions — the separation is absolute. Why? Without audit zone separation, the system administrator can modify logs before an audit; strict separation ensures logs are unmodifiable by the same actors generating the events. Standards: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-3, SOX §404 (log integrity), PCI DSS 4.0 Req 10.3.", "es": "Registro de Zona de Negocio (Auditoría) · business_zone. ¿Qué es? Contenedor que organiza los módulos del sistema de auditoría en zonas de acceso diferenciadas: zona de escritura de eventos (solo el motor de auditoría puede escribir — acceso de solo escritura, ningún módulo puede leer lo que acaba de escribir), zona de lectura de auditoría (el equipo de auditoría y los auditores externos pueden consultar eventos — acceso de solo lectura, ningún módulo puede modificar), zona de exportación (exportación regulatoria de logs a sistemas externos — acceso restringido y auditado), y zona de monitoreo en tiempo real (alertas de seguridad basadas en el stream de eventos — solo lectura del stream, sin acceso al log histórico). ¿Para qué sirve? Implementar la separación entre quién escribe el log (el sistema operativo) y quién lo lee (los auditores): el motor que genera los eventos no puede leerlos (evita la auto-certificación); los auditores que leen el log no pueden escribir en él ni modificarlo. ¿Cómo se usa? Cada módulo de auditoría se registra en su zona al inicializarse y solo puede realizar las operaciones permitidas por su zona; las políticas de zona son verificadas por el PEP de Kong en cada operación; las zonas de auditoría no tienen excepciones de emergencia — la separación es absoluta. ¿Por qué? Sin separación de zonas de auditoría, el administrador del sistema puede modificar los logs antes de una auditoría; la separación estricta garantiza que los logs son inmodificables por los mismos actores que generan los eventos. Normas: ISO 27001 A.8.15, NIST SP 800-53 R5 AU-3, SOX §404 (log integrity), PCI DSS 4.0 Req 10.3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 70, 'business_zone', 'B07') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f687-7974-84bc-6349c3107a64', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "Active Monitoring", "es": "Monitoreo Activo"}', '{"en": "Active Monitoring — NIST SP 800-53 R5 AU-6 · ISO 27001 A.8.16", "es": "Monitoreo Activo — NIST SP 800-53 R5 AU-6 · ISO 27001 A.8.16"}', NULL, '{"en": "Real-Time Monitoring · monitoring. What is it? Continuous monitoring system for the audit event stream with real-time anomalous pattern detection: authentications-per-second dashboard, access heatmap by geographic location, authentication failure spike detection (possible ongoing brute force attack), high-privilege role active outside hours alerts, ITDR anomaly counters, and health status of all identity plane components. Alerts are sent to Wazuh SIEM, bNotify (push to administrators), and the administration panel. What is it for? Providing real-time operational visibility into the identity plane''s security state: the security team can detect and respond to attacks in seconds instead of discovering them in the next day''s log review. How is it used? The monitoring engine consumes the Redis Streams event stream; applies real-time detection rules (60-second sliding windows for velocity detection); generates alerts when thresholds are exceeded; the administration panel updates counters in real time via WebSocket; critical alerts automatically trigger countermeasures (temporary origin blocking). Why? Post-hoc attack detection (reviewing logs the next day) has 10 times higher cost than real-time detection: the attacker already extracted data or escalated privileges while the log waited to be reviewed. Standards: ISO 27001 A.8.16, NIST SP 800-53 R5 IR-4, CIS Controls v8 §17, NIST SP 800-137.", "es": "Monitoreo en Tiempo Real · monitoring. ¿Qué es? Sistema de monitoreo continuo del stream de eventos de auditoría con detección de patrones anómalos en tiempo real: dashboard de autenticaciones por segundo, mapa de calor de accesos por ubicación geográfica, detección de picos de fallos de autenticación (posible ataque de fuerza bruta en curso), alertas de roles de alto privilegio activos fuera de horario, contadores de anomalías ITDR y estado de salud de todos los componentes del plano de identidad. Las alertas se envían a Wazuh SIEM, bNotify (push a administradores) y el panel de administración. ¿Para qué sirve? Proveer visibilidad operacional en tiempo real del estado de seguridad del plano de identidad: el equipo de seguridad puede detectar y responder a ataques en segundos en lugar de descubrirlos en la revisión de logs del día siguiente. ¿Cómo se usa? El motor de monitoreo consume el stream de eventos de Redis Streams; aplica las reglas de detección en tiempo real (ventanas deslizantes de 60 segundos para detección de velocidad); genera alertas cuando se superan los umbrales; el panel de administración actualiza los contadores en tiempo real vía WebSocket; las alertas críticas activan automáticamente contramedidas (bloqueo temporal del origen). ¿Por qué? La detección post-hoc de ataques (revisar logs al día siguiente) tiene un costo 10 veces mayor que la detección en tiempo real: el atacante ya extrajo los datos o escaló privilegios mientras el log esperaba ser revisado. Normas: ISO 27001 A.8.16, NIST SP 800-53 R5 IR-4, CIS Controls v8 §17, NIST SP 800-137."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.monitoring', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'monitoring', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f6c8-7f91-9314-c08830dfe5e7', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7578-a56d-097defc9c40a', 'block', '{"en": "Merkle Hash Anchoring", "es": "Anclaje Hash Merkle"}', '{"en": "Merkle Hash Anchoring — RFC 6962 §2.1 · EIP-712 · NIST SP 800-208", "es": "Anclaje Hash Merkle — RFC 6962 §2.1 · EIP-712 · NIST SP 800-208"}', NULL, '{"en": "Blockchain Anchoring · anchoring. What is it? Mechanism for periodic publication of cryptographic summaries (Merkle roots) of identity and audit records on a public or consortium blockchain, creating immutable timestamped proof of existence and non-alteration: every N hours, the engine calculates the Merkle root of all events for the period, publishes the hash on the blockchain (Besu private for the ecosystem or Ethereum mainnet for the most critical), and stores the reference (txHash + blockNumber) alongside the original data. What is it for? Providing irrefutable proof of existence to independent third parties: if an external auditor needs to verify that the audit log was not modified, they can compare the calculated Merkle root of the current data with the hash published on the blockchain — if they match, the data is authentic with mathematical certainty. How is it used? The blockchain anchor activates automatically every 6 hours (configurable); the engine obtains all events for the period, builds the Merkle tree, publishes the root on the blockchain via the Besu anchoring contract, and stores the transaction reference in the audit log; compliance reports include anchoring proofs for the covered period. Why? Blockchain anchoring converts the audit log into forensic evidence of evidentiary level in any jurisdiction: the hash on the blockchain is public, immutable, and verifiable by any third party without internal system access. Standards: NIST SP 800-209 §4.3, RFC 3161 Timestamping, ISO 27001 A.8.15, W3C VC Data Model §3.", "es": "Anclaje en Blockchain · anchoring. ¿Qué es? Mecanismo de publicación periódica de resúmenes criptográficos (Merkle roots) de los registros de identidad y auditoría en una blockchain pública o consorcio, creando pruebas de existencia y no-alteración con timestamp inmutable: cada N horas, el motor calcula el Merkle root de todos los eventos del período, publica el hash en la blockchain (Besu privada del ecosistema o Ethereum mainnet para los más críticos) y almacena la referencia (txHash + blockNumber) junto a los datos originales. ¿Para qué sirve? Proveer prueba de existencia irrefutable ante terceros independientes: si un auditor externo necesita verificar que el log de auditoría no fue modificado, puede comparar el Merkle root calculado de los datos actuales con el hash publicado en la blockchain — si coinciden, los datos son auténticos con certeza matemática. ¿Cómo se usa? El ancla blockchain se activa automáticamente cada 6 horas (configurable); el motor obtiene todos los eventos del período, construye el árbol Merkle, publica el root en la blockchain a través del contrato de anclaje de Besu, y almacena la referencia de la transacción en el log de auditoría; los informes de cumplimiento incluyen los proofs de anclaje para el período cubierto. ¿Por qué? El anclaje blockchain convierte el log de auditoría en evidencia forense de nivel probatorio ante cualquier jurisdicción: el hash en la blockchain es público, inmutable y verificable por cualquier tercero sin acceso al sistema interno. Normas: NIST SP 800-209 §4.3, RFC 3161 Timestamping, ISO 27001 A.8.15, W3C VC Data Model §3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D12.anchoring', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 10, 'anchoring', 'B01') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f427-7d6a-b8da-022720d2dc51', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c98-7ebd-ad96-88a315478d98', 'block', '{"en": "User Entity", "es": "Entidad del Usuario"}', '{"en": "User Entity — ISO/IEC 24760-1:2019 §5 · SCIM 2.0 RFC 7643", "es": "Entidad de Usuario — ISO/IEC 24760-1:2019 §5 · SCIM 2.0 RFC 7643"}', NULL, '{"en": "User Entity · usuario_entidad. What is it? Concrete, live instance of a user in the system: unique identifiers (UUID v7, UPN), verified personal data (name, email, phone), achieved IAL level, active credentials, assigned roles with their periods, authentication history, account status (ACTIVE, SUSPENDED, LOCKED, DELETED), and audit metadata with integrity hash. What is it for? Being the source of truth for the user''s current state for all identity operations: every authentication, authorization, audit, and notification references this entity. How is it used? Every authenticated request carries the user''s UUID; the PDP engine builds the evaluation context by reading the user entity along with their active roles; a suspension propagates to all PEPs in less than 30s via CAEP. Why? Centralizing user state in a single entity prevents inconsistencies between systems; without it, revoking access would require updating multiple independent databases with synchronization risk. Standards: ISO/IEC 24760-1:2019 §5, SCIM 2.0 RFC 7643 §4.1, NIST SP 800-53 R5 AC-2, GDPR Art. 4(1), CAEP 1.0 §5.", "es": "Entidad de Usuario · usuario_entidad. ¿Qué es? Instancia concreta y viva de un usuario en el sistema: identificadores únicos (UUID v7, UPN), datos personales verificados (nombre, email, teléfono), nivel IAL alcanzado, credenciales activas, roles asignados con sus períodos, historial de autenticación, estado de cuenta (ACTIVO, SUSPENDIDO, BLOQUEADO, ELIMINADO) y metadatos de auditoría con hash de integridad. ¿Para qué sirve? Ser la fuente de verdad del estado actual del usuario para todas las operaciones de identidad: cada autenticación, autorización, auditoría y notificación referencia esta entidad. ¿Cómo se usa? Cada request autenticado lleva el UUID del usuario; el motor PDP construye el contexto de evaluación leyendo la entidad de usuario junto con sus roles activos; una suspensión se propaga a todos los PEP en menos de 30s vía CAEP. ¿Por qué? Centralizar el estado del usuario en una única entidad evita inconsistencias entre sistemas; sin ella, revocar acceso requeriría actualizar múltiples bases de datos independientes con riesgo de desfase. Normas: ISO/IEC 24760-1:2019 §5, SCIM 2.0 RFC 7643 §4.1, NIST SP 800-53 R5 AC-2, GDPR Art. 4(1), CAEP 1.0 §5."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D00.usuario_entidad', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'usuario_entidad', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f4cf-7ed2-a18a-264abfc63e40', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', 'block', '{"en": "Financial SoD", "es": "SoD Financiero"}', '{"en": "Financial Segregation of Duties — NIST SP 800-53 R5 AC-5 · SOX §404 · COSO CC6.3", "es": "Segregación de Funciones Financieras — NIST SP 800-53 R5 AC-5 · SOX §404 · COSO CC6.3"}', NULL, '{"en": "Financial Segregation of Duties · segregation. What is it? Implementation of the Separation of Duties (SoD) principle specifically for financial operations: the same person cannot initiate and approve a transaction, nor approve and reconcile, nor create a vendor and pay them. The financial SoD matrix defines all incompatible function pairs; the engine verifies in real time that no role assignment violates this matrix before activating permissions. What is it for? Eliminating the possibility for a single person to commit and conceal financial fraud by controlling all steps of an operation, fulfilling the primary internal control requirement of SOX §404 and COSO. How is it used? When assigning a financial role to a user, the engine verifies they do not already have an incompatible role assigned per the SoD matrix; if there is a conflict, the assignment is rejected with an explanation of the detected conflict. Why? Without financial SoD, an employee can create fictitious invoices, approve them, and pay them to personal accounts without anyone detecting it; with SoD each step requires a different person, making fraud impossible without collusion. Standards: NIST SP 800-53 R5 AC-5, SOX §404, COSO CC6.3, ISO 27001 A.5.3, PCI DSS 4.0 Req 7.2.", "es": "Segregación de Funciones Financieras · segregation. ¿Qué es? Implementación del principio de separación de responsabilidades (SoD) específicamente para operaciones financieras: la misma persona no puede iniciar y aprobar una transacción, ni aprobar y conciliar, ni crear un proveedor y pagarle. La matriz SoD financiera define todos los pares de funciones incompatibles; el motor verifica en tiempo real que ninguna asignación de roles viole esta matriz antes de activar los permisos. ¿Para qué sirve? Eliminar la posibilidad de que una sola persona pueda cometer y ocultar fraude financiero controlando todos los pasos de una operación, cumpliendo el principal requisito de control interno de SOX §404 y COSO. ¿Cómo se usa? Al asignar un rol financiero a un usuario, el motor verifica que no tiene ya asignado ningún rol incompatible según la matriz SoD; si hay conflicto, la asignación es rechazada con explicación del conflicto detectado. ¿Por qué? Sin SoD financiero, un empleado puede crear facturas ficticias, aprobarlas y pagarlas a cuentas propias sin que nadie lo detecte; con SoD cada paso requiere una persona diferente, haciendo el fraude imposible sin complicidad. Normas: NIST SP 800-53 R5 AC-5, SOX §404, COSO CC6.3, ISO 27001 A.5.3, PCI DSS 4.0 Req 7.2."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D03.segregation', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'segregation', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f52a-7117-b116-82117f109650', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7261-a4fb-c610e94aa013', 'block', '{"en": "Business Zone Registry", "es": "Registro de Zona de Negocio"}', '{"en": "Business Zone Registry (Temporal) — NIST SP 800-53 R5 AC-2(2) · GTRBAC §3", "es": "Registro de Zona de Negocio (Temporal) — NIST SP 800-53 R5 AC-2(2) · GTRBAC §3"}', NULL, '{"en": "Business Zone Registry (Temporal) · business_zone. What is it? Container organizing system modules and functions into temporal zones with their own schedule restrictions: normal business hours operations zone (Mon-Fri 8:00-18:00), after-hours operations zone (requires additional authentication outside hours), weekend operations zone (enabled only for specific roles), and scheduled maintenance zone. What is it for? Applying differentiated temporal restrictions based on function sensitivity: high-value financial operations are only permitted during supervised business hours; maintenance operations only during scheduled windows. How is it used? Each system function is assigned to its temporal zone; the engine verifies that the current date/time is within the zone''s permitted schedule before evaluating the access policy; temporal zones intersect with the tenant''s holiday calendars. Why? Without temporal zones, schedule restrictions must be configured function by function; temporal zones inherit container restrictions, reducing configurations and guaranteeing consistency. Standards: NIST SP 800-53 R5 AC-2(2), GTRBAC §3, ISO 8601:2019, ISO 27001 A.5.15.", "es": "Registro de Zona de Negocio (Temporal) · business_zone. ¿Qué es? Contenedor que organiza los módulos y funciones del sistema en zonas temporales con sus propias restricciones de horario: zona de operaciones en horario laboral normal (L-V 8:00-18:00), zona de operaciones nocturnas (requiere autenticación adicional fuera de horario), zona de operaciones de fin de semana (habilitada solo para roles específicos) y zona de mantenimiento programado. ¿Para qué sirve? Aplicar restricciones temporales diferenciadas según la sensibilidad de la función: las operaciones financieras de alto valor solo se permiten en horario laboral supervisado; las operaciones de mantenimiento solo en ventanas programadas. ¿Cómo se usa? Cada función del sistema se asigna a su zona temporal; el motor verifica que la fecha/hora actual está dentro del horario permitido por la zona antes de evaluar la política de acceso; las zonas temporales se intersectan con los calendarios de feriados del tenant. ¿Por qué? Sin zonas temporales las restricciones de horario deben configurarse función por función; las zonas temporales heredan las restricciones del contenedor, reduciendo configuraciones y garantizando consistencia. Normas: NIST SP 800-53 R5 AC-2(2), GTRBAC §3, ISO 8601:2019, ISO 27001 A.5.15."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D04.business_zone', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'business_zone', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f539-7c00-816b-906027e7b865', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', 'block', '{"en": "1:N Biometric Identification", "es": "Identificación Biométrica 1:N"}', '{"en": "1:N Biometric Identification — ISO/IEC 19794-2:2011 §6 · NIST SP 800-76-2 §5", "es": "Identificación Biométrica 1:N — ISO/IEC 19794-2:2011 §6 · NIST SP 800-76-2 §5"}', NULL, '{"en": "1:N Biometric Identification · identification. What is it? Biometric comparison engine matching an unknown sample against the entire registered template database (1:N) to determine who the person is, without them declaring their identity first. Returns the identifier of the closest user if they exceed the match threshold, or \"unknown\" if no template exceeds the threshold. Supports modes: duplicate detection in enrollment, touchless access control identification, and passive surveillance (only with explicit legal authorization). What is it for? Identifying people in contexts where they cannot or should not declare their identity first: hands-free access control in clean rooms, automated reception visitor identification, exclusion list person detection. How is it used? The sensor captures the trait; the engine compares against all active templates using approximate search algorithms (LSHF, k-d tree) to maintain low latency even with millions of templates; if similarity exceeds the threshold, identity is confirmed. Why? 1:N identification enables user-interaction-free access flows (hands-free access), improving the experience in high-frequency zones without sacrificing security. Standards: ISO/IEC 19794-2:2011 §6, NIST SP 800-76-2 §5, ISO/IEC 24745:2022 §5, GDPR Art. 9 (biometric data).", "es": "Identificación Biométrica 1:N · identification. ¿Qué es? Motor de comparación biométrica de una muestra desconocida contra toda la base de templates registrados (1:N) para determinar quién es la persona, sin que ella declare su identidad previamente. Retorna el identificador del usuario más cercano si supera el umbral de coincidencia, o \"desconocido\" si ningún template supera el umbral. Soporta modos: verificación de duplicados en enrolamiento, identificación en control de acceso sin contacto, y vigilancia pasiva (solo con habilitación legal explícita). ¿Para qué sirve? Identificar personas en contextos donde no pueden o no deben declarar su identidad primero: control de acceso manos libres en salas limpias, identificación de visitantes en recepciones automatizadas, detección de personas en lista de exclusión. ¿Cómo se usa? El sensor captura el rasgo; el motor compara contra todos los templates activos usando algoritmos de búsqueda aproximada (LSHF, k-d tree) para mantener latencia baja incluso con millones de templates; si la similitud supera el umbral, confirma la identidad. ¿Por qué? La identificación 1:N permite flujos de acceso sin interacción del usuario (acceso manos libres), mejorando la experiencia en zonas de alta frecuencia sin sacrificar seguridad. Normas: ISO/IEC 19794-2:2011 §6, NIST SP 800-76-2 §5, ISO/IEC 24745:2022 §5, GDPR Art. 9 (datos biométricos)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D05.identification', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 40, 'identification', 'B04') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f557-7c98-bee6-bad76055bb1a', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-733a-a9f3-2421b043fa09', 'block', '{"en": "Impossible Travel Detection", "es": "Detección de Viaje Imposible"}', '{"en": "Impossible Travel Detection — NIST SP 800-53 R5 SI-4(13) · ISO 27001 A.8.16", "es": "Detección de Viaje Imposible — NIST SP 800-53 R5 SI-4(13) · ISO 27001 A.8.16"}', NULL, '{"en": "Impossible Travel Detection · velocity. What is it? Temporal-geospatial anomaly detector identifying physically impossible authentications: if a user authenticates from La Paz and 10 minutes later authenticates from Madrid, the distance divided by time yields an implied speed exceeding the maximum human air travel speed — the second access is a physical impossibility. The engine calculates the implied speed between consecutive authentications and flags them as suspicious if they exceed the configurable threshold (typically 900 km/h). What is it for? Automatically detecting when the same credentials are being used simultaneously from multiple geographically separated locations, which is direct evidence of credential compromise or account sharing. How is it used? The access evaluator records the location of each successful authentication; upon receiving the next request from the same user, it calculates the implied speed; if it exceeds the threshold, access is DENY and a reinforced identity verification flow is initiated (the user receives an alert and must confirm the first access was legitimate). Why? Impossible travel is one of the most accurate account compromise detectors with the fewest false positives: it is mathematically impossible to be in two distant places within minutes. Standards: NIST SP 800-207 §3.3, ISO 27001 A.8.16, RFC 7946 GeoJSON, NIST SP 800-53 R5 SI-4(24).", "es": "Detección de Viaje Imposible · velocity. ¿Qué es? Detector de anomalías temporales-geoespaciales que identifica autenticaciones físicamente imposibles: si un usuario autentica desde La Paz y 10 minutos después autentica desde Madrid, la distancia divide el tiempo y la velocidad resultante excede la velocidad máxima de viaje humano en avión — el segundo acceso es una imposibilidad física. El motor calcula la velocidad implícita entre autenticaciones consecutivas y las marca como sospechosas si superan el umbral configurable (típicamente 900 km/h). ¿Para qué sirve? Detectar automáticamente cuando las mismas credenciales están siendo usadas simultáneamente desde múltiples ubicaciones geográficamente separadas, lo que es evidencia directa de compromiso de credenciales o compartición de cuentas. ¿Cómo se usa? El evaluador de acceso registra la ubicación de cada autenticación exitosa; al recibir el siguiente request del mismo usuario, calcula la velocidad implícita; si supera el umbral, el acceso es DENY y se inicia flujo de verificación de identidad reforzado (el usuario recibe alerta y debe confirmar que el primer acceso fue legítimo). ¿Por qué? El viaje imposible es uno de los detectores de compromiso de cuentas más precisos y con menos falsos positivos: es matemáticamente imposible estar en dos lugares distantes en pocos minutos. Normas: NIST SP 800-207 §3.3, ISO 27001 A.8.16, RFC 7946 GeoJSON, NIST SP 800-53 R5 SI-4(24)."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D06.velocity', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 30, 'velocity', 'B03') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f65c-73ad-aa1d-4f57d1ef2cd2', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-74f4-aa58-2df9c390f38c', 'block', '{"en": "Granular API Authorization", "es": "Autorización Granular API"}', '{"en": "Granular API Authorization (RAR) — RFC 9396 §3 · OAuth 2.0 RFC 6749", "es": "Autorización Granular de API (RAR) — RFC 9396 §3 · OAuth 2.0 RFC 6749"}', NULL, '{"en": "Rich Authorization Requests (RAR) · rich_authorization. What is it? Implementation of RFC 9396 Rich Authorization Requests (RAR) standard, allowing specific details of the intended operation to be included in the token request, with a granularity traditional OAuth scopes cannot express: instead of requesting the generic scope `payments:write`, the client requests specific authorization for `{type: \"payment_initiation\", instructedAmount: {currency: \"USD\", amount: \"50.00\"}, creditorAccount: \"IBAN...\", remittanceInformation: \"Invoice 001\"}`. What is it for? Implementing the minimum authorization principle at the level of individual transactions: the user approves exactly the specific operation described to them, not a generic scope that could cover operations much broader than what the user understands they are authorizing. How is it used? The client includes the `authorization_details` object in the OAuth authorization request; bAuth presents to the user the exact details of the operation to authorize (amount, recipient, reference); the user approves or rejects; the issued token carries the authorization_details that the PEP verifies against the actual attempted operation. Why? Generic OAuth scopes like `payments:write` are a blank authorization: the user does not know what amount, to whom, or when; RAR makes authorization auditable at the individual transaction level, especially important for PSD2 and FAPI 2.0 compliance. Standards: RFC 9396 RAR, FAPI 2.0 §5, PSD2 Art. 97, ISO 20022.", "es": "Autorización Enriquecida (RAR) · rich_authorization. ¿Qué es? Implementación del estándar RFC 9396 Rich Authorization Requests (RAR) que permite incluir en la solicitud de token detalles específicos de la operación que se pretende realizar, con una granularidad que los scopes OAuth tradicionales no pueden expresar: en lugar de solicitar el scope genérico `payments:write`, el cliente solicita autorización específica para `{type: \"payment_initiation\", instructedAmount: {currency: \"USD\", amount: \"50.00\"}, creditorAccount: \"IBAN...\", remittanceInformation: \"Factura 001\"}`. ¿Para qué sirve? Implementar el principio de mínima autorización a nivel de transacción individual: el usuario aprueba exactamente la operación específica que se le describe, no un scope genérico que podría cubrir operaciones mucho más amplias de lo que el usuario entiende que está autorizando. ¿Cómo se usa? El cliente incluye el objeto `authorization_details` en la solicitud de autorización OAuth; bAuth presenta al usuario los detalles exactos de la operación a autorizar (monto, destinatario, referencia); el usuario aprueba o rechaza; el token emitido lleva los authorization_details que el PEP verifica contra la operación real intentada. ¿Por qué? Los scopes OAuth genéricos como `payments:write` son una autorización en blanco: el usuario no sabe qué cantidad, a quién ni cuándo; RAR hace la autorización auditable a nivel de transacción individual, especialmente importante para cumplir PSD2 y FAPI 2.0. Normas: RFC 9396 RAR, FAPI 2.0 §5, PSD2 Art. 97, ISO 20022."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D10.rich_authorization', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 60, 'rich_authorization', 'B06') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8d69-f697-7d7c-8df0-67140493c103', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c34-9c99-7537-8755-7cc582e1da21', 'block', '{"en": "SIEM Export", "es": "Exportación a SIEM"}', '{"en": "SIEM Export — NIST SP 800-53 R5 AU-9(2) · ISO 27001 A.8.15", "es": "Exportación al SIEM — NIST SP 800-53 R5 AU-9(2) · ISO 27001 A.8.15"}', NULL, '{"en": "Audit Export · export. What is it? Controlled and audited export system for the audit log to external systems: export to corporate SIEM (Wazuh in RFC 5424 syslog format), export to regulatory compliance repository (XBRL format for SOX, CSV/Excel for external audits), forensic export (canonical JSON format with integrity hashes for investigations), and real-time streaming API for external SIEM platform integration. All exports are recorded in the audit log itself (meta-audit: the audit is audited). What is it for? Allowing external auditors, the legal team, and regulators to access audit records in the format they need, without compromising the original log''s integrity or providing direct access to the production database. How is it used? The auditor requests an export specifying the date range, event type, and format; bAuth validates the requester has the auditor role for the requested period; generates the export with timestamp, integrity hash, and digital signature of the exported set; records the export in the audit log. Why? Regulators and external auditors cannot have direct access to the production database; controlled export provides the necessary evidence in the regulator''s standard format, with verifiable integrity guarantee. Standards: RFC 5424 syslog, SOX §404, ISO 27001 A.8.15, NIST SP 800-92 §3.", "es": "Exportación de Auditoría · export. ¿Qué es? Sistema de exportación controlada y auditada del log de auditoría a sistemas externos: exportación a SIEM corporativo (Wazuh en formato syslog RFC 5424), exportación a repositorio de cumplimiento regulatorio (formato XBRL para SOX, CSV/Excel para auditorías externas), exportación forense (formato JSON canónico con hashes de integridad para investigaciones), y API de streaming en tiempo real para integración con plataformas SIEM externas. Toda exportación es registrada en el propio log de auditoría (meta-auditoría: la auditoría se audita). ¿Para qué sirve? Permitir que los auditores externos, el equipo legal y los reguladores accedan a los registros de auditoría en el formato que necesitan, sin comprometer la integridad del log original ni dar acceso directo a la base de datos de producción. ¿Cómo se usa? El auditor solicita una exportación especificando el rango de fechas, el tipo de eventos y el formato; bAuth valida que el solicitante tiene el rol de auditor para el período solicitado; genera la exportación con marca de tiempo, hash de integridad y firma digital del conjunto exportado; registra la exportación en el log de auditoría. ¿Por qué? Los reguladores y auditores externos no pueden tener acceso directo a la base de datos de producción; la exportación controlada provee la evidencia necesaria en el formato estándar del regulador, con garantía de integridad verificable. Normas: RFC 5424 syslog, SOX §404, ISO 27001 A.8.15, NIST SP 800-92 §3."}', '{}', NULL, NULL, NULL, false, NULL, NULL, 2, 0, 'skull.D11.export', true, '1.0', '2026-07-23', NULL, '2026-07-23 05:19:18.981552+00', '2026-07-23 05:19:18.981552+00', 50, 'export', 'B05') ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-703f-b259-eb318efed879', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Logical Access Control", "es": "Control de Acceso Lógico"}', '{"en": "Logical Access Control", "es": "Control de Acceso Lógico"}', NULL, '{"en": "Logical Access Control · logical_access. What is it? The digital access decision engine (PDP — Policy Decision Point) based on NIST RBAC Level 3 with Dual 64-bit BitMask. Evaluates who can do what on which resource and under what condition, in real time. Governs: policy evaluation, digital role lifecycle, application zones, field-level access, access contracts, logical sessions, dynamic ABAC, and periodic recertification. What is it for? Authorizing or denying every digital operation (API, database, interface, button) with latency under 0.5ms. How is it used? The PEP (Kong) intercepts each request and consults this domain via JSON-RPC; receives PERMIT or DENY with the reason. Why? It is the fundamental protection mechanism for all digital resources; without it any user could access any data. Standards: NIST SP 800-53 R5.2 AC-2/AC-3/AC-6, XACML 3.0, OWASP ASVS v5.0 §4, ISO 27001:2022 A.5.15/A.5.18, ANSI INCITS 359-2004, ISO 9001:2015 §8.5.", "es": "Control de Acceso Lógico · logical_access. ¿Qué es? El motor de decisión de acceso digital (PDP — Policy Decision Point) basado en NIST RBAC Nivel 3 con BitMask Dual 64-bit. Evalúa quién puede hacer qué sobre qué recurso y bajo qué condición, en tiempo real. Gobierna: evaluación de políticas, ciclo de vida de roles digitales, zonas de aplicación, acceso a campos, contratos de acceso, sesiones lógicas, ABAC dinámico y recertificación periódica. ¿Para qué sirve? Autorizar o denegar cada operación digital (API, base de datos, interfaz, botón) con latencia inferior a 0.5ms. ¿Cómo se usa? El PEP (Kong) intercepta cada request y consulta este dominio vía JSON-RPC; recibe PERMIT o DENY con el motivo. ¿Por qué? Es el mecanismo de protección fundamental de todos los recursos digitales; sin él cualquier usuario podría acceder a cualquier dato. Normas: NIST SP 800-53 R5.2 AC-2/AC-3/AC-6, XACML 3.0, OWASP ASVS v5.0 §4, ISO 27001:2022 A.5.15/A.5.18, ANSI INCITS 359-2004, ISO 9001:2015 §8.5."}', '{}', NULL, NULL, NULL, false, NULL, 1, 1, 0, 'skull.D01', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 300, 'logical_access', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-72c3-89b5-e0b1bb2edf3e', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Biometric Authentication", "es": "Autenticación Biométrica"}', '{"en": "Biometric Authentication", "es": "Autenticación Biométrica"}', NULL, '{"en": "Biometric Authentication · biometric. What is it? The orchestrator of the complete biometric lifecycle: initial enrollment (biometric template capture and storage), 1:1 verification (confirming the presenter is who they claim to be, comparing against their own template), 1:N identification (finding who someone is within the entire template database), anti-spoofing liveness detection (PAD — Presentation Attack Detection, to reject photos, masks, or artificial fingers), quality control of the captured sample, and compromised template revocation. What is it for? Providing the highest available authentication level (AAL3), based on unique and irrefutable physiological traits, without passwords. How is it used? The sensor captures the trait (fingerprint, iris, face); the PAD module validates it is not an artifact; the ECDSA comparator evaluates 1:1 against the Vault-encrypted template; the result feeds the assurance engine that determines the active AAL. Why? Biometrics is the only authentication factor the user cannot lose, forget, or lend, and is mandatory for AAL3 (access to maximum-security areas and high-value operations). Standards: NIST SP 800-76-2, NIST SP 800-63B-4 §5.2.3 (AAL3), ISO/IEC 30107-3:2023 (PAD), ISO/IEC 19794-2:2011, FIDO2/CTAP2 Level 2, ISO/IEC 29794-1:2024.", "es": "Autenticación Biométrica · biometric. ¿Qué es? El orquestador del ciclo de vida completo de biometría: enrolamiento inicial (captura y almacenamiento del template biométrico), verificación 1:1 (confirmar que quien se presenta es quien dice ser, comparando contra su propio template), identificación 1:N (buscar quién es alguien dentro de toda la base de templates), detección de vivacidad anti-spoofing (PAD — Presentation Attack Detection, para rechazar fotos, máscaras o dedos artificiales), control de calidad de la muestra capturada y revocación de templates comprometidos. ¿Para qué sirve? Proporcionar el nivel de autenticación más alto disponible (AAL3), basado en rasgos fisiológicos únicos e irrenunciables, sin contraseñas. ¿Cómo se usa? El sensor captura el rasgo (huella dactilar, iris, cara); el módulo PAD valida que no es un artefacto; el comparador ECDSA evalúa 1:1 contra el template cifrado en Vault; el resultado alimenta el motor de garantía que determina el AAL activo. ¿Por qué? La biometría es el único factor de autenticación que el usuario no puede perder, olvidar ni prestar, y es obligatoria para AAL3 (acceso a áreas de máxima seguridad y operaciones de alto valor). Normas: NIST SP 800-76-2, NIST SP 800-63B-4 §5.2.3 (AAL3), ISO/IEC 30107-3:2023 (PAD), ISO/IEC 19794-2:2011, FIDO2/CTAP2 Level 2, ISO/IEC 29794-1:2024."}', '{}', NULL, NULL, NULL, false, NULL, 5, 1, 0, 'skull.D05', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 700, 'biometric', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-76b3-ad3e-3a360429c21d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Non-Human Identity (NHI)", "es": "Identidad No Humana (NHI)"}', '{"en": "Non-Human Identity (NHI)", "es": "Identidad No Humana (NHI)"}', NULL, '{"en": "Non-Human Identity (NHI) · non_human_identity. What is it? The domain responsible for the identity lifecycle of all non-human actors in the SBOS ecosystem: microservices, REST/gRPC APIs, CI/CD pipelines, automation scripts, Docker/Kubernetes containers, Artificial Intelligence agents, and any entity consuming or providing services without direct human intervention. Manages: service accounts (with mandatory human owner, declared purpose, and expiration date), SPIFFE/SPIRE workload cryptographic identity (X.509 SVIDs with URI spiffe://sbos/[service]/[environment], rotated every 60 minutes), Vault machine secrets (dynamic secrets: the DB password is generated on request and expires on completion), automatic zero-downtime credential rotation, cryptographic workload identity attestation (the SVID is only issued if the process is legitimate), and comprehensive NHI lifecycle governance with orphan and zombie account detection. What is it for? Ensuring every non-human entity has a verifiable identity, operates with least privilege, and its secrets never appear in source code or environment variables. How is it used? When deploying a new microservice, SPIRE automatically issues it an SVID; Vault injects necessary secrets at startup; the SVID rotates every hour; if the service stops reporting, the identity is revoked in < 30s. Why? 45% of breaches involve secrets exposed in code repositories or container images; SPIFFE/SPIRE eliminate the problem at its root. Standards: SPIFFE Spec v1.0, SPIRE Architecture, NIST SP 800-204A/B, CIS Controls v8 §5.4, CSA NHI Security Report 2025, OWASP API Security Top 10 2023.", "es": "Identidad No Humana (NHI) · non_human_identity. ¿Qué es? El dominio responsable del ciclo de vida de identidad de todos los actores no humanos del ecosistema SBOS: microservicios, APIs REST/gRPC, pipelines CI/CD, scripts de automatización, contenedores Docker/Kubernetes, agentes de Inteligencia Artificial y cualquier entidad que consuma o provea servicios sin intervención humana directa. Gestiona: cuentas de servicio (con propietario humano obligatorio, propósito declarado y fecha de vencimiento), identidad criptográfica de cargas de trabajo SPIFFE/SPIRE (SVIDs X.509 con URI spiffe://sbos/[servicio]/[entorno], rotados cada 60 minutos), secretos de máquina en Vault (dynamic secrets: la contraseña de BD se genera al solicitar y expira al terminar), rotación automática de todas las credenciales sin tiempo de inactividad, attestation criptográfica de la identidad del workload (el SVID solo se emite si el proceso es legítimo) y gobierno integral del ciclo de vida NHI con detección de cuentas huérfanas y zombis. ¿Para qué sirve? Asegurar que cada entidad no humana tenga una identidad verificable, opere con mínimo privilegio y sus secretos nunca aparezcan en código fuente ni variables de entorno. ¿Cómo se usa? Al desplegar un nuevo microservicio, SPIRE le emite un SVID automáticamente; Vault inyecta los secretos necesarios al arranque; el SVID se rota cada hora; si el servicio deja de reportar, la identidad se revoca en < 30s. ¿Por qué? El 45% de las brechas implica secretos expuestos en repositorios de código o imágenes de contenedor; SPIFFE/SPIRE eliminan el problema de raíz. Normas: SPIFFE Spec v1.0, SPIRE Architecture, NIST SP 800-204A/B, CIS Controls v8 §5.4, CSA NHI Security Report 2025, OWASP API Security Top 10 2023."}', '{}', NULL, NULL, NULL, false, NULL, 15, 1, 0, 'skull.D15', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1700, 'non_human_identity', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-70b7-af8d-a4e2793bca11', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Physical Access Control", "es": "Control de Acceso Físico"}', '{"en": "Physical Access Control", "es": "Control de Acceso Físico"}', NULL, '{"en": "Physical Access Control · physical_access. What is it? The physical perimeter security orchestrator: manages who enters and exits buildings, rooms, restricted zones, and data center areas. Controls doors, turnstiles, OSDP readers (v2.2 secure channel), dual-presence zones (mantrap), anti-passback, visitor registration, emergency evacuation, and personnel counting. What is it for? Protecting the organization physical perimeter: preventing unauthorized access to facilities containing critical assets (servers, files, laboratories). How is it used? OSDP readers capture the credential; the engine evaluates the user role, requested zone, schedule, and security conditions (is this user authorized in this room at this time?); responds PERMIT or DENY to the building control panel. Why? Physical protection complements logical: without physical access control, an attacker with building access can directly compromise servers. Standards: IEC 60839-11-5:2020, SIA OSDP v2.2.2, ISO 27001:2022 A.7.1/A.7.2/A.7.3, NIST SP 800-116 R2, ISO 9001:2015 §7.1.3, EN 50133.", "es": "Control de Acceso Físico · physical_access. ¿Qué es? El orquestador de seguridad perimetral física: gestiona quién entra y sale de edificios, salas, zonas restringidas y áreas de data center. Controla puertas, torniquetes, lectores OSDP (canal seguro v2.2), zonas de doble presencia (mantrap), anti-passback, registro de visitantes, evacuación de emergencia y conteo de personal. ¿Para qué sirve? Proteger el perímetro físico de la organización: impedir el acceso no autorizado a instalaciones que contienen activos críticos (servidores, archivos, laboratorios). ¿Cómo se usa? Los lectores OSDP capturan la credencial; el motor evalúa el rol del usuario, la zona solicitada, el horario y las condiciones de seguridad (¿está autorizado en esta sala a esta hora?); responde PERMIT o DENY al panel de control del edificio. ¿Por qué? La protección física complementa la lógica: sin control de acceso físico, un atacante con acceso al edificio puede comprometer directamente los servidores. Normas: IEC 60839-11-5:2020, SIA OSDP v2.2.2, ISO 27001:2022 A.7.1/A.7.2/A.7.3, NIST SP 800-116 R2, ISO 9001:2015 §7.1.3, EN 50133."}', '{}', NULL, NULL, NULL, false, NULL, 2, 1, 0, 'skull.D02', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 400, 'physical_access', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-74f4-aa58-2df9c390f38c', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Delegation & Impersonation", "es": "Delegación e Impersonación"}', '{"en": "Delegation & Impersonation", "es": "Delegación e Impersonación"}', NULL, '{"en": "Delegation & Impersonation · delegation. What is it? The mechanism allowing a user (delegator) to temporarily transfer a bounded subset of their permissions to another user or system (delegate), or for a system to act on behalf of a user with their explicit consent. A delegation has: defined scope (which permissions exactly), maximum duration, controlled sub-delegation possibility, SoD validation (delegation cannot create segregation conflicts), and complete immutable traceability. What is it for? Enabling business flows requiring someone to act on behalf of another: executive assistants approving in the executive absence, RPA robots executing automated processes, on-call engineers with temporary production access, and AI agents with permissions scoped to their task. How is it used? The delegator defines delegation parameters; the engine validates SoD and issues an RFC 8693 delegation token that the delegate uses in place of their own credentials for the authorized scope. Why? Uncontrolled delegation creates privilege escalation; with this domain every delegation is auditable, bounded in time and scope, and revocable at any time. Standards: RFC 8693 (OAuth 2.0 Token Exchange), RFC 9396 (Rich Authorization Requests), NIST SP 800-53 R5.2 AC-2(5), ANSI INCITS 359-2004 §4.5, ISO 27001:2022 A.5.18.", "es": "Delegación e Impersonación · delegation. ¿Qué es? El mecanismo que permite a un usuario (delegante) transferir temporalmente un subconjunto acotado de sus permisos a otro usuario o sistema (delegado), o que un sistema actúe en nombre de un usuario con su consentimiento explícito. La delegación tiene: alcance definido (qué permisos exactamente), duración máxima, posibilidad de sub-delegación controlada, validación SoD (la delegación no puede crear conflictos de segregación) y trazabilidad completa e inmutable. ¿Para qué sirve? Habilitar flujos de negocio que requieren que alguien actúe en nombre de otro: asistentes ejecutivos aprobando en ausencia del directivo, robots RPA ejecutando procesos automatizados, ingenieros on-call con acceso temporal a producción, y agentes de IA con permisos acotados a su tarea. ¿Cómo se usa? El delegante define los parámetros de la delegación; el motor valida SoD y emite un token de delegación RFC 8693 que el delegado usa en lugar de sus propias credenciales para el alcance autorizado. ¿Por qué? La delegación sin control genera escalada de privilegios; con este dominio cada delegación es auditable, acotada en tiempo y alcance, y revocable en cualquier momento. Normas: RFC 8693 (OAuth 2.0 Token Exchange), RFC 9396 (Rich Authorization Requests), NIST SP 800-53 R5.2 AC-2(5), ANSI INCITS 359-2004 §4.5, ISO 27001:2022 A.5.18."}', '{}', NULL, NULL, NULL, false, NULL, 10, 1, 0, 'skull.D10', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1200, 'delegation', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-760b-ba59-755ed11ea74b', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "External Digital Signature", "es": "Firma Digital Externa"}', '{"en": "External Digital Signature", "es": "Firma Digital Externa"}', NULL, '{"en": "External Digital Signature · digital_signature. What is it? The orchestrator of legally-valid digital signing operations using certificates issued by legally-recognized external certification authorities (ADSIB Bolivia, FNMT Spain, etc.). Covers the complete cycle: document signing in AdES formats (PAdES for PDF, CAdES for binaries, XAdES for XML), CA certification chains with real-time OCSP validation, RFC 3161 timestamps (temporal existence proof before a trusted third party), third-party signature verification, LTV long-term validation preservation (guarantees verifiability when the certificate expires), and EUDI wallet support per eIDAS 2.0. What is it for? Granting legal validity to electronic contracts, invoices, regulatory reports, and any document requiring non-repudiation (the signer cannot deny having signed). How is it used? The user requests document signing; bAuth verifies the OCSP status of the user ADSIB certificate, applies the signature with the private key stored in Vault HSM, adds the RFC 3161 timestamp from the TSA, and generates the LTV-signed document ready for archiving. Why? Bolivia Law 164 Art. 78 equates advanced electronic signatures to handwritten signatures; digitally signed contracts are legally binding and admissible as judicial evidence. Standards: Bolivia Law 164 Art. 15-20/78, ADSIB-FD-POLT-015 v2.3, eIDAS 2.0 (EU 2024/1183), RFC 3161 (TSP), RFC 5280, ETSI EN 319 102/122/132, PAdES EN 319 132, CAdES EN 319 122.", "es": "Firma Digital Externa · digital_signature. ¿Qué es? El orquestador de operaciones de firma digital con validez jurídica, usando certificados emitidos por autoridades certificadoras externas reconocidas por ley (ADSIB Bolivia, FNMT España, etc.). Cubre el ciclo completo: firma de documentos en formatos AdES (PAdES para PDF, CAdES para binarios, XAdES para XML), cadena de certificación CA con validación OCSP en tiempo real, sellos de tiempo RFC 3161 (prueba de existencia temporal ante un tercero de confianza), verificación de firmas de terceros, preservación a largo plazo LTV (garantiza la verificabilidad cuando el certificado vence) y soporte para wallets EUDI conforme a eIDAS 2.0. ¿Para qué sirve? Otorgar validez jurídica a contratos electrónicos, facturas, informes regulatorios y cualquier documento que requiera no-repudio (el firmante no puede negar haber firmado). ¿Cómo se usa? El usuario solicita la firma de un documento; bAuth verifica el estado OCSP del certificado ADSIB del usuario, aplica la firma con la clave privada almacenada en Vault HSM, añade el sello de tiempo RFC 3161 de la TSA y genera el documento LTV-firmado listo para archivo. ¿Por qué? Ley 164 Bolivia Art. 78 equipara la firma electrónica avanzada a la firma manuscrita; los contratos digitalmente firmados son legalmente vinculantes y admitidos como prueba judicial. Normas: Ley 164 Bolivia Art. 15-20/78, ADSIB-FD-POLT-015 v2.3, eIDAS 2.0 (UE 2024/1183), RFC 3161 (TSP), RFC 5280, ETSI EN 319 102/122/132, PAdES EN 319 132, CAdES EN 319 122."}', '{}', NULL, NULL, NULL, false, NULL, 13, 1, 0, 'skull.D13', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1500, 'digital_signature', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-71cd-8846-2cdd0f7bb8ef', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Financial Controls", "es": "Controles Financieros"}', '{"en": "Financial Controls", "es": "Controles Financieros"}', NULL, '{"en": "Financial Controls · financial. What is it? The custodian of rules protecting the organization financial resources: transactional limits by amount and frequency, dual approval (four-eyes principle, k-of-N quorum), financial segregation of duties (SoD: creator does not approve, approver does not reconcile), electronic invoicing per Bolivia SIN (CUIS/CUFD/SIAT), regulatory reporting, anomaly-based fraud detection, and automatic reconciliation. What is it for? Preventing internal and external financial fraud, ensuring traceability of every financial operation, and complying with accounting, tax, and payment regulations. How is it used? Every financial transaction is intercepted: amount verified against role limits, initiator role checked against SoD matrix, and if approval is required, the approver quorum is assembled. Why? Financial controls are a non-negotiable requirement of internal and external audit; their absence is sanctioned by regulators (ASFI, SBEF, Bolivia SIN). Standards: PCI DSS 4.0 Req 7-8, SOX §302/§404, ISO 20022, COSO Framework 2013, ISO 9001:2015 §8.4, Bolivia Law 843 Art. 70, Bolivia Law 164, SIN RND 102100000011.", "es": "Controles Financieros · financial. ¿Qué es? El custodio de las reglas que protegen los recursos financieros de la organización: límites transaccionales por monto y frecuencia, aprobación dual (principio de cuatro ojos, quórum k-de-N), segregación de funciones financieras (SoD: quien crea no aprueba, quien aprueba no concilia), facturación electrónica conforme a SIN Bolivia (CUIS/CUFD/SIAT), reportes regulatorios, detección de fraude por anomalías y conciliación automática. ¿Para qué sirve? Prevenir fraude financiero interno y externo, garantizar la trazabilidad de cada operación financiera y cumplir con regulaciones contables, fiscales y de pagos. ¿Cómo se usa? Toda transacción financiera es interceptada: se verifica el monto contra los límites del rol, el rol del iniciador contra la matriz SoD, y si requiere aprobación, se ensambla el quórum de aprobadores. ¿Por qué? Los controles financieros son requisito irrenunciable de auditoría interna y externa; su ausencia es sancionada por reguladores (ASFI, SBEF, SIN Bolivia). Normas: PCI DSS 4.0 Req 7-8, SOX §302/§404, ISO 20022, COSO Framework 2013, ISO 9001:2015 §8.4, Ley 843 Bolivia Art. 70, Ley 164 Bolivia, SIN RND 102100000011."}', '{}', NULL, NULL, NULL, false, NULL, 3, 1, 0, 'skull.D03', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 500, 'financial', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-7261-a4fb-c610e94aa013', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Temporal Access", "es": "Acceso Temporal"}', '{"en": "Temporal Access", "es": "Acceso Temporal"}', NULL, '{"en": "Temporal Access · temporal. What is it? The temporal restriction engine: defines when (not just who) can access a resource. Manages valid time windows (Monday to Friday 8:00-18:00), non-overlapping assignment periods (PostgreSQL 18 WITHOUT OVERLAPS / PERIOD), country and tenant holiday calendars, shift rotation with temporal inheritance, and schedule exceptions (on-call, overtime). What is it for? Ensuring permissions are only active during authorized schedules, reducing the attack exposure window outside business hours. How is it used? When evaluating access, the engine verifies that the current date and time fall within the user role valid time windows; outside business hours access is DENY even if the role is correct. Why? Statistically 40% of attacks occur outside business hours; temporal restrictions drastically reduce overnight and weekend risk without productivity impact. Standards: NIST SP 800-53 R5.2 AC-2(2)/AC-3(7), GTRBAC (Generalized Temporal RBAC) industry standard, ISO 8601, RFC 5545 (iCalendar), PostgreSQL 18 temporal constraints.", "es": "Acceso Temporal · temporal. ¿Qué es? El motor de restricciones temporales: define cuándo (no solo quién) puede acceder a un recurso. Gestiona ventanas horarias válidas (lunes a viernes 8:00-18:00), períodos de asignación sin solapamiento (PostgreSQL 18 WITHOUT OVERLAPS / PERIOD), calendarios de feriados por país y tenant, rotación de turnos con herencia temporal y excepciones de horario (guardias, horas extra). ¿Para qué sirve? Asegurar que los permisos estén activos únicamente en los horarios autorizados, reduciendo la ventana de exposición a ataques fuera de horario laboral. ¿Cómo se usa? Al evaluar un acceso, el motor verifica que la fecha y hora actuales caigan dentro de las ventanas temporales válidas del rol del usuario; fuera de horario el acceso es DENY aunque el rol sea correcto. ¿Por qué? Estadísticamente el 40% de los ataques ocurren fuera del horario laboral; las restricciones temporales reducen drásticamente el riesgo nocturno y de fin de semana sin impacto en productividad. Normas: NIST SP 800-53 R5.2 AC-2(2)/AC-3(7), GTRBAC (Generalized Temporal RBAC) estándar de industria, ISO 8601, RFC 5545 (iCalendar), PostgreSQL 18 temporal constraints."}', '{}', NULL, NULL, NULL, false, NULL, 4, 1, 0, 'skull.D04', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 600, 'temporal', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-7379-a1c1-278de324cdbb', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Network Security", "es": "Seguridad de Red"}', '{"en": "Network Security", "es": "Seguridad de Red"}', NULL, '{"en": "Network Security · network. What is it? The SBOS network infrastructure protection layer applied to identity control: validates that inter-service connections use mutual mTLS with SPIFFE SVIDs (no passwords between microservices), that access tokens cannot be stolen and reused (DPoP binding, PKCE), controls request rate by user/IP/route (rate limiting against brute force), evaluates connection point security posture, applies Zero Trust micro-segmentation (each service only communicates with the services it needs), inspects in-transit payload (DPI/DLP to detect sensitive data in unauthorized transit), and propagates identity context between services (W3C Trace Context v2). What is it for? Ensuring the communications network is a secure extension of identity control, not an unrestricted channel. How is it used? When establishing a connection between two microservices, both present their X.509 SVID; Kong validates DPoP on every API token; the rate limiter blocks when the threshold is exceeded. Why? Unsegmented internal networks are the primary lateral movement vector after an initial breach. Standards: RFC 8705 (mTLS), RFC 9449 (DPoP), RFC 7636 (PKCE), NIST SP 800-207 (Zero Trust Architecture), SBOS-054 NRS-01 to NRS-10, ISO 27001:2022 A.8.20/A.8.22.", "es": "Seguridad de Red · network. ¿Qué es? La capa de protección de la infraestructura de red del SBOS aplicada al control de identidad: valida que las conexiones entre servicios usen mTLS mutuo con SVIDs SPIFFE (sin contraseñas entre microservicios), que los tokens de acceso no puedan ser robados y reutilizados (DPoP binding, PKCE), controla la velocidad de peticiones por usuario/IP/ruta (rate limiting contra fuerza bruta), evalúa la postura de seguridad del punto de conexión, aplica micro-segmentación Zero Trust (cada servicio solo habla con los servicios que necesita), inspecciona el payload en tránsito (DPI/DLP para detectar datos sensibles en tránsito no autorizado) y propaga el contexto de identidad entre servicios (W3C Trace Context v2). ¿Para qué sirve? Garantizar que la red de comunicaciones sea una extensión segura del control de identidad, no un canal sin restricciones. ¿Cómo se usa? Al establecer una conexión entre dos microservicios, ambos presentan su SVID X.509; Kong valida DPoP en cada token de API; el rate limiter bloquea si se supera el umbral. ¿Por qué? Las redes internas sin segmentación son el principal vector de movimiento lateral tras una brecha inicial. Normas: RFC 8705 (mTLS), RFC 9449 (DPoP), RFC 7636 (PKCE), NIST SP 800-207 (Zero Trust Architecture), SBOS-054 NRS-01 a NRS-10, ISO 27001:2022 A.8.20/A.8.22."}', '{}', NULL, NULL, NULL, false, NULL, 7, 1, 0, 'skull.D07', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 900, 'network', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-74a6-b3c2-e98d39e04678', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Credential Management", "es": "Gestión de Credenciales"}', '{"en": "Credential Management", "es": "Gestión de Credenciales"}', NULL, '{"en": "Credential Management · credentials. What is it? Responsible for the complete lifecycle of all ecosystem credentials: passwords (NIST SP 800-63B-4 policy: Argon2id with salt, HIBP screening, minimum 15 characters, no mandatory periodic rotation), multi-factor authentication (TOTP/HOTP, FIDO2/WebAuthn, passkeys), X.509 certificates (issuance, renewal, revocation), JWT and opaque access tokens (issuance, refresh, introspection), multi-channel account recovery, authenticator binding (device binding), and any credential revocation in less than 30 seconds. What is it for? Ensuring credentials are secure from creation to revocation, and any compromised credential is neutralized in real time. How is it used? The user registers password + mandatory second factor; credentials stored with Argon2id; revocation propagated to Redis cache in < 30s and to all PEPs via CAEP. Why? Weak or compromised credentials are the number 1 attack vector: 81% of data breaches involve stolen or weak passwords (Verizon DBIR). Standards: NIST SP 800-63B-4 (Jul-2025), FIDO2/CTAP2, X.509 RFC 5280, RFC 6749/7519/7662, OWASP ASVS v5.0 §2, PCI DSS 4.0 Req 8, ISO 27001:2022 A.5.17.", "es": "Gestión de Credenciales · credentials. ¿Qué es? El responsable del ciclo de vida completo de todas las credenciales del ecosistema: contraseñas (política NIST SP 800-63B-4: Argon2id con salt, screening contra HIBP, mínimo 15 caracteres, sin rotación periódica obligatoria), autenticación multi-factor (TOTP/HOTP, FIDO2/WebAuthn, passkeys), certificados X.509 (emisión, renovación, revocación), tokens de acceso JWT y opacos (emisión, refresco, introspección), recuperación de cuenta multi-canal, vinculación de autenticador (device binding) y revocación de cualquier credencial en menos de 30 segundos. ¿Para qué sirve? Garantizar que las credenciales sean seguras desde su creación hasta su revocación, y que cualquier credencial comprometida sea neutralizada en tiempo real. ¿Cómo se usa? El usuario registra contraseña + segundo factor obligatorio; las credenciales se almacenan con Argon2id; la revocación se propaga al cache Redis en < 30s y a todos los PEP vía CAEP. ¿Por qué? Las credenciales débiles o comprometidas son el vector de ataque número 1: el 81% de las brechas de datos involucra contraseñas robadas o débiles (Verizon DBIR). Normas: NIST SP 800-63B-4 (jul-2025), FIDO2/CTAP2, X.509 RFC 5280, RFC 6749/7519/7662, OWASP ASVS v5.0 §2, PCI DSS 4.0 Req 8, ISO 27001:2022 A.5.17."}', '{}', NULL, NULL, NULL, false, NULL, 9, 1, 0, 'skull.D09', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1100, 'credentials', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-73b3-a6f3-eebc42cfa13d', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Context / Session", "es": "Contexto / Sesión"}', '{"en": "Context / Session", "es": "Contexto y Sesión"}', NULL, '{"en": "Context / Session · context_session. What is it? The engine maintaining complete contextual state for every operation in the ecosystem. The ctx_id is a 6-layer context identifier (tenant + user + device + session + operation + W3C trace) that inescapably accompanies every request across all microservices. Manages: ctx_id lifecycle (creation, propagation, expiration, revocation), continuous risk score (rises on anomalies: new device, unusual schedule, unexpected location), device posture (MDM, patch level), break-glass emergency access (with dual approval), active assurance level (AAL can decrease if risk rises, or increase via RFC 9470 step-up), and identity threat detection (ITDR). What is it for? Providing complete, real-time context to every access decision, enabling dynamic decisions based on the actual session state. How is it used? The ctx_id is generated at session start and propagated via W3C Trace Context across all microservices; each service includes it in its logs and decisions. Why? Without execution context the PDP can only apply static rules; with ctx_id it applies dynamic Zero Trust: evaluates every request as if it were the first. Standards: NIST SP 800-207 §3.3, W3C Trace Context v2, OpenTelemetry Baggage, RFC 9470 (Step-Up Auth), SBOS-049 (Context Plane), CAEP 1.0 Final Sep-2025.", "es": "Contexto y Sesión · context_session. ¿Qué es? El motor que mantiene el estado contextual completo de cada operación en el ecosistema. El ctx_id es un identificador de contexto de 6 capas (tenant + usuario + dispositivo + sesión + operación + trace W3C) que acompaña de forma ineludible cada request a través de todos los microservicios. Gestiona: el ciclo de vida del ctx_id (creación, propagación, expiración, revocación), la puntuación de riesgo continuo (sube ante anomalías: dispositivo nuevo, horario inusual, ubicación inesperada), postura del dispositivo (MDM, nivel de parches), acceso de emergencia break-glass (con doble aprobación), nivel de garantía activo (el AAL puede bajar si el riesgo sube, o subir vía step-up RFC 9470) y detección de amenazas de identidad (ITDR). ¿Para qué sirve? Proveer contexto completo y en tiempo real a cada decisión de acceso, habilitando decisiones dinámicas basadas en el estado actual de la sesión. ¿Cómo se usa? El ctx_id se genera al iniciar la sesión y se propaga vía W3C Trace Context en todos los microservicios; cada servicio lo incluye en sus logs y decisiones. ¿Por qué? Sin contexto de ejecución el PDP solo aplica reglas estáticas; con ctx_id aplica Zero Trust dinámico: evalúa cada request como si fuera el primero. Normas: NIST SP 800-207 §3.3, W3C Trace Context v2, OpenTelemetry Baggage, RFC 9470 (Step-Up Auth), SBOS-049 (Context Plane), CAEP 1.0 Final sep-2025."}', '{}', NULL, NULL, NULL, false, NULL, 8, 1, 0, 'skull.D08', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1000, 'context_session', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c96-7b9f-b9bc-e68dff0080fe', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Structural Registry", "es": "Registro Estructural"}', '{"en": "Structural Registry", "es": "Registro Estructural"}', NULL, '{"en": "Structural Registry · structural_registry. What is it? The administrative meta-domain describing and validating the architecture of the SBOS identity policy tree itself. It contains no business rules and makes no access decisions: its function is to describe and safeguard the tree structure. Contains: the canonical attribute schema (exhaustive list of all possible attributes, with data type, allowed values, whether PII/SPI, and the block it belongs to), the catalog of AtomLang evaluable atoms (each atom with its unique 64-bit BitMask position, verb_id, and evaluation condition), tree version control (who changed what, when, and why), and the structural business zone. What is it for? Guaranteeing the consistency and structural validity of the tree: no two atoms at the same BitMask position (which would cause silent false positives), every attribute referenced in an atom exists with the correct type, and tree changes are documented and approved. How is it used? The AtomLang compiler queries D98 before accepting a new atom; the versioning system records every change with mandatory HITL approval for production. Why? Without a structural registry, the tree could grow inconsistently generating BitMask collisions or references to nonexistent attributes, causing silent failures in policy evaluation. Standards: ISO/IEC 24760-2:2025 §6, SCIM 2.0 RFC 7643, AtomLang SBOS spec v1.0, NIST SP 800-162 §4, ISO 9001:2015 §7.5 (documented information management).", "es": "Registro Estructural · structural_registry. ¿Qué es? El meta-dominio administrativo que describe y valida la arquitectura del propio árbol de políticas de identidad SBOS. No contiene reglas de negocio ni toma decisiones de acceso: su función es describir y custodiar la estructura del árbol. Contiene: el esquema canónico de atributos (lista exhaustiva de todos los atributos posibles, con su tipo de dato, valores permitidos, si es PII/SPI y el bloque al que pertenece), el catálogo de átomos evaluables en AtomLang (cada átomo con su posición única en el BitMask 64-bit, verb_id y condición de evaluación), el control de versiones del árbol (quién cambió qué, cuándo y por qué) y la zona de negocios estructural. ¿Para qué sirve? Garantizar la coherencia y validez estructural del árbol: que no haya dos átomos en la misma posición del BitMask (lo que causaría falsos positivos silenciosos), que cada atributo referenciado en un átomo exista con el tipo correcto, y que los cambios al árbol estén documentados y aprobados. ¿Cómo se usa? El compilador AtomLang consulta D98 antes de aceptar un nuevo átomo; el sistema de versionado registra todo cambio con aprobación HITL obligatoria para producción. ¿Por qué? Sin un registro estructural, el árbol podría crecer de forma inconsistente generando colisiones de BitMask o referencias a atributos inexistentes, causando fallos silenciosos en la evaluación de políticas. Normas: ISO/IEC 24760-2:2025 §6, SCIM 2.0 RFC 7643, AtomLang SBOS spec v1.0, NIST SP 800-162 §4, ISO 9001:2015 §7.5 (gestión de información documentada)."}', '{}', NULL, NULL, NULL, false, NULL, 98, 1, 0, 'skull.D98', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 1800, 'structural_registry', NULL) ON CONFLICT DO NOTHING;
INSERT INTO bauth.idn_roles_template VALUES ('019f8c34-9c99-733a-a9f3-2421b043fa09', '019f8ae0-4282-731e-8d71-c42029fded2f', '019f8c82-0b2b-7909-a2d3-276b639531d8', 'domain', '{"en": "Geospatial Access", "es": "Acceso Geoespacial"}', '{"en": "Geospatial Access", "es": "Acceso Geoespacial"}', NULL, '{"en": "Geospatial Access · geospatial. What is it? The engine evaluating the user geographic position as an authorization factor. Manages geofences (geographic polygons with specific permissions: inside PERMIT, outside DENY), point-in-time location validation, impossible travel detection (if a user authenticates in Madrid and 5 minutes later in La Paz, it is a fraud anomaly), data sovereignty (citizen data of a country is only processed on servers in that country), and fleet-based access (a driver only accesses from the territory assigned to their unit). What is it for? Adding geographic context as a mandatory authorization dimension: a doctor can access patient records from the hospital but not from a café abroad. How is it used? The device IP is geocoded; corporate mobile GPS or network cell signal may also be used; the result is evaluated against the geofences configured for the user role and tenant. Why? Fulfills GDPR Art. 44-49 (international transfer restrictions), prevents access from high-risk jurisdictions, and limits blast radius when credentials are compromised. Standards: RFC 7946 (GeoJSON), ISO 6709, ISO 3166-1, GDPR Art. 44-49, NIST SP 800-53 R5.2 AC-3(11), Bolivia Law 1174 (data residency).", "es": "Acceso Geoespacial · geospatial. ¿Qué es? El motor que evalúa la posición geográfica del usuario como factor de autorización. Gestiona geocercas (polígonos geográficos con permisos específicos: dentro PERMIT, fuera DENY), validación de ubicación puntual, detección de viaje imposible (si un usuario se autentica en Madrid y 5 minutos después en La Paz, es una anomalía de fraude), soberanía de datos (los datos de ciudadanos de un país solo se procesan en servidores de ese país) y acceso por flota vehicular (un conductor solo accede desde el territorio asignado a su unidad). ¿Para qué sirve? Añadir el contexto geográfico como dimensión obligatoria de autorización: un médico puede acceder al historial del paciente desde el hospital pero no desde un café en el extranjero. ¿Cómo se usa? La IP del dispositivo se geocodifica; también puede usarse GPS del móvil corporativo o la celda de red; el resultado se evalúa contra las geocercas configuradas para el rol del usuario y el tenant. ¿Por qué? Cumple GDPR Art. 44-49 (restricciones de transferencia internacional), previene accesos desde jurisdicciones de riesgo alto y limita el radio de daño ante credenciales comprometidas. Normas: RFC 7946 (GeoJSON), ISO 6709, ISO 3166-1, GDPR Art. 44-49, NIST SP 800-53 R5.2 AC-3(11), Ley 1174 Bolivia (residencia de datos)."}', '{}', NULL, NULL, NULL, false, NULL, 6, 1, 0, 'skull.D06', true, '1.0', '2026-07-22', NULL, '2026-07-22 23:41:25.806886+00', '2026-07-22 23:41:25.806886+00', 800, 'geospatial', NULL) ON CONFLICT DO NOTHING;
